def _mirror_workspace_report_bundle(
    paths: Mapping[str, Path],
    as_of: str | dt.date,
) -> dict[str, Path]:
    """Copy user-facing artifacts into the code workspace for clickable links."""

    day = parse_as_of(as_of).isoformat()
    report_dir = project_root() / "reports" / day
    report_dir.mkdir(parents=True, exist_ok=True)
    artifact_keys = (
        "color_trade_board",
        "groko_trades",
        "report",
        "trade_tickets",
        "green_trade_tickets",
        "target_order_candidates",
        "execution_opportunity_audit",
        "chain_oi_overlay_provenance",
        "sizing_audit",
        "final_recommendations",
        "no_trade_audit",
        "decision_board",
        "manifest",
        "confidence_audit",
        "expectancy_evidence",
        "monthly_feasibility",
        "profitability_calibration",
    )
    for key in artifact_keys:
        source = paths.get(key)
        if source is None or not source.exists():
            continue
        destination = report_dir / source.name
        if source.resolve() != destination.resolve():
            shutil.copy2(source, destination)
    return {
        "workspace_report_dir": report_dir,
        "workspace_report": report_dir / paths["report"].name,
        "workspace_color_trade_board": report_dir / paths["color_trade_board"].name,
        "workspace_groko_trades": report_dir / paths["groko_trades"].name,
    }


def archive_existing_action_surface(
    paths: Mapping[str, Path],
    *,
    source_date: str,
) -> dict[str, Any]:
    """Preserve a completed actionable run before a same-date rerun overwrites it."""

    manifest_path = paths.get("manifest")
    out_dir = paths.get("out_dir")
    if manifest_path is None or out_dir is None or not manifest_path.exists():
        return {"status": "no_prior_completed_run", "archived_file_count": 0}
    try:
        prior_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return {
            "status": "prior_manifest_unreadable",
            "archived_file_count": 0,
            "error": str(exc),
        }
    row_counts = prior_manifest.get("row_counts") if isinstance(prior_manifest, Mapping) else {}
    row_counts = row_counts if isinstance(row_counts, Mapping) else {}
    green_count = int(_as_float(row_counts.get("green_trade_tickets")) or 0)
    target_count = int(_as_float(row_counts.get("target_order_ticket_rows")) or 0)
    if green_count + target_count <= 0:
        return {
            "status": "prior_run_had_no_action_surface",
            "archived_file_count": 0,
            "prior_green_count": green_count,
            "prior_target_count": target_count,
        }

    stamp = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    archive_dir = out_dir.parent / "run_history" / source_date / stamp
    archive_dir.mkdir(parents=True, exist_ok=False)
    archived: list[str] = []
    for key in ACTION_SURFACE_ARCHIVE_KEYS:
        path = paths.get(key)
        if path is None or not path.is_file():
            continue
        shutil.copy2(path, archive_dir / path.name)
        archived.append(path.name)
    chain_dir = out_dir / "schwab_chains"
    if chain_dir.is_dir():
        shutil.copytree(chain_dir, archive_dir / "schwab_chains")
        archived.append("schwab_chains/")
    metadata = {
        "status": "archived_prior_action_surface",
        "source_date": source_date,
        "archive_dir": str(archive_dir),
        "archived_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "archived_file_count": len(archived),
        "archived_files": archived,
        "prior_pipeline_version": _as_text(prior_manifest.get("pipeline_version")),
        "prior_green_count": green_count,
        "prior_target_count": target_count,
    }
    _write_json(archive_dir / "archive_metadata.json", metadata)
    return metadata


def resolve_date_dir(base_dir: Path, as_of: str | dt.date) -> Path:
    """Resolve either a trade-desk root or an already dated source directory."""

    day = parse_as_of(as_of).isoformat()
    base = Path(base_dir).expanduser().resolve()
    if base.name == day:
        return base
    return base / day


def _streaming_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def prepare_chain_oi_overlay_source(
    base_date_dir: Path,
    overlay_path: Path,
    staging_root: Path,
    *,
    base_analysis_date: str | dt.date,
) -> tuple[Path, dict[str, Any]]:
    """Stage an explicit later-date chain-OI overlay without relabeling it."""

    from ._vendor import data as uw_data

    base_day = parse_as_of(base_analysis_date)
    base_date_dir = Path(base_date_dir).expanduser().resolve()
    overlay_path = Path(overlay_path).expanduser().resolve()
    if not base_date_dir.is_dir():
        raise FileNotFoundError(f"base Options Agent source directory is missing: {base_date_dir}")
    if not overlay_path.is_file() or overlay_path.suffix.lower() not in {".csv", ".zip"}:
        raise FileNotFoundError(f"chain-OI overlay must be an existing CSV or ZIP: {overlay_path}")

    required_columns = {
        "option_symbol",
        "underlying_symbol",
        "last_oi",
        "curr_oi",
        "last_date",
        "curr_date",
    }
    profile = uw_data.read_csv_export(
        overlay_path,
        usecols=lambda column: column in required_columns,
        low_memory=False,
    )
    missing = sorted(required_columns - set(profile.columns))
    if missing:
        raise ValueError(f"chain-OI overlay is missing required columns: {missing}")
    if profile.empty:
        raise ValueError("chain-OI overlay contains no data rows")

    current_dates = sorted(
        {
            value.isoformat()
            for value in pd.to_datetime(profile["curr_date"], errors="coerce").dt.date.dropna()
        }
    )
    prior_dates = sorted(
        {
            value.isoformat()
            for value in pd.to_datetime(profile["last_date"], errors="coerce").dt.date.dropna()
        }
    )
    if len(current_dates) != 1:
        raise ValueError(f"chain-OI overlay must contain exactly one curr_date; found {current_dates}")
    overlay_day = parse_as_of(current_dates[0])
    if overlay_day < base_day:
        raise ValueError(
            f"chain-OI overlay date {overlay_day.isoformat()} precedes base analysis {base_day.isoformat()}"
        )
    if base_day.isoformat() not in prior_dates:
        raise ValueError(
            f"chain-OI overlay last_date values {prior_dates} do not include base analysis {base_day.isoformat()}"
        )
    filename_dates = sorted(set(re.findall(r"20\d{2}-\d{2}-\d{2}", overlay_path.name)))
    if filename_dates and overlay_day.isoformat() not in filename_dates:
        raise ValueError(
            f"chain-OI overlay filename date(s) {filename_dates} do not match curr_date {overlay_day.isoformat()}"
        )

    stage_dir = Path(staging_root).expanduser().resolve() / "_overlay_source" / base_day.isoformat()
    stage_dir.mkdir(parents=True, exist_ok=True)
    for source in sorted(base_date_dir.iterdir()):
        if source.name.startswith("chain-oi-changes-") or source.name in {
            ".codexuw_hash_cache.json",
            ".groko_hash_cache.json",
        }:
            continue
        target = stage_dir / source.name
        if target.is_symlink():
            target.unlink()
        elif target.exists():
            raise FileExistsError(f"overlay staging target already exists and is not a symlink: {target}")
        target.symlink_to(source, target_is_directory=source.is_dir())

    staged_overlay = stage_dir / f"chain-oi-changes-explicit-overlay{overlay_path.suffix.lower()}"
    if staged_overlay.is_symlink():
        staged_overlay.unlink()
    elif staged_overlay.exists():
        raise FileExistsError(
            f"overlay staging target already exists and is not a symlink: {staged_overlay}"
        )
    staged_overlay.symlink_to(overlay_path)
    metadata = {
        "schema_version": "options_agent.chain_oi_overlay.v1",
        "status": "validated",
        "overlay_kind": "chain_oi_only",
        "base_analysis_date": base_day.isoformat(),
        "overlay_date": overlay_day.isoformat(),
        "base_source_directory": str(base_date_dir),
        "overlay_source_original": str(overlay_path),
        "overlay_source_staged": str(staged_overlay),
        "overlay_sha256": _streaming_sha256(overlay_path),
        "overlay_size_bytes": int(overlay_path.stat().st_size),
        "overlay_row_count": int(len(profile)),
        "overlay_curr_dates": current_dates,
        "overlay_last_dates": prior_dates,
        "staged_source_directory": str(stage_dir),
    }
    return stage_dir, metadata


def apply_portfolio_risk_annotations(
    candidates: Iterable[Mapping[str, Any]],
    portfolio_context: Optional[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Annotate portfolio risk without hiding otherwise qualified trades."""

    portfolio = dict(portfolio_context or {})
    annotated: list[dict[str, Any]] = []
    for candidate in candidates:
        row = dict(candidate)
        ticker = _candidate_ticker(row)
        notes = _portfolio_notes_for_ticker(ticker, portfolio)
        removed_rejects, remaining_rejects = _split_portfolio_rejects(row.get("hard_rejects"))
        if removed_rejects and _is_otherwise_qualified(row, remaining_rejects):
            notes.append("portfolio-only blocker converted to annotation: " + "; ".join(removed_rejects))
            row["hard_rejects"] = "; ".join(remaining_rejects)
        elif remaining_rejects:
            row["hard_rejects"] = "; ".join(remaining_rejects)

        existing_note = str(row.get("portfolio_risk_note") or row.get("portfolio_note") or "").strip()
        if existing_note:
            notes.insert(0, existing_note)

        row["visible_in_final_board"] = True
        row["portfolio_risk_policy"] = "ANNOTATE_ONLY"
        row["portfolio_risk_flag"] = bool(notes)
        row["portfolio_risk_note"] = "; ".join(_dedupe_notes(notes))

        if remaining_rejects:
            row["recommendation_status"] = RecommendationStatus.AVOID.value
            row["status_reason"] = _append_reason(
                row.get("status_reason"),
                "objective hard blocker: " + "; ".join(remaining_rejects),
            )
        elif notes and _is_otherwise_qualified(row, remaining_rejects):
            current_status = str(row.get("recommendation_status") or "").strip().upper()
            if current_status in {"", RecommendationStatus.ENTER.value, "EXECUTE"}:
                row["recommendation_status"] = RecommendationStatus.ENTER_WITH_PORTFOLIO_RISK.value
            else:
                row.setdefault("recommendation_status", current_status)
        else:
            row.setdefault("recommendation_status", _default_status(row, remaining_rejects))

        annotated.append(row)
    return annotated


def build_manifest(
    as_of: str | dt.date,
    root: Optional[Path] = None,
    out_dir: Optional[Path] = None,
) -> dict[str, Any]:
    """Create a manifest skeleton for a design/smoke run."""

    day = parse_as_of(as_of).isoformat()
    resolved_root = root or project_root()
    paths = output_paths(day, root=resolved_root, out_dir=out_dir)
    return {
        "pipeline_name": PIPELINE_NAME,
        "pipeline_version": PIPELINE_VERSION,
        "pipeline_source_provenance": _pipeline_source_provenance(resolved_root),
        "as_of": day,
        "source_root": str(resolved_root),
        "out_dir": str(paths["out_dir"]),
        "agents": agent_roster(),
        "artifacts": {key: str(value) for key, value in paths.items() if key != "out_dir"},
        "visibility_invariant": (
            "portfolio annotations stay in portfolio_risk_note and risk_audit.csv; "
            "they must not hide an otherwise qualified trade"
        ),
        "status_counts": {},
        "warnings": ["live data integrations are not wired in this smoke slice"],
    }


def _pipeline_source_provenance(root: Path) -> dict[str, Any]:
    relative_paths = (
        "uwos/options_agent/core.py",
        "uwos/options_agent/replay.py",
        "uwos/options_agent/forward_registry.py",
        "uwos/options_agent/shadow_outcomes.py",
        "uwos/options_agent/_vendor/data.py",
        "uwos/options_agent/_vendor/schwab_live.py",
        "uwos/options_agent/_vendor/schwab_auth.py",
        "knowledge/options_agent_event_calendar_2026.json",
        "knowledge/groko_replay_pin.json",
    )
    _ = root
    code_root = project_root()
    fingerprints: dict[str, str] = {}
    for relative_path in relative_paths:
        path = code_root / relative_path
        if path.exists():
            fingerprints[relative_path] = hashlib.sha256(path.read_bytes()).hexdigest()
    try:
        sha = subprocess.run(
            ["git", "-C", str(code_root), "rev-parse", "--short", "HEAD"],
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()
        dirty = subprocess.run(
            ["git", "-C", str(code_root), "diff", "--quiet", "HEAD", "--", *relative_paths],
            check=False,
        ).returncode != 0
    except Exception:
        sha = ""
        dirty = True
    return {
        "code_root": str(code_root),
        "git_sha": sha,
        "relevant_files_dirty": dirty,
        "file_sha256": fingerprints,
    }


def _directed_registry_legs(row: Mapping[str, Any]) -> list[dict[str, Any]]:
    text = _as_text(row.get("trade_plan") or row.get("full_ticket"))
    pattern = re.compile(
        r"\b(BUY|SELL)\s+(\d+)\s+([A-Z][A-Z0-9.\-]{0,9})\s+"
        r"(20\d{2}-\d{2}-\d{2})\s+([0-9]+(?:\.[0-9]+)?)\s+(CALL|PUT)\b",
        re.IGNORECASE,
    )
    legs: list[dict[str, Any]] = []
    for match in pattern.finditer(text):
        symbol = _human_option_leg_symbol_key(
            ticker=match.group(3),
            expiry=match.group(4),
            strike=match.group(5),
            option_type=match.group(6),
        )
        if symbol:
            legs.append(
                {
                    "side": match.group(1).upper(),
                    "ratio": int(match.group(2)),
                    "occ_symbol": symbol,
                }
            )
    return legs


def _registry_logical_recommendation_id(
    *,
    account_id: str,
    recommendation_date: dt.date,
    legs: Sequence[Mapping[str, Any]],
) -> str:
    directed = "|".join(
        f"{_as_text(leg.get('side')).upper()}:{int(_as_float(leg.get('ratio')) or 0)}:{_as_text(leg.get('occ_symbol')).upper()}"
        for leg in legs
    )
    digest = hashlib.sha256(
        f"{account_id}|{recommendation_date.isoformat()}|{directed}".encode("utf-8")
    ).hexdigest()[:24]
    return f"oa-{recommendation_date.isoformat()}-{digest}"


