def build_source_inventory(date_dir: Path, as_of: str | dt.date) -> dict[str, Any]:
    """Inventory dated UW inputs without relying on any prior pipeline output."""

    from ._vendor import data as uw_data

    as_of_day = parse_as_of(as_of)
    day = as_of_day.isoformat()
    sources: dict[str, dict[str, Any]] = {}
    for label, prefix in {
        "stock_screener": "stock-screener-",
        "hot_chains": "hot-chains-",
        "chain_oi": "chain-oi-changes-",
        "bot_eod": "bot-eod-report-",
        "dp_eod": "dp-eod-report-",
    }.items():
        try:
            paths = uw_data.find_export_bundle(
                date_dir,
                prefix,
                asof_ceiling=as_of_day,
            )
            sources[label] = {
                "status": "present",
                "path": str(paths[0]) if len(paths) == 1 else "",
                "paths": [str(path) for path in paths],
                "part_count": len(paths),
                "size_bytes": sum(path.stat().st_size for path in paths),
            }
        except Exception as exc:
            sources[label] = {"status": "missing", "error": str(exc)}
    return {"as_of": day, "source_dir": str(date_dir), "sources": sources}


def build_raw_universe(
    date_dir: Path,
    as_of: str | dt.date,
    *,
    discovery_limit: Optional[int] = None,
    max_bot_rows: Optional[int] = None,
) -> tuple[pd.DataFrame, list[str]]:
    """Build a ticker-level raw universe directly from dated UW source files."""

    from ._vendor import data as uw_data

    day = parse_as_of(as_of)
    notes: list[str] = []
    screener = uw_data.load_stock_screener(date_dir, point_in_time=True)
    hot = uw_data.load_hot_chains(date_dir, day, point_in_time=True)
    chain_oi = uw_data.load_chain_oi(date_dir, day, point_in_time=True)

    screen_cols = [
        col
        for col in [
            "ticker",
            "close",
            "prev_close",
            "high",
            "low",
            "week_52_high",
            "week_52_low",
            "sector",
            "call_volume",
            "put_volume",
            "call_premium",
            "put_premium",
            "bullish_premium",
            "bearish_premium",
            "flow_total_premium",
            "flow_bias",
            "iv_rank",
            "iv30d",
            "next_earnings_dt",
            "marketcap",
            "issue_type",
            "is_index",
            "full_name",
            "total_volume",
            "avg30_volume",
            "total_open_interest",
        ]
        if col in screener.columns
    ]
    universe = screener[screen_cols].copy()
    universe = universe.rename(columns={"flow_bias": "screen_flow_bias", "flow_total_premium": "screen_total_premium"})

    hot_agg = aggregate_hot_chains(hot)
    oi_agg = aggregate_chain_oi(chain_oi)
    universe = universe.merge(hot_agg, on="ticker", how="outer").merge(oi_agg, on="ticker", how="outer")
    universe["ticker"] = universe["ticker"].astype(str).str.upper().str.strip()

    seed = universe.copy()
    seed_premium_columns = [
        column
        for column in ("screen_total_premium", "hot_total_premium", "oi_directional_premium")
        if column in seed.columns
    ]
    seed["seed_premium"] = seed[seed_premium_columns].fillna(0).max(axis=1)
    tickers = seed.sort_values("seed_premium", ascending=False)["ticker"].dropna().tolist()
    if discovery_limit is not None:
        tickers = tickers[: int(discovery_limit)]
    try:
        bot = uw_data.aggregate_bot_flow(
            date_dir,
            tickers,
            max_rows=max_bot_rows,
            point_in_time=True,
        )
        universe = universe.merge(bot, on="ticker", how="left")
    except Exception as exc:
        notes.append(f"bot_eod aggregation unavailable: {exc}")

    try:
        dark_pool = uw_data.aggregate_dark_pool_flow(
            date_dir,
            tickers,
            allow_missing=True,
            point_in_time=True,
        )
        dark_pool_status = str(dark_pool.attrs.get("source_status") or "missing_dp_eod")
        universe = universe.merge(dark_pool, on="ticker", how="left")
        universe["dark_pool_source_status"] = dark_pool_status
    except Exception as exc:
        notes.append(f"dp_eod aggregation unavailable: {exc}")
        universe["dark_pool_source_status"] = "dp_eod_error"

    for col in ("screen_flow_bias", "hot_flow_bias", "bot_flow_bias", "oi_directional_bias"):
        if col not in universe.columns:
            universe[col] = math.nan
    for col in ("dp_flow_bias", "dp_directional_ratio"):
        if col not in universe.columns:
            universe[col] = math.nan
    for col in (
        "screen_total_premium",
        "hot_total_premium",
        "bot_total_premium",
        "oi_directional_premium",
        "positive_oi_change",
        "dp_total_premium",
        "dp_directional_premium",
        "dp_prints",
    ):
        if col not in universe.columns:
            universe[col] = 0.0

    universe["combined_flow_bias"] = universe.apply(_combined_flow_bias, axis=1)
    universe["bias"] = universe["combined_flow_bias"].map(_bias_label)
    universe["flow_bias_label"] = universe["bias"]
    universe["signal_premium"] = universe[
        ["screen_total_premium", "hot_total_premium", "bot_total_premium", "oi_directional_premium"]
    ].fillna(0).max(axis=1)
    quality_rows = universe.apply(
        lambda row: pd.Series(_underlying_quality(row), index=["underlying_quality_tier", "underlying_quality_reason"]),
        axis=1,
    )
    universe = pd.concat([universe, quality_rows], axis=1)
    universe["underlying_quality_rank"] = universe["underlying_quality_tier"].map(_underlying_quality_sort_rank)
    universe["score"] = universe.apply(_score_universe_row, axis=1)
    universe["quality_status"] = universe.apply(_quality_status, axis=1)
    universe["flow_reason"] = universe.apply(_flow_reason, axis=1)
    universe = universe.sort_values(
        ["underlying_quality_rank", "score", "signal_premium"],
        ascending=[True, False, False],
    ).reset_index(drop=True)
    return universe, notes


def collect_market_price_spots(
    as_of: str | dt.date,
    out_dir: Path,
    *,
    live_schwab: bool = False,
    chain_snapshot_dir: Optional[Path] = None,
    strike_count: int = 80,
) -> tuple[dict[str, float], dict[str, Any], list[str]]:
    """Fetch early broad-market spot prices when a live/snapshot source is requested."""

    if not live_schwab and chain_snapshot_dir is None:
        return {}, {"source_mode": "uw_eod_only", "source": "UW stock screener close/prev_close"}, []
    try:
        from ._vendor.schwab_live import SchwabChainValidator, chain_spot
    except Exception as exc:
        return {}, {"source_mode": "uw_eod_only", "source": "UW stock screener close/prev_close"}, [
            f"early market-price Schwab import unavailable: {exc}"
        ]

    day = parse_as_of(as_of)
    validator = SchwabChainValidator(
        out_dir / "market_price_regime_live",
        strike_count=int(strike_count),
        snapshot_dir=chain_snapshot_dir,
        allow_live_fallback=bool(live_schwab),
    )
    query_from = day + dt.timedelta(days=MIN_LIVE_DTE)
    query_to = day + dt.timedelta(days=MAX_LIVE_DTE)
    spots: dict[str, float] = {}
    notes: list[str] = []
    for ticker in CORE_AUDIT_TICKERS:
        chain = validator.get_chain(ticker, query_from, query_to)
        if not chain:
            continue
        spot = chain_spot(chain)
        if math.isfinite(spot) and spot > 0:
            spots[ticker] = float(spot)
    try:
        validator.save()
    except Exception as exc:
        notes.append(f"early market-price chain snapshot save failed: {exc}")
    if not spots:
        notes.append("early market-price live/snapshot spots unavailable; market_price_regime fell back to UW EOD close/prev_close")
    source_mode = "schwab_live" if live_schwab and chain_snapshot_dir is None else "schwab_snapshot"
    return (
        spots,
        {
            "source_mode": source_mode if spots else "uw_eod_only",
            "source": "Schwab option chain underlying quote" if spots else "UW stock screener close/prev_close",
            "requested_tickers": list(CORE_AUDIT_TICKERS),
            "spot_tickers": sorted(spots),
            "chain_sources": validator.sources,
            "chain_errors": validator.errors,
        },
        notes,
    )


def collect_live_market_context(*, live_schwab: bool) -> dict[str, Any]:
    """Fetch current macro proxies for review without changing point-in-time selection."""

    if not live_schwab:
        return {
            "status": "not_requested",
            "source": "",
            "symbols": list(LIVE_MACRO_CONTEXT_SYMBOLS),
            "quotes": [],
        }
    try:
        from ._vendor.schwab_auth import SchwabAuthConfig, SchwabLiveDataService

        service = SchwabLiveDataService(
            SchwabAuthConfig.from_env(load_dotenv_file=True),
            interactive_login=False,
        )
        payload = service.get_quotes(LIVE_MACRO_CONTEXT_SYMBOLS)
    except Exception as exc:
        return {
            "status": "error",
            "source": "Schwab quotes",
            "symbols": list(LIVE_MACRO_CONTEXT_SYMBOLS),
            "quotes": [],
            "error": str(exc)[:500],
        }

    rows: list[dict[str, Any]] = []
    for symbol in LIVE_MACRO_CONTEXT_SYMBOLS:
        item = payload.get(symbol, {}) if isinstance(payload, Mapping) else {}
        quote = item.get("quote", item) if isinstance(item, Mapping) else {}
        last = _as_float(quote.get("lastPrice", quote.get("mark")))
        close = _as_float(quote.get("closePrice"))
        percent_change = _as_float(quote.get("netPercentChangeInDouble"))
        if percent_change is None and last is not None and close is not None and close > 0:
            percent_change = (last - close) / close * 100.0
        if last is None and close is None:
            continue
        rows.append(
            {
                "symbol": symbol,
                "last": last,
                "close": close,
                "percent_change": percent_change,
                "quote_time": quote.get("quoteTime", quote.get("tradeTime", "")),
            }
        )
    return {
        "status": "ok" if rows else "unavailable",
        "source": "Schwab quotes",
        "symbols": list(LIVE_MACRO_CONTEXT_SYMBOLS),
        "quotes": rows,
        "fetched_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "selection_authority": "context_only",
    }


def _live_market_context_note(context: Optional[Mapping[str, Any]]) -> str:
    if not isinstance(context, Mapping) or context.get("status") != "ok":
        return ""
    parts = []
    for row in context.get("quotes", []) if isinstance(context.get("quotes"), list) else []:
        if not isinstance(row, Mapping):
            continue
        symbol = _as_text(row.get("symbol"))
        last = _as_float(row.get("last"))
        change = _as_float(row.get("percent_change"))
        if not symbol or last is None:
            continue
        parts.append(f"{symbol} {last:.2f}" + (f" ({change:+.2f}%)" if change is not None else ""))
    return "live context: " + ", ".join(parts) if parts else ""


def _live_market_spots_are_source_aligned(
    source_as_of_date: dt.date,
    observation_session_date: dt.date,
    *,
    live_schwab: bool,
    chain_snapshot_dir: Optional[Path],
) -> bool:
    """Allow live price tape only when its prior-close basis matches the UW source day."""

    if chain_snapshot_dir is not None:
        # Snapshot callers deliberately supply their own dated chain context.
        return True
    return bool(live_schwab and source_as_of_date == observation_session_date)


def build_market_price_regime(
    raw_universe: pd.DataFrame,
    as_of: str | dt.date,
    *,
    live_spots: Optional[Mapping[str, float]] = None,
    live_source_meta: Optional[Mapping[str, Any]] = None,
    live_schwab_requested: bool = False,
    chain_snapshot_dir: Optional[Path] = None,
) -> dict[str, Any]:
    """Classify broad market tape from price moves, separate from option-flow regime."""

    day = parse_as_of(as_of).isoformat()
    live_spots = {str(k).upper(): float(v) for k, v in dict(live_spots or {}).items() if _as_float(v) is not None}
    meta = dict(live_source_meta or {})
    if raw_universe is None or raw_universe.empty:
        return {
            "status": "unavailable",
            "as_of": day,
            "source_mode": meta.get("source_mode", "uw_eod_only"),
            "reason": "raw universe empty",
            "tape_direction": "unavailable",
            "regime": "unknown",
            "readings": [],
        }
    raw_by_ticker = _frame_by_ticker(raw_universe)
    readings: list[dict[str, Any]] = []
    # Broad indices determine the market regime, but every loaded underlying needs
    # its own tape reading for candidate routing and auditability.
    reading_tickers = sorted(set(raw_by_ticker) | set(CORE_AUDIT_TICKERS))
    for ticker in reading_tickers:
        row = raw_by_ticker.get(ticker, {})
        live_spot = _as_float(live_spots.get(ticker))
        close = _as_float(row.get("close"))
        prev_close = _as_float(row.get("prev_close"))
        spot = live_spot if live_spot is not None and live_spot > 0 else close
        source = "schwab_live_or_snapshot" if live_spot is not None and live_spot > 0 else "uw_eod_close"
        move = (spot - prev_close) / prev_close if spot is not None and prev_close is not None and prev_close > 0 else None
        if row or spot is not None:
            readings.append(
                {
                    "ticker": ticker,
                    "source": source,
                    "spot": spot,
                    "close": close,
                    "prev_close": prev_close,
                    "move_pct": round(move, 6) if move is not None else None,
                    "underlying_quality_tier": row.get("underlying_quality_tier", ""),
                    "score": row.get("score", ""),
                }
            )
    index_moves = [
        _as_float(item.get("move_pct"))
        for item in readings
        if item.get("ticker") in CORE_INDEX_ETF_TICKERS and _as_float(item.get("move_pct")) is not None
    ]
    mega_moves = [
        _as_float(item.get("move_pct"))
        for item in readings
        if item.get("ticker") in CORE_MEGA_CAP_TICKERS and _as_float(item.get("move_pct")) is not None
    ]
    avg_index_move = sum(index_moves) / len(index_moves) if index_moves else None
    median_index_move = float(pd.Series(index_moves).median()) if index_moves else None
    index_positive_breadth = (
        sum(1 for move in index_moves if move >= MACRO_TAPE_DIRECTIONAL_MOVE_PCT) / len(index_moves)
        if index_moves
        else None
    )
    index_negative_breadth = (
        sum(1 for move in index_moves if move <= -MACRO_TAPE_DIRECTIONAL_MOVE_PCT) / len(index_moves)
        if index_moves
        else None
    )
    avg_mega_move = sum(mega_moves) / len(mega_moves) if mega_moves else None
    mega_negative_breadth = (
        sum(1 for move in mega_moves if move <= -MACRO_TAPE_DIRECTIONAL_MOVE_PCT) / len(mega_moves)
        if mega_moves
        else None
    )
    mega_positive_breadth = (
        sum(1 for move in mega_moves if move >= MACRO_TAPE_DIRECTIONAL_MOVE_PCT) / len(mega_moves)
        if mega_moves
        else None
    )
    mega_breadth_conflict_min = 5
    mega_breadth_conflict_pct = 0.60
    if avg_index_move is None:
        tape_direction = "unavailable"
        regime = "unknown"
        sizing = "normal"
        note = "price tape unavailable; using option-flow regime only"
    elif avg_index_move <= -MACRO_TAPE_DIRECTIONAL_MOVE_PCT:
        tape_direction = "bearish"
        regime = "risk_off"
        sizing = "reduced"
        note = "index price tape is bearish"
    elif avg_index_move >= MACRO_TAPE_DIRECTIONAL_MOVE_PCT:
        tape_direction = "bullish"
        regime = "risk_on"
        sizing = "normal"
        note = "index price tape is bullish"
    elif (
        median_index_move is not None
        and median_index_move >= MACRO_TAPE_DIRECTIONAL_MOVE_PCT
        and index_positive_breadth is not None
        and index_positive_breadth >= 0.75
    ):
        tape_direction = "bullish"
        regime = "risk_on"
        sizing = "normal"
        note = "index price tape is bullish by median move and 75% directional breadth"
    elif (
        median_index_move is not None
        and median_index_move <= -MACRO_TAPE_DIRECTIONAL_MOVE_PCT
        and index_negative_breadth is not None
        and index_negative_breadth >= 0.75
    ):
        tape_direction = "bearish"
        regime = "risk_off"
        sizing = "reduced"
        note = "index price tape is bearish by median move and 75% directional breadth"
    else:
        tape_direction = "mixed"
        regime = "mixed"
        sizing = "normal"
        note = "index price tape is mixed"
    if (
        tape_direction == "bullish"
        and len(mega_moves) >= mega_breadth_conflict_min
        and (
            (mega_negative_breadth is not None and mega_negative_breadth >= mega_breadth_conflict_pct)
            or (avg_mega_move is not None and avg_mega_move <= -MACRO_TAPE_DIRECTIONAL_MOVE_PCT)
        )
    ):
        tape_direction = "mixed"
        regime = "mixed"
        sizing = "normal"
        note = "index price tape is bullish but mega-cap breadth is bearish"
    elif (
        tape_direction == "bearish"
        and len(mega_moves) >= mega_breadth_conflict_min
        and (
            (mega_positive_breadth is not None and mega_positive_breadth >= mega_breadth_conflict_pct)
            or (avg_mega_move is not None and avg_mega_move >= MACRO_TAPE_DIRECTIONAL_MOVE_PCT)
        )
    ):
        tape_direction = "mixed"
        regime = "mixed"
        sizing = "normal"
        note = "index price tape is bearish but mega-cap breadth is bullish"
    source_mode = meta.get("source_mode") or ("schwab_live" if live_spots else "uw_eod_only")
    if live_schwab_requested and not live_spots:
        source_mode = "uw_eod_only"
        note = _append_reason(note, "live Schwab market-price snapshot unavailable; using dated UW EOD tape")
    return {
        "status": "ok" if readings else "unavailable",
        "as_of": day,
        "source_mode": source_mode,
        "source": meta.get("source", "UW stock screener close/prev_close"),
        "chain_snapshot_dir": str(Path(chain_snapshot_dir).expanduser().resolve()) if chain_snapshot_dir else "",
        "tape_direction": tape_direction,
        "regime": regime,
        "sizing_stance": sizing,
        "avg_index_move_pct": round(avg_index_move, 6) if avg_index_move is not None else None,
        "median_index_move_pct": round(median_index_move, 6) if median_index_move is not None else None,
        "index_positive_breadth": round(index_positive_breadth, 6) if index_positive_breadth is not None else None,
        "index_negative_breadth": round(index_negative_breadth, 6) if index_negative_breadth is not None else None,
        "avg_mega_cap_move_pct": round(avg_mega_move, 6) if avg_mega_move is not None else None,
        "mega_cap_negative_breadth": round(mega_negative_breadth, 6) if mega_negative_breadth is not None else None,
        "mega_cap_positive_breadth": round(mega_positive_breadth, 6) if mega_positive_breadth is not None else None,
        "directional_threshold_pct": MACRO_TAPE_DIRECTIONAL_MOVE_PCT,
        "note": note,
        "readings": readings,
        "readings_by_ticker": {str(item["ticker"]): item for item in readings},
    }


def annotate_macro_tape_candidates(raw_universe: pd.DataFrame, market_price_regime: Mapping[str, Any]) -> pd.DataFrame:
    """Promote neutral-flow core names into an auditable macro-tape candidate lane."""

    if raw_universe is None or raw_universe.empty:
        return raw_universe.copy() if raw_universe is not None else pd.DataFrame()
    out = raw_universe.copy()
    readings = market_price_regime.get("readings_by_ticker", {}) if isinstance(market_price_regime, Mapping) else {}
    direction = _as_text(market_price_regime.get("tape_direction") if isinstance(market_price_regime, Mapping) else "").lower()
    out["core_universe_member"] = out["ticker"].astype(str).str.upper().map(_is_core_audit_ticker)
    out["price_move_pct"] = out["ticker"].astype(str).str.upper().map(
        lambda ticker: _as_float((readings.get(ticker, {}) or {}).get("move_pct"))
    )
    out["price_tape_source"] = out["ticker"].astype(str).str.upper().map(
        lambda ticker: _as_text((readings.get(ticker, {}) or {}).get("source"))
    )
    out["macro_tape_direction"] = ""
    out["macro_tape_candidate"] = False
    out["candidate_source"] = out.get("candidate_source", pd.Series("flow_oi", index=out.index)).replace("", "flow_oi")
    out["macro_tape_reason"] = ""
    if direction not in {"bearish", "bullish"}:
        return out
    threshold = _as_float(
        market_price_regime.get("directional_threshold_pct") if isinstance(market_price_regime, Mapping) else None
    )
    threshold = threshold if threshold is not None and threshold > 0 else MACRO_TAPE_DIRECTIONAL_MOVE_PCT
    score = pd.to_numeric(out.get("score", pd.Series(0.0, index=out.index)), errors="coerce").fillna(0.0)
    tier = out.get("underlying_quality_tier", pd.Series("", index=out.index)).astype(str).str.lower()
    bias = out.get("bias", pd.Series("", index=out.index)).astype(str).str.lower()
    ticker = out.get("ticker", pd.Series("", index=out.index)).astype(str).str.upper()
    marketcap = pd.to_numeric(out.get("marketcap", pd.Series(0.0, index=out.index)), errors="coerce").fillna(0.0)
    core_or_mega = ticker.map(_is_core_audit_ticker) | marketcap.ge(MIN_CORE_MARKET_CAP)
    evaluated = tier.eq("core") & core_or_mega
    ticker_move = pd.to_numeric(out["price_move_pct"], errors="coerce")
    ticker_direction = pd.Series("", index=out.index, dtype=object)
    ticker_direction = ticker_direction.mask(ticker_move.le(-threshold), "bearish")
    ticker_direction = ticker_direction.mask(ticker_move.ge(threshold), "bullish")
    effective_direction = ticker_direction.where(ticker_direction.ne(""), direction)
    out.loc[evaluated, "macro_tape_direction"] = effective_direction.loc[evaluated]
    opposite_ticker_tape = evaluated & ticker_direction.ne("") & ticker_direction.ne(direction)
    out.loc[evaluated & ~opposite_ticker_tape, "macro_tape_reason"] = (
        "core/mega-cap reviewed against " + direction + " price tape"
    )
    out.loc[opposite_ticker_tape, "macro_tape_reason"] = (
        "core/mega-cap reviewed against "
        + direction
        + " index tape; ticker move is "
        + ticker_direction.loc[opposite_ticker_tape]
    )
    promote = bias.eq("neutral") & tier.eq("core") & core_or_mega & score.ge(MACRO_TAPE_CANDIDATE_SCORE_FLOOR)
    if not promote.any():
        return out
    out.loc[promote, "macro_tape_direction"] = effective_direction.loc[promote]
    out.loc[promote, "macro_tape_candidate"] = True
    out.loc[promote, "candidate_source"] = "macro_tape_candidate"
    out.loc[promote, "quality_status"] = "qualified"
    out.loc[promote, "bias"] = effective_direction.loc[promote]
    out.loc[promote, "macro_tape_reason"] = (
        "neutral UW flow rescued by "
        + effective_direction.loc[promote]
        + " price tape; original flow label preserved in flow_bias_label"
    )
    promoted_opposite = promote & opposite_ticker_tape
    out.loc[promoted_opposite, "macro_tape_reason"] = (
        "neutral UW flow rescued by "
        + effective_direction.loc[promoted_opposite]
        + " ticker tape despite "
        + direction
        + " index tape; original flow label preserved in flow_bias_label"
    )
    out.loc[promote, "flow_reason"] = out.loc[promote].apply(
        lambda row: _append_reason(row.get("flow_reason"), row.get("macro_tape_reason")),
        axis=1,
    )
    return out


def _is_core_audit_ticker(ticker: Any) -> bool:
    return _as_text(ticker).upper() in set(CORE_AUDIT_TICKERS)


def _uw_source_earnings_dates(frame: pd.DataFrame, column: str) -> pd.DataFrame:
    """Return the per-ticker modal UW earnings date carried by one dated source."""

    if frame.empty or "next_earnings_dt" not in frame.columns or "ticker" not in frame.columns:
        return pd.DataFrame(columns=["ticker", column])
    dated = frame[["ticker", "next_earnings_dt"]].dropna()
    if dated.empty:
        return pd.DataFrame(columns=["ticker", column])
    modal = (
        dated.groupby("ticker")["next_earnings_dt"]
        .agg(lambda values: values.mode().iloc[0] if not values.mode().empty else None)
        .reset_index()
        .rename(columns={"next_earnings_dt": column})
    )
    return modal


def _uw_earnings_corroboration(row: Mapping[str, Any]) -> tuple[Optional[dt.date], int]:
    """Return the agreed UW earnings date and how many dated files report it."""

    present = [
        value
        for value in (
            _row_date(row.get(column))
            for column in ("next_earnings_dt", "hot_next_earnings_dt", "oi_next_earnings_dt")
        )
        if value is not None
    ]
    if not present:
        return None, 0
    consensus = max(set(present), key=present.count)
    return consensus, present.count(consensus)


def aggregate_hot_chains(hot: pd.DataFrame) -> pd.DataFrame:
    """Aggregate option-chain activity by ticker."""

    if hot.empty:
        return pd.DataFrame(columns=["ticker"])
    df = hot.copy()
    volume = pd.to_numeric(df.get("volume", 0), errors="coerce").fillna(0)
    premium = pd.to_numeric(df.get("premium", 0), errors="coerce").fillna(0)
    ask_ratio = pd.to_numeric(df.get("ask_side_volume", 0), errors="coerce").fillna(0) / volume.where(volume > 0)
    bid_ratio = pd.to_numeric(df.get("bid_side_volume", 0), errors="coerce").fillna(0) / volume.where(volume > 0)
    is_call = df.get("right", "").astype(str).str.upper().eq("C")
    is_put = df.get("right", "").astype(str).str.upper().eq("P")
    df["hot_call_premium"] = premium.where(is_call, 0.0)
    df["hot_put_premium"] = premium.where(is_put, 0.0)
    df["hot_bull_premium"] = premium.where(is_call, 0.0).mul(ask_ratio.fillna(0)) + premium.where(is_put, 0.0).mul(
        bid_ratio.fillna(0)
    )
    df["hot_bear_premium"] = premium.where(is_put, 0.0).mul(ask_ratio.fillna(0)) + premium.where(is_call, 0.0).mul(
        bid_ratio.fillna(0)
    )
    df["hot_call_volume"] = volume.where(is_call, 0.0)
    df["hot_put_volume"] = volume.where(is_put, 0.0)
    top = df.sort_values("premium", ascending=False).drop_duplicates("ticker")[
        ["ticker", "option_symbol", "right", "expiry_dt", "strike", "bid", "ask", "dte"]
    ].rename(
        columns={
            "option_symbol": "hot_top_option",
            "right": "hot_top_right",
            "expiry_dt": "hot_top_expiry",
            "strike": "hot_top_strike",
            "bid": "hot_top_bid",
            "ask": "hot_top_ask",
            "dte": "hot_top_dte",
        }
    )
    agg = df.groupby("ticker", as_index=False).agg(
        hot_total_premium=("premium", "sum"),
        hot_volume=("volume", "sum"),
        hot_open_interest=("open_interest", "sum"),
        hot_call_premium=("hot_call_premium", "sum"),
        hot_put_premium=("hot_put_premium", "sum"),
        hot_bull_premium=("hot_bull_premium", "sum"),
        hot_bear_premium=("hot_bear_premium", "sum"),
        hot_call_volume=("hot_call_volume", "sum"),
        hot_put_volume=("hot_put_volume", "sum"),
        hot_avg_dte=("dte", "mean"),
    )
    denom = agg["hot_total_premium"].where(agg["hot_total_premium"].abs() > 0)
    agg["hot_flow_bias"] = (agg["hot_bull_premium"] - agg["hot_bear_premium"]) / denom
    return (
        agg.merge(top, on="ticker", how="left")
        .merge(_uw_source_earnings_dates(df, "hot_next_earnings_dt"), on="ticker", how="left")
    )


def aggregate_chain_oi(chain_oi: pd.DataFrame) -> pd.DataFrame:
    """Aggregate chain OI changes and infer opening-flow direction by ticker."""

    if chain_oi.empty:
        return pd.DataFrame(columns=["ticker"])
    df = chain_oi.copy()
    df["ticker"] = df.apply(_clean_chain_oi_ticker, axis=1)
    df = df[df["ticker"].astype(bool)].copy()
    for column in ("oi_diff_plain", "volume", "curr_oi", "dte"):
        df[column] = pd.to_numeric(
            df.get(column, pd.Series(0.0, index=df.index)),
            errors="coerce",
        ).fillna(0.0)
    df["positive_oi_change"] = df["oi_diff_plain"].clip(lower=0)
    aggregate = df.groupby("ticker", as_index=False).agg(
        oi_diff_plain=("oi_diff_plain", "sum"),
        positive_oi_change=("positive_oi_change", "sum"),
        chain_oi_volume=("volume", "sum"),
        curr_oi=("curr_oi", "sum"),
        oi_avg_dte=("dte", "mean"),
    )
    aggregate = aggregate.merge(
        _uw_source_earnings_dates(df, "oi_next_earnings_dt"), on="ticker", how="left"
    )

    opening = df[df["positive_oi_change"] > 0].copy()
    if opening.empty or "option_symbol" not in opening.columns:
        aggregate["oi_bullish_premium"] = 0.0
        aggregate["oi_bearish_premium"] = 0.0
        aggregate["oi_directional_premium"] = 0.0
        aggregate["oi_directional_bias"] = math.nan
        aggregate["positive_call_oi_change"] = 0.0
        aggregate["positive_put_oi_change"] = 0.0
        return aggregate

    parsed = opening["option_symbol"].map(_parse_occ_symbol)
    opening["right"] = parsed.map(lambda value: _as_text(value.get("right")) if value else "")
    for column in (
        "prev_ask_volume",
        "prev_bid_volume",
        "prev_total_premium",
        "avg_price",
    ):
        opening[column] = pd.to_numeric(
            opening.get(column, pd.Series(0.0, index=opening.index)),
            errors="coerce",
        ).fillna(0.0)
    opening["oi_effective_premium"] = opening["prev_total_premium"]
    missing_premium = opening["oi_effective_premium"] <= 0
    opening.loc[missing_premium, "oi_effective_premium"] = (
        opening.loc[missing_premium, "avg_price"].abs()
        * opening.loc[missing_premium, "volume"].clip(lower=1.0)
        * 100.0
    )
    side_volume = (opening["prev_ask_volume"] + opening["prev_bid_volume"]).replace(0, math.nan)
    opening["oi_ask_premium"] = (
        opening["oi_effective_premium"] * opening["prev_ask_volume"] / side_volume
    ).replace([math.inf, -math.inf], math.nan).fillna(0.0)
    opening["oi_bid_premium"] = (
        opening["oi_effective_premium"] * opening["prev_bid_volume"] / side_volume
    ).replace([math.inf, -math.inf], math.nan).fillna(0.0)
    is_call = opening["right"].eq("C")
    is_put = opening["right"].eq("P")
    opening["oi_bullish_premium"] = 0.0
    opening["oi_bearish_premium"] = 0.0
    opening.loc[is_call, "oi_bullish_premium"] = opening.loc[is_call, "oi_ask_premium"]
    opening.loc[is_put, "oi_bullish_premium"] = opening.loc[is_put, "oi_bid_premium"]
    opening.loc[is_put, "oi_bearish_premium"] = opening.loc[is_put, "oi_ask_premium"]
    opening.loc[is_call, "oi_bearish_premium"] = opening.loc[is_call, "oi_bid_premium"]
    opening["positive_call_oi_change"] = opening["positive_oi_change"].where(is_call, 0.0)
    opening["positive_put_oi_change"] = opening["positive_oi_change"].where(is_put, 0.0)
    directional = opening.groupby("ticker", as_index=False).agg(
        oi_bullish_premium=("oi_bullish_premium", "sum"),
        oi_bearish_premium=("oi_bearish_premium", "sum"),
        positive_call_oi_change=("positive_call_oi_change", "sum"),
        positive_put_oi_change=("positive_put_oi_change", "sum"),
    )
    directional["oi_directional_premium"] = (
        directional["oi_bullish_premium"] + directional["oi_bearish_premium"]
    )
    denominator = directional["oi_directional_premium"].where(
        directional["oi_directional_premium"] > 0
    )
    directional["oi_directional_bias"] = (
        directional["oi_bullish_premium"] - directional["oi_bearish_premium"]
    ) / denominator
    out = aggregate.merge(directional, on="ticker", how="left")
    for column in (
        "oi_bullish_premium",
        "oi_bearish_premium",
        "oi_directional_premium",
        "positive_call_oi_change",
        "positive_put_oi_change",
    ):
        out[column] = pd.to_numeric(out[column], errors="coerce").fillna(0.0)
    return out


def _clean_chain_oi_ticker(row: Mapping[str, Any]) -> str:
    ticker = row.get("ticker")
    if isinstance(ticker, str) and ticker.strip():
        return ticker.strip().upper()
    underlying = row.get("underlying_symbol")
    if isinstance(underlying, str) and underlying.strip():
        return underlying.strip().upper()
    return ""


def generate_candidates(
    raw_universe: pd.DataFrame,
    *,
    limit: Optional[int] = None,
    focus_tickers: Sequence[str] = CORE_AUDIT_TICKERS,
    market_price_regime: Optional[Mapping[str, Any]] = None,
) -> pd.DataFrame:
    """Create the ranked candidate generation table."""

    if raw_universe.empty:
        return raw_universe.copy()
    _ = market_price_regime
    macro_mask = raw_universe.get("macro_tape_candidate", pd.Series(False, index=raw_universe.index)).map(_truthy)
    macro_direction = raw_universe.get("macro_tape_direction", pd.Series("", index=raw_universe.index)).astype(str).str.lower()
    keep = raw_universe[raw_universe["bias"].ne("neutral") | macro_mask].copy()
    if "underlying_quality_rank" not in keep.columns:
        keep["underlying_quality_rank"] = keep.get("underlying_quality_tier", pd.Series("", index=keep.index)).map(
            _underlying_quality_sort_rank
        )
    keep = keep.sort_values(["underlying_quality_rank", "score", "signal_premium"], ascending=[True, False, False])
    if limit is not None:
        keep = keep.head(int(limit))
    if focus_tickers:
        focus_set = {str(ticker).strip().upper() for ticker in focus_tickers if str(ticker).strip()}
        ticker_series = raw_universe["ticker"].astype(str).str.upper()
        tier_series = raw_universe.get("underlying_quality_tier", pd.Series("", index=raw_universe.index)).astype(str).str.lower()
        focus = raw_universe[
            ticker_series.isin(focus_set)
            & tier_series.eq("core")
            & (
                raw_universe["bias"].ne("neutral")
                | macro_mask
                | macro_direction.isin(["bearish", "bullish"])
                | raw_universe["quality_status"].isin(["qualified", "watch"])
            )
        ].copy()
        if not focus.empty:
            core_review = (
                focus.get("bias", pd.Series("", index=focus.index)).astype(str).str.lower().eq("neutral")
                & ~focus.get("macro_tape_candidate", pd.Series(False, index=focus.index)).map(_truthy)
                & ~focus.get("macro_tape_direction", pd.Series("", index=focus.index)).astype(str).str.lower().isin(["bearish", "bullish"])
            )
            focus.loc[core_review, "candidate_source"] = "core_audit_review"
            focus.loc[core_review, "macro_tape_reason"] = "core watchlist review; neutral flow does not create a directional trade"
            keep = pd.concat([keep, focus], ignore_index=True).drop_duplicates("ticker", keep="first")
            if "underlying_quality_rank" not in keep.columns:
                keep["underlying_quality_rank"] = keep.get("underlying_quality_tier", pd.Series("", index=keep.index)).map(
                    _underlying_quality_sort_rank
                )
            keep = keep.sort_values(["underlying_quality_rank", "score", "signal_premium"], ascending=[True, False, False])
    keep["candidate_rank"] = range(1, len(keep) + 1)
    keep["recommendation_status"] = keep["quality_status"].map(lambda v: "REVIEW" if v == "qualified" else "AVOID")
    keep["status_reason"] = keep.apply(
        lambda row: _candidate_status_reason(row),
        axis=1,
    )
    return keep.reset_index(drop=True)


def _candidate_status_reason(row: Mapping[str, Any]) -> str:
    if _as_text(row.get("candidate_source")) == "core_audit_review":
        return "core watchlist reviewed; neutral/no-edge flow stays watch-only unless directional flow or macro tape improves"
    if row.get("quality_status") != "qualified":
        return _as_text(row.get("flow_reason"))
    if _truthy(row.get("macro_tape_candidate")):
        return _append_reason(
            "qualified macro-tape research candidate; requires fresh Schwab quote and subagent review",
            row.get("macro_tape_reason"),
        )
    return "qualified EOD research candidate; requires fresh Schwab quote"


def build_market_regime(raw_universe: pd.DataFrame, market_price_regime: Optional[Mapping[str, Any]] = None) -> dict[str, Any]:
    """Build a simple market-regime review from index rows in the raw universe."""

    if raw_universe.empty:
        return {"status": "unavailable", "reason": "raw universe empty", "sizing_stance": "review"}
    index_rows = raw_universe[raw_universe["ticker"].isin(["SPY", "QQQ", "IWM", "DIA"])] if "ticker" in raw_universe.columns else pd.DataFrame()
    readings = []
    for _, row in index_rows.iterrows():
        readings.append(
            {
                "ticker": row.get("ticker", ""),
                "bias": row.get("bias", ""),
                "combined_flow_bias": _as_float(row.get("combined_flow_bias")),
                "signal_premium": _as_float(row.get("signal_premium")) or 0.0,
                "score": _as_float(row.get("score")) or 0.0,
            }
        )
    if not readings:
        return {"status": "unavailable", "reason": "SPY/QQQ/IWM rows not found", "sizing_stance": "normal"}

    avg_bias = sum(float(item["combined_flow_bias"] or 0.0) for item in readings) / len(readings)
    price_regime = dict(market_price_regime or {})
    price_direction = _as_text(price_regime.get("tape_direction")).lower()
    if price_direction == "bullish":
        regime = "risk_on"
        sizing = "normal"
        note = "index price tape leans bullish"
    elif price_direction == "bearish":
        regime = "risk_off"
        sizing = "reduced"
        note = "index price tape leans bearish; prefer smaller size and faster validation"
    elif avg_bias >= 0.08:
        regime = "risk_on"
        sizing = "normal"
        note = "index option flow leans bullish"
    elif avg_bias <= -0.08:
        regime = "risk_off"
        sizing = "reduced"
        note = "index option flow leans bearish; prefer smaller size and faster validation"
    else:
        regime = "mixed"
        sizing = "normal"
        note = "index option flow is mixed"
    return {
        "status": "ok",
        "regime": regime,
        "sizing_stance": sizing,
        "avg_index_flow_bias": round(avg_bias, 4),
        "price_tape_direction": price_direction or "unavailable",
        "avg_index_price_move_pct": price_regime.get("avg_index_move_pct"),
        "note": note,
        "readings": readings,
    }


def build_catalyst_evidence(date_dir: Path, as_of: str | dt.date, candidates: pd.DataFrame) -> pd.DataFrame:
    """Collect auditable earnings and local news evidence for catalyst reviews."""

    columns = [
        "ticker",
        "evidence_type",
        "evidence_status",
        "source",
        "headline",
        "sentiment",
        "red_flag_terms",
        "support_terms",
        "objective_blocker",
        "days_to_earnings",
        "note",
    ]
    if candidates.empty:
        return pd.DataFrame(columns=columns)

    day = parse_as_of(as_of)
    rows: list[dict[str, Any]] = []
    for _, candidate in candidates.iterrows():
        ticker = str(candidate.get("ticker") or "").strip().upper()
        if not ticker:
            continue
        found = False
        earnings = _row_date(candidate.get("next_earnings_dt"))
        days_to_earnings = (earnings - day).days if earnings else None
        if days_to_earnings is not None:
            found = True
            if 0 <= days_to_earnings <= 7:
                status = "event_risk"
            elif 8 <= days_to_earnings <= 21:
                status = "watch_event"
            else:
                status = "clear"
            rows.append(
                {
                    "ticker": ticker,
                    "evidence_type": "earnings",
                    "evidence_status": status,
                    "source": "stock_screener.next_earnings_dt",
                    "headline": "",
                    "sentiment": "event" if status != "clear" else "neutral",
                    "red_flag_terms": "",
                    "support_terms": "",
                    "objective_blocker": False,
                    "days_to_earnings": days_to_earnings,
                    "note": f"earnings in {days_to_earnings} days",
                }
            )

        news_paths = _local_news_paths(date_dir, ticker, day)
        for news_path in news_paths:
            found = True
            evidence = _news_evidence_row(ticker, news_path)
            evidence["days_to_earnings"] = days_to_earnings if days_to_earnings is not None else ""
            rows.append(evidence)

        if not found:
            rows.append(
                {
                    "ticker": ticker,
                    "evidence_type": "summary",
                    "evidence_status": "clear",
                    "source": "",
                    "headline": "",
                    "sentiment": "neutral",
                    "red_flag_terms": "",
                    "support_terms": "",
                    "objective_blocker": False,
                    "days_to_earnings": "",
                    "note": "no local catalyst file or near-term earnings flag",
                }
            )
    return pd.DataFrame(rows, columns=columns)


def build_catalyst_reviews(
    date_dir: Path,
    as_of: str | dt.date,
    candidates: pd.DataFrame,
    *,
    catalyst_evidence: Optional[pd.DataFrame] = None,
) -> pd.DataFrame:
    """Review local earnings/news catalyst context for generated candidates."""

    if candidates.empty:
        return pd.DataFrame(
            columns=[
                "ticker",
                "catalyst_status",
                "catalyst_note",
                "news_source",
                "days_to_earnings",
                "news_sentiment",
                "red_flag_terms",
                "support_terms",
                "objective_blocker",
            ]
        )
    day = parse_as_of(as_of)
    evidence = catalyst_evidence if catalyst_evidence is not None else build_catalyst_evidence(date_dir, day, candidates)
    evidence_by_ticker = {
        ticker: group.copy()
        for ticker, group in evidence.groupby(evidence["ticker"].astype(str).str.upper())
    } if not evidence.empty and "ticker" in evidence.columns else {}
    rows: list[dict[str, Any]] = []
    for _, candidate in candidates.iterrows():
        ticker = str(candidate.get("ticker") or "").strip().upper()
        ticker_evidence = evidence_by_ticker.get(ticker, pd.DataFrame())
        status, notes, source, days_to_earnings, sentiment, red_terms, support_terms, objective = _summarize_catalyst_evidence(
            ticker_evidence
        )
        if not notes:
            notes.append("no local catalyst file or near-term earnings flag")
        rows.append(
            {
                "ticker": ticker,
                "catalyst_status": status,
                "catalyst_note": "; ".join(notes),
                "news_source": source,
                "days_to_earnings": days_to_earnings if days_to_earnings is not None else "",
                "news_sentiment": sentiment,
                "red_flag_terms": red_terms,
                "support_terms": support_terms,
                "objective_blocker": objective,
            }
        )
    return pd.DataFrame(rows)


def apply_catalyst_reviews(priced: pd.DataFrame, catalyst_reviews: pd.DataFrame) -> pd.DataFrame:
    """Attach catalyst review fields without suppressing otherwise visible rows."""

    if priced.empty or catalyst_reviews.empty:
        return priced.copy()
    catalyst_reviews = _dedupe_ticker_rows(catalyst_reviews)
    out = priced.merge(
        catalyst_reviews[
            [
                "ticker",
                "catalyst_status",
                "catalyst_note",
                "days_to_earnings",
                "news_sentiment",
                "red_flag_terms",
                "support_terms",
                "objective_blocker",
            ]
        ],
        on="ticker",
        how="left",
    )
    event_mask = out["catalyst_status"].astype(str).isin(["event_risk", "news_red_flag"])
    if event_mask.any():
        out.loc[event_mask, "recommendation_status"] = RecommendationStatus.REVIEW.value
        out.loc[event_mask, "status_reason"] = out.loc[event_mask].apply(
            lambda row: _append_reason(row.get("status_reason"), f"catalyst review: {row.get('catalyst_note')}"),
            axis=1,
        )
    objective_mask = (
        out["objective_blocker"].map(_truthy) if "objective_blocker" in out.columns else pd.Series(False, index=out.index)
    )
    if objective_mask.any():
        out.loc[objective_mask, "recommendation_status"] = RecommendationStatus.AVOID.value
        out.loc[objective_mask, "hard_rejects"] = out.loc[objective_mask].apply(
            lambda row: _append_reason(row.get("hard_rejects"), "catalyst_objective_blocker"),
            axis=1,
        )
        out.loc[objective_mask, "status_reason"] = out.loc[objective_mask].apply(
            lambda row: _append_reason(row.get("status_reason"), f"catalyst objective blocker: {row.get('catalyst_note')}"),
            axis=1,
        )
    return out


def build_research_tasks(
    candidates: pd.DataFrame,
    market_regime: Mapping[str, Any],
    catalyst_reviews: pd.DataFrame,
    *,
    top_trades: int,
    lesson_pack: Optional[Any] = None,
) -> dict[str, Any]:
    """Create explicit research tasks for external/subagent reviewers."""

    # Kept for API compatibility; research dispatch must cover the full candidate set.
    _ = top_trades
    lesson_digest = str(getattr(lesson_pack, "digest", ""))
    lesson_context = str(getattr(lesson_pack, "markdown", "") or "")
    lesson_ids = [
        str(lesson.get("id") or "")
        for lesson in getattr(lesson_pack, "lessons", [])
        if str(lesson.get("status") or "") == "active"
    ]
    catalyst_by_ticker = _frame_by_ticker(catalyst_reviews)
    tasks: list[dict[str, Any]] = []
    for _, row in candidates.iterrows():
        ticker = str(row.get("ticker") or "").strip().upper()
        catalyst = catalyst_by_ticker.get(ticker, {})
        candidate_id = f"{ticker}:{row.get('bias', '')}:{int(_as_float(row.get('score')) or 0)}"
        tasks.append(
            {
                "candidate_id": candidate_id,
                "ticker": ticker,
                "bias": row.get("bias", ""),
                "flow_bias_label": row.get("flow_bias_label", row.get("bias", "")),
                "candidate_source": row.get("candidate_source", "flow_oi"),
                "macro_tape_candidate": bool(_truthy(row.get("macro_tape_candidate"))),
                "macro_tape_direction": row.get("macro_tape_direction", ""),
                "macro_tape_reason": row.get("macro_tape_reason", ""),
                "price_move_pct": row.get("price_move_pct", ""),
                "price_tape_source": row.get("price_tape_source", ""),
                "score": _as_float(row.get("score")) or 0.0,
                "flow_reason": row.get("flow_reason", ""),
                "market_regime": market_regime.get("regime", "unknown"),
                "catalyst_status": catalyst.get("catalyst_status", ""),
                "catalyst_note": catalyst.get("catalyst_note", ""),
                "lesson_pack_digest": lesson_digest,
                "must_apply_lesson_ids": lesson_ids,
                "reviewer_assignments": [
                    "catalyst_news",
                    "macro_regime",
                    "structure_builder",
                    "skeptic",
                    "portfolio_management",
                ],
                "research_questions": [
                    "Does current news/catalyst context support or invalidate the setup?",
                    "Are there earnings, regulatory, macro, analyst, or company-specific risks inside the mandatory planned holding horizon?",
                    "Is the proposed option structure aligned with the thesis and market regime?",
                    "If this is a good setup but portfolio exposure is crowded, call out the risk without hiding it.",
                ],
                "expected_review_schema": {
                    "candidate_id": candidate_id,
                    "ticker": ticker,
                    "agent": "catalyst_news|macro_regime|structure_builder|skeptic|portfolio_management",
                    "agent_type": "subagent",
                    "review_stage": "subagent_review",
                    "verdict": "supportive|caution|avoid",
                    "confidence": "low|medium|high",
                    "note": "short evidence-backed review",
                    "objective_blocker": False,
                    "portfolio_risk_only": False,
                    "evidence": "optional source or observation",
                },
            }
        )
    return {
        "schema_version": "options_agent.dispatch_tasks.v1",
        "dispatch_model": "codex_subagents",
        "review_output_path": "agentic_reviews.json",
        "lesson_pack_digest": lesson_digest,
        "lesson_context": lesson_context,
        "must_apply_lesson_ids": lesson_ids,
        "review_schema": {
            "candidate_id": "stable candidate id from research task",
            "ticker": "ticker",
            "agent": "catalyst_news|macro_regime|structure_builder|skeptic|portfolio_management",
            "agent_type": "subagent",
            "review_stage": "subagent_review",
            "verdict": "supportive|caution|avoid",
            "confidence": "low|medium|high",
            "note": "short evidence-backed review",
            "objective_blocker": False,
            "portfolio_risk_only": False,
            "evidence": "optional source or observation",
        },
        "instructions": (
            "External or subagent reviews may flag objective blockers, but portfolio risk must be annotated "
            "rather than used to hide an otherwise good trade."
        ),
        "tasks": tasks,
    }


def _unique_ordered_tickers(values: Iterable[Any]) -> list[str]:
    tickers: list[str] = []
    seen: set[str] = set()
    for value in values:
        ticker = _as_text(value).strip().upper()
        if not ticker or ticker in seen:
            continue
        seen.add(ticker)
        tickers.append(ticker)
    return tickers


def _required_review_tickers_for_dispatch(
    tasks: Sequence[Mapping[str, Any]],
    *,
    max_count: int = MAX_REQUIRED_SUBAGENT_REVIEW_TICKERS,
) -> list[str]:
    """Choose a bounded must-review ticker list for each subagent lane."""

    if max_count <= 0:
        return []
    by_ticker: dict[str, dict[str, Any]] = {}
    first_seen: dict[str, int] = {}
    focus_set = set(CORE_AUDIT_TICKERS) | set(ACTIONABLE_ETF_ALLOWLIST)
    for idx, task in enumerate(tasks):
        ticker = _as_text(task.get("ticker")).strip().upper()
        if not ticker:
            continue
        score = _as_float(task.get("score")) or 0.0
        candidate_source = _as_text(task.get("candidate_source"))
        macro_tape = bool(_truthy(task.get("macro_tape_candidate")))
        current = by_ticker.setdefault(
            ticker,
            {
                "score": score,
                "candidate_source": candidate_source,
                "macro_tape_candidate": macro_tape,
                "focus": ticker in focus_set,
            },
        )
        current["score"] = max(_as_float(current.get("score")) or 0.0, score)
        current["macro_tape_candidate"] = bool(current.get("macro_tape_candidate")) or macro_tape
        if not _as_text(current.get("candidate_source")) and candidate_source:
            current["candidate_source"] = candidate_source
        first_seen.setdefault(ticker, idx)

    def _sort_key(item: tuple[str, Mapping[str, Any]]) -> tuple[int, int, float, int, str]:
        ticker, meta = item
        focus_rank = 0 if bool(meta.get("focus")) else 1
        macro_rank = 0 if bool(meta.get("macro_tape_candidate")) else 1
        score = _as_float(meta.get("score")) or 0.0
        return (focus_rank, macro_rank, -score, first_seen.get(ticker, 999_999), ticker)

    ordered = [ticker for ticker, _ in sorted(by_ticker.items(), key=_sort_key)]
    return ordered[:max_count]


def build_agent_dispatch_plan(
    research_tasks: Mapping[str, Any],
    as_of: str | dt.date,
    paths: Mapping[str, Path],
    lesson_pack: Optional[Any] = None,
) -> dict[str, Any]:
    """Create the Codex subagent dispatch contract for the agentic second pass."""

    day = parse_as_of(as_of).isoformat()
    tasks = [task for task in research_tasks.get("tasks", []) if isinstance(task, Mapping)]
    tickers = _unique_ordered_tickers(task.get("ticker") for task in tasks)
    required_review_tickers = _required_review_tickers_for_dispatch(tasks)
    active_lessons = [
        lesson
        for lesson in getattr(lesson_pack, "lessons", [])
        if isinstance(lesson, Mapping) and str(lesson.get("status") or "") == "active"
    ]
    lesson_digest = str(getattr(lesson_pack, "digest", ""))
    lesson_context = str(getattr(lesson_pack, "markdown", "") or "")
    lesson_ids = [str(lesson.get("id") or "") for lesson in active_lessons]
    common_context = {
        "as_of": day,
        "portfolio_policy": "Portfolio risk is annotate-only. Do not hide or suppress an otherwise good setup for portfolio risk.",
        "lesson_pack_version": str(getattr(lesson_pack, "version", "none")),
        "lesson_pack_digest": lesson_digest,
        "lesson_context": lesson_context,
        "must_apply_lesson_ids": lesson_ids,
        "required_review_tickers": required_review_tickers,
        "required_review_ticker_count": len(required_review_tickers),
        "candidate_universe_ticker_count": len(tickers),
        "required_review_policy": (
            "Each subagent lane must return at least one review for every required_review_tickers item before "
            "adding optional broader-universe reviews."
        ),
        "contract_review_policy": CONTRACT_AGENT_REVIEW_POLICY,
        "review_output_schema": {
            "ticker": "string ticker from the task list",
            "agent": "catalyst_news|macro_regime|structure_builder|skeptic|portfolio_management",
            "verdict": "supportive|caution|avoid",
            "confidence": "low|medium|high",
            "note": "concise evidence-backed reason",
            "objective_blocker": False,
            "blocker_type": "required concrete defect code when objective_blocker=true; otherwise empty",
            "evidence": "optional source or observation",
            "contract_key": "exact key from contract_review_tasks.json when reviewing a priced contract",
            "contract_specific": "true only when the exact legs/expiry/quote were reviewed",
            "strategy_route": "exact route for a contract-specific review",
            "expiry": "exact YYYY-MM-DD expiry for a contract-specific review",
            "trade_plan": "exact plain-language legs for a contract-specific review",
        },
        "input_artifacts": {
            "research_tasks": str(paths["research_tasks"]),
            "candidate_generation": str(paths["candidate_generation"]),
            "catalyst_evidence": str(paths["catalyst_evidence"]),
            "catalyst_reviews": str(paths["catalyst_reviews"]),
            "priced_candidates": str(paths["priced_candidates"]),
            "structure_attempts": str(paths["structure_attempts"]),
            "live_chain_validation": str(paths["live_chain_validation"]),
            "strategy_routing_audit": str(paths["strategy_routing_audit"]),
            "decision_board": str(paths["decision_board"]),
            "management_plan": str(paths["management_plan"]),
            "contract_review_tasks": str(paths["contract_review_tasks"]),
            "portfolio_context": str(paths["portfolio_context"]),
        },
    }
    lanes = [
        {
            "task_id": f"{day}:catalyst_news",
            "agent": "catalyst_news",
            "role": "Research current news, events, earnings, filings, analyst actions, and macro catalysts for the candidate list.",
            "focus": [
                "Confirm whether catalyst context supports, cautions, or objectively invalidates each setup.",
                "Use objective_blocker=true only for non-portfolio facts that should block entry.",
                "For every exact contract that lists catalyst_news in required_review_agents, verify earnings against an issuer-investor-relations or SEC source, copy the exact contract identity, and include the source URL in evidence.",
            ],
        },
        {
            "task_id": f"{day}:macro_regime",
            "agent": "macro_regime",
            "role": "Review market regime, sector exposure, macro tape, event calendar, and whether each setup direction fits the backdrop.",
            "focus": [
                "Call out regime or sector conflicts as caution unless they objectively invalidate the setup.",
                "Do not treat portfolio concentration as a setup-quality blocker.",
            ],
        },
        {
            "task_id": f"{day}:structure_builder",
            "agent": "structure_builder",
            "role": "Propose or validate executable option structures, payoff math, entry limits, expiries, and live-validation needs.",
            "focus": [
                "Prefer defined-risk structures with explicit max profit, max loss, target exit, and invalidation.",
                "Call out missing legs, wide markets, and absent live validation.",
                "Review every exact structure assigned in contract_review_tasks.json and copy its contract_key, "
                "strategy_route, expiry, and trade_plan into a contract_specific=true review. Set an objective "
                "blocker only when the exact quantitative contract-review policy fails. Return supportive when it passes.",
            ],
        },
        {
            "task_id": f"{day}:skeptic",
            "agent": "skeptic",
            "role": "Independently try to disprove each setup and identify objective blockers, stale tickers, deal risk, bad liquidity, or thesis breaks.",
            "focus": [
                "Use objective_blocker=true only for non-portfolio facts that should block entry.",
                "Do not mark portfolio crowding as an objective blocker.",
                "Review every exact structure assigned in contract_review_tasks.json and copy its contract_key, "
                "strategy_route, expiry, and trade_plan into a contract_specific=true review. Try to disprove the "
                "actual priced contract, including event crossings, probability, theta, quote quality, and evidence scope. "
                "Return supportive when no concrete defect remains; do not manufacture a generic caution.",
            ],
        },
        {
            "task_id": f"{day}:portfolio_management",
            "agent": "portfolio_management",
            "role": "Review portfolio fit, sizing, target exits, invalidation, and management plan quality.",
            "focus": [
                "Flag concentration, correlation, and size risks as portfolio-risk annotations.",
                "Portfolio-risk-only avoid/caution must keep objective_blocker=false.",
            ],
        },
    ]
    subagent_tasks = []
    for lane in lanes:
        subagent_tasks.append(
            {
                **lane,
                "tickers": required_review_tickers,
                "required_review_tickers": required_review_tickers,
                "candidate_universe_ticker_count": len(tickers),
                "input_task_count": len(tasks),
                "lesson_pack_digest": lesson_digest,
                "lesson_context": lesson_context,
                "must_apply_lesson_ids": lesson_ids,
                "prompt": _agent_dispatch_prompt(lane, common_context, tasks),
            }
        )
    return {
        "schema_version": "options_agent.agent_dispatch.v1",
        "as_of": day,
        "dispatch_status": "ready_for_codex_subagents",
        "dispatch_tool": "multi_agent_v1.spawn_agent",
        "expected_reviews_json": str(paths["agentic_reviews"]),
        "common_context": common_context,
        "subagent_tasks": subagent_tasks,
        "merge_instruction": (
            "Collect each subagent's JSON reviews into agentic_reviews.json as {'reviews': [...]} "
            "and rerun groko with --agent-reviews-json pointing at that file."
        ),
    }


def _load_existing_agent_dispatch_plan(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if _is_valid_agent_dispatch_plan(payload) else {}


def _agent_reviews_match_dispatch_contract(
    prior_plan: Mapping[str, Any],
    *,
    agent_reviews_json: Optional[Path],
    expected_reviews_json: Path,
) -> bool:
    if not agent_reviews_json or not _is_valid_agent_dispatch_plan(prior_plan):
        return False
    try:
        resolved_reviews = Path(agent_reviews_json).expanduser().resolve()
    except Exception:
        return False
    expected_paths = [_as_text(prior_plan.get("expected_reviews_json")), str(expected_reviews_json)]
    for value in expected_paths:
        if not value:
            continue
        try:
            if Path(value).expanduser().resolve() == resolved_reviews:
                return True
        except Exception:
            continue
    return False


def _load_dispatch_pricing_snapshot(
    paths: Mapping[str, Path],
    *,
    prior_plan: Mapping[str, Any],
    agent_reviews_json: Optional[Path],
    expected_reviews_json: Path,
    external_agent_reviews: pd.DataFrame,
    max_snapshot_age_seconds: Optional[float] = None,
) -> tuple[Optional[dict[str, Any]], str]:
    """Load the immutable pass-1 contract set reviewed by subagents."""

    if not _agent_reviews_match_dispatch_contract(
        prior_plan,
        agent_reviews_json=agent_reviews_json,
        expected_reviews_json=expected_reviews_json,
    ):
        return None, "not_requested"
    frame_keys = {
        "priced_candidates": "dispatch_priced_candidates",
        "strategy_routing_audit": "dispatch_strategy_routing_audit",
        "live_chain_validation": "dispatch_live_chain_validation",
        "structure_attempts": "dispatch_structure_attempts",
    }
    required_paths = [paths.get(path_key) for path_key in frame_keys.values()]
    task_path = paths.get("dispatch_contract_review_tasks")
    if task_path is None or any(path is None or not Path(path).exists() for path in required_paths):
        return None, "dispatch_snapshot_missing"
    if not Path(task_path).exists():
        return None, "dispatch_snapshot_missing"
    snapshot_paths = [Path(path) for path in required_paths if path is not None] + [Path(task_path)]
    if max_snapshot_age_seconds is not None:
        if float(max_snapshot_age_seconds) <= 0:
            return None, "live_pass2_reprice_required"
        try:
            oldest_mtime = min(path.stat().st_mtime for path in snapshot_paths)
        except OSError:
            return None, "dispatch_snapshot_missing"
        age_seconds = max(0.0, dt.datetime.now().timestamp() - oldest_mtime)
        if age_seconds > max(float(max_snapshot_age_seconds), 0.0):
            return None, "dispatch_snapshot_expired"
    try:
        snapshot = {
            name: pd.read_csv(paths[path_key], keep_default_na=False)
            for name, path_key in frame_keys.items()
        }
        task_payload = json.loads(Path(task_path).read_text(encoding="utf-8"))
    except (OSError, ValueError, pd.errors.EmptyDataError, json.JSONDecodeError):
        return None, "dispatch_snapshot_unreadable"
    if not isinstance(task_payload, Mapping):
        return None, "dispatch_contract_tasks_invalid"
    priced = snapshot["priced_candidates"]
    priced_contract_keys = {
        contract_review_key(row)
        for row in priced.to_dict("records")
        if contract_review_key(row)
    }
    tasked_contract_keys = {
        _as_text(contract.get("contract_key"))
        for contract in task_payload.get("contracts", [])
        if isinstance(contract, Mapping) and _as_text(contract.get("contract_key"))
    }
    if not tasked_contract_keys.issubset(priced_contract_keys):
        return None, "dispatch_contract_identity_drift"
    contract_tasks = [
        contract
        for contract in task_payload.get("contracts", [])
        if isinstance(contract, Mapping)
    ]
    review_records = (
        external_agent_reviews.to_dict("records")
        if external_agent_reviews is not None and not external_agent_reviews.empty
        else []
    )
    for contract in contract_tasks:
        contract_key = _as_text(contract.get("contract_key"))
        matching_agents = {
            _as_text(review.get("agent"))
            for review in review_records
            if _contract_review_matches_row(review, contract, row_contract_key=contract_key)
        }
        if any(agent not in matching_agents for agent in _required_contract_review_agents(contract)):
            return None, "dispatch_contract_review_identity_mismatch"
    snapshot["contract_review_tasks"] = dict(task_payload)
    return snapshot, "reused_fresh_exact_contract_snapshot"


def _is_valid_agent_dispatch_plan(payload: Any) -> bool:
    return bool(
        isinstance(payload, Mapping)
        and payload.get("schema_version") == "options_agent.agent_dispatch.v1"
        and isinstance(payload.get("subagent_tasks"), list)
        and payload.get("subagent_tasks")
    )


def _resolve_agent_dispatch_plan_for_reviews(
    current_plan: Mapping[str, Any],
    prior_plan: Mapping[str, Any],
    *,
    agent_reviews_json: Optional[Path],
    expected_reviews_json: Path,
) -> Mapping[str, Any]:
    """Keep the pass-1 review contract stable when pass 2 ingests reviews."""

    if _agent_reviews_match_dispatch_contract(
        prior_plan,
        agent_reviews_json=agent_reviews_json,
        expected_reviews_json=expected_reviews_json,
    ):
        return prior_plan
    return dict(current_plan)


def _required_review_tickers_from_dispatch_plan(plan: Mapping[str, Any]) -> list[str]:
    common = plan.get("common_context") if isinstance(plan, Mapping) else {}
    required = _unique_ordered_tickers(
        common.get("required_review_tickers") if isinstance(common, Mapping) else []
    )
    if required:
        return required
    tickers: list[str] = []
    for task in plan.get("subagent_tasks", []) if isinstance(plan, Mapping) else []:
        if not isinstance(task, Mapping):
            continue
        tickers.extend(_unique_ordered_tickers(task.get("required_review_tickers") or task.get("tickers") or []))
    return _unique_ordered_tickers(tickers)


def _dispatch_plan_drift_summary(
    review_contract_plan: Mapping[str, Any],
    current_plan: Mapping[str, Any],
) -> dict[str, Any]:
    contract = set(_required_review_tickers_from_dispatch_plan(review_contract_plan))
    current = set(_required_review_tickers_from_dispatch_plan(current_plan))
    added = sorted(current - contract)
    removed = sorted(contract - current)
    return {
        "contract_required_review_ticker_count": len(contract),
        "current_required_review_ticker_count": len(current),
        "added_required_ticker_count": len(added),
        "removed_required_ticker_count": len(removed),
        "added_required_ticker_examples": added[:20],
        "removed_required_ticker_examples": removed[:20],
        "status": "drift" if added or removed else "stable",
    }


def _load_contract_review_task_payload(path: Path) -> dict[str, Any]:
    try:
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return {}
    return dict(payload) if isinstance(payload, Mapping) else {}


def _contract_review_task_drift_summary(
    review_contract_tasks: Mapping[str, Any],
    current_contract_tasks: Mapping[str, Any],
) -> dict[str, Any]:
    def _contract_agents(payload: Mapping[str, Any]) -> dict[str, tuple[str, ...]]:
        result: dict[str, tuple[str, ...]] = {}
        for contract in payload.get("contracts", []) if isinstance(payload, Mapping) else []:
            if not isinstance(contract, Mapping):
                continue
            key = _as_text(contract.get("contract_key"))
            if not key:
                continue
            explicit_agents = contract.get("required_review_agents")
            agents = (
                tuple(_as_text(agent) for agent in explicit_agents if _as_text(agent))
                if isinstance(explicit_agents, (list, tuple, set))
                else _required_contract_review_agents(contract)
            )
            result[key] = tuple(sorted(agents))
        return result

    prior = _contract_agents(review_contract_tasks)
    current = _contract_agents(current_contract_tasks)
    added = sorted(set(current) - set(prior))
    removed = sorted(set(prior) - set(current))
    shared_keys = set(prior) & set(current)
    changed_agents = sorted(
        key
        for key in shared_keys
        if not set(current.get(key, ())).issubset(set(prior.get(key, ())))
    )
    relaxed_agents = sorted(
        key
        for key in shared_keys
        if set(current.get(key, ())) < set(prior.get(key, ()))
    )
    comparable = bool(prior)
    drift = bool(added or removed or changed_agents) if comparable else False
    return {
        "reviewed_contract_count": len(prior),
        "current_contract_count": len(current),
        "added_contract_count": len(added),
        "removed_contract_count": len(removed),
        "changed_required_agent_contract_count": len(changed_agents),
        "relaxed_required_agent_contract_count": len(relaxed_agents),
        "added_contract_examples": added[:20],
        "removed_contract_examples": removed[:20],
        "changed_required_agent_contract_examples": changed_agents[:20],
        "relaxed_required_agent_contract_examples": relaxed_agents[:20],
        "contract_snapshot_available": comparable,
        "contract_status": "drift" if drift else "stable" if comparable else "not_comparable",
    }


def build_agentic_review_contract_coverage(
    dispatch_plan: Mapping[str, Any],
    external_reviews: pd.DataFrame,
    *,
    min_lanes_per_ticker: int = MIN_AGENTIC_REVIEW_LANES_PER_TICKER,
) -> dict[str, Any]:
    required = _required_review_tickers_from_dispatch_plan(dispatch_plan)
    required_set = set(required)
    if not required:
        return {
            "required_review_ticker_count": 0,
            "required_review_ticker_reviewed_count": 0,
            "required_review_ticker_missing_count": 0,
            "required_review_ticker_coverage_pct": 0.0,
            "required_review_missing_ticker_examples": [],
            "min_lanes_per_ticker": int(min_lanes_per_ticker),
            "status": "not_required",
        }
    agents_by_ticker: dict[str, set[str]] = {ticker: set() for ticker in required}
    if external_reviews is not None and not external_reviews.empty and {"ticker", "agent"}.issubset(external_reviews.columns):
        for _, review in external_reviews.iterrows():
            if _truthy(review.get("contract_specific")):
                continue
            ticker = _as_text(review.get("ticker")).upper()
            if ticker not in required_set:
                continue
            agent = _as_text(review.get("agent"))
            if agent:
                agents_by_ticker.setdefault(ticker, set()).add(agent)
    reviewed = [
        ticker
        for ticker in required
        if len(agents_by_ticker.get(ticker, set())) >= max(int(min_lanes_per_ticker), 0)
    ]
    missing = [ticker for ticker in required if ticker not in set(reviewed)]
    coverage = len(reviewed) / len(required) if required else 0.0
    return {
        "required_review_ticker_count": len(required),
        "required_review_ticker_reviewed_count": len(reviewed),
        "required_review_ticker_missing_count": len(missing),
        "required_review_ticker_coverage_pct": round(coverage, 4),
        "required_review_missing_ticker_examples": missing[:30],
        "min_lanes_per_ticker": int(min_lanes_per_ticker),
        "status": "pass" if not missing else "block",
    }


def _agent_dispatch_prompt(lane: Mapping[str, Any], common_context: Mapping[str, Any], tasks: Sequence[Mapping[str, Any]]) -> str:
    required_tickers = _unique_ordered_tickers(common_context.get("required_review_tickers") or [])
    if not required_tickers:
        required_tickers = _required_review_tickers_for_dispatch(tasks)
    required_ticker_text = ", ".join(required_tickers)
    lesson_context = str(common_context.get("lesson_context") or "").strip()
    lesson_block = (
        f"Active lesson pack: {common_context.get('lesson_pack_version')} "
        f"({common_context.get('lesson_pack_digest')}).\n"
        f"Lessons you must apply:\n{lesson_context}\n"
        if lesson_context
        else f"Active lesson pack: {common_context.get('lesson_pack_version')} ({common_context.get('lesson_pack_digest')}).\n"
    )
    lane_name = _as_text(lane.get("agent"))
    contract_clause = ""
    if lane_name in CONTRACT_REVIEW_CAPABLE_AGENTS:
        contract_clause = (
            "In addition to ticker coverage, read contract_review_tasks.json and return one extra review for every "
            "assigned exact contract. Copy contract_key, strategy_route, expiry, and trade_plan exactly; set "
            "contract_specific=true only after reviewing those exact legs, quote, Greeks, event crossings, and sizing. "
            "A generic ticker review does not satisfy contract review coverage. Return supportive when an exact "
            "contract passes the policy; caution is for a concrete non-blocking issue and avoid requires an objective "
            "blocker with blocker_type.\n"
            f"Exact contract review policy: {json.dumps(common_context.get('contract_review_policy', {}), sort_keys=True)}\n"
        )
    return (
        f"You are the Options Agent {lane.get('agent')} subagent for {common_context.get('as_of')}.\n"
        f"Role: {lane.get('role')}\n"
        f"Required review tickers ({len(required_tickers)}): {required_ticker_text}\n"
        f"Full candidate universe ticker count: {common_context.get('candidate_universe_ticker_count')}.\n"
        f"{lesson_block}"
        "Read the input artifacts listed below from the local workspace, then return only JSON with a top-level "
        "`reviews` list. Each review must follow this schema: "
        f"{json.dumps(common_context.get('review_output_schema', {}), sort_keys=True)}\n"
        "Return at least one review for every required review ticker before adding optional broader-universe "
        "reviews. Use the required ticker as the `ticker` value exactly once or more in your lane output. "
        "If evidence is mixed, return caution rather than omitting the ticker.\n"
        "Portfolio risk is annotate-only: never set objective_blocker=true solely because of concentration, "
        "correlation, buying power, or existing exposure. Use objective_blocker=true only for non-portfolio facts "
        "that should block the setup.\n"
        "Dispatch-only/pass-1 writes live priced_candidates.csv, structure_attempts.csv, live_chain_validation.csv, "
        "and contract_review_tasks.json when Schwab data is available. If an exact contract task is present, review "
        "that contract rather than a hypothetical expiry or structure.\n"
        f"{contract_clause}"
        f"Input artifacts: {json.dumps(common_context.get('input_artifacts', {}), sort_keys=True)}\n"
        f"Focus: {' '.join(str(item) for item in lane.get('focus', []))}"
    )


def load_external_agent_reviews(path: Optional[Path]) -> tuple[pd.DataFrame, list[str]]:
    """Load optional external/subagent reviews from JSON."""

    if path is None:
        return pd.DataFrame(columns=EXTERNAL_REVIEW_COLUMNS), []
    resolved_path = Path(path).expanduser().resolve()
    default_agent_type = "subagent" if resolved_path.name in {"agentic_reviews.json", "subagent_reviews.json"} else "external"
    try:
        payload = json.loads(resolved_path.read_text(encoding="utf-8"))
    except Exception as exc:
        return pd.DataFrame(columns=EXTERNAL_REVIEW_COLUMNS), [f"external agent reviews unavailable: {exc}"]

    reviews = payload.get("reviews", payload) if isinstance(payload, dict) else payload
    if not isinstance(reviews, list):
        return pd.DataFrame(columns=EXTERNAL_REVIEW_COLUMNS), ["external agent reviews JSON did not contain a review list"]
    rows = []
    invalid_reviews: list[str] = []
    for review in reviews:
        if not isinstance(review, Mapping):
            continue
        ticker = str(review.get("ticker") or "").strip().upper()
        agent = str(review.get("agent") or "external").strip()
        note = _sanitize_visible_review_note(review.get("note"))
        verdict = str(review.get("verdict") or "").strip().lower()
        objective_blocker = _truthy(review.get("objective_blocker"))
        blocker_type = str(review.get("blocker_type") or "").strip()
        if _is_pass_one_artifact_absence_review(
            agent=agent,
            note=note,
            objective_blocker=objective_blocker,
        ):
            objective_blocker = False
            blocker_type = ""
            if verdict == "avoid":
                verdict = "caution"
            note = _append_reason(
                note,
                "Pass-1 placeholder artifact absence is caution-only; pass-2 structure/live validation decides actionability.",
            )
        legacy_external_portfolio_agent = bool(agent == "portfolio_risk" and default_agent_type == "external")
        if agent not in KNOWN_EXTERNAL_REVIEW_AGENTS and not legacy_external_portfolio_agent:
            invalid_reviews.append(f"{ticker or 'missing_ticker'}:{agent or 'missing_agent'}:unknown_agent")
            continue
        if not ticker or verdict not in {"supportive", "caution", "avoid"} or not note:
            invalid_reviews.append(f"{ticker or 'missing_ticker'}:{agent}:invalid_required_fields")
            continue
        if objective_blocker and not blocker_type:
            invalid_reviews.append(f"{ticker}:{agent}:objective_blocker_missing_type")
            continue
        contract_specific = _truthy(review.get("contract_specific"))
        if contract_specific and any(
            not _as_text(review.get(field))
            for field in ("contract_key", "strategy_route", "expiry", "trade_plan")
        ):
            invalid_reviews.append(f"{ticker}:{agent}:incomplete_contract_identity")
            continue
        evidence = str(review.get("evidence") or "").strip()
        if contract_specific and agent == "catalyst_news" and not re.search(r"https://", evidence, flags=re.IGNORECASE):
            invalid_reviews.append(f"{ticker}:{agent}:issuer_source_url_required")
            continue
        rows.append(
            {
                "candidate_id": str(review.get("candidate_id") or f"{ticker}:{agent}:subagent_review").strip(),
                "ticker": ticker,
                "agent": agent,
                "agent_type": str(review.get("agent_type") or default_agent_type).strip(),
                "review_stage": str(review.get("review_stage") or "subagent_review").strip(),
                "verdict": verdict,
                "confidence": str(review.get("confidence") or "").strip().lower(),
                "note": note,
                "objective_blocker": objective_blocker,
                "blocker_type": blocker_type,
                "portfolio_risk_only": _truthy(review.get("portfolio_risk_only")) if "portfolio_risk_only" in review else "",
                "evidence": evidence,
                "source_artifact": str(review.get("source_artifact") or "agentic_reviews.json").strip(),
                "as_of": str(review.get("as_of") or "").strip(),
                "contract_key": str(review.get("contract_key") or "").strip(),
                "contract_specific": contract_specific,
                "strategy_route": str(review.get("strategy_route") or "").strip(),
                "expiry": str(review.get("expiry") or "").strip(),
                "trade_plan": str(review.get("trade_plan") or "").strip(),
            }
        )
    warnings = []
    if invalid_reviews:
        warnings.append(
            f"ignored {len(invalid_reviews)} invalid external agent reviews: "
            + "; ".join(invalid_reviews[:10])
        )
    return pd.DataFrame(rows, columns=EXTERNAL_REVIEW_COLUMNS), warnings


def _is_pass_one_artifact_absence_review(*, agent: str, note: str, objective_blocker: bool) -> bool:
    """Detect subagent hard rejects caused only by dispatch/pass-1 placeholder artifacts."""

    if not objective_blocker:
        return False
    lane = str(agent or "").strip().lower()
    if lane not in {"structure_builder", "skeptic"}:
        return False
    text = str(note or "").strip().lower()
    if not text:
        return False
    pass_two_artifacts_empty = (
        "structure_attempts" in text
        and "priced_candidates" in text
        and "decision_board" in text
        and any(marker in text for marker in ("empty", "absent", "missing"))
    )
    dispatch_no_priced_structure = (
        "no priced structure" in text
        and "dispatch artifact" in text
        and (
            "structure math is regenerated" in text
            or "not entry-ready" in text
            or "decision-board row" in text
        )
    )
    return pass_two_artifacts_empty or dispatch_no_priced_structure


def _sanitize_visible_review_note(value: Any) -> str:
    """Keep account/portfolio routing language out of user-facing trade notes."""

    text = str(value or "").strip()
    if not text:
        return ""
    text = re.sub(
        r"(?i)\bexisting\s+[^.;]*?\s+exposure\s+is\s+portfolio\s+annotation\s+only,\s*but\s*",
        "",
        text,
    )
    text = re.sub(r"(?i)\bportfolio\s+note\s+is\s+annotation\s+only\b", "", text)
    text = re.sub(r"(?i)\bportfolio\s+annotation\s+only,\s*but\s*", "", text)
    text = re.sub(r"(?i)\bportfolio\s+annotation\s+only\b", "", text)
    text = re.sub(r"(?i)\bportfolio\s+risk\s+(?:noted|annotated)\b", "", text)
    text = re.sub(r"(?i)\bvisibility\s+policy\b:?\s*", "", text)
    text = re.sub(r"(?i)\btrade\s+remains\s+visible\b", "", text)
    text = re.sub(r"\s+([,.;:])", r"\1", text)
    text = re.sub(r"^[,.;:\s]+", "", text)
    text = re.sub(r"\s{2,}", " ", text)
    if text.lower().startswith("but "):
        text = text[4:]
    return text.strip(" ;")


def build_internal_agent_reviews(
    candidates: pd.DataFrame,
    market_regime: Mapping[str, Any],
    catalyst_reviews: pd.DataFrame,
    priced: pd.DataFrame,
    *,
    as_of: str,
    live_market_context: Optional[Mapping[str, Any]] = None,
) -> pd.DataFrame:
    """Run deterministic built-in review agents and return a normalized board."""

    if candidates.empty and priced.empty:
        return pd.DataFrame(columns=AGENT_REVIEW_COLUMNS)

    candidate_by_ticker = _frame_by_ticker(candidates)
    catalyst_by_ticker = _frame_by_ticker(catalyst_reviews)
    priced_by_ticker = _frame_by_ticker(priced)
    ordered_tickers = _ordered_review_tickers(priced, candidates)
    rows: list[dict[str, Any]] = []
    regime = str(market_regime.get("regime") or "unknown")
    regime_note = str(market_regime.get("note") or market_regime.get("reason") or "market regime unavailable")
    live_context_note = _live_market_context_note(live_market_context)
    if live_context_note:
        regime_note = f"{regime_note}; {live_context_note}"

    for ticker in ordered_tickers:
        candidate = candidate_by_ticker.get(ticker, {})
        priced_row = priced_by_ticker.get(ticker, {})
        catalyst = catalyst_by_ticker.get(ticker, {})
        bias = str(candidate.get("bias") or priced_row.get("bias") or "").strip().lower()

        regime_verdict = "supportive"
        regime_confidence = "medium" if market_regime.get("status") == "ok" else "low"
        if (regime == "risk_off" and bias == "bullish") or (regime == "risk_on" and bias == "bearish"):
            regime_verdict = "caution"
        rows.append(
            _agent_review_row(
                ticker,
                "market_regime",
                "market_regime",
                regime_verdict,
                regime_confidence,
                f"{regime}: {regime_note}",
                source_artifact="market_regime.json",
                as_of=as_of,
            )
        )

        catalyst_status = str(catalyst.get("catalyst_status") or "").strip()
        catalyst_note = str(catalyst.get("catalyst_note") or "no catalyst review note").strip()
        catalyst_verdict = "supportive"
        catalyst_confidence = "medium"
        if catalyst_status in {"event_risk", "news_red_flag", "watch_event", "news_mixed", "local_news_available"}:
            catalyst_verdict = "caution"
            catalyst_confidence = "high" if catalyst_status in {"event_risk", "news_red_flag"} else "medium"
        rows.append(
            _agent_review_row(
                ticker,
                "catalyst",
                "catalyst",
                catalyst_verdict,
                catalyst_confidence,
                catalyst_note,
                evidence=catalyst_status,
                source_artifact="catalyst_reviews.csv",
                as_of=as_of,
            )
        )

    reviewed_contracts: set[str] = set()
    for priced_row in priced.to_dict("records"):
        ticker = str(priced_row.get("ticker") or "").strip().upper()
        row_contract_key = contract_review_key(priced_row)
        if not ticker or not row_contract_key or row_contract_key in reviewed_contracts:
            continue
        reviewed_contracts.add(row_contract_key)
        status = str(priced_row.get("recommendation_status") or "").strip().upper()
        hard_rejects = str(priced_row.get("hard_rejects") or "").strip()
        ticket = str(priced_row.get("trade_plan") or priced_row.get("full_ticket") or "").strip()
        status_reason = str(priced_row.get("status_reason") or "").strip()
        if hard_rejects:
            structure_verdict = "avoid"
            structure_note = f"objective structure blocker: {hard_rejects}"
            objective_blocker = True
            blocker_type = "execution"
            confidence = "high"
        elif not ticket:
            structure_verdict = "caution"
            structure_note = status_reason or "no executable ticket yet"
            objective_blocker = False
            blocker_type = ""
            confidence = "high"
        elif status == RecommendationStatus.WAIT_FOR_PRICE.value:
            structure_verdict = "caution"
            structure_note = status_reason or "entry price not ready"
            objective_blocker = False
            blocker_type = ""
            confidence = "medium"
        else:
            structure_verdict = "supportive"
            structure_note = status_reason or "structure has executable pricing"
            objective_blocker = False
            blocker_type = ""
            confidence = "medium"
        contract_fields = {
            "contract_key": row_contract_key,
            "contract_specific": True,
            "strategy_route": str(priced_row.get("strategy_route") or "").strip(),
            "expiry": str(priced_row.get("expiry") or "").strip(),
            "trade_plan": ticket,
        }
        rows.append(
            _agent_review_row(
                ticker,
                "structure",
                "structure",
                structure_verdict,
                confidence,
                structure_note,
                objective_blocker=objective_blocker,
                blocker_type=blocker_type,
                evidence=str(priced_row.get("full_ticket") or priced_row.get("invalidation") or ""),
                source_artifact="priced_candidates.csv",
                as_of=as_of,
                **contract_fields,
            )
        )

        skeptic_verdict = "supportive"
        skeptic_note = "no objective blocker after structure review"
        skeptic_objective = False
        skeptic_blocker = ""
        if hard_rejects:
            skeptic_verdict = "avoid"
            skeptic_note = f"objective blocker remains: {hard_rejects}"
            skeptic_objective = True
            skeptic_blocker = "thesis_or_execution"
        elif status in {RecommendationStatus.REVIEW.value, RecommendationStatus.WAIT_FOR_PRICE.value}:
            skeptic_verdict = "caution"
            skeptic_note = status_reason or "requires human confirmation before entry"
        rows.append(
            _agent_review_row(
                ticker,
                "skeptic",
                "skeptic",
                skeptic_verdict,
                "medium",
                skeptic_note,
                objective_blocker=skeptic_objective,
                blocker_type=skeptic_blocker,
                source_artifact="priced_candidates.csv",
                as_of=as_of,
                **contract_fields,
            )
        )
    return pd.DataFrame(rows, columns=AGENT_REVIEW_COLUMNS)


def build_single_process_execution_reviews(
    internal_reviews: pd.DataFrame,
    dispatch_plan: Mapping[str, Any],
    priced: pd.DataFrame,
    *,
    as_of: str,
) -> pd.DataFrame:
    """Build an auditable four-lane review packet without spawning subagents."""

    required_tickers = _required_review_tickers_from_dispatch_plan(dispatch_plan)
    if not required_tickers:
        required_tickers = _ordered_review_tickers(priced, pd.DataFrame())
    internal_records = (
        internal_reviews.to_dict("records")
        if internal_reviews is not None and not internal_reviews.empty
        else []
    )
    generic_lookup = {
        (_as_text(review.get("ticker")).upper(), _as_text(review.get("agent"))): review
        for review in internal_records
        if not _truthy(review.get("contract_specific"))
    }
    priced_by_ticker: dict[str, list[dict[str, Any]]] = {}
    for row in priced.to_dict("records") if priced is not None and not priced.empty else []:
        ticker = _as_text(row.get("ticker")).upper()
        if ticker:
            priced_by_ticker.setdefault(ticker, []).append(row)

    rows: list[dict[str, Any]] = []
    for ticker in required_tickers:
        for source_agent, local_agent, stage in (
            ("market_regime", "macro_regime", "single_process_macro_regime"),
            ("catalyst", "catalyst_news", "single_process_catalyst_news"),
        ):
            source = generic_lookup.get((ticker, source_agent), {})
            rows.append(
                _agent_review_row(
                    ticker,
                    local_agent,
                    stage,
                    _as_text(source.get("verdict")) or "caution",
                    _as_text(source.get("confidence")) or "medium",
                    _as_text(source.get("note")) or f"{local_agent} evidence unavailable",
                    agent_type="deterministic_local",
                    objective_blocker=_truthy(source.get("objective_blocker")),
                    blocker_type=_as_text(source.get("blocker_type")),
                    evidence=_as_text(source.get("evidence")),
                    source_artifact=_as_text(source.get("source_artifact")) or "single_process_review",
                    as_of=as_of,
                )
            )

        ticker_contracts = priced_by_ticker.get(ticker, [])
        clean_contracts = [
            row
            for row in ticker_contracts
            if _as_text(row.get("trade_plan") or row.get("full_ticket"))
            and not _as_text(row.get("hard_rejects"))
            and _as_text(row.get("live_validation_status")).upper() == "PASS"
        ]
        rows.append(
            _agent_review_row(
                ticker,
                "structure_builder",
                "single_process_structure_coverage",
                "supportive" if clean_contracts else "caution",
                "high" if ticker_contracts else "medium",
                (
                    f"{len(clean_contracts)} clean live-priced contract(s) available for exact review"
                    if clean_contracts
                    else "no clean live-priced contract available; ticker remains research-only"
                ),
                agent_type="deterministic_local",
                source_artifact="priced_candidates.csv",
                as_of=as_of,
            )
        )
        rows.append(
            _agent_review_row(
                ticker,
                "skeptic",
                "single_process_skeptic_coverage",
                "supportive" if clean_contracts else "caution",
                "medium",
                (
                    "at least one exact contract has no objective execution defect"
                    if clean_contracts
                    else "no exact contract clears the objective execution checks"
                ),
                agent_type="deterministic_local",
                source_artifact="priced_candidates.csv",
                as_of=as_of,
            )
        )

    seen_exact: set[tuple[str, str]] = set()
    for review in internal_records:
        if not _truthy(review.get("contract_specific")):
            continue
        source_agent = _as_text(review.get("agent"))
        local_agent = "structure_builder" if source_agent == "structure" else source_agent
        if local_agent not in CONTRACT_REVIEW_REQUIRED_AGENTS:
            continue
        contract_key = _as_text(review.get("contract_key"))
        dedupe_key = (contract_key, local_agent)
        if not contract_key or dedupe_key in seen_exact:
            continue
        seen_exact.add(dedupe_key)
        rows.append(
            _agent_review_row(
                _as_text(review.get("ticker")),
                local_agent,
                f"single_process_exact_{local_agent}",
                _as_text(review.get("verdict")) or "caution",
                _as_text(review.get("confidence")) or "medium",
                _as_text(review.get("note")) or "exact contract reviewed deterministically",
                agent_type="deterministic_local",
                objective_blocker=_truthy(review.get("objective_blocker")),
                blocker_type=_as_text(review.get("blocker_type")),
                evidence=_as_text(review.get("evidence")),
                source_artifact=_as_text(review.get("source_artifact")) or "priced_candidates.csv",
                as_of=as_of,
                contract_key=contract_key,
                contract_specific=True,
                strategy_route=_as_text(review.get("strategy_route")),
                expiry=_as_text(review.get("expiry")),
                trade_plan=_as_text(review.get("trade_plan")),
            )
        )

    seen_catalyst_contracts: set[str] = set()
    for contract in priced.to_dict("records") if priced is not None and not priced.empty else []:
        if "catalyst_news" not in _required_contract_review_agents(contract):
            continue
        contract_key = contract_review_key(contract)
        if not contract_key or contract_key in seen_catalyst_contracts:
            continue
        seen_catalyst_contracts.add(contract_key)
        earnings_status = _as_text(contract.get("earnings_source_status")).lower()
        if earnings_status in {"missing", "unverified"}:
            verdict = "avoid"
            objective = True
            blocker_type = "stale_event"
            note = "earnings calendar is not authoritative for this exact contract"
        elif earnings_status == "provisional_after_expiry":
            verdict = "caution"
            objective = False
            blocker_type = ""
            note = "earnings is provisionally after expiry; verify the date before entry"
        elif earnings_status == "provisional_after_holding_horizon":
            verdict = "supportive"
            objective = False
            blocker_type = ""
            note = "dated earnings is after the mandatory time exit; no scheduled earnings falls inside the holding horizon"
        else:
            verdict = "supportive"
            objective = False
            blocker_type = ""
            note = "contract event-calendar check passed"
        rows.append(
            _agent_review_row(
                _as_text(contract.get("ticker")),
                "catalyst_news",
                "single_process_exact_catalyst_news",
                verdict,
                "high",
                note,
                agent_type="deterministic_local",
                objective_blocker=objective,
                blocker_type=blocker_type,
                evidence=_as_text(contract.get("contract_event_risk_note")),
                source_artifact="options_event_calendar.csv",
                as_of=as_of,
                contract_key=contract_key,
                contract_specific=True,
                strategy_route=_as_text(contract.get("strategy_route")),
                expiry=_as_text(contract.get("expiry")),
                trade_plan=_as_text(contract.get("trade_plan") or contract.get("full_ticket")),
            )
        )
    return pd.DataFrame(rows, columns=AGENT_REVIEW_COLUMNS)


def build_portfolio_agent_reviews(final: pd.DataFrame, *, as_of: str) -> pd.DataFrame:
    """Emit portfolio-risk agent reviews after portfolio annotations are applied."""

    if final.empty:
        return pd.DataFrame(columns=AGENT_REVIEW_COLUMNS)
    rows: list[dict[str, Any]] = []
    for _, row in final.iterrows():
        ticker = str(row.get("ticker") or "").strip().upper()
        risk_note = str(row.get("portfolio_risk_note") or "").strip()
        if risk_note:
            rows.append(
                _agent_review_row(
                    ticker,
                    "portfolio_risk",
                    "portfolio",
                    "caution",
                    "high",
                    risk_note,
                    portfolio_risk_only=True,
                    blocker_type="portfolio",
                    source_artifact="risk_audit.csv",
                    as_of=as_of,
                )
            )
    return pd.DataFrame(rows, columns=AGENT_REVIEW_COLUMNS)


def combine_agent_reviews(*frames: pd.DataFrame, as_of: str) -> pd.DataFrame:
    """Merge built-in and optional external reviews into the canonical board."""

    rows: list[dict[str, Any]] = []
    for frame in frames:
        if frame is None or frame.empty:
            continue
        for _, review in frame.iterrows():
            rows.append(_normalize_agent_review(review.to_dict(), as_of=as_of))
    if not rows:
        return pd.DataFrame(columns=AGENT_REVIEW_COLUMNS)
    return pd.DataFrame(rows, columns=AGENT_REVIEW_COLUMNS)


def summarize_agent_reviews(agent_review_board: pd.DataFrame) -> dict[str, Any]:
    """Summarize review-board coverage for the manifest."""

    if agent_review_board.empty:
        return {
            "total": 0,
            "by_agent_type": {},
            "by_verdict": {},
            "objective_blockers": 0,
            "portfolio_risk_only": 0,
            "external_reviews_present": False,
        }
    return {
        "total": int(len(agent_review_board)),
        "by_agent_type": _value_counts(agent_review_board, "agent_type"),
        "by_verdict": _value_counts(agent_review_board, "verdict"),
        "objective_blockers": int(agent_review_board["objective_blocker"].astype(bool).sum()),
        "portfolio_risk_only": int(agent_review_board["portfolio_risk_only"].astype(bool).sum()),
        "external_reviews_present": bool(agent_review_board["agent_type"].map(_is_external_or_subagent_agent_type).any()),
    }


def _is_external_or_subagent_agent_type(value: Any) -> bool:
    agent_type = str(value or "").strip().lower().replace("-", "_")
    return bool(
        agent_type == "external"
        or agent_type == "subagent"
        or agent_type == "deterministic_local"
        or agent_type.startswith("external_")
        or agent_type.startswith("subagent_")
    )


def apply_synthesis_ranking(
    final: pd.DataFrame,
    agent_review_board: pd.DataFrame,
    *,
    top_trades: int,
    lesson_pack: Optional[Any] = None,
    execution_context: Optional[Mapping[str, Any]] = None,
) -> pd.DataFrame:
    """Rank final rows using setup quality, execution readiness, and agent evidence."""

    # Kept for API compatibility; ranking must not trim the final board.
    _ = top_trades
    if final.empty:
        return final.copy()
    rows: list[dict[str, Any]] = []
    for _, row in final.iterrows():
        out = row.to_dict()
        summary = _review_summary_for_row(agent_review_board, out)
        score, reason = _synthesis_score(out, summary, execution_context=execution_context)
        lesson_delta, lesson_reasons, lesson_rows = apply_synthesis_actions(
            out,
            getattr(lesson_pack, "lessons", []) if lesson_pack is not None else [],
        )
        if lesson_delta:
            score = round(score + lesson_delta, 2)
        if lesson_reasons:
            reason = "; ".join([reason, *lesson_reasons])
        out["synthesis_score"] = score
        out["synthesis_reason"] = reason
        out["lesson_score_delta"] = lesson_delta
        out["lesson_ids_applied"] = "; ".join(
            str(item.get("lesson_id") or "") for item in lesson_rows if str(item.get("lesson_id") or "")
        )
        out["lesson_application_rows"] = json.dumps(lesson_rows, sort_keys=True)
        out["agent_support_count"] = int(summary.get("supportive", 0))
        out["agent_caution_count"] = int(summary.get("caution", 0))
        out["agent_objective_blocker_count"] = int(summary.get("objective_blockers", 0))
        out["agent_portfolio_risk_only_count"] = int(summary.get("portfolio_risk_only", 0))
        rows.append(out)
    ranked = pd.DataFrame(rows)
    ranked = ranked.sort_values(["synthesis_score", "score", "signal_premium"], ascending=[False, False, False])
    ranked["recommendation_rank"] = range(1, len(ranked) + 1)
    return ranked.reset_index(drop=True)


def _clear_resolved_exact_catalyst_review_requirement(value: Any) -> str:
    return "; ".join(
        part
        for part in (_as_text(item).strip() for item in _as_text(value).split(";"))
        if part and part.lower() != "exact catalyst review still required"
    )


def apply_agent_reviews(priced: pd.DataFrame, reviews: pd.DataFrame) -> pd.DataFrame:
    """Apply normalized agent reviews before portfolio annotation."""

    if priced.empty:
        return _ensure_external_review_columns(priced.copy())
    if reviews.empty:
        return _ensure_external_review_columns(priced.copy())
    grouped: dict[str, list[dict[str, Any]]] = {}
    for _, review in reviews.iterrows():
        ticker = str(review.get("ticker") or "").strip().upper()
        if ticker:
            grouped.setdefault(ticker, []).append(review.to_dict())

    rows: list[dict[str, Any]] = []
    for _, row in priced.iterrows():
        out = row.to_dict()
        ticker = str(out.get("ticker") or "").strip().upper()
        ticker_reviews = grouped.get(ticker, [])
        required_contract_agents = _required_contract_review_agents(out)
        if not ticker_reviews:
            row_contract_key = contract_review_key(out)
            contract_review_required = bool(
                row_contract_key
                and _as_text(out.get("live_validation_status")).upper() == "PASS"
                and _as_text(out.get("underlying_quality_tier")).lower() in {"core", "liquid"}
            )
            out["contract_key"] = row_contract_key
            out["contract_review_count"] = 0
            out["contract_review_agents"] = ""
            out["contract_review_missing_agents"] = (
                "; ".join(required_contract_agents) if contract_review_required else ""
            )
            out["contract_review_status"] = "BLOCK" if contract_review_required else "NOT_REQUIRED"
            rows.append(out)
            continue
        row_contract_key = contract_review_key(out)
        applicable_reviews = [
            _normalize_contract_review_against_priced(review, out)
            for review in ticker_reviews
            if not _truthy(review.get("contract_specific"))
            or _contract_review_applies_to_row(
                review,
                out,
                row_contract_key=row_contract_key,
            )
            or _price_independent_contract_blocker_applies_to_row(
                review,
                out,
                row_contract_key=row_contract_key,
            )
        ]
        notes = [
            f"{review.get('agent', 'external')}={review.get('verdict', '')}: {review.get('note', '')}".strip()
            for review in applicable_reviews
            if str(review.get("note") or "").strip() or str(review.get("verdict") or "").strip()
        ]
        external_reviews = [
            review
            for review in applicable_reviews
            if _is_external_or_subagent_agent_type(review.get("agent_type"))
        ]
        generic_external_reviews = [
            review for review in external_reviews if not _truthy(review.get("contract_specific"))
        ]
        contract_reviews = [
            review
            for review in external_reviews
            if _contract_review_applies_to_row(
                review,
                out,
                row_contract_key=row_contract_key,
            )
            or _price_independent_contract_blocker_applies_to_row(
                review,
                out,
                row_contract_key=row_contract_key,
            )
        ]
        contract_review_agents = sorted(
            {
                _as_text(review.get("agent"))
                for review in contract_reviews
                if _as_text(review.get("agent"))
            }
        )
        missing_contract_agents = [
            agent for agent in required_contract_agents if agent not in contract_review_agents
        ]
        contract_review_verdicts = {
            agent: sorted(
                {
                    _as_text(review.get("verdict")).lower()
                    for review in contract_reviews
                    if _as_text(review.get("agent")) == agent and _as_text(review.get("verdict"))
                }
            )
            for agent in required_contract_agents
        }
        contract_objective_blockers = [
            review for review in contract_reviews if _truthy(review.get("objective_blocker"))
        ]
        contract_avoid_reviews = [
            review for review in contract_reviews if _as_text(review.get("verdict")).lower() == "avoid"
        ]
        provisional_earnings_caution = bool(
            _as_text(out.get("earnings_source_status")).lower() == "provisional_after_expiry"
            and any(
                _as_text(review.get("agent")) == "catalyst_news"
                and _as_text(review.get("verdict")).lower() == "caution"
                for review in contract_reviews
            )
        )
        contract_review_required = bool(
            row_contract_key
            and _as_text(out.get("live_validation_status")).upper() == "PASS"
            and _as_text(out.get("underlying_quality_tier")).lower() in {"core", "liquid"}
        )
        out["contract_key"] = row_contract_key
        out["contract_review_count"] = len(contract_reviews)
        out["contract_review_agents"] = "; ".join(contract_review_agents)
        out["contract_review_missing_agents"] = "; ".join(missing_contract_agents) if contract_review_required else ""
        out["contract_review_verdicts"] = "; ".join(
            f"{agent}={','.join(contract_review_verdicts.get(agent, [])) or 'missing'}"
            for agent in required_contract_agents
        ) if contract_review_required else ""
        out["contract_review_note"] = "; ".join(
            _dedupe_notes(
                _as_text(review.get("note"))
                for review in contract_reviews
                if _as_text(review.get("note"))
            )
        )
        if not contract_review_required:
            out["contract_review_status"] = "NOT_REQUIRED"
        elif missing_contract_agents or contract_objective_blockers or contract_avoid_reviews:
            out["contract_review_status"] = "BLOCK"
        elif provisional_earnings_caution:
            # A dated UW estimate after expiry is not an objective rejection,
            # but it needs an authoritative calendar check before entry.
            out["contract_review_status"] = "WARN"
        else:
            out["contract_review_status"] = "PASS"
        if out["contract_review_status"] == "PASS" and "catalyst_news" in contract_review_agents:
            for field in ("contract_event_risk_note", "status_reason"):
                out[field] = _clear_resolved_exact_catalyst_review_requirement(out.get(field))
        external_notes = [
            f"{review.get('agent', 'external')}={review.get('verdict', '')}: {review.get('note', '')}".strip()
            for review in generic_external_reviews
            if str(review.get("note") or "").strip() or str(review.get("verdict") or "").strip()
            if not _is_portfolio_management_process_note(review)
            and not _is_portfolio_risk_review(review)
        ]
        distinct_external_agents = sorted(
            {
                str(review.get("agent") or "").strip()
                for review in generic_external_reviews
                if str(review.get("agent") or "").strip()
            }
        )
        out["external_agent_review_count"] = len(generic_external_reviews)
        out["external_agent_distinct_review_count"] = len(distinct_external_agents)
        out["external_agent_review_agents"] = "; ".join(distinct_external_agents)
        out["external_agent_review_note"] = "; ".join(_dedupe_notes(external_notes))
        portfolio_review_notes = [
            str(review.get("note") or "external portfolio risk").strip()
            for review in applicable_reviews
            if not _truthy(review.get("objective_blocker"))
            and _is_portfolio_risk_review(review)
            and str(review.get("verdict") or "").strip().lower() == "avoid"
        ]
        objective_blockers = [
            str(review.get("note") or review.get("verdict") or "external objective blocker").strip()
            for review in applicable_reviews
            if _truthy(review.get("objective_blocker"))
        ]
        cautions = [
            str(review.get("note") or "external caution").strip()
            for review in applicable_reviews
            if str(review.get("verdict") or "").strip().lower() == "caution"
            and not _truthy(review.get("objective_blocker"))
            and not _is_portfolio_risk_review(review)
            and not _is_portfolio_management_process_note(review)
            and not _resolved_generic_post_expiry_catalyst_caution(review, out)
        ]
        unsupported_avoids = [
            str(review.get("note") or "avoid verdict without objective blocker").strip()
            for review in applicable_reviews
            if str(review.get("verdict") or "").strip().lower() == "avoid"
            and not _truthy(review.get("objective_blocker"))
            and not _is_portfolio_risk_review(review)
            and not _is_portfolio_management_process_note(review)
        ]
        built_in_cautions = [
            str(review.get("note") or "built-in agent caution").strip()
            for review in applicable_reviews
            if str(review.get("verdict") or "").strip().lower() == "caution"
            and not _truthy(review.get("objective_blocker"))
            and not _is_portfolio_risk_review(review)
            and not _is_external_or_subagent_agent_type(review.get("agent_type"))
            and not _resolved_generic_post_expiry_catalyst_caution(review, out)
        ]
        review_blocking_builtin_cautions = [
            str(review.get("note") or "built-in review gate").strip()
            for review in applicable_reviews
            if _is_review_blocking_builtin_caution(review)
        ]
        built_in_avoids = [
            str(review.get("note") or "built-in avoid verdict").strip()
            for review in applicable_reviews
            if str(review.get("verdict") or "").strip().lower() == "avoid"
            and not _truthy(review.get("objective_blocker"))
            and not _is_portfolio_risk_review(review)
            and not _is_external_or_subagent_agent_type(review.get("agent_type"))
        ]
        if portfolio_review_notes:
            out["portfolio_risk_note"] = _append_reason(
                out.get("portfolio_risk_note"),
                "external portfolio risk review: " + "; ".join(_dedupe_notes(portfolio_review_notes)),
            )
        if objective_blockers:
            out["recommendation_status"] = RecommendationStatus.AVOID.value
            out["hard_rejects"] = _append_reason(out.get("hard_rejects"), "external_agent_objective_blocker")
            out["status_reason"] = _append_reason(out.get("status_reason"), "external agent blocker: " + "; ".join(objective_blockers))
        elif review_blocking_builtin_cautions and str(out.get("recommendation_status") or "").upper() in {
            RecommendationStatus.ENTER.value,
            RecommendationStatus.ENTER_WITH_PORTFOLIO_RISK.value,
        }:
            out["recommendation_status"] = RecommendationStatus.REVIEW.value
            caution_text = "; ".join(_dedupe_notes(review_blocking_builtin_cautions))
            out["status_reason"] = _append_reason(out.get("status_reason"), "built-in review gate: " + caution_text)
        elif built_in_cautions or built_in_avoids:
            caution_text = "; ".join(_dedupe_notes(built_in_cautions + [f"avoid without objective blocker: {note}" for note in built_in_avoids]))
            out["status_reason"] = _append_reason(out.get("status_reason"), "built-in agent caution: " + caution_text)
        elif cautions or unsupported_avoids:
            caution_text = "; ".join(_dedupe_notes(cautions + [f"avoid without objective blocker: {note}" for note in unsupported_avoids]))
            out["status_reason"] = _append_reason(out.get("status_reason"), "external agent caution: " + caution_text)
        rows.append(out)
    return _ensure_external_review_columns(pd.DataFrame(rows))


def _ensure_external_review_columns(frame: pd.DataFrame) -> pd.DataFrame:
    out = frame.copy()
    for column, default in (
        ("external_agent_review_count", 0),
        ("external_agent_distinct_review_count", 0),
        ("external_agent_review_agents", ""),
        ("external_agent_review_note", ""),
        ("contract_key", ""),
        ("contract_review_count", 0),
        ("contract_review_agents", ""),
        ("contract_review_missing_agents", ""),
        ("contract_review_verdicts", ""),
        ("contract_review_note", ""),
        ("contract_review_status", "NOT_REQUIRED"),
    ):
        if column not in out.columns:
            out[column] = default
        else:
            out[column] = out[column].fillna(default)
    return out


def price_candidates(
    date_dir: Path,
    as_of: str | dt.date,
    candidates: pd.DataFrame,
    *,
    limit: Optional[int] = None,
    root: Optional[Path] = None,
) -> pd.DataFrame:
    """Construct first-pass spread tickets from dated UW hot-chain quotes."""

    priced, _ = price_candidates_with_routing_audit(
        date_dir,
        as_of,
        candidates,
        limit=limit,
        root=root,
    )
    return priced


def _dated_option_chain_for_construction(
    date_dir: Path,
    as_of: str | dt.date,
) -> pd.DataFrame:
    """Build the broad dated construction chain from hot and chain-OI exports."""

    from ._vendor import data as uw_data

    day = parse_as_of(as_of)
    frames: list[pd.DataFrame] = []
    try:
        hot = uw_data.load_hot_chains(date_dir, day, point_in_time=True).copy()
    except Exception:
        hot = pd.DataFrame()
    if not hot.empty:
        hot["dated_quote_source"] = "hot_chain"
        hot["dated_quote_source_rank"] = 0
        frames.append(hot)

    try:
        chain_oi = uw_data.load_chain_oi(date_dir, day, point_in_time=True).copy()
    except Exception:
        chain_oi = pd.DataFrame()
    if not chain_oi.empty:
        chain_oi = chain_oi.rename(
            columns={
                "last_bid": "bid",
                "last_ask": "ask",
                "curr_oi": "open_interest",
            }
        )
        chain_oi["ticker"] = chain_oi.get(
            "ticker",
            chain_oi.get("underlying_symbol", pd.Series("", index=chain_oi.index)),
        )
        chain_oi["mid"] = (
            pd.to_numeric(chain_oi.get("bid"), errors="coerce")
            + pd.to_numeric(chain_oi.get("ask"), errors="coerce")
        ) / 2.0
        chain_oi["premium"] = pd.to_numeric(
            chain_oi.get("avg_price", chain_oi.get("last_fill", pd.Series(math.nan, index=chain_oi.index))),
            errors="coerce",
        )
        chain_oi["dated_quote_source"] = "chain_oi"
        chain_oi["dated_quote_source_rank"] = 1
        frames.append(chain_oi)
    if not frames:
        return pd.DataFrame(
            columns=[
                "option_symbol",
                "ticker",
                "right",
                "expiry_dt",
                "strike",
                "bid",
                "ask",
                "mid",
                "premium",
                "open_interest",
                "volume",
                "dte",
                "dated_quote_source",
                "dated_quote_source_rank",
            ]
        )

    chain = pd.concat(frames, ignore_index=True, sort=False)
    for column in ("option_symbol", "ticker", "right"):
        if column not in chain.columns:
            chain[column] = ""
        chain[column] = chain[column].fillna("").astype(str).str.upper().str.strip()
    if "expiry_dt" not in chain.columns:
        chain["expiry_dt"] = pd.NaT
    chain["expiry_dt"] = pd.to_datetime(chain["expiry_dt"], errors="coerce").dt.date
    for column in ("strike", "bid", "ask", "mid", "premium", "open_interest", "volume", "dte"):
        if column not in chain.columns:
            chain[column] = math.nan
        chain[column] = pd.to_numeric(chain[column], errors="coerce")
    chain = chain[
        chain["option_symbol"].ne("")
        & chain["ticker"].ne("")
        & chain["right"].isin(["C", "P"])
        & chain["expiry_dt"].notna()
        & chain["strike"].gt(0)
        & chain["bid"].ge(0)
        & chain["ask"].gt(0)
        & chain["ask"].ge(chain["bid"])
    ].copy()
    if chain.empty:
        return chain
    chain = chain.sort_values(
        ["option_symbol", "dated_quote_source_rank", "volume", "open_interest"],
        ascending=[True, True, False, False],
        kind="mergesort",
    ).drop_duplicates("option_symbol", keep="first")
    return chain.reset_index(drop=True)


def price_candidates_with_routing_audit(
    date_dir: Path,
    as_of: str | dt.date,
    candidates: pd.DataFrame,
    *,
    limit: Optional[int] = None,
    root: Optional[Path] = None,
    preserve_failed_routes_for_live: bool = False,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Construct first-pass tickets and the strategy-router audit."""

    if candidates.empty:
        return pd.DataFrame(), pd.DataFrame(columns=STRATEGY_ROUTING_AUDIT_COLUMNS)
    hot = _dated_option_chain_for_construction(date_dir, as_of)
    rows = []
    audit_rows: list[dict[str, Any]] = []
    qualified = candidates[candidates["quality_status"].eq("qualified")]
    if limit is not None:
        qualified = qualified.head(int(limit))
    evidence_as_of = parse_as_of(as_of)
    strategy_metrics = _closed_trade_strategy_family_metrics(root, as_of=evidence_as_of)
    route_metrics = _closed_trade_strategy_route_metrics(root, as_of=evidence_as_of)
    positive_strategy_routes = _positive_closed_trade_strategy_routes(root, metrics_by_route=route_metrics)
    positive_strategy_routes.update(_positive_closed_trade_strategy_families(root, metrics_by_family=strategy_metrics))
    replay_supported_routes = _positive_replay_strategy_routes(root, as_of=parse_as_of(as_of))
    chain_by_ticker = {
        _as_text(ticker).upper(): group.copy()
        for ticker, group in hot.groupby(
            hot.get("ticker", pd.Series("", index=hot.index)).astype(str).str.upper(),
            sort=False,
        )
        if _as_text(ticker)
    }
    empty_chain = hot.iloc[0:0].copy()
    for _, candidate in qualified.iterrows():
        candidate_rows: list[dict[str, Any]] = []
        candidate_errors: list[dict[str, Any]] = []
        candidate_chain = chain_by_ticker.get(
            _as_text(candidate.get("ticker")).upper(),
            empty_chain,
        )
        routes = _candidate_strategy_routes(
            candidate,
            positive_strategy_routes,
            route_metrics,
            strategy_metrics,
            replay_supported_routes=replay_supported_routes,
        )
        for route in routes:
            constructed = _construct_strategy_route(candidate, candidate_chain, route)
            constructed = _attach_strategy_route_metadata(constructed, route)
            constructed_ok = bool(_as_text(constructed.get("trade_plan"))) and ((_as_float(constructed.get("entry_limit")) or 0.0) > 0)
            if constructed_ok:
                candidate_rows.append(constructed)
            else:
                candidate_errors.append(constructed)
            audit_rows.append(_strategy_route_audit_row(candidate, constructed, route, constructed_ok))
        if candidate_rows:
            rows.extend(candidate_rows)
        if candidate_errors and preserve_failed_routes_for_live:
            rows.extend(candidate_errors)
        elif not candidate_rows and candidate_errors:
            rows.append(candidate_errors[0])
    return pd.DataFrame(rows), pd.DataFrame(audit_rows, columns=STRATEGY_ROUTING_AUDIT_COLUMNS)


def _closed_trade_strategy_family_metrics(
    root: Optional[Path],
    *,
    as_of: str | dt.date | None = None,
) -> dict[str, dict[str, Any]]:
    if root is None:
        return {}
    resolved_root = Path(root).expanduser().resolve()
    out_root = resolved_root if resolved_root.name == "out" else resolved_root / "out"
    working = _actual_calibration_frame(resolved_root, out_root, as_of=as_of)
    if working.empty or "realized_pnl" not in working.columns:
        return {}
    working["ticker"] = working.get("ticker", pd.Series("", index=working.index)).astype(str).str.upper()
    working["canonical_ticker"] = working["ticker"].map(canonical_ticker_key)
    if "strategy_family" not in working.columns:
        working["strategy_family"] = working.get("strategy", pd.Series("", index=working.index)).map(_normal_strategy_family)
    working["realized_pnl"] = pd.to_numeric(working["realized_pnl"], errors="coerce")
    return _actual_forward_metrics_by_strategy_family(
        working[working["realized_pnl"].notna() & working["strategy_family"].astype(str).str.strip().ne("")]
    )


def _closed_trade_strategy_route_metrics(
    root: Optional[Path],
    *,
    as_of: str | dt.date | None = None,
) -> dict[str, dict[str, Any]]:
    if root is None:
        return {}
    resolved_root = Path(root).expanduser().resolve()
    out_root = resolved_root if resolved_root.name == "out" else resolved_root / "out"
    actual = _actual_calibration_frame(resolved_root, out_root, as_of=as_of)
    return _actual_forward_metrics_by_strategy_route(actual)


def _positive_closed_trade_strategy_families(
    root: Optional[Path],
    *,
    metrics_by_family: Optional[Mapping[str, Mapping[str, Any]]] = None,
) -> set[str]:
    if metrics_by_family is None:
        metrics_by_family = _closed_trade_strategy_family_metrics(root)
    if not metrics_by_family:
        return set()
    positive: set[str] = set()
    for family, metrics in metrics_by_family.items():
        family_text = _as_text(family)
        if not family_text:
            continue
        if _as_text(metrics.get("status")).upper() == "PASS":
            positive.add(family_text)
    return positive


def _positive_closed_trade_strategy_routes(
    root: Optional[Path],
    *,
    metrics_by_route: Optional[Mapping[str, Mapping[str, Any]]] = None,
) -> set[str]:
    if metrics_by_route is None:
        metrics_by_route = _closed_trade_strategy_route_metrics(root)
    if not metrics_by_route:
        return set()
    positive: set[str] = set()
    for route, metrics in metrics_by_route.items():
        route_text = _as_text(route)
        if route_text and _as_text(metrics.get("status")).upper() == "PASS":
            positive.add(route_text)
    return positive


def _positive_replay_strategy_routes(root: Optional[Path], *, as_of: dt.date) -> set[str]:
    if root is None:
        return set()
    resolved_root = Path(root).expanduser().resolve()
    out_root = resolved_root if resolved_root.name == "out" else resolved_root / "out"
    replay_root = _evidence_out_root_with_replay(resolved_root, out_root)
    replay, _, _ = _profitability_replay_frame(replay_root, as_of=as_of)
    if replay.empty or "strategy_route" not in replay.columns:
        return set()
    positive: set[str] = set()
    for route, group in replay.groupby("strategy_route", dropna=False):
        route_text = _as_text(route)
        if not route_text:
            continue
        metrics = _calibration_metrics_row(
            pd.to_numeric(group.get("pnl_1x", pd.Series(dtype=float)), errors="coerce"),
            status_func=_expectancy_status,
        )
        if _as_text(metrics.get("status")).upper() == "PASS":
            positive.add(route_text)
    return positive


def _candidate_strategy_routes(
    candidate: Mapping[str, Any],
    positive_strategy_routes: set[str],
    metrics_by_route: Mapping[str, Mapping[str, Any]],
    metrics_by_family: Mapping[str, Mapping[str, Any]],
    replay_supported_routes: Optional[set[str]] = None,
) -> list[dict[str, Any]]:
    bias = _as_text(candidate.get("bias")).lower()
    if bias not in {"bullish", "bearish"}:
        return []
    tier = _as_text(candidate.get("underlying_quality_tier")).lower()
    if not tier:
        tier, _ = _underlying_quality(candidate)
    core_or_liquid = tier in {"core", "liquid"}
    if not core_or_liquid:
        return [_strategy_route("bull_put_credit" if bias == "bullish" else "bear_call_credit", "audit_only_low_quality_underlying")]

    routes: list[dict[str, Any]] = []
    if bias == "bullish":
        short_put_replay_bridge = bool(
            replay_supported_routes
            and "short_put" in replay_supported_routes
            and _route_has_positive_or_near_ready_actual_evidence("short_put", metrics_by_route)
        )
        short_put_supported_routes = set(positive_strategy_routes)
        if short_put_replay_bridge:
            short_put_supported_routes.add("short_put")
        if ENABLE_CASH_SECURED_PUT_ROUTE and _candidate_prefers_short_put(candidate, short_put_supported_routes):
            routes.append(
                _strategy_route(
                    "short_put",
                    "positive_short_put_actual_evidence"
                    if "short_put" in positive_strategy_routes
                    else "positive_short_put_replay_with_near_ready_actual_evidence",
                )
            )
        routes.append(
            _strategy_route(
                "long_call",
                "bullish_core_independent_long_call_replay_route",
            )
        )
        routes.extend(
            [
                _strategy_route("bull_call_debit", "bullish_core_defined_risk_upside_route"),
                _strategy_route("bull_put_credit", "bullish_core_credit_route"),
            ]
        )
    else:
        routes.append(
            _strategy_route(
                "long_put",
                "bearish_core_independent_long_put_replay_route",
            )
        )
        routes.extend(
            [
                _strategy_route("bear_put_debit", "bearish_core_defined_risk_downside_route"),
                _strategy_route("bear_call_credit", "bearish_core_credit_route"),
            ]
        )

    seen: set[str] = set()
    out: list[dict[str, Any]] = []
    for route in routes:
        strategy = route["strategy"]
        if strategy in seen:
            continue
        seen.add(strategy)
        metrics, evidence_scope = _strategy_route_evidence(route, metrics_by_route, metrics_by_family)
        status = _as_text(metrics.get("status")).upper()
        route["route_evidence_scope"] = evidence_scope
        route["route_evidence_status"] = _as_text(metrics.get("status")) or "MISSING"
        route["route_evidence_sample_size"] = metrics.get("sample_size", "")
        route["route_evidence_avg_pnl"] = metrics.get("avg_pnl", "")
        route["route_evidence_profit_factor"] = metrics.get("profit_factor", "")
        if status == "BLOCK" and _strategy_evidence_metrics_are_negative(metrics):
            route["route_action"] = "construct_research_only_negative_family_evidence"
        elif status == "BLOCK":
            route["route_action"] = "construct_research_only_weak_family_evidence"
        elif status == "PASS" and strategy in FAMILY_LEVEL_STRATEGY_EXPECTANCY_FALLBACKS:
            route["route_action"] = "construct_allowed_positive_family_route"
        elif status == "PASS":
            route["route_action"] = (
                "construct_research_only_route_positive_ticker_proof_required"
                if evidence_scope == "strategy_route"
                else "construct_research_only_family_positive_ticker_proof_required"
            )
        else:
            route["route_action"] = "construct_research_only_expectancy_missing"
        out.append(route)
    return out


def _route_has_positive_or_near_ready_actual_evidence(
    strategy: str,
    metrics_by_route: Mapping[str, Mapping[str, Any]],
) -> bool:
    metrics = metrics_by_route.get(strategy) or {}
    sample = int(_as_float(metrics.get("sample_size")) or 0)
    avg_pnl = _as_float(metrics.get("avg_pnl"))
    profit_factor = _as_float(metrics.get("profit_factor"))
    status = _as_text(metrics.get("status")).upper()
    near_ready_sample = max(MIN_TICKER_EXPECTANCY_SAMPLE_SIZE, MIN_EXPECTANCY_SAMPLE_SIZE - 5)
    return bool(
        sample >= near_ready_sample
        and avg_pnl is not None
        and avg_pnl > 0
        and (profit_factor is None or math.isinf(profit_factor) or profit_factor >= 1.0)
        and status in {"WARN", "PASS"}
    )


def _strategy_route_evidence(
    route: Mapping[str, Any],
    metrics_by_route: Mapping[str, Mapping[str, Any]],
    metrics_by_family: Mapping[str, Mapping[str, Any]],
) -> tuple[Mapping[str, Any], str]:
    strategy = _as_text(route.get("strategy"))
    route_metrics = metrics_by_route.get(strategy)
    if route_metrics:
        return route_metrics, "strategy_route"
    family = _as_text(route.get("strategy_family"))
    family_metrics = metrics_by_family.get(family)
    if family_metrics:
        return family_metrics, "strategy_family"
    return {}, "missing"


def _strategy_evidence_metrics_are_negative(metrics: Mapping[str, Any]) -> bool:
    sample = int(_as_float(metrics.get("sample_size")) or 0)
    if sample < MIN_EXPECTANCY_SAMPLE_SIZE:
        return False
    avg_pnl = _as_float(metrics.get("avg_pnl"))
    profit_factor = _as_float(metrics.get("profit_factor"))
    return bool(
        (avg_pnl is not None and avg_pnl < 0)
        or (profit_factor is not None and profit_factor < 1.0)
    )


def _strategy_route(strategy: str, reason: str) -> dict[str, Any]:
    routes = {
        "short_put": {
            "bias": "bullish",
            "strategy_family": "short_put",
            "entry_type": "CREDIT",
            "direction": "Short Put",
            "structure": "cash secured put",
        },
        "bull_put_credit": {
            "bias": "bullish",
            "strategy_family": "vertical_spread",
            "entry_type": "CREDIT",
            "direction": "Bull Put",
            "structure": "bull put spread",
        },
        "bull_call_debit": {
            "bias": "bullish",
            "strategy_family": "vertical_spread",
            "entry_type": "DEBIT",
            "direction": "Bull Call",
            "structure": "bull call debit spread",
        },
        "bear_call_credit": {
            "bias": "bearish",
            "strategy_family": "vertical_spread",
            "entry_type": "CREDIT",
            "direction": "Bear Call",
            "structure": "bear call spread",
        },
        "bear_put_debit": {
            "bias": "bearish",
            "strategy_family": "vertical_spread",
            "entry_type": "DEBIT",
            "direction": "Bear Put",
            "structure": "bear put debit spread",
        },
        "long_call": {
            "bias": "bullish",
            "strategy_family": "long_call",
            "entry_type": "DEBIT",
            "direction": "Long Call",
            "structure": "long call",
        },
        "long_put": {
            "bias": "bearish",
            "strategy_family": "long_put",
            "entry_type": "DEBIT",
            "direction": "Long Put",
            "structure": "long put",
        },
    }
    route = dict(routes[strategy])
    route["strategy"] = strategy
    route["route_reason"] = reason
    route["route_action"] = "construct_research_only_expectancy_missing"
    return route


def _construct_strategy_route(candidate: Mapping[str, Any], hot: pd.DataFrame, route: Mapping[str, Any]) -> dict[str, Any]:
    strategy = _as_text(route.get("strategy"))
    if strategy == "short_put":
        constructed = construct_short_put(candidate, hot)
    elif strategy in {"long_call", "long_put"}:
        constructed = construct_long_option(candidate, hot, direction=_as_text(route.get("direction")))
    elif _as_text(route.get("entry_type")).upper() == "DEBIT":
        constructed = construct_debit_spread(candidate, hot, direction=_as_text(route.get("direction")))
    else:
        constructed = construct_credit_spread(candidate, hot)
    for column in (
        "iv_rank",
        "iv30d",
        "candidate_source",
        "next_earnings_dt",
        "hot_next_earnings_dt",
        "oi_next_earnings_dt",
        "dp_flow_bias",
        "dp_directional_ratio",
        "dp_directional_premium",
        "dp_total_premium",
        "dp_prints",
        "dark_pool_source_status",
    ):
        if not _as_text(constructed.get(column)):
            constructed[column] = candidate.get(column, "")
    return constructed


def _attach_strategy_route_metadata(
    row: Mapping[str, Any],
    route: Mapping[str, Any],
) -> dict[str, Any]:
    out = dict(row)
    family = _as_text(route.get("strategy_family"))
    out["strategy"] = _as_text(route.get("strategy"))
    out["strategy_family"] = family
    out["strategy_route"] = _as_text(route.get("strategy"))
    out["entry_type"] = _as_text(out.get("entry_type")) or _as_text(route.get("entry_type"))
    out["direction"] = _as_text(out.get("direction")) or _as_text(route.get("direction"))
    out["structure"] = _as_text(out.get("structure")) or _as_text(route.get("structure"))
    out["route_action"] = _as_text(route.get("route_action"))
    out["route_reason"] = _as_text(route.get("route_reason"))
    out["route_evidence_scope"] = _as_text(route.get("route_evidence_scope")) or "missing"
    out["route_evidence_status"] = _as_text(route.get("route_evidence_status")) or "MISSING"
    out["route_evidence_sample_size"] = route.get("route_evidence_sample_size", "")
    out["route_evidence_avg_pnl"] = route.get("route_evidence_avg_pnl", "")
    out["route_evidence_profit_factor"] = route.get("route_evidence_profit_factor", "")
    return out


def _strategy_route_audit_row(
    candidate: Mapping[str, Any],
    row: Mapping[str, Any],
    route: Mapping[str, Any],
    constructed_ok: bool,
) -> dict[str, Any]:
    family = _as_text(route.get("strategy_family"))
    return {
        "candidate_rank": candidate.get("candidate_rank", ""),
        "ticker": _as_text(candidate.get("ticker")).upper(),
        "bias": candidate.get("bias", ""),
        "underlying_quality_tier": candidate.get("underlying_quality_tier", ""),
        "macro_tape_direction": candidate.get("macro_tape_direction", ""),
        "strategy": route.get("strategy", ""),
        "strategy_family": family,
        "route_action": route.get("route_action", ""),
        "route_status": "constructed" if constructed_ok else "construction_failed",
        "route_reason": route.get("route_reason", ""),
        "evidence_scope": route.get("route_evidence_scope", "missing"),
        "evidence_status": route.get("route_evidence_status", "MISSING"),
        "evidence_sample_size": route.get("route_evidence_sample_size", ""),
        "evidence_avg_pnl": route.get("route_evidence_avg_pnl", ""),
        "evidence_profit_factor": route.get("route_evidence_profit_factor", ""),
        "selected_structure": row.get("structure", route.get("structure", "")),
        "selected_trade_plan": row.get("trade_plan", ""),
        "entry_type": route.get("entry_type", ""),
        "entry_limit": row.get("entry_limit", ""),
        "quality_gate_reason": row.get("quality_gate_reason", row.get("status_reason", "")),
    }


def _candidate_prefers_short_put(candidate: Mapping[str, Any], positive_strategy_families: set[str]) -> bool:
    if "short_put" not in positive_strategy_families:
        return False
    if _as_text(candidate.get("bias")).lower() != "bullish":
        return False
    tier = _as_text(candidate.get("underlying_quality_tier")).lower()
    if not tier:
        tier, _ = _underlying_quality(candidate)
    if tier != "core":
        return False
    if not _truthy(candidate.get("macro_tape_candidate")) and (_as_float(candidate.get("combined_flow_bias")) or 0.0) < MIN_DIRECTIONAL_BIAS:
        return False
    return True


def _live_chain_ticker_cap() -> Optional[int]:
    raw = os.environ.get(
        "UWOS_OPTIONS_AGENT_LIVE_CHAIN_TICKER_CAP",
        str(DEFAULT_LIVE_CHAIN_TICKER_CAP),
    ).strip().lower()
    if raw in {"", "0", "all", "none", "unlimited"}:
        return None
    try:
        value = int(float(raw))
    except (TypeError, ValueError):
        return None
    return value if value > 0 else None


def _replay_liquidity_backfill_day_cap() -> Optional[int]:
    raw = os.environ.get("UWOS_OPTIONS_AGENT_REPLAY_LIQUIDITY_DAY_CAP", "12").strip().lower()
    if raw in {"", "0", "all", "none", "unlimited"}:
        return None
    try:
        value = int(float(raw))
    except (TypeError, ValueError):
        return 12
    return value if value > 0 else None


_STRUCTURE_VETO_REJECT_PREFIXES = (
    "entry_credit_below_",
    "credit_width_ratio_below_",
    "entry_debit_required",
    "positive_max_profit_required",
    "short_put_cash_risk_unavailable",
    "debit_width_ratio_above_65pct",
)
_QUALITY_NOTE_REJECT_PREFIXES = (
    "directional_bias_below_",
    "signal_premium_below_",
    "one_lot_max_loss_above_",
    "external_agent_objective_blocker",
    "catalyst_objective_blocker",
)


def _is_structure_veto_reject(reason: str) -> bool:
    text = _as_text(reason)
    return bool(text) and text.startswith(_STRUCTURE_VETO_REJECT_PREFIXES)


def _is_quality_note_reject(reason: str) -> bool:
    text = _as_text(reason)
    return bool(text) and text.startswith(_QUALITY_NOTE_REJECT_PREFIXES)


def _selector_blocking_hard_rejects(row: Mapping[str, Any]) -> list[str]:
    """Return construction rejects that still wipe a row off the board.

    Flow, $1M premium, $750 1-lot, and agent echo are notes. They are not a
    reason to AVOID a live-validated structure or to hide the review surface.
    Width below 16% / credit below $0.25 still veto the structure.
    """

    return [
        part.strip()
        for part in _as_text(row.get("hard_rejects")).split(";")
        if part.strip()
        and not _is_quality_note_reject(part.strip())
        and _is_structure_veto_reject(part.strip())
    ]


def _send_now_credit_needs_live_chain(row: Mapping[str, Any]) -> bool:
    """Fetch a live chain for send-now-width credits even if dated volume/quote/flow are incomplete.

    Dated structure volume/OI/quote decide whether that specific contract can
    send now. They are not a reason to skip the Schwab chain: live construction
    may find a tighter, more liquid 25-30% alternative.
    """

    route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
    if route not in {"bull_put_credit", "bear_call_credit"}:
        return False
    if _selector_underlying_asset_class(row) == "etf":
        return False
    credit_width = _as_float(row.get("credit_width_ratio"))
    if credit_width is None or not MIN_SEND_NOW_CREDIT_WIDTH_RATIO <= credit_width <= 0.30:
        return False
    credit_dollars = _as_float(row.get("entry_credit"))
    if credit_dollars is None:
        credit_dollars = _as_float(row.get("credit"))
    if credit_dollars is None:
        credit_dollars = _as_float(row.get("target_entry"))
    if credit_dollars is not None and credit_dollars < MIN_SEND_NOW_CREDIT:
        return False
    return True


def _debit_vertical_needs_live_chain(row: Mapping[str, Any]) -> bool:
    """Fetch a live chain for priced debit verticals. After-hours Schwab is valid."""

    route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
    if route not in {"bull_call_debit", "bear_put_debit"}:
        return False
    if _selector_underlying_asset_class(row) == "etf":
        return False
    dte = int(_as_float(row.get("dte")) or 0)
    if dte and not MIN_LIVE_DTE <= dte <= 45:
        return False
    debit = _as_float(row.get("entry_debit"))
    if debit is None:
        debit = _as_float(row.get("entry_limit"))
    if debit is None:
        debit = _as_float(row.get("target_entry"))
    return debit is None or debit > 0


def _active_selector_source_preflight_ready(row: Mapping[str, Any]) -> bool:
    """Reserve live-chain capacity for source-qualified promoted-lane candidates.

    This deliberately uses only source-session properties that were available
    to the replay. It is a validation-priority hint, not a selector approval:
    live expected-move, quote-width, and contract-quality gates still decide
    whether a candidate can reach the order surface.
    """

    policy = _promoted_selector_policy_definition()
    if not policy:
        return False
    route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
    entry_type = _as_text(row.get("entry_type")).upper() or _entry_type_from_route(route)
    allowed_entry_types = {
        _as_text(value).upper()
        for value in policy.get("allowed_entry_types", ())
        if _as_text(value)
    }
    allowed_routes = {
        _as_text(value)
        for value in policy.get("allowed_strategy_routes", ())
        if _as_text(value)
    }
    required_tiers = {
        _as_text(value).lower()
        for value in policy.get("required_underlying_tiers", ())
        if _as_text(value)
    }
    if allowed_entry_types and entry_type not in allowed_entry_types:
        return False
    if allowed_routes and route not in allowed_routes:
        return False
    if required_tiers and _as_text(row.get("underlying_quality_tier")).lower() not in required_tiers:
        return False
    if _as_text(policy.get("replay_asset_class")).lower() == "common_stock" and _selector_underlying_asset_class(row) == "etf":
        return False
    if _selector_blocking_hard_rejects(row) or _earnings_within_planned_holding_horizon(row):
        return False
    if _active_selector_direct_ticker_evidence_negative(row):
        return False
    if entry_type != "CREDIT":
        return False
    dte = int(_as_float(row.get("dte")) or 0)
    minimum_dte = int(_as_float(policy.get("min_credit_dte")) or 7)
    maximum_dte = int(_as_float(policy.get("max_credit_dte")) or 45)
    if not minimum_dte <= dte <= maximum_dte:
        return False
    minimum_volume = _as_float(policy.get("min_contract_volume"))
    contract_volume = _selector_contract_volume(row)
    if minimum_volume is not None and (contract_volume is None or contract_volume < minimum_volume):
        return False
    credit_width = _as_float(row.get("credit_width_ratio"))
    if credit_width is None or not MIN_SEND_NOW_CREDIT_WIDTH_RATIO <= credit_width <= 0.30:
        return False
    quote_width = _as_float(row.get("entry_quote_width_pct"))
    if quote_width is None:
        quote_width = _as_float(row.get("live_quote_width_pct"))
    if quote_width is not None and quote_width > MAX_SELECTOR_ENTRY_QUOTE_WIDTH_PCT:
        return False
    credit_dollars = _as_float(row.get("entry_credit"))
    if credit_dollars is None:
        credit_dollars = _as_float(row.get("credit"))
    if credit_dollars is not None and credit_dollars < MIN_SEND_NOW_CREDIT:
        return False
    return True


def _active_selector_live_credit_dte_window(
    row: Mapping[str, Any],
) -> Optional[tuple[int, int]]:
    """Return the frozen selector's live-replacement DTE window when applicable."""

    if not _active_selector_source_preflight_ready(row):
        return None
    policy = _promoted_selector_policy_definition()
    if not policy:
        return None
    return (
        int(_as_float(policy.get("min_credit_dte")) or 7),
        int(_as_float(policy.get("max_credit_dte")) or 45),
    )


def _active_selector_direct_ticker_evidence_negative(row: Mapping[str, Any]) -> bool:
    """Keep mature ticker losses out of the live-validation priority lane.

    The promoted lane's replay is the relevant route evidence. A sparse or
    generic managed-route cohort can remain diagnostic, but must not crowd out
    a source-qualified candidate before live pricing. Mature direct ticker
    losses remain a hard exclusion from this priority lane.
    """

    for prefix in ("actual_forward_expectancy", "actual_forward_strategy_expectancy"):
        if prefix == "actual_forward_strategy_expectancy":
            scope = _as_text(row.get(f"{prefix}_scope")).lower()
            if scope and scope not in {"ticker", "ticker_route", "ticker_strategy"}:
                continue
        status = _as_text(row.get(f"{prefix}_status")).upper()
        sample = int(_as_float(row.get(f"{prefix}_sample_size")) or 0)
        if status == "BLOCK" and sample >= MIN_TICKER_EXPECTANCY_SAMPLE_SIZE:
            if _expectancy_values_are_negative(row, prefix):
                return True
    return False


def _live_validation_priority_score(row: Mapping[str, Any]) -> float:
    score = _as_float(row.get("score"))
    if score is None or not math.isfinite(score):
        score = 0.0
    status = _as_text(row.get("recommendation_status")).upper()
    quality = _as_text(row.get("trade_quality_status")).upper()
    route_status = _as_text(row.get("route_evidence_status")).upper()
    tier = _as_text(row.get("underlying_quality_tier")).lower()
    if status in {RecommendationStatus.ENTER.value, RecommendationStatus.ENTER_WITH_PORTFOLIO_RISK.value}:
        score += 1000.0
    elif status in {RecommendationStatus.WAIT_FOR_PRICE.value, RecommendationStatus.REVIEW.value}:
        score += 250.0
    if _truthy(row.get("visible_in_final_board")):
        score += 200.0
    if quality == "PASS":
        score += 100.0
    if route_status == "POSITIVE":
        score += 75.0
    elif route_status == "WEAK_POSITIVE":
        score += 35.0
    if tier == "core":
        score += 25.0
    review_count = _as_float(row.get("external_agent_distinct_review_count"))
    if review_count is None:
        review_count = 0.0
    if math.isfinite(review_count):
        score += min(review_count, 4.0) * 10.0
    if _active_selector_source_preflight_ready(row):
        score += 2000.0
    elif _send_now_credit_needs_live_chain(row) or _debit_vertical_needs_live_chain(row):
        score += 1500.0
    return score


def _allowed_live_validation_tickers(priced: pd.DataFrame, *, enabled: bool) -> tuple[set[str], Optional[int], int]:
    tickers = {
        _as_text(value).upper()
        for value in priced.get("ticker", pd.Series(dtype=object)).tolist()
        if _as_text(value).strip()
    }
    if not enabled:
        return tickers, None, 0
    cap = _live_chain_ticker_cap()
    if cap is None or len(tickers) <= cap:
        return tickers, cap, 0
    priorities: dict[str, float] = {}
    source_qualified_tickers: set[str] = set()
    for row in priced.to_dict("records"):
        ticker = _as_text(row.get("ticker")).upper()
        if not ticker:
            continue
        priorities[ticker] = max(priorities.get(ticker, -math.inf), _live_validation_priority_score(row))
        if (
            _active_selector_source_preflight_ready(row)
            or _send_now_credit_needs_live_chain(row)
            or _debit_vertical_needs_live_chain(row)
        ):
            source_qualified_tickers.add(ticker)
    explicit_cap = bool(
        os.environ.get("UWOS_OPTIONS_AGENT_LIVE_CHAIN_TICKER_CAP", "").strip()
    )
    if not explicit_cap:
        # The default remains bounded, but it must never exclude a ticker that
        # can enter the promoted selector after live repricing. Explicit
        # operator overrides remain hard limits for rate-control emergencies.
        cap = max(cap, len(source_qualified_tickers))
    ordered = sorted(tickers, key=lambda ticker: (-priorities.get(ticker, -math.inf), ticker))
    allowed = set(ordered[:cap])
    return allowed, cap, len(tickers) - len(allowed)


def _acceptable_live_quote_sessions(
    asof_date: dt.date,
    now: Optional[dt.datetime] = None,
) -> set[dt.date]:
    """Sessions that count as a live Schwab quote for EOD analysis.

    Groko prices yesterday's UW folder after the close and the next morning.
    Exact as-of matching marked today's Schwab stamps STALE and zeroed send-now
    every session. Accept the UW date, the latest observable regular session,
    the prior regular session, and today's calendar date (overnight stamps).
    """

    current = _market_datetime(now)
    latest = _latest_observable_regular_market_session_date(current)
    prior = _latest_regular_market_day_on_or_before(latest - dt.timedelta(days=1))
    return {asof_date, latest, prior, current.date()}


def _live_quote_sessions_are_fresh(
    quoted_sessions: set[dt.date],
    asof_date: dt.date,
    now: Optional[dt.datetime] = None,
) -> bool:
    """A chain is usable when any quote stamp lands on an allowed session.

    Requiring max(quote dates) to equal as-of zeroed the book whenever one
    far-dated contract carried a newer timestamp than the rest of the chain.
    """

    if not quoted_sessions:
        return False
    return not quoted_sessions.isdisjoint(_acceptable_live_quote_sessions(asof_date, now=now))


def _contracts_quoted_on_session(contracts: pd.DataFrame, session_date: dt.date) -> pd.DataFrame:
    """Keep a live order from using an individually stale option contract."""

    if contracts is None or contracts.empty or "quote_date" not in contracts.columns:
        return pd.DataFrame(columns=contracts.columns if contracts is not None else None)
    quote_dates = contracts["quote_date"].map(_row_date)
    allowed = _acceptable_live_quote_sessions(session_date)
    fresh = contracts.loc[quote_dates.isin(allowed)].copy()
    if fresh.empty:
        return fresh
    newest = fresh["quote_date"].map(_row_date).max()
    return fresh.loc[fresh["quote_date"].map(_row_date).eq(newest)].copy()


def _fresh_reprice_reviewed_contract(
    row: Mapping[str, Any],
    contracts: pd.DataFrame,
    *,
    spot: float,
    asof_date: dt.date,
    chain_source: str,
) -> tuple[Optional[dict[str, Any]], str]:
    """Reprice the exact reviewed legs without allowing pass 2 to choose replacements."""

    from ._vendor.schwab_live import find_credit_spread_alternatives, find_debit_spread_alternatives

    reviewed_key = contract_review_key(row)
    expiry = _row_date(row.get("expiry"))
    if not reviewed_key or expiry is None:
        return None, "reviewed contract identity or expiry is missing"
    route = _as_text(row.get("strategy_route") or row.get("strategy")).lower()
    if _strategy_family_from_ticket_row(row) == "short_put":
        direction = "Short Put"
        right = "P"
        wanted_strikes = [_as_float(row.get("short_strike"))]
    elif _route_prefers_long_option(row):
        direction = _long_option_direction(row)
        right = _direction_right(direction)
        wanted_strikes = [_as_float(row.get("long_strike"))]
    elif _route_prefers_debit_spread(row):
        direction = _debit_direction(row)
        right = _direction_right(direction)
        wanted_strikes = [_as_float(row.get("long_strike")), _as_float(row.get("short_strike"))]
    else:
        direction = _credit_direction(row)
        right = _direction_right(direction)
        wanted_strikes = [_as_float(row.get("short_strike")), _as_float(row.get("long_strike"))]
    wanted = [strike for strike in wanted_strikes if strike is not None and strike > 0]
    expected_leg_count = 1 if direction in {"Short Put", "Long Call", "Long Put"} else 2
    if len(wanted) != expected_leg_count:
        return None, "reviewed contract strikes are incomplete"

    strike_values = pd.to_numeric(contracts.get("strike", pd.Series(dtype=float)), errors="coerce")
    expiry_values = contracts.get("expiry", pd.Series(dtype=object))
    right_values = contracts.get("right", pd.Series(dtype=object)).astype(str)
    strike_mask = pd.Series(False, index=contracts.index)
    for strike in wanted:
        strike_mask |= strike_values.sub(strike).abs().le(0.0001)
    exact_chain = contracts[expiry_values.eq(expiry) & right_values.eq(right) & strike_mask].copy()
    exact_strikes = {
        round(float(value), 4)
        for value in pd.to_numeric(exact_chain.get("strike", pd.Series(dtype=float)), errors="coerce").dropna()
    }
    if len(exact_strikes) != expected_leg_count:
        return None, "fresh Schwab chain does not contain every reviewed leg"

    if direction == "Short Put":
        alternatives = _find_short_put_alternatives(
            exact_chain,
            expiry=expiry,
            spot=spot,
            expected_move_pct=_expected_move_pct_for_expiry(row, expiry, asof_date),
            max_alternatives=2,
        )
        best = _select_live_short_put_alternative(row, alternatives)
        if _as_text(best.get("live_status")).upper() != "PASS":
            return None, _as_text(best.get("live_blocker") or best.get("live_status") or "exact short put failed fresh pricing")
        updated = _apply_live_short_put(
            row,
            best,
            expiry=expiry,
            spot=spot,
            asof_date=asof_date,
            chain_source=chain_source,
        )
    elif direction in {"Long Call", "Long Put"}:
        alternatives = _find_long_option_alternatives(
            exact_chain,
            direction=direction,
            expiry=expiry,
            spot=spot,
            anchor_strike=wanted[0],
            asof_date=asof_date,
            max_alternatives=2,
        )
        best = _select_live_long_option_alternative(row, alternatives)
        if _as_text(best.get("live_status")).upper() != "PASS":
            return None, _as_text(best.get("live_blocker") or best.get("live_status") or "exact long option failed fresh pricing")
        updated = _apply_live_long_option(
            row,
            best,
            direction=direction,
            expiry=expiry,
            spot=spot,
            asof_date=asof_date,
            chain_source=chain_source,
        )
    elif route in {"bull_call_debit", "bear_put_debit"} or direction in {"Bull Call", "Bear Put"}:
        alternatives = _options_agent_debit_spread_alternatives(
            exact_chain,
            direction=direction,
            expiry=expiry,
            spot=spot,
            preferred_width=abs(wanted[1] - wanted[0]),
            anchor_strike=_as_float(row.get("long_strike")),
            expected_move_pct=_expected_move_pct_for_expiry(row, expiry, asof_date),
            as_of_date=asof_date,
            max_alternatives=4,
        )
        for alternative in alternatives:
            alternative["selected_expiry"] = expiry.isoformat()
            alternative["dte"] = (expiry - asof_date).days
        best = _select_live_alternative(row, alternatives, entry_type="DEBIT")
        if _as_text(best.get("live_status")).upper() != "PASS":
            return None, _as_text(best.get("live_blocker") or best.get("live_status") or "exact debit spread failed fresh pricing")
        updated = _apply_live_debit_spread(
            row,
            best,
            direction=direction,
            expiry=expiry,
            spot=spot,
            asof_date=asof_date,
            chain_source=chain_source,
        )
    else:
        alternatives = _options_agent_credit_spread_alternatives(
            exact_chain,
            direction=direction,
            expiry=expiry,
            spot=spot,
            preferred_width=abs(wanted[1] - wanted[0]),
            anchor_strike=_as_float(row.get("short_strike")),
            expected_move_pct=_expected_move_pct_for_expiry(row, expiry, asof_date),
            as_of_date=asof_date,
            max_alternatives=4,
        )
        for alternative in alternatives:
            alternative["selected_expiry"] = expiry.isoformat()
            alternative["dte"] = (expiry - asof_date).days
        best = _select_live_alternative(row, alternatives, entry_type="CREDIT")
        if _as_text(best.get("live_status")).upper() != "PASS":
            return None, _as_text(best.get("live_blocker") or best.get("live_status") or "exact credit spread failed fresh pricing")
        updated = _apply_live_credit_spread(
            row,
            best,
            direction=direction,
            expiry=expiry,
            spot=spot,
            asof_date=asof_date,
            chain_source=chain_source,
        )

    if contract_review_key(updated) != reviewed_key:
        return None, "fresh exact-leg repricing changed the reviewed contract identity"
    updated["live_validation_status"] = "PASS"
    updated["live_validation_note"] = _append_reason(
        updated.get("status_reason"),
        "fresh Schwab quote retained the exact subagent-reviewed legs",
    )
    updated["live_chain_source"] = chain_source
    updated["construction_source"] = "reviewed_contract_fresh_reprice"
    updated["construction_reason"] = "fresh Schwab quote for the exact subagent-reviewed legs"
    return updated, ""


def _credit_vertical_route(row: Mapping[str, Any]) -> bool:
    route = _as_text(row.get("strategy_route") or row.get("strategy")).lower() or _strategy_route_from_row(row)
    return route in {"bull_put_credit", "bear_call_credit"}


def _credit_send_now_economics_ok(row: Mapping[str, Any]) -> bool:
    """True when a live/dated credit still clears send-now 25-30% / $0.50 / quote ≤25%."""

    if _as_text(row.get("entry_type")).upper() != "CREDIT" and not _credit_vertical_route(row):
        return False
    credit = _as_float(row.get("entry_limit"))
    if credit is None:
        credit = _as_float(row.get("entry_credit"))
    if credit is None:
        credit = _as_float(row.get("credit"))
    width_ratio = _as_float(row.get("credit_width_ratio"))
    quote_width = _as_float(row.get("live_quote_width_pct"))
    if quote_width is None:
        quote_width = _as_float(row.get("entry_quote_width_pct"))
    return bool(
        credit is not None
        and credit >= MIN_SEND_NOW_CREDIT
        and width_ratio is not None
        and MIN_SEND_NOW_CREDIT_WIDTH_RATIO <= width_ratio <= 0.30
        and (quote_width is None or quote_width <= MAX_SELECTOR_ENTRY_QUOTE_WIDTH_PCT)
    )


def _collect_live_credit_alternatives(
    row: Mapping[str, Any],
    contracts: pd.DataFrame,
    *,
    spot: float,
    asof_date: dt.date,
    preferred_expiry: Optional[dt.date],
    event_calendar: Optional[Mapping[str, Any]] = None,
) -> list[dict[str, Any]]:
    """Enumerate live credit verticals in the promoted 7-45 window."""

    _ = event_calendar
    direction = _credit_direction(row)
    selector_credit_dte_window = _active_selector_live_credit_dte_window(row)
    credit_expiries = _live_expiry_candidates(
        contracts,
        asof_date,
        preferred_expiry,
        direction,
        minimum_dte=(selector_credit_dte_window or (None, None))[0],
        maximum_dte=(selector_credit_dte_window or (None, None))[1],
    )
    alternatives: list[dict[str, Any]] = []
    for candidate_expiry in credit_expiries:
        expiry_alternatives = _options_agent_credit_spread_alternatives(
            contracts,
            direction=direction,
            expiry=candidate_expiry,
            spot=spot,
            preferred_width=_preferred_width(row),
            anchor_strike=_as_float(row.get("anchor_strike") or row.get("short_strike")),
            expected_move_pct=_expected_move_pct_for_expiry(row, candidate_expiry, asof_date),
            as_of_date=asof_date,
            max_alternatives=8,
        )
        for alternative in expiry_alternatives:
            alternative["selected_expiry"] = candidate_expiry.isoformat()
            alternative["dte"] = (candidate_expiry - asof_date).days
        alternatives.extend(expiry_alternatives)
    return alternatives


def _recover_live_send_now_credit(
    row: Mapping[str, Any],
    contracts: pd.DataFrame,
    *,
    spot: float,
    asof_date: dt.date,
    chain_source: str,
    event_calendar: Optional[Mapping[str, Any]] = None,
) -> Optional[dict[str, Any]]:
    """Replace a cheapened/widened reviewed credit with a live 25-30% send-now.

    Exact-leg pass-2 kept dated strikes after the tape moved. Neighboring
    strikes on the same chain still paid send-now and were discarded.
    """

    if not _credit_vertical_route(row) or contracts is None or contracts.empty:
        return None
    current = dict(row)
    current["spot_live"] = spot
    alternatives = _collect_live_credit_alternatives(
        current,
        contracts,
        spot=spot,
        asof_date=asof_date,
        preferred_expiry=_row_date(current.get("expiry")),
        event_calendar=event_calendar,
    )
    send_now = [
        alternative
        for alternative in alternatives
        if _as_text(alternative.get("live_status")).upper() == "PASS"
        and _live_alternative_send_now_economics(alternative, entry_type="CREDIT")
    ]
    if not send_now:
        return None
    best = _select_live_alternative(
        current,
        send_now,
        entry_type="CREDIT",
        event_calendar=event_calendar,
        as_of=asof_date,
    )
    if _as_text(best.get("live_status")).upper() != "PASS":
        return None
    expiry = _row_date(best.get("selected_expiry"))
    if expiry is None:
        return None
    updated = _apply_live_credit_spread(
        current,
        best,
        direction=_credit_direction(current),
        expiry=expiry,
        spot=spot,
        asof_date=asof_date,
        chain_source=chain_source,
    )
    if not _credit_send_now_economics_ok(updated):
        return None
    original_key = contract_review_key(current)
    recovered_key = contract_review_key(updated)
    updated["live_validation_status"] = "PASS"
    updated["construction_source"] = "live_send_now_recovery"
    updated["live_chain_source"] = chain_source
    note = (
        "live chain recovered a 25-30% send-now credit after the reviewed structure "
        "cheapened or widened"
    )
    if original_key and recovered_key and original_key != recovered_key:
        note = f"{note}; replaced reviewed legs"
    updated["live_validation_note"] = _append_reason(updated.get("status_reason"), note)
    updated["construction_reason"] = note
    return updated


def validate_priced_candidates_live(
    priced: pd.DataFrame,
    as_of: str | dt.date,
    out_dir: Path,
    *,
    chain_snapshot_dir: Optional[Path] = None,
    strike_count: int = 80,
    allow_live_fallback: bool = True,
    market_session_open: Optional[bool] = None,
    reviewed_contract_keys: Optional[set[str]] = None,
    market_regime: Optional[Mapping[str, Any]] = None,
    event_calendar: Optional[Mapping[str, Any]] = None,
) -> tuple[pd.DataFrame, pd.DataFrame, list[str]]:
    """Replace dated pricing with live/snapshot Schwab chain alternatives when available."""

    if priced.empty:
        return priced.copy(), empty_live_validation_frame(), []

    from ._vendor.schwab_live import (
        SchwabChainValidator,
        chain_quote_dates,
        chain_spot,
        chain_to_contracts,
        find_credit_spread_alternatives,
        find_debit_spread_alternatives,
    )

    asof_date = parse_as_of(as_of)
    validator = SchwabChainValidator(
        out_dir,
        strike_count=int(strike_count),
        snapshot_dir=chain_snapshot_dir,
        allow_live_fallback=allow_live_fallback,
    )
    market_closed_live_recheck = bool(
        chain_snapshot_dir is None
        and allow_live_fallback
        and market_session_open is False
    )
    live_ticker_cap_enabled = chain_snapshot_dir is None and allow_live_fallback
    allowed_live_tickers, live_ticker_cap, deferred_ticker_count = _allowed_live_validation_tickers(
        priced,
        enabled=live_ticker_cap_enabled,
    )
    rows: list[dict[str, Any]] = []
    audit: list[dict[str, Any]] = []
    notes: list[str] = []
    reviewed_keys = {
        _as_text(value)
        for value in (reviewed_contract_keys or set())
        if _as_text(value)
    }
    input_route_keys = {
        (
            _as_text(row.get("ticker")).upper(),
            (
                _as_text(row.get("strategy_route") or row.get("strategy")).lower()
                or _strategy_route_from_row(row)
            ),
        )
        for row in priced.to_dict("records")
        if _as_text(row.get("ticker"))
    }
    run_regime = _regime_bucket(
        market_regime.get("regime") if isinstance(market_regime, Mapping) else ""
    )
    if live_ticker_cap_enabled and deferred_ticker_count > 0:
        notes.append(
            f"live Schwab chain validation limited to top {live_ticker_cap} tickers; "
            f"{deferred_ticker_count} lower-priority tickers deferred"
        )
    unavailable_source_label = "Schwab snapshot chain" if chain_snapshot_dir is not None and not allow_live_fallback else "live Schwab chain"
    for _, row in priced.iterrows():
        current = row.to_dict()
        current_regime = _regime_bucket(current.get("regime") or current.get("market_regime"))
        if current_regime == "regime_unknown" and run_regime != "regime_unknown":
            current["regime"] = run_regime
        ticker = str(current.get("ticker") or "").strip().upper()
        if not ticker:
            rows.append(current)
            continue
        if ticker not in allowed_live_tickers:
            message = (
                f"live Schwab chain validation deferred by top-{live_ticker_cap} ticker cap; "
                "not eligible for send-now order entry until rerun with live validation"
            )
            current["live_validation_status"] = "LIVE_CHAIN_DEFERRED"
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(current.get("status_reason"), message)
            rows.append(current)
            audit.append(_live_audit_row(current, "LIVE_CHAIN_DEFERRED", message, ""))
            continue

        preferred_expiry = _row_date(current.get("expiry")) or _row_date(current.get("anchor_expiry"))
        # The validator caches one chain per ticker, so every first request must expose the
        # full trade window. Otherwise a short-DTE anchor hides safer expiries from every
        # later route for the same underlying.
        query_from = asof_date + dt.timedelta(days=MIN_LIVE_DTE)
        query_to = asof_date + dt.timedelta(days=MAX_LIVE_DTE)
        chain = validator.get_chain(ticker, query_from, query_to)
        if not chain:
            message = validator.errors.get(ticker, "no live chain returned")
            if market_closed_live_recheck and _has_complete_target_math(current):
                updated = _preserve_market_closed_target_recheck(current, message)
                rows.append(updated)
                audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                continue
            current["live_validation_status"] = "CHAIN_UNAVAILABLE"
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(
                current.get("status_reason"),
                f"{unavailable_source_label} unavailable; keep as visible review row",
            )
            rows.append(current)
            audit.append(_live_audit_row(current, "CHAIN_UNAVAILABLE", message, validator.sources.get(ticker, "")))
            continue

        if chain_snapshot_dir is None and allow_live_fallback:
            quoted_sessions = chain_quote_dates(chain)
            allowed_sessions = _acceptable_live_quote_sessions(asof_date)
            if not _live_quote_sessions_are_fresh(quoted_sessions, asof_date):
                available = ", ".join(sorted(day.isoformat() for day in quoted_sessions)) or "none"
                allowed = ", ".join(sorted(day.isoformat() for day in allowed_sessions)) or "none"
                message = (
                    f"live chain quote session mismatch: as-of {asof_date.isoformat()}, "
                    f"allowed {allowed}, received {available}; do not use this chain for order entry"
                )
                current["live_validation_status"] = "STALE_LIVE_QUOTE"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(
                    _live_audit_row(
                        current,
                        "STALE_LIVE_QUOTE",
                        message,
                        validator.sources.get(ticker, ""),
                    )
                )
                continue

        contracts = chain_to_contracts(chain)
        if chain_snapshot_dir is None and allow_live_fallback:
            contracts = _contracts_quoted_on_session(contracts, asof_date)
        spot = chain_spot(chain)
        if contracts.empty or not math.isfinite(spot):
            message = (
                "live chain has no current-session option contracts or no usable underlying price"
                if chain_snapshot_dir is None and allow_live_fallback
                else "chain returned no contracts or no usable underlying price"
            )
            if market_closed_live_recheck and _has_complete_target_math(current):
                updated = _preserve_market_closed_target_recheck(current, message)
                rows.append(updated)
                audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                continue
            current["live_validation_status"] = "NO_USABLE_CHAIN"
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(current.get("status_reason"), message)
            rows.append(current)
            audit.append(_live_audit_row(current, "NO_USABLE_CHAIN", message, validator.sources.get(ticker, "")))
            continue

        current_contract_key = contract_review_key(current)
        if current_contract_key and current_contract_key in reviewed_keys:
            chain_source = validator.sources.get(ticker, "")
            updated, exact_error = _fresh_reprice_reviewed_contract(
                current,
                contracts,
                spot=spot,
                asof_date=asof_date,
                chain_source=chain_source,
            )
            recovered = None
            exact_off_send_now = bool(
                _credit_vertical_route(current)
                and (updated is None or not _credit_send_now_economics_ok(updated))
            )
            if exact_off_send_now:
                recovered = _recover_live_send_now_credit(
                    current,
                    contracts,
                    spot=spot,
                    asof_date=asof_date,
                    chain_source=chain_source,
                    event_calendar=event_calendar,
                )
            if recovered is not None:
                rows.append(recovered)
                audit.append(_live_audit_row(recovered, "PASS", recovered["live_validation_note"], chain_source))
                continue
            if updated is None:
                message = _append_reason(
                    "fresh exact-contract repricing failed",
                    exact_error or "reviewed legs are unavailable",
                )
                current["live_validation_status"] = "EXACT_CONTRACT_REPRICE_FAILED"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, "EXACT_CONTRACT_REPRICE_FAILED", message, chain_source))
                continue
            rows.append(updated)
            audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))
            continue

        current_route = (
            _as_text(current.get("strategy_route") or current.get("strategy")).lower()
            or _strategy_route_from_row(current)
        )
        fallback_debit_direction = _debit_direction(current)
        fallback_debit_route = (
            "bull_call_debit"
            if fallback_debit_direction == "Bull Call"
            else "bear_put_debit"
        )
        parallel_debit_route_present = bool(
            current_route in {"bull_put_credit", "bear_call_credit"}
            and (ticker, fallback_debit_route) in input_route_keys
        )

        if reviewed_keys:
            message = (
                "contract was not included in the immutable pass-1 review snapshot; "
                "keep as diagnostic and do not construct replacement legs"
            )
            current["live_validation_status"] = "REVIEW_SNAPSHOT_EXCLUDED"
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(current.get("status_reason"), message)
            current["construction_source"] = "unreviewed_snapshot_diagnostic"
            rows.append(current)
            audit.append(
                _live_audit_row(
                    current,
                    "REVIEW_SNAPSHOT_EXCLUDED",
                    message,
                    validator.sources.get(ticker, ""),
                )
            )
            continue

        if _strategy_family_from_ticket_row(current) == "short_put":
            expiry = _select_live_expiry(contracts, asof_date, preferred_expiry, "Bull Put")
            if expiry is None:
                message = "no suitable Schwab-chain expiry for short-put construction"
                if market_closed_live_recheck and _has_complete_target_math(current):
                    updated = _preserve_market_closed_target_recheck(current, message)
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                    continue
                current["live_validation_status"] = "NO_LIVE_EXPIRY"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
                continue
            alternatives = _find_short_put_alternatives(
                contracts,
                expiry=expiry,
                spot=spot,
                expected_move_pct=_expected_move_pct_for_expiry(current, expiry, asof_date),
                max_alternatives=8,
            )
            best = _select_live_short_put_alternative(current, alternatives)
            if best.get("live_status") != "PASS":
                message = str(best.get("live_blocker") or best.get("live_status") or "live chain did not produce a valid short put")
                if market_closed_live_recheck and _has_complete_target_math(current):
                    updated = _preserve_market_closed_target_recheck(current, message)
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                    continue
                current["live_validation_status"] = str(best.get("live_status") or "NO_LIVE_SHORT_PUT")
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, current["live_validation_status"], message, validator.sources.get(ticker, "")))
                continue
            chain_source = validator.sources.get(ticker, "")
            updated = _apply_live_short_put(
                current,
                best,
                expiry=expiry,
                spot=spot,
                asof_date=asof_date,
                chain_source=chain_source,
            )
            if market_closed_live_recheck:
                preserved = _preserve_target_when_closed_market_quote_is_transiently_bad(
                    current,
                    updated,
                )
                if preserved is not None:
                    rows.append(preserved)
                    audit.append(
                        _live_audit_row(
                            preserved,
                            "TARGET_QUOTE_REFRESH",
                            preserved["live_validation_note"],
                            chain_source,
                        )
                    )
                    continue
            updated["live_validation_status"] = "PASS"
            updated["live_validation_note"] = str(updated.get("status_reason") or best.get("construction_reason") or "chain validated")
            updated["live_chain_source"] = chain_source
            rows.append(updated)
            audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))
            continue

        if _route_prefers_long_option(current):
            long_direction = _long_option_direction(current)
            long_expiries = _live_expiry_candidates(
                contracts,
                asof_date,
                preferred_expiry,
                long_direction,
            )
            if not long_expiries:
                message = "no suitable Schwab-chain expiry for long-option construction"
                if market_closed_live_recheck and _has_complete_target_math(current):
                    updated = _preserve_market_closed_target_recheck(current, message)
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                    continue
                current["live_validation_status"] = "NO_LIVE_EXPIRY"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
                continue
            long_alternatives: list[dict[str, Any]] = []
            for candidate_expiry in long_expiries:
                expiry_alternatives = _find_long_option_alternatives(
                    contracts,
                    direction=long_direction,
                    expiry=candidate_expiry,
                    spot=spot,
                    anchor_strike=_as_float(current.get("anchor_strike")),
                    asof_date=asof_date,
                    max_alternatives=8,
                )
                for alternative in expiry_alternatives:
                    alternative["selected_expiry"] = candidate_expiry.isoformat()
                long_alternatives.extend(expiry_alternatives)
            long_best = _select_live_long_option_alternative(current, long_alternatives)
            if long_best.get("live_status") != "PASS":
                message = str(long_best.get("live_blocker") or long_best.get("live_status") or "live chain did not produce a valid long option")
                if market_closed_live_recheck and _has_complete_target_math(current):
                    updated = _preserve_market_closed_target_recheck(current, message)
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                    continue
                current["live_validation_status"] = str(long_best.get("live_status") or "NO_LIVE_LONG_OPTION")
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, current["live_validation_status"], message, validator.sources.get(ticker, "")))
                continue
            long_expiry = _row_date(long_best.get("selected_expiry"))
            if long_expiry is None:
                message = "selected long-option alternative did not retain its expiry"
                current["live_validation_status"] = "NO_LIVE_EXPIRY"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
                continue
            chain_source = validator.sources.get(ticker, "")
            updated = _apply_live_long_option(
                current,
                long_best,
                direction=long_direction,
                expiry=long_expiry,
                spot=spot,
                asof_date=asof_date,
                chain_source=chain_source,
            )
            if market_closed_live_recheck:
                preserved = _preserve_target_when_closed_market_quote_is_transiently_bad(
                    current,
                    updated,
                )
                if preserved is not None:
                    rows.append(preserved)
                    audit.append(
                        _live_audit_row(
                            preserved,
                            "TARGET_QUOTE_REFRESH",
                            preserved["live_validation_note"],
                            chain_source,
                        )
                    )
                    continue
            updated["live_validation_status"] = "PASS"
            updated["live_validation_note"] = str(
                updated.get("status_reason") or long_best.get("construction_reason") or "chain validated"
            )
            updated["live_chain_source"] = chain_source
            rows.append(updated)
            audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))
            continue

        if _route_prefers_debit_spread(current):
            debit_direction = _debit_direction(current)
            debit_min_dte, debit_max_dte = _debit_vertical_preferred_dte_window(debit_direction)
            debit_expiries = _live_expiry_candidates(
                contracts,
                asof_date,
                preferred_expiry,
                debit_direction,
                minimum_dte=debit_min_dte,
                maximum_dte=debit_max_dte,
            )
            if not debit_expiries and debit_min_dte > MIN_LIVE_DTE:
                debit_expiries = _live_expiry_candidates(
                    contracts,
                    asof_date,
                    preferred_expiry,
                    debit_direction,
                    minimum_dte=MIN_LIVE_DTE,
                    maximum_dte=debit_max_dte,
                )
            if not debit_expiries:
                message = "no suitable Schwab-chain expiry for debit-spread construction"
                if market_closed_live_recheck and _has_complete_target_math(current):
                    updated = _preserve_market_closed_target_recheck(current, message)
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                    continue
                current["live_validation_status"] = "NO_LIVE_EXPIRY"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
                continue
            debit_alternatives: list[dict[str, Any]] = []
            for candidate_expiry in debit_expiries:
                expiry_alternatives = _options_agent_debit_spread_alternatives(
                    contracts,
                    direction=debit_direction,
                    expiry=candidate_expiry,
                    spot=spot,
                    preferred_width=_preferred_width(current),
                    anchor_strike=_as_float(current.get("anchor_strike")),
                    expected_move_pct=_expected_move_pct_for_expiry(current, candidate_expiry, asof_date),
                    as_of_date=asof_date,
                    max_alternatives=8,
                )
                for alternative in expiry_alternatives:
                    alternative["selected_expiry"] = candidate_expiry.isoformat()
                    alternative["dte"] = (candidate_expiry - asof_date).days
                debit_alternatives.extend(expiry_alternatives)
            debit_best = (
                _select_live_alternative(
                    current,
                    debit_alternatives,
                    entry_type="DEBIT",
                    event_calendar=event_calendar,
                    as_of=asof_date,
                )
                if debit_alternatives
                else {"live_status": "no_live_alternative", "live_blocker": "no debit alternative returned"}
            )
            if debit_best.get("live_status") != "PASS":
                message = str(debit_best.get("live_blocker") or debit_best.get("live_status") or "live chain did not produce a valid debit spread")
                if market_closed_live_recheck and _has_complete_target_math(current):
                    updated = _preserve_market_closed_target_recheck(current, message)
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                    continue
                current["live_validation_status"] = str(debit_best.get("live_status") or "NO_LIVE_DEBIT_SPREAD")
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, current["live_validation_status"], message, validator.sources.get(ticker, "")))
                continue
            debit_expiry = _row_date(debit_best.get("selected_expiry"))
            if debit_expiry is None:
                message = "selected debit-spread alternative did not retain its expiry"
                current["live_validation_status"] = "NO_LIVE_EXPIRY"
                current["live_validation_note"] = message
                current["recommendation_status"] = _preserve_non_entry_status(current)
                current["status_reason"] = _append_reason(current.get("status_reason"), message)
                rows.append(current)
                audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
                continue
            chain_source = validator.sources.get(ticker, "")
            updated = _apply_live_debit_spread(
                current,
                debit_best,
                direction=debit_direction,
                expiry=debit_expiry,
                spot=spot,
                asof_date=asof_date,
                chain_source=chain_source,
            )
            if market_closed_live_recheck:
                preserved = _preserve_target_when_closed_market_quote_is_transiently_bad(
                    current,
                    updated,
                )
                if preserved is not None:
                    rows.append(preserved)
                    audit.append(
                        _live_audit_row(
                            preserved,
                            "TARGET_QUOTE_REFRESH",
                            preserved["live_validation_note"],
                            chain_source,
                        )
                    )
                    continue
            updated["live_validation_status"] = "PASS"
            updated["live_validation_note"] = str(
                updated.get("status_reason") or debit_best.get("construction_reason") or "chain validated"
            )
            updated["live_chain_source"] = chain_source
            rows.append(updated)
            audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))
            continue

        direction = _credit_direction(current)
        selector_credit_dte_window = _active_selector_live_credit_dte_window(current)
        credit_expiries = _live_expiry_candidates(
            contracts,
            asof_date,
            preferred_expiry,
            direction,
            minimum_dte=(selector_credit_dte_window or (None, None))[0],
            maximum_dte=(selector_credit_dte_window or (None, None))[1],
        )
        if not credit_expiries:
            debit_direction = _debit_direction(current)
            debit_expiry = _select_live_expiry(contracts, asof_date, preferred_expiry, debit_direction)
            if (
                selector_credit_dte_window is None
                and debit_expiry is not None
                and not parallel_debit_route_present
            ):
                debit_alternatives = _options_agent_debit_spread_alternatives(
                    contracts,
                    direction=debit_direction,
                    expiry=debit_expiry,
                    spot=spot,
                    preferred_width=_preferred_width(current),
                    anchor_strike=_as_float(current.get("anchor_strike")),
                    expected_move_pct=_expected_move_pct_for_expiry(current, debit_expiry, asof_date),
                    as_of_date=asof_date,
                    max_alternatives=8,
                )
                debit_best = (
                    _select_live_alternative(
                        current,
                        debit_alternatives,
                        entry_type="DEBIT",
                        event_calendar=event_calendar,
                        as_of=asof_date,
                    )
                    if debit_alternatives
                    else {"live_status": "no_live_alternative", "live_blocker": "no debit alternative returned"}
                )
                if debit_best.get("live_status") == "PASS":
                    chain_source = validator.sources.get(ticker, "")
                    updated = _apply_live_debit_spread(
                        current,
                        debit_best,
                        direction=debit_direction,
                        expiry=debit_expiry,
                        spot=spot,
                        asof_date=asof_date,
                        chain_source=chain_source,
                    )
                    if market_closed_live_recheck:
                        preserved = _preserve_target_when_closed_market_quote_is_transiently_bad(
                            current,
                            updated,
                        )
                        if preserved is not None:
                            rows.append(preserved)
                            audit.append(
                                _live_audit_row(
                                    preserved,
                                    "TARGET_QUOTE_REFRESH",
                                    preserved["live_validation_note"],
                                    chain_source,
                                )
                            )
                            continue
                    updated["live_validation_status"] = "PASS"
                    updated["live_validation_note"] = str(
                        updated.get("status_reason") or debit_best.get("construction_reason") or "chain validated"
                    )
                    updated["live_chain_source"] = chain_source
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))
                    continue
            message = "no suitable Schwab-chain expiry for credit-spread construction"
            if market_closed_live_recheck and _has_complete_target_math(current):
                updated = _preserve_market_closed_target_recheck(current, message)
                rows.append(updated)
                audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                continue
            current["live_validation_status"] = "NO_LIVE_EXPIRY"
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(current.get("status_reason"), message)
            rows.append(current)
            audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
            continue

        alternatives: list[dict[str, Any]] = []
        for candidate_expiry in credit_expiries:
            expiry_alternatives = _options_agent_credit_spread_alternatives(
                contracts,
                direction=direction,
                expiry=candidate_expiry,
                spot=spot,
                preferred_width=_preferred_width(current),
                anchor_strike=_as_float(current.get("anchor_strike")),
                expected_move_pct=_expected_move_pct_for_expiry(current, candidate_expiry, asof_date),
                as_of_date=asof_date,
                max_alternatives=8,
            )
            for alternative in expiry_alternatives:
                alternative["selected_expiry"] = candidate_expiry.isoformat()
                alternative["dte"] = (candidate_expiry - asof_date).days
            alternatives.extend(expiry_alternatives)
        best = (
            _select_live_alternative(
                current,
                alternatives,
                entry_type="CREDIT",
                event_calendar=event_calendar,
                as_of=asof_date,
            )
            if alternatives
            else {"live_status": "no_live_alternative", "live_blocker": "no alternative returned"}
        )
        if best.get("live_status") != "PASS":
            debit_direction = _debit_direction(current)
            debit_expiry = _select_live_expiry(contracts, asof_date, preferred_expiry, debit_direction)
            if (
                selector_credit_dte_window is None
                and debit_expiry is not None
                and not parallel_debit_route_present
            ):
                debit_alternatives = _options_agent_debit_spread_alternatives(
                    contracts,
                    direction=debit_direction,
                    expiry=debit_expiry,
                    spot=spot,
                    preferred_width=_preferred_width(current),
                    anchor_strike=_as_float(current.get("anchor_strike")),
                    expected_move_pct=_expected_move_pct_for_expiry(current, debit_expiry, asof_date),
                    as_of_date=asof_date,
                    max_alternatives=8,
                )
                debit_best = (
                    _select_live_alternative(
                        current,
                        debit_alternatives,
                        entry_type="DEBIT",
                        event_calendar=event_calendar,
                        as_of=asof_date,
                    )
                    if debit_alternatives
                    else {"live_status": "no_live_alternative", "live_blocker": "no debit alternative returned"}
                )
                if debit_best.get("live_status") == "PASS":
                    chain_source = validator.sources.get(ticker, "")
                    updated = _apply_live_debit_spread(
                        current,
                        debit_best,
                        direction=debit_direction,
                        expiry=debit_expiry,
                        spot=spot,
                        asof_date=asof_date,
                        chain_source=chain_source,
                    )
                    if market_closed_live_recheck:
                        preserved = _preserve_target_when_closed_market_quote_is_transiently_bad(
                            current,
                            updated,
                        )
                        if preserved is not None:
                            rows.append(preserved)
                            audit.append(
                                _live_audit_row(
                                    preserved,
                                    "TARGET_QUOTE_REFRESH",
                                    preserved["live_validation_note"],
                                    chain_source,
                                )
                            )
                            continue
                    updated["live_validation_status"] = "PASS"
                    updated["live_validation_note"] = str(
                        updated.get("status_reason") or debit_best.get("construction_reason") or "chain validated"
                    )
                    updated["live_chain_source"] = chain_source
                    rows.append(updated)
                    audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))
                    continue
            message = str(best.get("live_blocker") or best.get("live_status") or "live chain did not produce a valid spread")
            if market_closed_live_recheck and _has_complete_target_math(current):
                updated = _preserve_market_closed_target_recheck(current, message)
                rows.append(updated)
                audit.append(_live_audit_row(updated, "TARGET_QUOTE_REFRESH", updated["live_validation_note"], validator.sources.get(ticker, "")))
                continue
            current["live_validation_status"] = str(best.get("live_status") or "NO_LIVE_SPREAD")
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(current.get("status_reason"), message)
            rows.append(current)
            audit.append(_live_audit_row(current, current["live_validation_status"], message, validator.sources.get(ticker, "")))
            continue

        expiry = _row_date(best.get("selected_expiry"))
        if expiry is None:
            message = "selected credit-spread alternative did not retain its expiry"
            current["live_validation_status"] = "NO_LIVE_EXPIRY"
            current["live_validation_note"] = message
            current["recommendation_status"] = _preserve_non_entry_status(current)
            current["status_reason"] = _append_reason(current.get("status_reason"), message)
            rows.append(current)
            audit.append(_live_audit_row(current, "NO_LIVE_EXPIRY", message, validator.sources.get(ticker, "")))
            continue

        chain_source = validator.sources.get(ticker, "")
        updated = _apply_live_credit_spread(
            current,
            best,
            direction=direction,
            expiry=expiry,
            spot=spot,
            asof_date=asof_date,
            chain_source=chain_source,
        )
        if str(updated.get("recommendation_status") or "").upper() == RecommendationStatus.AVOID.value:
            debit_direction = _debit_direction(current)
            debit_expiry = _select_live_expiry(contracts, asof_date, preferred_expiry, debit_direction)
            if debit_expiry is not None and not parallel_debit_route_present:
                debit_alternatives = _options_agent_debit_spread_alternatives(
                    contracts,
                    direction=debit_direction,
                    expiry=debit_expiry,
                    spot=spot,
                    preferred_width=_preferred_width(current),
                    anchor_strike=_as_float(current.get("anchor_strike")),
                    expected_move_pct=_expected_move_pct_for_expiry(current, debit_expiry, asof_date),
                    as_of_date=asof_date,
                    max_alternatives=8,
                )
                debit_best = (
                    _select_live_alternative(
                        current,
                        debit_alternatives,
                        entry_type="DEBIT",
                        event_calendar=event_calendar,
                        as_of=asof_date,
                    )
                    if debit_alternatives
                    else {"live_status": "no_live_alternative", "live_blocker": "no debit alternative returned"}
                )
                if debit_best.get("live_status") == "PASS":
                    updated = _apply_live_debit_spread(
                        current,
                        debit_best,
                        direction=debit_direction,
                        expiry=debit_expiry,
                        spot=spot,
                        asof_date=asof_date,
                        chain_source=chain_source,
                    )
        if market_closed_live_recheck:
            preserved = _preserve_target_when_closed_market_quote_is_transiently_bad(
                current,
                updated,
            )
            if preserved is not None:
                rows.append(preserved)
                audit.append(
                    _live_audit_row(
                        preserved,
                        "TARGET_QUOTE_REFRESH",
                        preserved["live_validation_note"],
                        chain_source,
                    )
                )
                continue
        updated["live_validation_status"] = "PASS"
        updated["live_validation_note"] = str(updated.get("status_reason") or best.get("construction_reason") or "chain validated")
        updated["live_chain_source"] = chain_source
        rows.append(updated)
        audit.append(_live_audit_row(updated, "PASS", updated["live_validation_note"], chain_source))

    try:
        validator.save()
    except Exception as exc:
        notes.append(f"live chain snapshot save failed: {exc}")

    result = pd.DataFrame(rows)
    audit_frame = pd.DataFrame(audit)
    if "live_route_recovery_required" in result.columns:
        recovery_rows = result["live_route_recovery_required"].map(_truthy)
        recovery_succeeded = result.get(
            "live_validation_status",
            pd.Series("", index=result.index),
        ).astype(str).str.upper().isin({"PASS", *DEFERRED_TARGET_VALIDATION_STATUSES})
        # Failed recovery attempts belong in the diagnostics, not the order-facing
        # recommendation frame. The audit frame deliberately retains them below.
        result = result[~recovery_rows | recovery_succeeded].copy()
    result, duplicate_contract_count = _dedupe_exact_contract_rows(result)
    audit_frame, _ = _dedupe_exact_contract_rows(audit_frame)
    if duplicate_contract_count:
        notes.append(
            f"deduplicated {duplicate_contract_count} live rows that converged on already-priced exact contracts"
        )
    if audit_frame.empty:
        audit_frame = empty_live_validation_frame()
    return result, audit_frame, notes


def _dedupe_exact_contract_rows(frame: pd.DataFrame) -> tuple[pd.DataFrame, int]:
    """Keep the first route-priority row when live recovery converges on identical legs."""

    if frame is None or frame.empty:
        return frame.copy() if frame is not None else pd.DataFrame(), 0
    working = frame.copy()
    working["__contract_key"] = working.apply(contract_review_key, axis=1)
    exact = working["__contract_key"].astype(str).ne("")
    duplicate = exact & working.duplicated("__contract_key", keep="first")
    duplicate_count = int(duplicate.sum())
    if duplicate_count:
        working = working[~duplicate].copy()
    return working.drop(columns=["__contract_key"], errors="ignore").reset_index(drop=True), duplicate_count


def empty_live_validation_frame() -> pd.DataFrame:
    return pd.DataFrame(
        columns=[
            "ticker",
            "live_validation_status",
            "recommendation_status",
            "chain_source",
            "expiry",
            "entry_limit",
            "target_entry",
            "trade_plan",
            "sell_leg",
            "buy_leg",
            "sell_leg_bid",
            "sell_leg_ask",
            "sell_leg_mid",
            "buy_leg_bid",
            "buy_leg_ask",
            "buy_leg_mid",
            "short_leg",
            "long_leg",
            "strategy_route",
            "live_route_recovery_required",
            "note",
        ]
    )


def build_structure_attempts(
    dated_priced: pd.DataFrame,
    final_priced: pd.DataFrame,
    live_validation: pd.DataFrame,
) -> pd.DataFrame:
    """Create an audit trail for dated and live structure construction attempts."""

    columns = [
        "ticker",
        "attempt_stage",
        "attempt_status",
        "structure",
        "full_ticket",
        "trade_plan",
        "expiry",
        "entry_limit",
        "target_entry",
        "max_profit",
        "max_loss",
        "sell_leg",
        "buy_leg",
        "short_leg",
        "long_leg",
        "source",
        "note",
    ]
    rows: list[dict[str, Any]] = []
    if not dated_priced.empty:
        for _, row in dated_priced.iterrows():
            status = _structure_attempt_status(row, stage="dated")
            rows.append(
                {
                    "ticker": row.get("ticker", ""),
                    "attempt_stage": "dated_hot_chain",
                    "attempt_status": status,
                    "structure": row.get("structure", ""),
                    "full_ticket": row.get("full_ticket", ""),
                    "trade_plan": row.get("trade_plan", row.get("full_ticket", "")),
                    "expiry": row.get("expiry", ""),
                    "entry_limit": row.get("entry_limit", ""),
                    "target_entry": "",
                    "max_profit": row.get("max_profit", ""),
                    "max_loss": row.get("max_loss", ""),
                    "sell_leg": row.get("sell_leg", row.get("short_leg", "")),
                    "buy_leg": row.get("buy_leg", row.get("long_leg", "")),
                    "short_leg": row.get("short_leg", ""),
                    "long_leg": row.get("long_leg", ""),
                    "source": "dated UW hot-chain",
                    "note": row.get("status_reason", ""),
                }
            )
    if not live_validation.empty:
        final_by_ticker = _frame_by_ticker(final_priced)
        final_by_route = {
            (
                _as_text(row.get("ticker")).upper(),
                _as_text(row.get("strategy_route")).lower(),
            ): row.to_dict()
            for _, row in final_priced.iterrows()
        }
        for _, row in live_validation.iterrows():
            ticker = str(row.get("ticker") or "").strip().upper()
            route = _as_text(row.get("strategy_route")).lower()
            priced = final_by_route.get((ticker, route), final_by_ticker.get(ticker, {}))
            rows.append(
                {
                    "ticker": ticker,
                    "attempt_stage": "live_schwab_chain",
                    "attempt_status": str(row.get("live_validation_status") or "").strip() or "UNKNOWN",
                    "structure": priced.get("structure", ""),
                    "full_ticket": priced.get("full_ticket", ""),
                    "trade_plan": priced.get("trade_plan", priced.get("full_ticket", "")),
                    "expiry": row.get("expiry", ""),
                    "entry_limit": row.get("entry_limit", ""),
                    "target_entry": row.get("target_entry", ""),
                    "max_profit": priced.get("max_profit", ""),
                    "max_loss": priced.get("max_loss", ""),
                    "sell_leg": row.get("sell_leg", priced.get("sell_leg", "")),
                    "buy_leg": row.get("buy_leg", priced.get("buy_leg", "")),
                    "short_leg": row.get("short_leg", ""),
                    "long_leg": row.get("long_leg", ""),
                    "source": row.get("chain_source", ""),
                    "note": row.get("note", ""),
                }
            )
    return pd.DataFrame(rows, columns=columns)


def _structure_attempt_status(row: Mapping[str, Any], *, stage: str) -> str:
    ticket = str(row.get("full_ticket") or "").strip()
    entry = _as_float(row.get("entry_limit")) or 0.0
    max_profit = _as_float(row.get("max_profit")) or 0.0
    max_loss = _as_float(row.get("max_loss")) or 0.0
    if ticket and entry > 0 and max_profit > 0 and max_loss > 0:
        return str(row.get("recommendation_status") or "CONSTRUCTED").strip() or "CONSTRUCTED"
    if ticket:
        return "INCOMPLETE_PAYOFF"
    if stage == "dated":
        return "CONSTRUCTION_GAP"
    return "NO_STRUCTURE"


def unavailable_portfolio_context(error: str) -> dict[str, Any]:
    return {
        "status": "unavailable",
        "error": str(error),
        "total_value": 0.0,
        "cash": 0.0,
        "position_count": 0,
        "option_underlyings": [],
        "short_option_underlyings": [],
        "equity_exposure": {},
        "option_market_value": {},
        "large_equity_exposure": {},
        "risk_actions": [],
        "portfolio_income_actions": [],
    }


def resolve_portfolio_context(
    out_dir: Path,
    *,
    portfolio_context: Optional[Mapping[str, Any]] = None,
    portfolio_json: Optional[Path] = None,
    live_portfolio: bool = False,
) -> tuple[dict[str, Any], list[str]]:
    """Load or fetch portfolio context with Options Agent-owned artifacts."""

    if portfolio_context is not None:
        return dict(portfolio_context), []

    if portfolio_json is not None:
        try:
            path = Path(portfolio_json).expanduser().resolve()
            return json.loads(path.read_text(encoding="utf-8")), []
        except Exception as exc:
            return unavailable_portfolio_context(f"portfolio json unavailable: {exc}"), [f"portfolio json unavailable: {exc}"]

    if not live_portfolio:
        return unavailable_portfolio_context("portfolio context not requested"), []

    try:
        from ._vendor.portfolio import summarize_positions
        from ._vendor.schwab_auth import SchwabAuthConfig, SchwabLiveDataService

        service = SchwabLiveDataService(SchwabAuthConfig.from_env(load_dotenv_file=True), interactive_login=False)
        payload = service.get_account_positions()
        positions = pd.DataFrame(payload.get("positions", []) or [])
        positions.to_csv(out_dir / "groko_open_positions_from_schwab.csv", index=False)
        return summarize_positions(payload), []
    except Exception as exc:
        message = f"live portfolio context unavailable: {exc}"
        return unavailable_portfolio_context(message), [message]


def _dated_expected_move_pct(candidate: Mapping[str, Any], dte: int) -> Optional[float]:
    """Return a point-in-time one-standard-deviation move for dated construction."""

    annualized_iv = _as_float(candidate.get("iv30d"))
    if annualized_iv is None or annualized_iv <= 0 or dte <= 0:
        return None
    if annualized_iv > 3.0:
        annualized_iv /= 100.0
    return annualized_iv * math.sqrt(dte / 365.0)


def _dated_hot_contracts(
    hot: pd.DataFrame,
    *,
    ticker: str,
    right: str,
) -> pd.DataFrame:
    """Normalize dated UW hot-chain rows for the shared spread enumerator."""

    chain = hot[
        hot["ticker"].astype(str).str.upper().eq(ticker)
        & hot["right"].astype(str).str.upper().eq(right)
    ].copy()
    if chain.empty:
        return chain
    chain["expiry"] = chain["expiry_dt"].map(_optional_iso_date)
    chain["symbol"] = chain.get("option_symbol", pd.Series("", index=chain.index)).astype(str)
    chain["mark"] = pd.to_numeric(
        chain.get("mid", chain.get("close", pd.Series(math.nan, index=chain.index))),
        errors="coerce",
    )
    for column in (
        "strike",
        "bid",
        "ask",
        "mark",
        "delta",
        "theta",
        "gamma",
        "vega",
        "iv",
        "open_interest",
        "volume",
        "dte",
    ):
        if column not in chain.columns:
            chain[column] = math.nan
        chain[column] = pd.to_numeric(chain[column], errors="coerce")
    return chain


def _dated_spread_pair(
    candidate: Mapping[str, Any],
    hot: pd.DataFrame,
    *,
    direction: str,
    entry_type: str,
) -> Optional[tuple[pd.Series, pd.Series, dict[str, Any]]]:
    """Enumerate dated spread pairs and choose one using entry-time quality only."""

    from ._vendor.schwab_live import (
        find_credit_spread_alternatives,
        find_debit_spread_alternatives,
    )

    ticker = _as_text(candidate.get("ticker")).upper()
    close = _as_float(candidate.get("close"))
    if not ticker or close is None or close <= 0:
        return None
    right = "P" if direction in {"Bull Put", "Bear Put"} else "C"
    contracts = _dated_hot_contracts(hot, ticker=ticker, right=right)
    if contracts.empty:
        return None

    minimum_dte = 14 if direction == "Bear Put" else MIN_LIVE_DTE
    expiry_rows = contracts.dropna(subset=["expiry"]).groupby("expiry", as_index=False)["dte"].median()
    expiry_rows = expiry_rows[
        pd.to_numeric(expiry_rows["dte"], errors="coerce").between(
            minimum_dte,
            45,
            inclusive="both",
        )
    ]
    alternatives: list[dict[str, Any]] = []
    for _, expiry_row in expiry_rows.iterrows():
        expiry = expiry_row["expiry"]
        dte = int(_as_float(expiry_row.get("dte")) or 0)
        if not isinstance(expiry, dt.date) or dte <= 0:
            continue
        expected_move_pct = _dated_expected_move_pct(candidate, dte)
        common = {
            "direction": direction,
            "expiry": expiry,
            "spot": close,
            "anchor_strike": _as_float(candidate.get("hot_top_strike")),
            "expected_move_pct": expected_move_pct,
            "as_of_date": expiry - dt.timedelta(days=dte),
        }
        if entry_type == "CREDIT":
            found = _options_agent_credit_spread_alternatives(
                contracts,
                max_alternatives=12,
                min_actionable_credit_width_ratio=MIN_SEND_NOW_CREDIT_WIDTH_RATIO,
                **common,
            )
        else:
            found = _options_agent_debit_spread_alternatives(
                contracts,
                max_alternatives=8,
                **common,
            )
        for alternative in found:
            if _as_text(alternative.get("live_status")).upper() != "PASS":
                continue
            item = dict(alternative)
            item["expiry"] = expiry
            item["dte"] = dte
            item["expected_move_pct"] = expected_move_pct
            alternatives.append(item)
    if not alternatives:
        return None

    by_symbol = {
        _as_text(row.get("symbol")).upper(): row
        for _, row in contracts.sort_values(
            ["volume", "open_interest"], ascending=[False, False], kind="mergesort"
        ).iterrows()
        if _as_text(row.get("symbol"))
    }
    ranked: list[tuple[tuple[float, ...], pd.Series, pd.Series, dict[str, Any]]] = []
    for item in alternatives:
        short = by_symbol.get(_as_text(item.get("short_leg")).upper())
        long = by_symbol.get(_as_text(item.get("long_leg")).upper())
        if short is None or long is None:
            continue
        width = abs((_as_float(short.get("strike")) or 0.0) - (_as_float(long.get("strike")) or 0.0))
        if width <= 0:
            continue
        short_bid = _as_float(short.get("bid")) or 0.0
        short_ask = _as_float(short.get("ask")) or 0.0
        long_bid = _as_float(long.get("bid")) or 0.0
        long_ask = _as_float(long.get("ask")) or 0.0
        combo_bid = short_bid - long_ask if entry_type == "CREDIT" else long_bid - short_ask
        combo_ask = short_ask - long_bid if entry_type == "CREDIT" else long_ask - short_bid
        combo_mid = (combo_bid + combo_ask) / 2.0
        entry = combo_bid if entry_type == "CREDIT" else combo_ask
        if entry <= 0 or entry >= width or combo_ask < combo_bid:
            continue
        quote_width = (combo_ask - combo_bid) / max(abs(combo_mid), 0.01)
        dte = int(_as_float(item.get("dte")) or 0)
        expected_move = _as_float(item.get("expected_move_pct"))
        short_strike = _as_float(short.get("strike")) or 0.0
        long_strike = _as_float(long.get("strike")) or 0.0
        liquidity = _as_float(item.get("liq_score")) or 0.0
        if entry_type == "CREDIT":
            breakeven = short_strike - entry if direction == "Bull Put" else short_strike + entry
            distance_pct = abs(breakeven - close) / close
            expected_ratio = (
                distance_pct / expected_move
                if expected_move is not None and expected_move > 0
                else None
            )
            economics_ratio = entry / width
            requirement_count = sum(
                (
                    MIN_SEND_NOW_CREDIT_WIDTH_RATIO <= economics_ratio <= 0.30,
                    entry >= MIN_SEND_NOW_CREDIT,
                    quote_width <= MAX_SELECTOR_ENTRY_QUOTE_WIDTH_PCT,
                    liquidity >= 100.0,
                    (width - entry) * 100.0 <= 750.0,
                )
            )
            quality_pass = requirement_count == 5
            score = (
                float(quality_pass),
                float(requirement_count),
                -abs(dte - 35),
                -abs(economics_ratio - 0.275),
                min(liquidity, 5000.0) / 5000.0,
                -quote_width,
            )
        else:
            breakeven = long_strike + entry if direction == "Bull Call" else long_strike - entry
            distance_pct = max(
                (breakeven - close) / close
                if direction == "Bull Call"
                else (close - breakeven) / close,
                0.001,
            )
            expected_ratio = (
                expected_move / distance_pct
                if expected_move is not None and expected_move > 0
                else None
            )
            economics_ratio = entry / width
            reward_risk = (width - entry) / entry
            minimum_expected_ratio = 1.0 if direction == "Bull Call" else 1.25
            requirement_count = sum(
                (
                    0 < economics_ratio <= 0.45,
                    reward_risk >= 1.25,
                    expected_ratio is not None and expected_ratio >= minimum_expected_ratio,
                    quote_width <= 0.25,
                    liquidity >= 100.0,
                )
            )
            quality_pass = requirement_count == 5
            # Prefer the 15-45 window that clears short-DTE macro. Weeklies into
            # NFP/FOMC were winning dated rank then dying at the selector.
            macro_safe_dte = 1.0 if dte >= MIN_MACRO_SCALE_DTE else 0.0
            score = (
                float(quality_pass),
                float(macro_safe_dte),
                float(requirement_count),
                -abs(dte - 28),
                min(reward_risk, 3.0),
                min(expected_ratio or 0.0, 3.0),
                -quote_width,
                -abs(long_strike - close) / close,
            )
        item["dated_combo_quote_width_pct"] = quote_width
        item["dated_expected_move_ratio"] = expected_ratio
        item["dated_entry_price"] = entry
        item["dated_breakeven"] = breakeven
        item["dated_quote_sources"] = "+".join(
            sorted(
                {
                    _as_text(short.get("dated_quote_source")),
                    _as_text(long.get("dated_quote_source")),
                }
                - {""}
            )
        )
        ranked.append((score, short, long, item))
    if not ranked:
        return None
    _, short, long, selected = max(ranked, key=lambda value: value[0])
    return short, long, selected


def _credit_send_now_target_entry(
    width: float,
    source_target: Optional[float] = None,
) -> float:
    """Limit price for a credit send-now: $0.50 and 25% of width, never the 16% construction floor."""

    send_now_width_target = (
        math.ceil(max(width, 0.0) * MIN_SEND_NOW_CREDIT_WIDTH_RATIO * 100.0 - 1e-9) / 100.0
        if width > 0
        else 0.0
    )
    return round(
        max(
            source_target or 0.0,
            MIN_SEND_NOW_CREDIT,
            send_now_width_target,
        ),
        2,
    )


def construct_credit_spread(candidate: Mapping[str, Any], hot: pd.DataFrame) -> dict[str, Any]:
    """Build a conservative one-lot credit spread attempt for a candidate."""

    ticker = str(candidate.get("ticker") or "").upper()
    bias = str(candidate.get("bias") or "").lower()
    close = _as_float(candidate.get("close"))
    right = "P" if bias == "bullish" else "C"
    structure = "bull put spread" if right == "P" else "bear call spread"
    chain = hot[hot["ticker"].astype(str).str.upper().eq(ticker) & hot["right"].astype(str).str.upper().eq(right)].copy()
    if close is not None:
        if right == "P":
            chain = chain[chain["strike"] < close]
        else:
            chain = chain[chain["strike"] > close]
    if chain.empty:
        return priced_error_row(candidate, structure, "missing suitable short leg in dated UW hot-chain source")

    preferred = chain[
        (pd.to_numeric(chain["dte"], errors="coerce") >= MIN_LIVE_DTE)
        & (pd.to_numeric(chain["dte"], errors="coerce") <= 45)
    ]
    if preferred.empty:
        return priced_error_row(candidate, structure, "no dated UW hot-chain expiry in 7-45 DTE window")
    pair = _dated_spread_pair(
        candidate,
        hot,
        direction="Bull Put" if right == "P" else "Bear Call",
        entry_type="CREDIT",
    )
    if pair is None:
        return priced_error_row(
            candidate,
            structure,
            "no quality-aware protective spread pair in dated UW hot-chain source",
        )
    short, long, dated_selection = pair
    short_bid = _as_float(short.get("bid")) or 0.0
    short_ask = _as_float(short.get("ask")) or 0.0
    long_bid = _as_float(long.get("bid")) or 0.0
    long_ask = _as_float(long.get("ask")) or 0.0
    short_mid = (short_bid + short_ask) / 2 if short_bid or short_ask else 0.0
    long_mid = (long_bid + long_ask) / 2 if long_bid or long_ask else 0.0
    conservative_credit = short_bid - long_ask
    mid_credit = short_mid - long_mid
    entry_credit = conservative_credit if conservative_credit > 0 else mid_credit
    width = abs(float(short["strike"]) - float(long["strike"]))

    if entry_credit <= 0 or width <= 0:
        return priced_error_row(candidate, structure, "spread credit could not be estimated from dated bid/ask")

    max_profit = round(entry_credit * 100, 2)
    max_loss = round(max((width - entry_credit) * 100, 0), 2)
    credit_width_ratio = round(entry_credit / width, 4) if width > 0 else 0.0
    breakeven = float(short["strike"]) - entry_credit if right == "P" else float(short["strike"]) + entry_credit
    short_symbol = _as_text(short.get("option_symbol"))
    long_symbol = _as_text(long.get("option_symbol"))
    sell_leg = _format_option_leg(
        short_symbol,
        "SELL",
        ticker=ticker,
        expiry=short["expiry_dt"],
        strike=short["strike"],
        right=right,
    )
    buy_leg = _format_option_leg(
        long_symbol,
        "BUY",
        ticker=ticker,
        expiry=long["expiry_dt"],
        strike=long["strike"],
        right=right,
    )
    trade_plan = _format_trade_plan(sell_leg, buy_leg, entry_credit, entry_type="CREDIT")
    bid_ask_width = max((short_ask - short_bid) + (long_ask - long_bid), 0.0)
    liquidity_note = "dated UW EOD quote; refresh Schwab chain before entry"
    status = RecommendationStatus.REVIEW.value
    hard_rejects = ""
    if bid_ask_width > max(entry_credit, 0.01) * 1.5:
        status = RecommendationStatus.WAIT_FOR_PRICE.value
        liquidity_note = "dated bid/ask width is wide; keep visible and re-price with fresh Schwab chain"
    quality_rejects = _trade_quality_rejects(
        entry_credit=entry_credit,
        credit_width_ratio=credit_width_ratio,
        max_loss=max_loss,
        signal_premium=_as_float(candidate.get("signal_premium")) or 0.0,
        combined_flow_bias=_as_float(candidate.get("combined_flow_bias")) or 0.0,
        macro_tape_candidate=_truthy(candidate.get("macro_tape_candidate")),
    )
    status, hard_rejects, quality_gate_reason, trade_quality_status, liquidity_note = (
        _finalize_quality_rejects(status, quality_rejects, note=liquidity_note)
    )
    underlying_tier, underlying_reason = _underlying_quality(candidate)
    strategy_route = "bull_put_credit" if right == "P" else "bear_call_credit"
    direction = "Bull Put" if right == "P" else "Bear Call"

    return {
        "ticker": ticker,
        "full_name": candidate.get("full_name", ""),
        "issue_type": candidate.get("issue_type", ""),
        "marketcap": candidate.get("marketcap", ""),
        "avg30_volume": candidate.get("avg30_volume", ""),
        "total_volume": candidate.get("total_volume", ""),
        "total_open_interest": candidate.get("total_open_interest", ""),
        "underlying_quality_tier": underlying_tier,
        "underlying_quality_reason": underlying_reason,
        "bias": candidate.get("bias"),
        "flow_bias_label": candidate.get("flow_bias_label", candidate.get("bias")),
        "candidate_source": candidate.get("candidate_source", "flow_oi"),
        "macro_tape_candidate": candidate.get("macro_tape_candidate", False),
        "macro_tape_direction": candidate.get("macro_tape_direction", ""),
        "macro_tape_reason": candidate.get("macro_tape_reason", ""),
        "price_move_pct": candidate.get("price_move_pct", ""),
        "price_tape_source": candidate.get("price_tape_source", ""),
        "strategy": strategy_route,
        "strategy_family": "vertical_spread",
        "strategy_route": strategy_route,
        "entry_type": "CREDIT",
        "direction": direction,
        "structure": structure,
        "full_ticket": trade_plan,
        "trade_plan": trade_plan,
        "expiry": str(short["expiry_dt"]),
        "dte": int(float(short.get("dte") or 0)),
        "sell_leg": sell_leg,
        "buy_leg": buy_leg,
        "short_leg": sell_leg,
        "long_leg": buy_leg,
        "sell_leg_bid": round(short_bid, 2),
        "sell_leg_ask": round(short_ask, 2),
        "sell_leg_mid": round(short_mid, 2),
        "buy_leg_bid": round(long_bid, 2),
        "buy_leg_ask": round(long_ask, 2),
        "buy_leg_mid": round(long_mid, 2),
        "anchor_expiry": str(candidate.get("hot_top_expiry") or short["expiry_dt"]),
        "anchor_strike": float(candidate.get("hot_top_strike") or short["strike"]),
        "short_strike": float(short["strike"]),
        "long_strike": float(long["strike"]),
        "spread_width": width,
        "entry_limit": round(entry_credit, 2),
        "mid": round(mid_credit, 2),
        "bid": round(conservative_credit, 2),
        "ask": "",
        "max_profit": max_profit,
        "max_loss": max_loss,
        "credit_width_ratio": credit_width_ratio,
        "trade_quality_status": trade_quality_status,
        "quality_gate_reason": quality_gate_reason,
        "remaining_upside": max_profit,
        "breakeven": round(breakeven, 2),
        "target_exit": round(entry_credit * CREDIT_TAKE_PROFIT_REMAINING, 2),
        "target_entry": _credit_send_now_target_entry(width),
        "invalidation": "fresh quote fails, thesis breaks, or underlying violates breakeven/flow support",
        "score": round(float(candidate.get("score") or 0), 2),
        "signal_premium": round(float(candidate.get("signal_premium") or 0), 2),
        "combined_flow_bias": candidate.get("combined_flow_bias", ""),
        "oi_directional_bias": candidate.get("oi_directional_bias", ""),
        "oi_directional_premium": candidate.get("oi_directional_premium", ""),
        "oi_bullish_premium": candidate.get("oi_bullish_premium", ""),
        "oi_bearish_premium": candidate.get("oi_bearish_premium", ""),
        "quality_status": candidate.get("quality_status"),
        "recommendation_status": status,
        "status_reason": liquidity_note,
        "hard_rejects": hard_rejects,
        "portfolio_risk_flag": False,
        "portfolio_risk_note": "",
        "visible_in_final_board": True,
        "flow_reason": candidate.get("flow_reason"),
        "dated_construction_source": dated_selection.get("construction_source", ""),
        "dated_quote_sources": dated_selection.get("dated_quote_sources", ""),
        "dated_combo_quote_width_pct": dated_selection.get("dated_combo_quote_width_pct", ""),
        "dated_expected_move_ratio": dated_selection.get("dated_expected_move_ratio", ""),
        "source_contract_oi": min(
            _as_float(short.get("open_interest")) or 0.0,
            _as_float(long.get("open_interest")) or 0.0,
        ),
        "source_contract_volume": min(
            _as_float(short.get("volume")) or 0.0,
            _as_float(long.get("volume")) or 0.0,
        ),
    }


def construct_debit_spread(candidate: Mapping[str, Any], hot: pd.DataFrame, *, direction: str) -> dict[str, Any]:
    """Build a conservative one-lot debit spread attempt from dated UW hot-chain quotes."""

    ticker = str(candidate.get("ticker") or "").upper()
    direction = _as_text(direction)
    if direction not in {"Bull Call", "Bear Put"}:
        return priced_error_row(candidate, "debit spread", f"unsupported debit direction {direction or 'missing'}")
    close = _as_float(candidate.get("close"))
    right = "C" if direction == "Bull Call" else "P"
    structure = "bull call debit spread" if direction == "Bull Call" else "bear put debit spread"
    chain = hot[hot["ticker"].astype(str).str.upper().eq(ticker) & hot["right"].astype(str).str.upper().eq(right)].copy()
    if close is not None and close > 0:
        strikes = pd.to_numeric(chain["strike"], errors="coerce")
        if direction == "Bull Call":
            chain = chain[strikes.between(close * 0.96, close * 1.08, inclusive="both")]
        else:
            chain = chain[strikes.between(close * 0.90, close * 1.04, inclusive="both")]
    if chain.empty:
        return priced_error_row(candidate, structure, "missing suitable debit-spread long leg in dated UW hot-chain source")

    minimum_dte = 14 if direction == "Bear Put" else MIN_LIVE_DTE
    preferred = chain[
        (pd.to_numeric(chain["dte"], errors="coerce") >= minimum_dte)
        & (pd.to_numeric(chain["dte"], errors="coerce") <= 45)
    ].copy()
    if preferred.empty:
        return priced_error_row(
            candidate,
            structure,
            f"no dated UW hot-chain debit expiry in {minimum_dte}-45 DTE window",
        )
    pair = _dated_spread_pair(
        candidate,
        hot,
        direction=direction,
        entry_type="DEBIT",
    )
    if pair is None:
        return priced_error_row(
            candidate,
            structure,
            "no reward/risk-aware debit spread pair in dated UW hot-chain source",
        )
    short, long, dated_selection = pair
    long_bid = _as_float(long.get("bid")) or 0.0
    long_ask = _as_float(long.get("ask")) or 0.0
    short_bid = _as_float(short.get("bid")) or 0.0
    short_ask = _as_float(short.get("ask")) or 0.0
    long_mid = (long_bid + long_ask) / 2 if long_bid or long_ask else 0.0
    short_mid = (short_bid + short_ask) / 2 if short_bid or short_ask else 0.0
    natural_debit = long_ask - short_bid
    mid_debit = long_mid - short_mid
    entry_debit = natural_debit if natural_debit > 0 else mid_debit
    width = abs(float(short["strike"]) - float(long["strike"]))

    if entry_debit <= 0 or width <= 0 or entry_debit >= width:
        return priced_error_row(candidate, structure, "spread debit could not be estimated from dated bid/ask")

    max_profit = round(max((width - entry_debit) * 100, 0), 2)
    max_loss = round(entry_debit * 100, 2)
    debit_width_ratio = round(entry_debit / width, 4) if width > 0 else 0.0
    breakeven = float(long["strike"]) + entry_debit if direction == "Bull Call" else float(long["strike"]) - entry_debit
    buy_leg = _format_option_leg(
        _as_text(long.get("option_symbol")),
        "BUY",
        ticker=ticker,
        expiry=long["expiry_dt"],
        strike=long["strike"],
        right=right,
    )
    sell_leg = _format_option_leg(
        _as_text(short.get("option_symbol")),
        "SELL",
        ticker=ticker,
        expiry=short["expiry_dt"],
        strike=short["strike"],
        right=right,
    )
    trade_plan = _format_trade_plan(buy_leg, sell_leg, entry_debit, entry_type="DEBIT")
    bid_ask_width = max((long_ask - long_bid) + (short_ask - short_bid), 0.0)
    liquidity_note = "dated UW EOD debit-spread quote; refresh Schwab chain before entry"
    status = RecommendationStatus.REVIEW.value
    hard_rejects = ""
    quality_rejects = _debit_trade_quality_rejects(
        entry_debit=entry_debit,
        debit_width_ratio=debit_width_ratio,
        max_profit=max_profit,
        max_loss=max_loss,
        signal_premium=_as_float(candidate.get("signal_premium")) or 0.0,
        combined_flow_bias=_as_float(candidate.get("combined_flow_bias")) or 0.0,
        macro_tape_candidate=_truthy(candidate.get("macro_tape_candidate")),
    )
    if bid_ask_width > max(entry_debit, 0.01) * 1.5:
        status = RecommendationStatus.WAIT_FOR_PRICE.value
        liquidity_note = "dated debit-spread bid/ask width is wide; keep visible and re-price with fresh Schwab chain"
    status, hard_rejects, quality_gate_reason, trade_quality_status, liquidity_note = (
        _finalize_quality_rejects(status, quality_rejects, note=liquidity_note)
    )
    underlying_tier, underlying_reason = _underlying_quality(candidate)
    strategy_route = "bull_call_debit" if direction == "Bull Call" else "bear_put_debit"

    return {
        "ticker": ticker,
        "full_name": candidate.get("full_name", ""),
        "issue_type": candidate.get("issue_type", ""),
        "marketcap": candidate.get("marketcap", ""),
        "avg30_volume": candidate.get("avg30_volume", ""),
        "total_volume": candidate.get("total_volume", ""),
        "total_open_interest": candidate.get("total_open_interest", ""),
        "underlying_quality_tier": underlying_tier,
        "underlying_quality_reason": underlying_reason,
        "bias": candidate.get("bias"),
        "flow_bias_label": candidate.get("flow_bias_label", candidate.get("bias")),
        "candidate_source": candidate.get("candidate_source", "flow_oi"),
        "macro_tape_candidate": candidate.get("macro_tape_candidate", False),
        "macro_tape_direction": candidate.get("macro_tape_direction", ""),
        "macro_tape_reason": candidate.get("macro_tape_reason", ""),
        "price_move_pct": candidate.get("price_move_pct", ""),
        "price_tape_source": candidate.get("price_tape_source", ""),
        "strategy": strategy_route,
        "strategy_family": "vertical_spread",
        "strategy_route": strategy_route,
        "entry_type": "DEBIT",
        "direction": direction,
        "structure": structure,
        "full_ticket": trade_plan,
        "trade_plan": trade_plan,
        "expiry": str(long["expiry_dt"]),
        "dte": int(float(long.get("dte") or 0)),
        "sell_leg": sell_leg,
        "buy_leg": buy_leg,
        "short_leg": sell_leg,
        "long_leg": buy_leg,
        "sell_leg_bid": round(short_bid, 2),
        "sell_leg_ask": round(short_ask, 2),
        "sell_leg_mid": round(short_mid, 2),
        "buy_leg_bid": round(long_bid, 2),
        "buy_leg_ask": round(long_ask, 2),
        "buy_leg_mid": round(long_mid, 2),
        "anchor_expiry": str(candidate.get("hot_top_expiry") or long["expiry_dt"]),
        "anchor_strike": float(candidate.get("hot_top_strike") or long["strike"]),
        "short_strike": float(short["strike"]),
        "long_strike": float(long["strike"]),
        "spread_width": width,
        "entry_limit": round(entry_debit, 2),
        "mid": round(mid_debit, 2),
        "bid": "",
        "ask": round(natural_debit, 2),
        "max_profit": max_profit,
        "max_loss": max_loss,
        "credit_width_ratio": 0.0,
        "debit_width_ratio": debit_width_ratio,
        "trade_quality_status": trade_quality_status,
        "quality_gate_reason": quality_gate_reason,
        "remaining_upside": max_profit,
        "breakeven": round(breakeven, 2),
        "target_exit": round(
            min(width * 0.80, entry_debit * DEBIT_TAKE_PROFIT_MULTIPLIER),
            2,
        ),
        "target_entry": round(width * 0.45, 2),
        "invalidation": "fresh quote fails, thesis breaks, or underlying fails to progress toward breakeven",
        "score": round(float(candidate.get("score") or 0), 2),
        "signal_premium": round(float(candidate.get("signal_premium") or 0), 2),
        "combined_flow_bias": candidate.get("combined_flow_bias", ""),
        "oi_directional_bias": candidate.get("oi_directional_bias", ""),
        "oi_directional_premium": candidate.get("oi_directional_premium", ""),
        "oi_bullish_premium": candidate.get("oi_bullish_premium", ""),
        "oi_bearish_premium": candidate.get("oi_bearish_premium", ""),
        "quality_status": candidate.get("quality_status"),
        "recommendation_status": status,
        "status_reason": liquidity_note,
        "hard_rejects": hard_rejects,
        "portfolio_risk_flag": False,
        "portfolio_risk_note": "",
        "visible_in_final_board": True,
        "flow_reason": candidate.get("flow_reason"),
        "dated_construction_source": dated_selection.get("construction_source", ""),
        "dated_quote_sources": dated_selection.get("dated_quote_sources", ""),
        "dated_combo_quote_width_pct": dated_selection.get("dated_combo_quote_width_pct", ""),
        "dated_expected_move_ratio": dated_selection.get("dated_expected_move_ratio", ""),
        "source_contract_oi": min(
            _as_float(short.get("open_interest")) or 0.0,
            _as_float(long.get("open_interest")) or 0.0,
        ),
        "source_contract_volume": min(
            _as_float(short.get("volume")) or 0.0,
            _as_float(long.get("volume")) or 0.0,
        ),
    }


def construct_long_option(candidate: Mapping[str, Any], hot: pd.DataFrame, *, direction: str) -> dict[str, Any]:
    """Build a conservative one-lot long call/put attempt from dated UW hot-chain quotes."""

    ticker = str(candidate.get("ticker") or "").upper()
    direction = _as_text(direction)
    if direction not in {"Long Call", "Long Put"}:
        return priced_error_row(candidate, "long option", f"unsupported long-option direction {direction or 'missing'}")
    close = _as_float(candidate.get("close"))
    right = "C" if direction == "Long Call" else "P"
    route = "long_call" if direction == "Long Call" else "long_put"
    structure = "long call" if direction == "Long Call" else "long put"
    chain = hot[hot["ticker"].astype(str).str.upper().eq(ticker) & hot["right"].astype(str).str.upper().eq(right)].copy()
    if close is not None and close > 0:
        strikes = pd.to_numeric(chain["strike"], errors="coerce")
        if direction == "Long Call":
            chain = chain[strikes.between(close * 0.96, close * 1.10, inclusive="both")]
        else:
            chain = chain[strikes.between(close * 0.90, close * 1.04, inclusive="both")]
    if chain.empty:
        return priced_error_row(candidate, structure, "missing suitable long-option leg in dated UW hot-chain source")

    preferred = chain[
        (pd.to_numeric(chain["dte"], errors="coerce") >= MIN_LIVE_DTE)
        & (pd.to_numeric(chain["dte"], errors="coerce") <= MAX_LIVE_DTE)
    ].copy()
    if preferred.empty:
        return priced_error_row(candidate, structure, "no dated UW hot-chain long-option expiry in 7-60 DTE window")
    if close is not None and close > 0:
        preferred["_moneyness_distance"] = (pd.to_numeric(preferred["strike"], errors="coerce") - close).abs()
    else:
        preferred["_moneyness_distance"] = 0.0
    option = preferred.sort_values(["_moneyness_distance", "premium", "volume"], ascending=[True, False, False]).iloc[0]
    bid = _as_float(option.get("bid")) or 0.0
    ask = _as_float(option.get("ask")) or 0.0
    mark = _as_float(option.get("premium")) or 0.0
    mid = (bid + ask) / 2 if bid or ask else mark
    entry_debit = ask if ask > 0 else mid
    strike = float(option["strike"])
    if entry_debit <= 0 or strike <= 0:
        return priced_error_row(candidate, structure, "long-option debit could not be estimated from dated bid/ask")

    max_loss = round(entry_debit * 100, 2)
    breakeven = strike + entry_debit if right == "C" else strike - entry_debit
    buy_leg = _format_option_leg(
        _as_text(option.get("option_symbol")),
        "BUY",
        ticker=ticker,
        expiry=option["expiry_dt"],
        strike=strike,
        right=right,
    )
    trade_plan = _format_trade_plan("", buy_leg, entry_debit, entry_type="DEBIT")
    bid_ask_width = max(ask - bid, 0.0)
    liquidity_note = "dated UW EOD long-option quote; refresh Schwab chain before entry"
    status = RecommendationStatus.REVIEW.value
    hard_rejects = ""
    quality_rejects = _long_option_quality_rejects(
        entry_debit=entry_debit,
        max_loss=max_loss,
        signal_premium=_as_float(candidate.get("signal_premium")) or 0.0,
        combined_flow_bias=_as_float(candidate.get("combined_flow_bias")) or 0.0,
        macro_tape_candidate=_truthy(candidate.get("macro_tape_candidate")),
    )
    if bid_ask_width > max(entry_debit, 0.01) * 1.5:
        status = RecommendationStatus.WAIT_FOR_PRICE.value
        liquidity_note = "dated long-option bid/ask width is wide; keep visible and re-price with fresh Schwab chain"
    status, hard_rejects, quality_gate_reason, trade_quality_status, liquidity_note = (
        _finalize_quality_rejects(status, quality_rejects, note=liquidity_note)
    )
    underlying_tier, underlying_reason = _underlying_quality(candidate)

    return {
        "ticker": ticker,
        "full_name": candidate.get("full_name", ""),
        "issue_type": candidate.get("issue_type", ""),
        "marketcap": candidate.get("marketcap", ""),
        "avg30_volume": candidate.get("avg30_volume", ""),
        "total_volume": candidate.get("total_volume", ""),
        "total_open_interest": candidate.get("total_open_interest", ""),
        "underlying_quality_tier": underlying_tier,
        "underlying_quality_reason": underlying_reason,
        "bias": candidate.get("bias"),
        "flow_bias_label": candidate.get("flow_bias_label", candidate.get("bias")),
        "candidate_source": candidate.get("candidate_source", "flow_oi"),
        "macro_tape_candidate": candidate.get("macro_tape_candidate", False),
        "macro_tape_direction": candidate.get("macro_tape_direction", ""),
        "macro_tape_reason": candidate.get("macro_tape_reason", ""),
        "price_move_pct": candidate.get("price_move_pct", ""),
        "price_tape_source": candidate.get("price_tape_source", ""),
        "strategy": route,
        "strategy_family": route,
        "strategy_route": route,
        "entry_type": "DEBIT",
        "direction": direction,
        "structure": structure,
        "full_ticket": trade_plan,
        "trade_plan": trade_plan,
        "expiry": str(option["expiry_dt"]),
        "dte": int(float(option.get("dte") or 0)),
        "sell_leg": "",
        "buy_leg": buy_leg,
        "short_leg": "",
        "long_leg": buy_leg,
        "sell_leg_bid": "",
        "sell_leg_ask": "",
        "sell_leg_mid": "",
        "buy_leg_bid": round(bid, 2),
        "buy_leg_ask": round(ask, 2) if ask else "",
        "buy_leg_mid": round(mid, 2),
        "anchor_expiry": str(candidate.get("hot_top_expiry") or option["expiry_dt"]),
        "anchor_strike": float(candidate.get("hot_top_strike") or strike),
        "short_strike": "",
        "long_strike": strike,
        "spread_width": "",
        "entry_limit": round(entry_debit, 2),
        "mid": round(mid, 2),
        "bid": round(bid, 2),
        "ask": round(ask, 2) if ask else "",
        "max_profit": "",
        "max_loss": max_loss,
        "credit_width_ratio": 0.0,
        "debit_width_ratio": "",
        "trade_quality_status": trade_quality_status,
        "quality_gate_reason": quality_gate_reason,
        "remaining_upside": "",
        "breakeven": round(breakeven, 2),
        "target_exit": round(entry_debit * LONG_OPTION_TAKE_PROFIT_MULTIPLIER, 2),
        "target_entry": round(entry_debit, 2),
        "invalidation": f"underlying fails to progress toward breakeven {breakeven:.2f}, thesis breaks, or live quote degrades",
        "score": round(float(candidate.get("score") or 0), 2),
        "signal_premium": round(float(candidate.get("signal_premium") or 0), 2),
        "combined_flow_bias": candidate.get("combined_flow_bias", ""),
        "oi_directional_bias": candidate.get("oi_directional_bias", ""),
        "oi_directional_premium": candidate.get("oi_directional_premium", ""),
        "oi_bullish_premium": candidate.get("oi_bullish_premium", ""),
        "oi_bearish_premium": candidate.get("oi_bearish_premium", ""),
        "quality_status": candidate.get("quality_status"),
        "recommendation_status": status,
        "status_reason": liquidity_note,
        "hard_rejects": hard_rejects,
        "portfolio_risk_flag": False,
        "portfolio_risk_note": "",
        "visible_in_final_board": True,
        "flow_reason": candidate.get("flow_reason"),
    }


def construct_short_put(candidate: Mapping[str, Any], hot: pd.DataFrame) -> dict[str, Any]:
    """Build a one-lot cash-secured put attempt from dated UW hot-chain quotes."""

    ticker = str(candidate.get("ticker") or "").upper()
    close = _as_float(candidate.get("close"))
    chain = hot[hot["ticker"].astype(str).str.upper().eq(ticker) & hot["right"].astype(str).str.upper().eq("P")].copy()
    if close is not None:
        chain = chain[chain["strike"] < close]
        distance = (close - pd.to_numeric(chain["strike"], errors="coerce")) / close
        chain = chain[distance >= MIN_SHORT_PUT_DISTANCE_PCT]
    if chain.empty:
        return priced_error_row(candidate, "cash secured put", "missing suitable short-put leg in dated UW hot-chain source")

    preferred = chain[
        (pd.to_numeric(chain["dte"], errors="coerce") >= MIN_LIVE_DTE)
        & (pd.to_numeric(chain["dte"], errors="coerce") <= MAX_LIVE_DTE)
    ].copy()
    if preferred.empty:
        return priced_error_row(candidate, "cash secured put", "no dated UW hot-chain put expiry in 7-60 DTE window")
    short = preferred.sort_values(["premium", "volume"], ascending=[False, False]).iloc[0]
    short_bid = _as_float(short.get("bid")) or 0.0
    short_ask = _as_float(short.get("ask")) or 0.0
    short_mid = (short_bid + short_ask) / 2 if short_bid or short_ask else (_as_float(short.get("premium")) or 0.0)
    entry_credit = short_bid if short_bid > 0 else short_mid
    short_strike = float(short["strike"])
    if entry_credit <= 0 or short_strike <= 0:
        return priced_error_row(candidate, "cash secured put", "short-put credit could not be estimated from dated bid/ask")

    max_profit = round(entry_credit * 100, 2)
    max_loss = round(max((short_strike - entry_credit) * 100, 0), 2)
    breakeven = short_strike - entry_credit
    sell_leg = _format_option_leg(
        _as_text(short.get("option_symbol")),
        "SELL",
        ticker=ticker,
        expiry=short["expiry_dt"],
        strike=short_strike,
        right="P",
    )
    trade_plan = _format_trade_plan(sell_leg, "", entry_credit, entry_type="CREDIT")
    bid_ask_width = max(short_ask - short_bid, 0.0)
    liquidity_note = "dated UW EOD short-put quote; refresh Schwab chain before entry"
    status = RecommendationStatus.REVIEW.value
    hard_rejects = ""
    quality_rejects = _short_put_quality_rejects(
        entry_credit=entry_credit,
        max_loss=max_loss,
        signal_premium=_as_float(candidate.get("signal_premium")) or 0.0,
        combined_flow_bias=_as_float(candidate.get("combined_flow_bias")) or 0.0,
        macro_tape_candidate=_truthy(candidate.get("macro_tape_candidate")),
        spot=close,
        short_strike=short_strike,
    )
    if bid_ask_width > max(entry_credit, 0.01) * 1.5:
        status = RecommendationStatus.WAIT_FOR_PRICE.value
        liquidity_note = "dated short-put bid/ask width is wide; keep visible and re-price with fresh Schwab chain"
    status, hard_rejects, quality_gate_reason, trade_quality_status, liquidity_note = (
        _finalize_quality_rejects(status, quality_rejects, note=liquidity_note)
    )
    underlying_tier, underlying_reason = _underlying_quality(candidate)

    return {
        "ticker": ticker,
        "full_name": candidate.get("full_name", ""),
        "issue_type": candidate.get("issue_type", ""),
        "marketcap": candidate.get("marketcap", ""),
        "avg30_volume": candidate.get("avg30_volume", ""),
        "total_volume": candidate.get("total_volume", ""),
        "total_open_interest": candidate.get("total_open_interest", ""),
        "underlying_quality_tier": underlying_tier,
        "underlying_quality_reason": underlying_reason,
        "bias": candidate.get("bias"),
        "flow_bias_label": candidate.get("flow_bias_label", candidate.get("bias")),
        "candidate_source": candidate.get("candidate_source", "flow_oi"),
        "macro_tape_candidate": candidate.get("macro_tape_candidate", False),
        "macro_tape_direction": candidate.get("macro_tape_direction", ""),
        "macro_tape_reason": candidate.get("macro_tape_reason", ""),
        "price_move_pct": candidate.get("price_move_pct", ""),
        "price_tape_source": candidate.get("price_tape_source", ""),
        "structure": "cash secured put",
        "full_ticket": trade_plan,
        "trade_plan": trade_plan,
        "expiry": str(short["expiry_dt"]),
        "dte": int(float(short.get("dte") or 0)),
        "sell_leg": sell_leg,
        "buy_leg": "",
        "short_leg": sell_leg,
        "long_leg": "",
        "sell_leg_bid": round(short_bid, 2),
        "sell_leg_ask": round(short_ask, 2) if short_ask else "",
        "sell_leg_mid": round(short_mid, 2),
        "buy_leg_bid": "",
        "buy_leg_ask": "",
        "buy_leg_mid": "",
        "anchor_expiry": str(candidate.get("hot_top_expiry") or short["expiry_dt"]),
        "anchor_strike": float(candidate.get("hot_top_strike") or short_strike),
        "short_strike": short_strike,
        "long_strike": "",
        "spread_width": "",
        "entry_limit": round(entry_credit, 2),
        "mid": round(short_mid, 2),
        "bid": round(short_bid, 2),
        "ask": round(short_ask, 2) if short_ask else "",
        "max_profit": max_profit,
        "max_loss": max_loss,
        "credit_width_ratio": "",
        "short_put_cash_required": max_loss,
        "trade_quality_status": trade_quality_status,
        "quality_gate_reason": quality_gate_reason,
        "remaining_upside": max_profit,
        "breakeven": round(breakeven, 2),
        "target_exit": round(entry_credit * CREDIT_TAKE_PROFIT_REMAINING, 2),
        "target_entry": max(MIN_SEND_NOW_CREDIT, round(entry_credit, 2)),
        "invalidation": "fresh quote fails, thesis breaks, or underlying violates breakeven/flow support",
        "score": round(float(candidate.get("score") or 0), 2),
        "signal_premium": round(float(candidate.get("signal_premium") or 0), 2),
        "combined_flow_bias": candidate.get("combined_flow_bias", ""),
        "oi_directional_bias": candidate.get("oi_directional_bias", ""),
        "oi_directional_premium": candidate.get("oi_directional_premium", ""),
        "oi_bullish_premium": candidate.get("oi_bullish_premium", ""),
        "oi_bearish_premium": candidate.get("oi_bearish_premium", ""),
        "quality_status": candidate.get("quality_status"),
        "recommendation_status": status,
        "status_reason": liquidity_note,
        "hard_rejects": hard_rejects,
        "portfolio_risk_flag": False,
        "portfolio_risk_note": "",
        "visible_in_final_board": True,
        "flow_reason": candidate.get("flow_reason"),
    }


