def _selector_policy_definition(policy_id: str) -> Mapping[str, Any]:
    """Return one configured selector policy by its stable identifier."""

    return next(
        (
            policy
            for policy in SELECTOR_CHALLENGER_POLICIES
            if _as_text(policy.get("policy_id")) == _as_text(policy_id)
        ),
        {},
    )


def _promoted_selector_policy_definition() -> Mapping[str, Any]:
    """Return the configured credit policy that governs the established sleeve."""

    return _selector_policy_definition(PROMOTED_SELECTOR_POLICY_ID)


def _promoted_selector_daily_cap() -> int:
    policy = _promoted_selector_policy_definition()
    return max(
        int(_as_float(policy.get("daily_cap")) or MAX_WALKFORWARD_SELECTIONS_PER_DAY),
        1,
    )


def _selector_challenger_replay_frame(
    out_root: Path,
    *,
    as_of: Optional[dt.date] = None,
) -> tuple[pd.DataFrame, Optional[dt.date], str, str]:
    pinned_path, pin_error, _ = _codexuw_pinned_replay_path(out_root)
    if pin_error or pinned_path is None or not pinned_path.exists():
        return pd.DataFrame(), None, str(pinned_path or ""), pin_error or "pinned replay missing"
    manifest_path = _replay_manifest_path_for_detail(pinned_path)
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        split_day = _optional_iso_date(manifest.get("split_day")) if isinstance(manifest, Mapping) else None
        raw = pd.read_csv(pinned_path, low_memory=False)
    except (OSError, json.JSONDecodeError, pd.errors.ParserError) as exc:
        return pd.DataFrame(), None, str(pinned_path), f"selector replay source unreadable: {exc}"
    if split_day is None:
        return pd.DataFrame(), None, str(pinned_path), "selector replay manifest missing split_day"
    required = {
        "asof",
        "exit_day",
        "ticker",
        "pnl_1x",
        "exact_fillable",
        "exact_evaluated",
        "next_session_reprice_observed",
        "next_session_reprice_approved",
        "promotion_outcome_available_date",
        "promotion_outcome_eligible",
        "regime",
    }
    if raw.empty or not required.issubset(raw.columns):
        return pd.DataFrame(), split_day, str(pinned_path), "selector replay source missing required columns"

    frame = raw[raw["exact_fillable"].map(_truthy)].copy()
    frame["signal_date"] = pd.to_datetime(frame["asof"], errors="coerce")
    frame["outcome_available_date"] = pd.to_datetime(
        frame["promotion_outcome_available_date"],
        errors="coerce",
    )
    frame["realized_pnl"] = pd.to_numeric(frame["pnl_1x"], errors="coerce")
    promotion_eligible = frame["promotion_outcome_eligible"].map(_truthy)
    frame.loc[~promotion_eligible, "realized_pnl"] = math.nan
    frame = frame[
        frame["signal_date"].notna()
        & frame["outcome_available_date"].notna()
    ].copy()
    if as_of is not None:
        cutoff = pd.Timestamp(as_of)
        frame = frame[frame["signal_date"].dt.date.le(as_of)].copy()

        # The pinned replay is generated later than many historical report dates.
        # Keep then-visible proposals in the selector opportunity set, but mask
        # execution and outcome fields that were not knowable at the requested
        # as-of. Otherwise a historical run can borrow a future close from the
        # same immutable replay file.
        planned_entry = pd.to_datetime(
            frame.get("planned_entry_date", pd.Series(pd.NaT, index=frame.index)),
            errors="coerce",
        )
        fallback_entry = frame["signal_date"].map(
            lambda value: pd.Timestamp(_add_regular_market_days(value.date(), 1))
        )
        planned_entry = planned_entry.where(planned_entry.notna(), fallback_entry)
        future_entry = planned_entry >= cutoff
        for column in (
            "next_session_bid",
            "next_session_ask",
            "next_session_mid",
            "next_session_quote_width_pct",
            "executed_entry_price",
            "executed_entry_credit",
            "executed_entry_debit",
        ):
            if column in frame.columns:
                frame.loc[future_entry, column] = math.nan
        for column in ("next_session_reprice_observed", "next_session_reprice_approved"):
            if column in frame.columns:
                frame.loc[future_entry, column] = False
        if "next_session_reprice_reason" in frame.columns:
            frame.loc[future_entry, "next_session_reprice_reason"] = "not_available_as_of"

        future_outcome = frame["outcome_available_date"] >= cutoff
        frame.loc[future_outcome, "realized_pnl"] = math.nan
        frame.loc[future_outcome, "exact_evaluated"] = False
        for column in (
            "executed_target_exit",
            "executed_stop_exit",
            "exit_value",
            "holding_sessions",
            "pnl_1x",
            "return_on_risk",
        ):
            if column in frame.columns:
                frame.loc[future_outcome, column] = math.nan
        for column in ("exact_reason", "exit_trigger"):
            if column in frame.columns:
                frame.loc[future_outcome, column] = "not_available_as_of"
    if frame.empty:
        return frame, split_day, str(pinned_path), "selector replay source has no fillable rows before as-of"

    frame["strategy_route"] = frame.get(
        "strategy_route",
        frame.get("strategy", pd.Series("", index=frame.index)).map(_strategy_route_from_text),
    ).map(lambda value: _as_text(value) or _strategy_route_from_text(value))
    frame["regime"] = frame["regime"].map(_regime_bucket)
    frame["dte_bucket"] = frame.get("dte", pd.Series(index=frame.index, dtype=float)).map(_dte_bucket)
    frame["liquidity_bucket"] = frame.apply(_liquidity_bucket, axis=1)
    entry_type = frame.apply(
        lambda row: _as_text(row.get("entry_side") or row.get("strategy_kind")).upper(),
        axis=1,
    )
    frame["entry_type"] = entry_type
    frame["economics_bucket"] = [
        _economics_bucket(row, side)
        for (_, row), side in zip(frame.iterrows(), entry_type)
    ]
    for column in (
        "decision_score",
        "flow_total_premium",
        "source_contract_oi",
        "entry_quote_width_pct",
        "combined_flow_bias",
        "entry_credit_pct_width",
        "entry_debit_pct_width",
        "reward_risk",
        "expected_move_ratio",
        "iv_rank",
        "dte",
    ):
        frame[column] = pd.to_numeric(
            frame.get(column, pd.Series(index=frame.index, dtype=float)),
            errors="coerce",
        )
    frame["ticker"] = frame["ticker"].map(lambda value: _as_text(value).upper())
    frame["decision_pass"] = frame.get(
        "decision_pass",
        pd.Series(False, index=frame.index),
    ).map(_truthy)
    frame = frame[
        frame["ticker"].ne("")
        & frame["strategy_route"].astype(str).str.strip().ne("")
        & frame["regime"].astype(str).str.strip().ne("")
    ].copy()
    frame = frame.sort_values(
        [
            "signal_date",
            "ticker",
            "strategy_route",
            "regime",
            "decision_pass",
            "decision_score",
            "flow_total_premium",
            "source_contract_oi",
            "entry_quote_width_pct",
        ],
        ascending=[True, True, True, True, False, False, False, False, True],
        kind="mergesort",
    ).drop_duplicates(["signal_date", "ticker", "strategy_route", "regime"], keep="first")
    return frame, split_day, str(pinned_path), ""


def _selector_training_metrics(pnl: pd.Series, day_count: int) -> Optional[dict[str, float]]:
    values = pd.to_numeric(pnl, errors="coerce").dropna()
    if values.empty:
        return None
    gross_profit = float(values[values > 0].sum())
    gross_loss = float(-values[values < 0].sum())
    profit_factor = gross_profit / gross_loss if gross_loss > 0 else (math.inf if gross_profit > 0 else math.nan)
    return {
        "sample_size": float(len(values)),
        "day_count": float(day_count),
        "profit_factor": float(profit_factor),
        "avg_pnl": float(values.mean()),
        "win_rate": float((values > 0).mean()),
    }


def _selector_v4_replay_assessment(
    row: Mapping[str, Any],
    policy: Optional[Mapping[str, Any]] = None,
) -> tuple[bool, float, list[str], str]:
    """Map point-in-time replay fields into the promoted live selector contract."""

    mapped = dict(row)
    entry_type = _as_text(row.get("entry_type") or row.get("entry_side") or row.get("strategy_kind")).upper()
    expected_move_ratio = _as_float(row.get("expected_move_ratio"))
    earnings = _row_date(row.get("next_earnings_dt"))
    expiry = _row_date(row.get("expiry"))
    signal_day = _row_date(row.get("asof") or row.get("signal_date"))
    route = _as_text(row.get("strategy_route")) or _strategy_route_from_text(
        row.get("strategy")
    )
    management_sessions = _management_holding_sessions(
        {**mapped, "strategy_route": route, "entry_type": entry_type}
    )
    planned_exit = (
        _planned_trade_exit_date(signal_day, expiry, management_sessions)
        if signal_day
        else None
    )
    selector_risk_exit = (
        _planned_trade_exit_date(
            signal_day,
            expiry,
            PLANNED_TRADE_HOLDING_SESSIONS,
        )
        if signal_day
        else None
    )
    mapped.update(
        {
            "strategy_route": route,
            "entry_type": entry_type,
            "underlying_quality_tier": _as_text(row.get("underlying_quality_tier")) or "unknown",
            "hard_rejects": _as_text(row.get("hard_rejects") or row.get("quality_gate_reason")),
            "earnings_before_expiry": bool(earnings and expiry and earnings <= expiry),
            "planned_holding_exit_date": planned_exit.isoformat() if planned_exit else "",
            "planned_holding_sessions": management_sessions,
            "management_holding_exit_date": planned_exit.isoformat() if planned_exit else "",
            "management_holding_sessions": management_sessions,
            "earnings_within_holding_horizon": bool(
                signal_day
                and earnings
                and planned_exit
                and signal_day <= earnings <= planned_exit
            ),
            "selector_risk_exit_date": (
                selector_risk_exit.isoformat() if selector_risk_exit else ""
            ),
            "selector_risk_horizon_sessions": PLANNED_TRADE_HOLDING_SESSIONS,
            "earnings_within_selector_risk_horizon": bool(
                signal_day
                and earnings
                and selector_risk_exit
                and signal_day <= earnings <= selector_risk_exit
            ),
            "macro_event_count_within_holding_horizon": row.get(
                "macro_event_count_within_holding_horizon",
                row.get("macro_event_count_before_expiry", 0),
            ),
            "live_quote_width_pct": row.get("entry_quote_width_pct"),
            "credit_width_ratio": row.get("entry_credit_pct_width"),
            "entry_credit": row.get("entry_credit"),
            "debit_width_ratio": row.get("entry_debit_pct_width"),
            "live_distance_pct": expected_move_ratio if entry_type == "CREDIT" else "",
            "live_expected_move_pct": 1.0 if entry_type == "CREDIT" else "",
            "live_breakeven_expected_move_ratio": (
                1.0 / expected_move_ratio
                if entry_type == "DEBIT" and expected_move_ratio is not None and expected_move_ratio > 0
                else ""
            ),
            "max_profit": row.get("reward_risk"),
            "max_loss": 1.0,
            "synthesis_score": row.get("decision_score"),
            "selector_replay_mode": True,
        }
    )
    return _selector_policy_row_assessment(
        mapped,
        require_live_probability=False,
        policy=policy,
    )


def _select_challenger_policy_rows(frame: pd.DataFrame, policy: Mapping[str, Any]) -> pd.DataFrame:
    selected: list[pd.Series] = []
    group_columns = list(policy.get("group_columns") or ())
    lookback_days = int(_as_float(policy.get("lookback_days")) or 0)
    minimum_training_sample = int(
        _as_float(policy.get("minimum_training_sample")) or MIN_WALKFORWARD_TRAIN_SAMPLE_SIZE
    )
    daily_cap = int(_as_float(policy.get("daily_cap")) or 1)
    rank_mode = _as_text(policy.get("rank_mode"))
    required_true_columns = tuple(policy.get("required_true_columns") or ())
    use_training_gate = bool(policy.get("use_training_gate", True))
    for signal_day in sorted(frame["signal_date"].dropna().unique()):
        current = frame[frame["signal_date"] == signal_day].copy()
        for column in required_true_columns:
            current = current[current.get(column, pd.Series(False, index=current.index)).map(_truthy)].copy()
        if current.empty:
            continue
        # A policy with an entry-filter profile is a live-parity selector. Do
        # not maintain a profile-name allowlist here: a new profiled policy
        # would otherwise silently skip its route, liquidity, event, and
        # economic eligibility checks during replay.
        if _as_text(policy.get("entry_filter_profile")):
            assessments = current.apply(
                lambda row: _selector_v4_replay_assessment(row, policy=policy),
                axis=1,
            )
            current["__selector_eligible"] = assessments.map(lambda value: bool(value[0]))
            current["__selector_score"] = assessments.map(lambda value: float(value[1]))
            current["__selector_structural_score"] = current.apply(
                lambda row: _selector_structural_score(row["__selector_score"], row),
                axis=1,
            )
            current["__selector_sleeve"] = assessments.map(lambda value: _as_text(value[3]).upper())
            current["__selector_target_profit"] = current.apply(
                _selector_one_lot_target_profit,
                axis=1,
            )
            current["__selector_economic_score"] = current.apply(
                lambda row: _selector_economic_score(
                    row["__selector_score"],
                    row["__selector_target_profit"],
                ),
                axis=1,
            )
            current = current[current["__selector_eligible"]].copy()
            if current.empty:
                continue
            sleeve_cap = int(_as_float(policy.get("daily_sleeve_cap")) or 1)
            second_slot_max_structural_score_gap = (
                _as_float(policy.get("second_slot_max_structural_score_gap"))
                if policy.get("second_slot_max_structural_score_gap") is not None
                else MAX_SELECTOR_SECOND_SLOT_STRUCTURAL_SCORE_GAP
            )
            seen_tickers: set[str] = set()
            selected_structural_scores: list[float] = []
            for sleeve in ("CREDIT", "DEBIT"):
                ranked = _selector_policy_ranked_frame(
                    current[current["__selector_sleeve"].eq(sleeve)],
                    policy,
                )
                selected_in_sleeve = 0
                for _, selected_row in ranked.iterrows():
                    if len(seen_tickers) >= daily_cap:
                        break
                    ticker = canonical_ticker_key(selected_row.get("ticker"))
                    if ticker in seen_tickers:
                        continue
                    selected.append(selected_row)
                    seen_tickers.add(ticker)
                    selected_structural_scores.append(float(selected_row["__selector_structural_score"]))
                    selected_in_sleeve += 1
                    if selected_in_sleeve >= sleeve_cap:
                        break
                if len(seen_tickers) >= daily_cap:
                    break
            if len(seen_tickers) < daily_cap and selected_structural_scores:
                ranked_remaining = _selector_policy_ranked_frame(current, policy)
                daily_best_structural_score = max(selected_structural_scores)
                for _, selected_row in ranked_remaining.iterrows():
                    ticker = canonical_ticker_key(selected_row.get("ticker"))
                    structural_score = float(selected_row["__selector_structural_score"])
                    if ticker in seen_tickers:
                        continue
                    if (
                        second_slot_max_structural_score_gap is not None
                        and daily_best_structural_score - structural_score > second_slot_max_structural_score_gap
                    ):
                        continue
                    selected.append(selected_row)
                    seen_tickers.add(ticker)
                    if len(seen_tickers) >= daily_cap:
                        break
            continue
        if not use_training_gate:
            ranked = current.sort_values(
                [
                    "decision_score",
                    "flow_total_premium",
                    "source_contract_oi",
                    "entry_quote_width_pct",
                    "ticker",
                ],
                ascending=[False, False, False, True, True],
                kind="mergesort",
            )
            seen_tickers: set[str] = set()
            for _, row in ranked.iterrows():
                ticker = canonical_ticker_key(row.get("ticker"))
                if ticker in seen_tickers:
                    continue
                selected.append(row)
                seen_tickers.add(ticker)
                if len(seen_tickers) >= daily_cap:
                    break
            continue
        history = frame[frame["outcome_available_date"] < signal_day]
        if lookback_days > 0:
            history = history[
                history["outcome_available_date"] >= signal_day - pd.Timedelta(days=lookback_days)
            ]
        qualified: dict[tuple[str, ...], dict[str, float]] = {}
        for key, group in history.groupby(group_columns, dropna=False):
            normalized_key = key if isinstance(key, tuple) else (key,)
            metrics = _selector_training_metrics(group["realized_pnl"], int(group["signal_date"].nunique()))
            if metrics is None:
                continue
            if (
                metrics["sample_size"] >= minimum_training_sample
                and metrics["day_count"] >= MIN_WALKFORWARD_TRAIN_DAYS
                and metrics["profit_factor"] >= MIN_EXPECTANCY_PROFIT_FACTOR
                and metrics["avg_pnl"] > 0
                and metrics["win_rate"] >= MIN_EXPECTANCY_WIN_RATE
            ):
                qualified[tuple(_as_text(value) for value in normalized_key)] = metrics
        if not qualified:
            continue
        current["__policy_key"] = current.apply(
            lambda row: tuple(_as_text(row.get(column)) for column in group_columns),
            axis=1,
        )
        current = current[current["__policy_key"].isin(qualified)].copy()
        if current.empty:
            continue
        current["__training_avg_pnl"] = current["__policy_key"].map(
            lambda key: qualified[key]["avg_pnl"]
        )
        current["__training_profit_factor"] = current["__policy_key"].map(
            lambda key: qualified[key]["profit_factor"]
        )
        current["__training_sample_size"] = current["__policy_key"].map(
            lambda key: qualified[key]["sample_size"]
        )
        if rank_mode == "training_edge_then_decision":
            rank_columns = [
                "__training_avg_pnl",
                "__training_profit_factor",
                "__training_sample_size",
                "decision_score",
                "flow_total_premium",
                "source_contract_oi",
                "entry_quote_width_pct",
                "ticker",
            ]
            ascending = [False, False, False, False, False, False, True, True]
        else:
            rank_columns = [
                "decision_score",
                "flow_total_premium",
                "source_contract_oi",
                "entry_quote_width_pct",
                "ticker",
            ]
            ascending = [False, False, False, True, True]
        ranked = current.sort_values(rank_columns, ascending=ascending, kind="mergesort")
        seen_tickers: set[str] = set()
        for _, row in ranked.iterrows():
            ticker = canonical_ticker_key(row.get("ticker"))
            if ticker in seen_tickers:
                continue
            selected.append(row)
            seen_tickers.add(ticker)
            if len(seen_tickers) >= daily_cap:
                break
    if not selected:
        return frame.iloc[0:0].copy()
    return pd.DataFrame(selected).reset_index(drop=True)


def _selector_partition_metrics(
    selected: pd.DataFrame,
    *,
    policy: Mapping[str, Any],
    partition: str,
    source_path: str,
) -> dict[str, Any]:
    selected_count = int(len(selected))
    realized_pnl = pd.to_numeric(
        selected.get("realized_pnl", pd.Series(dtype=float)),
        errors="coerce",
    )
    reprice_observed = selected.get(
        "next_session_reprice_observed",
        pd.Series(False, index=selected.index),
    ).map(_truthy)
    reprice_approved = selected.get(
        "next_session_reprice_approved",
        pd.Series(False, index=selected.index),
    ).map(_truthy)
    exact_evaluated = selected.get(
        "exact_evaluated",
        pd.Series(False, index=selected.index),
    ).map(_truthy)
    reprice_reason = selected.get(
        "next_session_reprice_reason",
        pd.Series("", index=selected.index),
    ).astype(str)
    missing_next_session_quote = reprice_reason.eq("missing_next_session_entry_leg_quote")
    executed = reprice_approved & exact_evaluated & realized_pnl.notna()
    known_no_entry = (reprice_observed & ~reprice_approved) | missing_next_session_quote
    # Reprice approval resolves the execution decision immediately; final P/L may
    # remain censored until the position exits. Do not let open approved trades
    # masquerade as missing execution observations and invalidate a fresh replay.
    # A missing next-session print is also a resolved no-trade: the tape had no
    # quote to fill, so it is not an incomplete observation of a live book.
    execution_resolved = known_no_entry | reprice_approved
    reprice_observed_or_resolved = reprice_observed | missing_next_session_quote
    executed_rows = selected.loc[executed].copy()
    pnl = realized_pnl.loc[executed].dropna()
    metrics = _selector_training_metrics(
        pnl,
        int(executed_rows.get("signal_date", pd.Series(dtype=object)).nunique()),
    )
    risk_returns = pd.to_numeric(
        executed_rows.get("return_on_risk", pd.Series(math.nan, index=executed_rows.index)),
        errors="coerce",
    )
    risk_return_rows = executed_rows.loc[risk_returns.notna()]
    risk_metrics = _selector_training_metrics(
        risk_returns,
        int(risk_return_rows.get("signal_date", pd.Series(dtype=object)).nunique()),
    )
    sample_size = int(metrics["sample_size"]) if metrics else 0
    risk_normalized_sample_size = int(risk_metrics["sample_size"]) if risk_metrics else 0
    outcome_coverage = float(execution_resolved.sum() / selected_count) if selected_count else 0.0
    reprice_observed_coverage = (
        float(reprice_observed_or_resolved.sum() / selected_count) if selected_count else 0.0
    )
    reprice_approval_rate = float(reprice_approved.sum() / selected_count) if selected_count else 0.0
    day_count = int(metrics["day_count"]) if metrics else 0
    profit_factor = metrics["profit_factor"] if metrics else math.nan
    avg_pnl = metrics["avg_pnl"] if metrics else math.nan
    risk_normalized_profit_factor = (
        risk_metrics["profit_factor"] if risk_metrics else math.nan
    )
    risk_normalized_avg_return = risk_metrics["avg_pnl"] if risk_metrics else math.nan
    ticker_counts = executed_rows.get("ticker", pd.Series(dtype=str)).astype(str).value_counts()
    unique_ticker_count = int(len(ticker_counts))
    top_ticker = _as_text(ticker_counts.index[0]) if not ticker_counts.empty else ""
    top_ticker_count = int(ticker_counts.iloc[0]) if not ticker_counts.empty else 0
    # Concentration describes the realized trade sample, not every source plan
    # that was later declined by the next-session reprice. Using selected_count
    # understates single-name concentration whenever many planned entries did
    # not become trades.
    top_ticker_share = (
        float(top_ticker_count / len(executed_rows)) if not executed_rows.empty else math.nan
    )
    blocking_reasons: list[str] = []
    required_sample_size = (
        MIN_SELECTOR_HELDOUT_SAMPLE_SIZE
        if partition == "heldout_test"
        else MIN_SELECTOR_PROMOTION_SAMPLE_SIZE
    )
    if sample_size < required_sample_size:
        blocking_reasons.append("sample_size_below_minimum")
    if risk_normalized_sample_size < required_sample_size:
        blocking_reasons.append("risk_normalized_sample_size_below_minimum")
    if risk_normalized_sample_size != sample_size:
        blocking_reasons.append("risk_normalized_sample_incomplete")
    if selected_count and reprice_observed_coverage < MIN_SELECTOR_EXECUTION_RESOLUTION_COVERAGE:
        blocking_reasons.append("next_session_reprice_observation_coverage_below_95pct")
    if selected_count and outcome_coverage < MIN_SELECTOR_EXECUTION_RESOLUTION_COVERAGE:
        blocking_reasons.append("selected_execution_resolution_coverage_below_95pct")
    if day_count < MIN_SELECTOR_PROMOTION_DAY_COUNT:
        blocking_reasons.append("day_count_below_minimum")
    if math.isnan(profit_factor) or profit_factor < MIN_EXPECTANCY_PROFIT_FACTOR:
        blocking_reasons.append("profit_factor_below_minimum")
    if not math.isfinite(avg_pnl) or avg_pnl <= 0:
        blocking_reasons.append("average_pnl_not_positive")
    if (
        math.isnan(risk_normalized_profit_factor)
        or risk_normalized_profit_factor < MIN_EXPECTANCY_PROFIT_FACTOR
    ):
        blocking_reasons.append("risk_normalized_profit_factor_below_minimum")
    if not math.isfinite(risk_normalized_avg_return) or risk_normalized_avg_return <= 0:
        blocking_reasons.append("risk_normalized_average_return_not_positive")
    return {
        "policy_id": _as_text(policy.get("policy_id")),
        "partition": partition,
        "partition_start": (
            selected["signal_date"].min().date().isoformat() if not selected.empty else ""
        ),
        "partition_end": selected["signal_date"].max().date().isoformat() if not selected.empty else "",
        "selected_count": selected_count,
        "sample_size": sample_size,
        "outcome_coverage": round(outcome_coverage, 6),
        "reprice_observed_count": int(reprice_observed.sum()),
        "reprice_observed_coverage": round(reprice_observed_coverage, 6),
        "reprice_approved_count": int(reprice_approved.sum()),
        "reprice_approval_rate": round(reprice_approval_rate, 6),
        "executed_count": int(executed.sum()),
        "execution_resolution_count": int(execution_resolved.sum()),
        "required_sample_size": required_sample_size,
        "day_count": day_count,
        "required_day_count": MIN_SELECTOR_PROMOTION_DAY_COUNT,
        "profit_factor": round(profit_factor, 6) if not math.isnan(profit_factor) else "",
        "required_profit_factor": MIN_EXPECTANCY_PROFIT_FACTOR,
        "avg_pnl": round(avg_pnl, 4) if math.isfinite(avg_pnl) else "",
        "risk_normalized_sample_size": risk_normalized_sample_size,
        "risk_normalized_profit_factor": (
            round(risk_normalized_profit_factor, 6)
            if not math.isnan(risk_normalized_profit_factor)
            else ""
        ),
        "risk_normalized_avg_return": (
            round(risk_normalized_avg_return, 6)
            if math.isfinite(risk_normalized_avg_return)
            else ""
        ),
        "total_pnl": round(float(pnl.sum()), 4) if not pnl.empty else "",
        "max_drawdown": round(_series_max_drawdown(pnl), 4) if not pnl.empty else "",
        "win_rate": round(metrics["win_rate"], 6) if metrics else "",
        "unique_ticker_count": unique_ticker_count,
        "top_ticker": top_ticker,
        "top_ticker_count": top_ticker_count,
        "top_ticker_share": round(top_ticker_share, 6) if math.isfinite(top_ticker_share) else "",
        "partition_status": "PASS" if not blocking_reasons else "BLOCK",
        "promotion_status": "PENDING",
        "blocking_reasons": "; ".join(blocking_reasons),
        "selected_routes": "; ".join(
            sorted(
                {
                    _as_text(value)
                    for value in executed_rows.get("strategy_route", pd.Series(dtype=object))
                    if _as_text(value)
                }
            )
        ),
        "selection_outcome_independent": True,
        "policy_definition": json.dumps(dict(policy), sort_keys=True),
        "source_path": source_path,
    }


def build_selector_challenger_audit(
    out_root: Path,
    *,
    as_of: Optional[dt.date] = None,
) -> pd.DataFrame:
    frame, split_day, source_path, error = _selector_challenger_replay_frame(out_root, as_of=as_of)
    if error or frame.empty or split_day is None:
        return pd.DataFrame(columns=SELECTOR_CHALLENGER_AUDIT_COLUMNS)
    rows: list[dict[str, Any]] = []
    for policy in SELECTOR_CHALLENGER_POLICIES:
        selected = _select_challenger_policy_rows(frame, policy)
        partitions = {
            "pre_split": selected[selected["signal_date"].dt.date <= split_day].copy(),
            "heldout_test": selected[selected["signal_date"].dt.date > split_day].copy(),
        }
        policy_rows = [
            _selector_partition_metrics(
                partition_rows,
                policy=policy,
                partition=partition,
                source_path=source_path,
            )
            for partition, partition_rows in partitions.items()
        ]
        promoted = all(row["partition_status"] == "PASS" for row in policy_rows)
        overall_row = _selector_partition_metrics(
            selected,
            policy=policy,
            partition="overall",
            source_path=source_path,
        )
        policy_rows.append(overall_row)
        for row in policy_rows:
            row["promotion_status"] = "PROMOTED" if promoted else "REJECTED"
            rows.append(row)
    return pd.DataFrame(rows, columns=SELECTOR_CHALLENGER_AUDIT_COLUMNS)


def summarize_selector_challenger_audit(audit: pd.DataFrame) -> dict[str, Any]:
    if audit is None or audit.empty:
        return {
            "status": "block",
            "policy_count": 0,
            "promoted_policy_ids": [],
            "reason": "no selector challenger audit rows",
        }
    promoted = sorted(
        {
            _as_text(value)
            for value in audit.loc[
                audit["promotion_status"].astype(str).str.upper().eq("PROMOTED"),
                "policy_id",
            ]
            if _as_text(value)
        }
    )
    heldout = audit[audit["partition"].astype(str).eq("heldout_test")].copy()
    best = heldout.sort_values(
        ["profit_factor", "sample_size", "avg_pnl"],
        ascending=[False, False, False],
        kind="mergesort",
    ).head(1)
    best_row = best.iloc[0].to_dict() if not best.empty else {}
    active_overall = audit[
        audit["partition"].astype(str).eq("overall")
        & audit["policy_id"].astype(str).eq(PROMOTED_SELECTOR_POLICY_ID)
    ].sort_values(
        ["profit_factor", "sample_size", "avg_pnl"],
        ascending=[False, False, False],
        kind="mergesort",
    ).head(1)
    active_overall_row = active_overall.iloc[0].to_dict() if not active_overall.empty else {}
    active_heldout = audit[
        audit["partition"].astype(str).eq("heldout_test")
        & audit["policy_id"].astype(str).eq(PROMOTED_SELECTOR_POLICY_ID)
    ].sort_values(
        ["profit_factor", "sample_size", "avg_pnl"],
        ascending=[False, False, False],
        kind="mergesort",
    ).head(1)
    active_heldout_row = active_heldout.iloc[0].to_dict() if not active_heldout.empty else {}
    active_policy_status = (
        "UNAVAILABLE"
        if not active_overall_row
        else "PROMOTED"
        if (
            _as_text(active_overall_row.get("promotion_status")).upper() == "PROMOTED"
            and _as_text(active_overall_row.get("partition_status")).upper() == "PASS"
        )
        else "REJECTED"
    )
    # A passing challenger is useful research, but it is not the policy that
    # screens the live board. Do not let its PF or sample appear as active
    # selector evidence when the configured policy failed its own partitions.
    active_metrics = active_overall_row if active_policy_status == "PROMOTED" else {}
    active_heldout_metrics = active_heldout_row if active_policy_status == "PROMOTED" else {}
    return {
        "status": "pass" if promoted else "block",
        "active_policy_id": PROMOTED_SELECTOR_POLICY_ID,
        "active_policy_status": active_policy_status,
        "production_status": "block",
        "validation_scope": (
            "development_backtest_policy_tuned_through_"
            + PROMOTED_SELECTOR_DEVELOPMENT_CUTOFF
            + "_prospective_tracking_started_"
            + PROMOTED_SELECTOR_PROSPECTIVE_START
        ),
        "policy_count": int(audit["policy_id"].astype(str).nunique()),
        "promoted_policy_ids": promoted,
        "promoted_policy_id": PROMOTED_SELECTOR_POLICY_ID if active_metrics else "",
        "promoted_profit_factor": _as_float(active_metrics.get("profit_factor")),
        "promoted_sample_size": int(_as_float(active_metrics.get("sample_size")) or 0),
        "promoted_day_count": int(_as_float(active_metrics.get("day_count")) or 0),
        "promoted_reprice_approval_rate": _as_float(
            active_metrics.get("reprice_approval_rate")
        ),
        "promoted_execution_resolution_coverage": _as_float(
            active_metrics.get("outcome_coverage")
        ),
        "promoted_avg_pnl": _as_float(active_metrics.get("avg_pnl")),
        "promoted_win_rate": _as_float(active_metrics.get("win_rate")),
        "promoted_selection_start": _as_text(active_metrics.get("partition_start")),
        "promoted_selection_end": _as_text(active_metrics.get("partition_end")),
        "promoted_unique_ticker_count": int(_as_float(active_metrics.get("unique_ticker_count")) or 0),
        "promoted_top_ticker": _as_text(active_metrics.get("top_ticker")),
        "promoted_top_ticker_share": _as_float(active_metrics.get("top_ticker_share")),
        "promoted_heldout_profit_factor": _as_float(active_heldout_metrics.get("profit_factor")),
        "promoted_heldout_sample_size": int(
            _as_float(active_heldout_metrics.get("sample_size")) or 0
        ),
        "promoted_heldout_avg_pnl": _as_float(active_heldout_metrics.get("avg_pnl")),
        "best_heldout_policy_id": _as_text(best_row.get("policy_id")),
        "best_heldout_profit_factor": _as_float(best_row.get("profit_factor")),
        "best_heldout_sample_size": int(_as_float(best_row.get("sample_size")) or 0),
        "required_profit_factor": MIN_EXPECTANCY_PROFIT_FACTOR,
        "required_pre_split_sample_size": MIN_SELECTOR_PROMOTION_SAMPLE_SIZE,
        "required_heldout_sample_size": MIN_SELECTOR_HELDOUT_SAMPLE_SIZE,
        "required_partition_day_count": MIN_SELECTOR_PROMOTION_DAY_COUNT,
    }


def _strategy_route_series(frame: Optional[pd.DataFrame]) -> pd.Series:
    if frame is None or frame.empty:
        return pd.Series(dtype=object)
    if "strategy_route" in frame.columns:
        routes = frame["strategy_route"].fillna("").astype(str)
    elif "strategy" in frame.columns:
        routes = frame["strategy"].map(_strategy_route_from_text)
    elif "structure" in frame.columns:
        routes = frame["structure"].map(_strategy_route_from_text)
    else:
        routes = pd.Series("", index=frame.index, dtype=object)
    return routes.map(_as_text)


def _selector_policy_partition_row(
    audit: pd.DataFrame,
    policy_id: str,
    partition: str,
) -> Mapping[str, Any]:
    if audit is None or audit.empty:
        return {}
    rows = audit[
        audit["policy_id"].astype(str).eq(policy_id)
        & audit["partition"].astype(str).eq(partition)
    ]
    return rows.iloc[0].to_dict() if not rows.empty else {}


def build_strategy_breadth_audit(
    structure_attempts: pd.DataFrame,
    priced: pd.DataFrame,
    final: pd.DataFrame,
    trade_tickets: pd.DataFrame,
    selector_audit: pd.DataFrame,
    *,
    supported_routes_by_policy: Optional[Mapping[str, set[str]]] = None,
) -> pd.DataFrame:
    """Expose strategy construction and production authorization in one artifact."""

    frames = {
        "attempted": structure_attempts,
        "priced": priced,
        "reviewed": final,
        "tickets": trade_tickets,
    }
    routes = {name: _strategy_route_series(frame) for name, frame in frames.items()}
    final_status = (
        final.get("selector_policy_status", pd.Series("", index=final.index))
        .fillna("")
        .astype(str)
        .str.upper()
        if final is not None and not final.empty
        else pd.Series(dtype=object)
    )
    ticket_ready = (
        trade_tickets.get("ready_to_enter", pd.Series(False, index=trade_tickets.index)).map(_truthy)
        if trade_tickets is not None and not trade_tickets.empty
        else pd.Series(dtype=bool)
    )
    target_status = (
        trade_tickets.get("target_order_status", pd.Series("", index=trade_tickets.index))
        .fillna("")
        .astype(str)
        .str.lower()
        if trade_tickets is not None and not trade_tickets.empty
        else pd.Series(dtype=object)
    )
    rows: list[dict[str, Any]] = []
    for item in STRATEGY_BREADTH_ROUTE_CATALOG:
        route = item["strategy_route"]
        entry_type = item["entry_type"]
        implementation = item["implementation_status"]
        policy_id = (
            SELECTOR_POLICY_ID_BY_ROUTE.get(route, "")
            if implementation == "IMPLEMENTED"
            else ""
        )
        pre = _selector_policy_partition_row(selector_audit, policy_id, "pre_split")
        post = _selector_policy_partition_row(selector_audit, policy_id, "heldout_test")
        overall = _selector_policy_partition_row(selector_audit, policy_id, "overall")
        policy_promoted = bool(
            policy_id
            and _as_text(overall.get("promotion_status")).upper() == "PROMOTED"
            and _as_text(pre.get("partition_status")).upper() == "PASS"
            and _as_text(post.get("partition_status")).upper() == "PASS"
        )
        policy_supported_routes = (
            set(supported_routes_by_policy.get(policy_id, set()))
            if supported_routes_by_policy is not None
            else set()
        )
        route_replay_supported = bool(
            policy_promoted
            and (
                route in policy_supported_routes
                if supported_routes_by_policy is not None
                else True
            )
        )
        attempted_count = int(routes["attempted"].eq(route).sum())
        priced_count = int(routes["priced"].eq(route).sum())
        reviewed_count = int(routes["reviewed"].eq(route).sum())
        selector_pass_count = int(
            (routes["reviewed"].eq(route) & final_status.eq("PASS")).sum()
        ) if reviewed_count else 0
        ticket_count = int(routes["tickets"].eq(route).sum())
        target_count = int(
            (routes["tickets"].eq(route) & target_status.str.startswith("target_order")).sum()
        ) if ticket_count else 0
        green_count = int(
            (routes["tickets"].eq(route) & ticket_ready).sum()
        ) if ticket_count else 0
        execution_authorized = bool(
            implementation == "IMPLEMENTED" and route_replay_supported
        )
        if implementation == "NOT_IMPLEMENTED":
            gap = "candidate constructor and leakage-safe replay do not exist"
        elif implementation == "RESEARCH_SHADOW_ONLY":
            gap = "research shadow lacks production-authorized point-in-time evidence"
        elif not policy_promoted:
            gap = "independent selector failed or lacks one frozen replay partition"
        elif not route_replay_supported:
            gap = "route failed or lacks independently passing frozen replay partitions"
        elif priced_count <= 0:
            gap = "no dated structure priced for this run"
        elif selector_pass_count <= 0:
            gap = "no current contract passed its independently promoted selector"
        elif green_count <= 0:
            gap = "current selected contracts did not clear order-entry mechanics"
        else:
            gap = "none"
        rows.append(
            {
                **item,
                "attempted_count": attempted_count,
                "priced_count": priced_count,
                "reviewed_count": reviewed_count,
                "selector_pass_count": selector_pass_count,
                "ticket_count": ticket_count,
                "target_count": target_count,
                "green_count": green_count,
                "selector_policy_id": policy_id,
                "selector_policy_status": (
                    "PROMOTED"
                    if policy_promoted
                    else "REJECTED"
                    if policy_id
                    else "UNASSIGNED"
                ),
                "route_replay_supported": route_replay_supported,
                "pre_split_sample_size": int(_as_float(pre.get("sample_size")) or 0),
                "pre_split_profit_factor": _as_float(pre.get("profit_factor")),
                "pre_split_risk_normalized_profit_factor": _as_float(
                    pre.get("risk_normalized_profit_factor")
                ),
                "post_split_sample_size": int(_as_float(post.get("sample_size")) or 0),
                "post_split_profit_factor": _as_float(post.get("profit_factor")),
                "post_split_risk_normalized_profit_factor": _as_float(
                    post.get("risk_normalized_profit_factor")
                ),
                "execution_authorized": execution_authorized,
                "primary_gap": gap,
            }
        )
    return pd.DataFrame(rows, columns=STRATEGY_BREADTH_AUDIT_COLUMNS)


def summarize_strategy_breadth_audit(audit: pd.DataFrame) -> dict[str, Any]:
    if audit is None or audit.empty:
        return {
            "status": "UNAVAILABLE",
            "strategy_breadth_confidence_rating": 0.0,
            "production_entry_types": [],
            "production_routes": [],
            "route_evidence": [],
            "reason": "strategy breadth audit is unavailable",
        }
    implemented = audit[audit["implementation_status"].astype(str).eq("IMPLEMENTED")].copy()
    priced_routes = sorted(
        implemented.loc[
            pd.to_numeric(implemented["priced_count"], errors="coerce").fillna(0).gt(0),
            "strategy_route",
        ].astype(str).unique()
    )
    authorized = implemented[implemented["execution_authorized"].map(_truthy)].copy()
    production_routes = sorted(authorized["strategy_route"].astype(str).unique())
    production_entry_types = sorted(authorized["entry_type"].astype(str).unique())
    green_routes = sorted(
        implemented.loc[
            pd.to_numeric(implemented["green_count"], errors="coerce").fillna(0).gt(0),
            "strategy_route",
        ].astype(str).unique()
    )
    if {"CREDIT", "DEBIT"}.issubset(set(production_entry_types)):
        status = "DIVERSE"
        rating = 8.0 if len(production_routes) >= 4 else 7.0
        reason = "credit and debit sleeves are independently replay-authorized"
    elif production_entry_types:
        status = "CONCENTRATED"
        rating = 4.0
        reason = (
            "production approval is limited to "
            + ", ".join(value.lower() for value in production_entry_types)
            + " strategies"
        )
    else:
        status = "BLOCK"
        rating = 0.0
        reason = "no strategy sleeve has independently passing replay evidence"
    route_evidence = []
    for _, row in audit.iterrows():
        route_evidence.append(
            {
                "strategy_route": _as_text(row.get("strategy_route")),
                "strategy_label": _as_text(row.get("strategy_label")),
                "entry_type": _as_text(row.get("entry_type")).upper(),
                "implementation_status": _as_text(
                    row.get("implementation_status")
                ).upper(),
                "priced_count": int(_as_float(row.get("priced_count")) or 0),
                "selector_policy_status": _as_text(
                    row.get("selector_policy_status")
                ).upper(),
                "pre_split_sample_size": int(
                    _as_float(row.get("pre_split_sample_size")) or 0
                ),
                "pre_split_profit_factor": _as_float(
                    row.get("pre_split_profit_factor")
                ),
                "pre_split_risk_normalized_profit_factor": _as_float(
                    row.get("pre_split_risk_normalized_profit_factor")
                ),
                "post_split_sample_size": int(
                    _as_float(row.get("post_split_sample_size")) or 0
                ),
                "post_split_profit_factor": _as_float(
                    row.get("post_split_profit_factor")
                ),
                "post_split_risk_normalized_profit_factor": _as_float(
                    row.get("post_split_risk_normalized_profit_factor")
                ),
                "execution_authorized": _truthy(
                    row.get("execution_authorized")
                ),
                "primary_gap": _as_text(row.get("primary_gap")),
            }
        )
    return {
        "status": status,
        "strategy_breadth_confidence_rating": rating,
        "priced_routes": priced_routes,
        "production_routes": production_routes,
        "production_entry_types": production_entry_types,
        "green_routes": green_routes,
        "non_credit_production_route_count": int(
            authorized[~authorized["entry_type"].astype(str).eq("CREDIT")]["strategy_route"].nunique()
        ),
        "route_evidence": route_evidence,
        "reason": reason,
    }


def _selector_policy_replay_support_frame(
    out_root: Path,
    *,
    policy_id: str,
    as_of: Optional[dt.date] = None,
) -> tuple[pd.DataFrame, str]:
    """Return policy-selected rows only after both frozen partitions pass."""

    frame, split_day, source_path, error = _selector_challenger_replay_frame(out_root, as_of=as_of)
    if error or frame.empty or split_day is None:
        return pd.DataFrame(), error or f"selector replay unavailable for {policy_id}"
    policy = _selector_policy_definition(policy_id)
    if not policy:
        return pd.DataFrame(), f"selector policy {policy_id} is not configured"
    selected = _select_challenger_policy_rows(frame, policy)
    partition_rows = [
        _selector_partition_metrics(
            selected[selected["signal_date"].dt.date <= split_day].copy(),
            policy=policy,
            partition="pre_split",
            source_path=source_path,
        ),
        _selector_partition_metrics(
            selected[selected["signal_date"].dt.date > split_day].copy(),
            policy=policy,
            partition="heldout_test",
            source_path=source_path,
        ),
    ]
    failed = [row for row in partition_rows if row["partition_status"] != "PASS"]
    if failed:
        detail = "; ".join(
            f"{row['partition']}:{row['blocking_reasons']}" for row in failed
        )
        return pd.DataFrame(), (
            f"selector policy {policy_id} is not promoted as of {as_of or 'latest'}: {detail}"
        )
    out = selected.copy()
    out["pnl_1x"] = pd.to_numeric(out["realized_pnl"], errors="coerce")
    out["replay_source"] = "options_agent_selector_policy_replay"
    out["selector_policy_id"] = policy_id
    out["selector_partition"] = out["signal_date"].map(
        lambda value: "pre_split" if value.date() <= split_day else "heldout_test"
    )
    out["selector_split_day"] = split_day.isoformat()
    return out[out["pnl_1x"].notna()].reset_index(drop=True), ""


def _active_selector_replay_support_frame(
    out_root: Path,
    *,
    as_of: Optional[dt.date] = None,
) -> tuple[pd.DataFrame, str]:
    """Return replay support for the established credit sleeve."""

    return _selector_policy_replay_support_frame(
        out_root,
        policy_id=PROMOTED_SELECTOR_POLICY_ID,
        as_of=as_of,
    )


def _production_selector_replay_support_frame(
    out_root: Path,
    *,
    as_of: Optional[dt.date] = None,
    selector_audit: Optional[pd.DataFrame] = None,
) -> tuple[pd.DataFrame, str]:
    """Return the union of independently promoted production policy frames."""

    frames: list[pd.DataFrame] = []
    rejected: list[str] = []
    policy_ids = (PROMOTED_SELECTOR_POLICY_ID, *DEBIT_SELECTOR_POLICY_IDS)
    if selector_audit is not None and not selector_audit.empty:
        promoted_ids = {
            _as_text(value)
            for value in selector_audit.loc[
                selector_audit["promotion_status"]
                .astype(str)
                .str.upper()
                .eq("PROMOTED"),
                "policy_id",
            ]
            if _as_text(value)
        }
        policy_ids = tuple(policy_id for policy_id in policy_ids if policy_id in promoted_ids)
    for policy_id in policy_ids:
        frame, error = _selector_policy_replay_support_frame(
            out_root,
            policy_id=policy_id,
            as_of=as_of,
        )
        if frame is not None and not frame.empty:
            frames.append(frame)
        elif error:
            rejected.append(f"{policy_id}: {error}")
    if not frames:
        return pd.DataFrame(), "; ".join(rejected) or "no promoted selector replay support"
    return pd.concat(frames, ignore_index=True, sort=False), "; ".join(rejected)


def _selector_policy_supported_routes(
    frame: pd.DataFrame,
    *,
    policy_id: str,
) -> set[str]:
    """Return routes that independently pass one selector policy's partitions."""

    if frame is None or frame.empty or "strategy_route" not in frame.columns:
        return set()
    policy = _selector_policy_definition(policy_id)
    if not policy:
        return set()
    allowed_routes = {
        _as_text(route)
        for route in policy.get("allowed_strategy_routes", ())
        if _as_text(route)
    }
    supported: set[str] = set()
    for route, group in frame.groupby("strategy_route", dropna=False):
        route_name = _as_text(route)
        if not route_name or (allowed_routes and route_name not in allowed_routes):
            continue
        # ``frame`` is the scored subset of a policy that already passed the
        # full coverage gate in ``_active_selector_replay_support_frame``. A
        # route must use the exact same partition sample, day, PF, and P/L
        # contract as the promoted policy. The old model-only cold-start check
        # required a larger held-out sample and could veto the promoted lane.
        partitions = (
            (
                "pre_split",
                group.loc[
                    group.get("selector_partition", pd.Series("", index=group.index))
                    .astype(str)
                    .eq("pre_split")
                ].copy(),
            ),
            (
                "heldout_test",
                group.loc[
                    group.get("selector_partition", pd.Series("", index=group.index))
                    .astype(str)
                    .eq("heldout_test")
                ].copy(),
            ),
        )
        partition_rows = [
            _selector_partition_metrics(
                partition_frame,
                policy=policy,
                partition=partition,
                source_path="options_agent_selector_policy_replay",
            )
            for partition, partition_frame in partitions
        ]
        if all(_route_keeps_promoted_sleeve_eligibility(row) for row in partition_rows):
            supported.add(route_name)
    return supported


def _route_keeps_promoted_sleeve_eligibility(row: Mapping[str, Any]) -> bool:
    """Keep a sleeve route live if it was not a losing book on its own.

    The mixed credit policy already passed both frozen partitions. Requiring
    each route to independently clear the sleeve's 1.20 PF / n=30/10 bars
    zeroed live send-now: replay is 44% bull-put, and those were the only
    25-30% tight-quote names on the 2026-08-26 live board.
    """

    sample = int(_as_float(row.get("sample_size")) or 0)
    if sample < 1:
        return False
    profit_factor = _as_float(row.get("profit_factor"))
    avg_pnl = _as_float(row.get("avg_pnl"))
    if profit_factor is None or avg_pnl is None:
        return False
    return profit_factor >= MIN_SLEEVE_ROUTE_PROFIT_FACTOR and avg_pnl > 0


def _active_selector_supported_routes(frame: pd.DataFrame) -> set[str]:
    """Return sleeve routes that were not losing books inside the promoted credit policy."""

    return _selector_policy_supported_routes(
        frame,
        policy_id=PROMOTED_SELECTOR_POLICY_ID,
    )


def _wheel_csp_profitability_replay_frame(out_root: Path, *, as_of: Optional[dt.date] = None) -> tuple[pd.DataFrame, str, str]:
    paths = [
        path
        for path in sorted(
            out_root.glob("fresh_wheel*replay*/fresh-wheel-replay-outcomes*.csv"),
            key=lambda item: item.stat().st_mtime,
            reverse=True,
        )
        if _safe_non_v4_path(path)
    ]
    if not paths:
        return (
            pd.DataFrame(),
            str(out_root / "fresh_wheel*replay*/fresh-wheel-replay-outcomes*.csv"),
            "no wheel CSP replay source found",
        )
    frames: list[pd.DataFrame] = []
    source_paths: list[str] = []
    errors: list[str] = []
    for path in paths:
        try:
            raw = pd.read_csv(path, low_memory=False)
        except Exception as exc:
            errors.append(f"{path.name}: {exc}")
            continue
        converted = _convert_wheel_csp_replay_frame(raw, path=path, as_of=as_of)
        if not converted.empty:
            frames.append(converted)
            source_paths.append(str(path))
    if not frames:
        return pd.DataFrame(), str(paths[0]), "; ".join(errors) or "no scored wheel CSP replay rows before as-of date"
    replay = pd.concat(frames, ignore_index=True, sort=False)
    replay = _dedupe_wheel_csp_replay_frame(replay)
    return replay, "; ".join(source_paths), ""


def _dedupe_wheel_csp_replay_frame(frame: pd.DataFrame) -> pd.DataFrame:
    if frame is None or frame.empty:
        return pd.DataFrame()
    key_columns = [
        column
        for column in (
            "signal_date",
            "ticker",
            "action",
            "option_symbol",
            "expiry",
            "strike",
            "entry_date",
        )
        if column in frame.columns
    ]
    if not key_columns:
        return frame.reset_index(drop=True)
    out = frame.copy()
    out["__original_order"] = range(len(out))
    exit_reason = out.get("exit_reason", pd.Series("", index=out.index)).map(_as_text).str.lower()
    out["__terminal_priority"] = exit_reason.map(lambda value: 1 if value in {"", "horizon_mark"} else 0)
    signal_date = pd.to_datetime(out.get("signal_date", pd.Series("", index=out.index)), errors="coerce")
    exit_date = pd.to_datetime(out.get("exit_date", pd.Series("", index=out.index)), errors="coerce")
    out["__horizon_distance"] = ((exit_date - signal_date).dt.days - 14).abs().fillna(10_000)
    out["__exit_date"] = exit_date
    out = out.sort_values(
        ["__terminal_priority", "__horizon_distance", "__exit_date"],
        ascending=[True, True, True],
        kind="mergesort",
    ).drop_duplicates(key_columns, keep="first").sort_values("__original_order", kind="mergesort")
    return out.drop(
        columns=["__original_order", "__terminal_priority", "__horizon_distance", "__exit_date"],
        errors="ignore",
    ).reset_index(drop=True)


def _convert_wheel_csp_replay_frame(raw: pd.DataFrame, *, path: Path, as_of: Optional[dt.date]) -> pd.DataFrame:
    required = {"ticker", "action", "pnl_per_contract", "entry_credit", "dte"}
    if raw is None or raw.empty or not required.issubset(raw.columns):
        return pd.DataFrame()
    action = raw["action"].astype(str).str.upper()
    frame = raw[action.isin({"OPEN_CSP", "SELL_CSP"})].copy()
    if "outcome_status" in frame.columns:
        frame = frame[frame["outcome_status"].astype(str).str.lower().eq("scored")].copy()
    frame = _filter_replay_by_exit_date(frame, "exit_date", as_of)
    if frame.empty:
        return pd.DataFrame()
    frame["pnl_1x"] = pd.to_numeric(frame["pnl_per_contract"], errors="coerce")
    frame["entry_credit"] = pd.to_numeric(frame["entry_credit"], errors="coerce")
    frame["entry_limit"] = frame["entry_credit"]
    frame["dte"] = pd.to_numeric(frame["dte"], errors="coerce")
    frame = frame[frame["pnl_1x"].notna() & frame["entry_credit"].notna() & frame["dte"].notna()].copy()
    if frame.empty:
        return pd.DataFrame()
    frame["strategy"] = "Short Put"
    frame["strategy_route"] = "short_put"
    frame["strategy_family"] = "short_put"
    frame["entry_side"] = "credit"
    frame["entry_type"] = "CREDIT"
    frame["strategy_kind"] = "Credit"
    frame["direction_bucket"] = frame.apply(lambda row: _direction_bucket_from_row(row, row.get("strategy_route")), axis=1)
    frame["regime"] = frame.get("regime", pd.Series("", index=frame.index)).map(_regime_bucket)
    frame["exact_evaluated"] = True
    frame["decision_pass"] = True
    frame["iv_rank_bucket"] = "iv_unknown"
    frame["dte_bucket"] = frame["dte"].map(_dte_bucket)
    frame["economics_bucket"] = frame.apply(lambda item: _economics_bucket(item, item.get("entry_type")), axis=1)
    frame["liquidity_bucket"] = frame.apply(_liquidity_bucket, axis=1)
    frame["replay_source"] = "fresh_wheel_csp_replay"
    frame["replay_source_path"] = str(path)
    return frame


def _pattern_validation_replay_frame(out_root: Path, *, as_of: Optional[dt.date] = None) -> tuple[pd.DataFrame, str, str]:
    paths = _pattern_validation_replay_source_paths(out_root, as_of=as_of)
    if not paths:
        return (
            pd.DataFrame(),
            str(out_root / "options_pattern_pipeline_v1/*/validation_details.csv"),
            "no pattern validation replay source found",
        )
    errors: list[str] = []
    frames: list[pd.DataFrame] = []
    source_paths: list[str] = []
    for path in paths:
        raw, read_error = _read_pattern_validation_scored_rows(path)
        if read_error:
            errors.append(f"{path.name}: {read_error}")
            continue
        converted = _convert_pattern_validation_replay_frame(raw, path=path, as_of=as_of)
        if not converted.empty:
            frames.append(converted)
            source_paths.append(str(path))
    if not frames:
        return pd.DataFrame(), str(paths[0]), "; ".join(errors) or "no scored pattern validation rows before as-of date"
    replay = pd.concat(frames, ignore_index=True, sort=False)
    replay = _dedupe_pattern_validation_replay_frame(replay)
    return replay, "; ".join(source_paths), ""


MAX_PATTERN_VALIDATION_REPLAY_SOURCE_FILES = 4


def _pattern_validation_replay_source_paths(out_root: Path, *, as_of: Optional[dt.date] = None) -> list[Path]:
    paths = [
        path
        for path in sorted(
            out_root.glob("options_pattern_pipeline_v1/*/validation_details.csv"),
            key=lambda item: (_pattern_validation_path_date(item) or dt.date.min, item.stat().st_mtime),
            reverse=True,
        )
        if _safe_non_v4_path(path)
    ]
    if as_of is not None:
        # Undated validation folders can be aliases or post-date scratch runs; exclude them
        # from dated confidence evidence to avoid accidental look-ahead leakage.
        paths = [
            path
            for path in paths
            if (_pattern_validation_path_date(path) is not None and _pattern_validation_path_date(path) <= as_of)
        ]
    if len(paths) <= MAX_PATTERN_VALIDATION_REPLAY_SOURCE_FILES:
        return paths
    selected: list[Path] = []
    seen_family: set[str] = set()
    for path in paths:
        family = _pattern_validation_source_family(path)
        if family in seen_family:
            continue
        selected.append(path)
        seen_family.add(family)
        if len(selected) >= MAX_PATTERN_VALIDATION_REPLAY_SOURCE_FILES:
            break
    return selected


def _pattern_validation_source_family(path: Path) -> str:
    name = path.parent.name
    family = re.sub(r"^20\d{2}-\d{2}-\d{2}_?", "", name).strip()
    return family or "default_dated"


def _read_pattern_validation_scored_rows(path: Path) -> tuple[pd.DataFrame, str]:
    rg = shutil.which("rg")
    if rg:
        try:
            header = path.open("rb").readline()
            if _pattern_validation_header_supports_rg_prefilter(header):
                result = subprocess.run(
                    [
                        rg,
                        "--no-heading",
                        "--no-line-number",
                        r",VALIDATION,.*,False,[^,]*,SCORED,",
                        str(path),
                    ],
                    check=False,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    timeout=120,
                )
                if result.returncode == 0 and result.stdout:
                    raw = pd.read_csv(
                        io.BytesIO(header + result.stdout),
                        low_memory=False,
                        usecols=lambda column: column in PATTERN_VALIDATION_REPLAY_USECOLS,
                    )
                    return raw, ""
                if result.returncode not in {0, 1}:
                    stderr = result.stderr.decode("utf-8", errors="replace").strip()
                    return pd.DataFrame(), f"pattern validation rg prefilter failed: {stderr or result.returncode}"
                if result.returncode == 1:
                    return pd.DataFrame(columns=sorted(PATTERN_VALIDATION_REPLAY_USECOLS)), ""
        except Exception:
            pass
    return _read_pattern_validation_scored_rows_with_pandas(path)


def _pattern_validation_header_supports_rg_prefilter(header: bytes) -> bool:
    text = header.decode("utf-8", errors="replace").strip()
    return text.startswith("split,sample,") and ",blocked,block_reasons,status," in text


def _read_pattern_validation_scored_rows_with_pandas(path: Path) -> tuple[pd.DataFrame, str]:
    try:
        chunks = pd.read_csv(
            path,
            low_memory=False,
            chunksize=250_000,
            usecols=lambda column: column in PATTERN_VALIDATION_REPLAY_USECOLS,
        )
    except Exception as exc:
        return pd.DataFrame(), str(exc)
    filtered: list[pd.DataFrame] = []
    try:
        for raw in chunks:
            if not {"sample", "status", "blocked"}.issubset(raw.columns):
                continue
            mask = (
                raw["sample"].astype(str).str.upper().eq("VALIDATION")
                & raw["status"].astype(str).str.upper().eq("SCORED")
                & ~raw["blocked"].map(_truthy)
            )
            if bool(mask.any()):
                filtered.append(raw[mask].copy())
    except Exception as exc:
        return pd.DataFrame(), str(exc)
    if not filtered:
        return pd.DataFrame(columns=sorted(PATTERN_VALIDATION_REPLAY_USECOLS)), ""
    return pd.concat(filtered, ignore_index=True, sort=False), ""


PATTERN_VALIDATION_REPLAY_USECOLS = {
    "sample",
    "status",
    "blocked",
    "strategy_type",
    "net_r",
    "managed_exit_date",
    "target_date",
    "signal_date",
    "ticker",
    "lead_option_symbol",
    "horizon",
    "pattern_family",
    "market_regime",
    "direction",
    "bias",
    "entry_credit",
    "entry_ask",
    "legs_json",
    "credit_width_ratio",
    "estimated_credit_pct_width",
    "estimated_debit_pct_width",
    "entry_debit_pct_width",
    "reward_risk",
    "max_profit",
    "max_loss",
}


def _dedupe_pattern_validation_replay_frame(frame: pd.DataFrame) -> pd.DataFrame:
    """Keep one fixed-horizon outcome per exact pattern recommendation."""

    if frame is None or frame.empty:
        return pd.DataFrame()
    out = frame.copy()
    horizon_priority = {"5d": 0, "10d": 1, "3d": 2, "20d": 3, "1d": 4}
    out["__horizon_priority"] = out.get("horizon", pd.Series("", index=out.index)).map(
        lambda value: horizon_priority.get(_as_text(value).lower(), len(horizon_priority))
    )
    lead = out.get("lead_option_symbol", pd.Series("", index=out.index)).map(_as_text)
    legs = out.get("legs_json", pd.Series("", index=out.index)).map(_as_text)
    out["__contract_identity"] = lead + "|" + legs
    missing_contract = out["__contract_identity"].eq("|")
    out.loc[missing_contract, "__contract_identity"] = out.index[missing_contract].map(lambda value: f"row:{value}")
    key_columns = [
        column
        for column in ("signal_date", "ticker", "strategy_type", "__contract_identity")
        if column in out.columns
    ]
    out = out.sort_values("__horizon_priority", kind="mergesort")
    if key_columns:
        out = out.drop_duplicates(key_columns, keep="first")
    return out.drop(columns=["__horizon_priority", "__contract_identity"], errors="ignore").reset_index(drop=True)


def _convert_pattern_validation_replay_frame(raw: pd.DataFrame, *, path: Path, as_of: Optional[dt.date]) -> pd.DataFrame:
    required = {"sample", "status", "blocked", "strategy_type", "net_r"}
    if raw is None or raw.empty or not required.issubset(raw.columns):
        return pd.DataFrame()
    frame = raw.copy()
    frame = frame[
        frame["sample"].astype(str).str.upper().eq("VALIDATION")
        & frame["status"].astype(str).str.upper().eq("SCORED")
        & ~frame["blocked"].map(_truthy)
    ].copy()
    if frame.empty:
        return pd.DataFrame()
    exit_source = pd.Series("", index=frame.index, dtype=object)
    if "managed_exit_date" in frame.columns:
        exit_source = frame["managed_exit_date"]
    if "target_date" in frame.columns:
        has_exit = exit_source.notna() & exit_source.astype(str).str.strip().ne("") & exit_source.astype(str).str.lower().ne("nan")
        exit_source = exit_source.where(has_exit, frame["target_date"])
    frame["exit_day"] = exit_source
    frame = _filter_replay_by_exit_date(frame, "exit_day", as_of)
    frame["pnl_1x"] = pd.to_numeric(frame["net_r"], errors="coerce")
    frame = frame[frame["pnl_1x"].notna()].copy()
    if frame.empty:
        return pd.DataFrame()
    dedupe_columns = [
        column
        for column in [
            "signal_date",
            "target_date",
            "managed_exit_date",
            "ticker",
            "strategy_type",
            "lead_option_symbol",
            "horizon",
            "pattern_family",
        ]
        if column in frame.columns
    ]
    if dedupe_columns:
        frame = frame.sort_values(dedupe_columns, kind="mergesort").drop_duplicates(dedupe_columns, keep="last")
    frame["strategy"] = frame["strategy_type"].astype(str)
    frame["strategy_route"] = frame["strategy_type"].map(_strategy_route_from_text)
    frame = frame[frame["strategy_route"].astype(str).str.strip().ne("")].copy()
    if frame.empty:
        return pd.DataFrame()
    frame["strategy_family"] = frame["strategy_route"].map(_strategy_family_from_route)
    frame["entry_type"] = frame["strategy_type"].map(_pattern_validation_entry_type)
    frame["entry_side"] = frame["entry_type"].str.lower()
    frame["strategy_kind"] = frame["entry_type"].str.title()
    frame["direction_bucket"] = _pattern_validation_direction_bucket_series(frame)
    frame["regime"] = frame.get("market_regime", pd.Series("", index=frame.index)).map(_regime_bucket)
    frame["entry_credit"] = pd.to_numeric(frame.get("entry_credit", pd.Series(dtype=float)), errors="coerce")
    frame["entry_ask"] = pd.to_numeric(frame.get("entry_ask", pd.Series(dtype=float)), errors="coerce")
    frame["entry_limit"] = frame["entry_credit"].where(frame["entry_type"].eq("CREDIT"), frame["entry_ask"])
    frame["spread_width"] = frame.get("legs_json", pd.Series("", index=frame.index)).map(
        _pattern_validation_spread_width_from_legs_json
    )
    frame["entry_credit_pct_width"] = frame["entry_credit"] / frame["spread_width"].replace(0, pd.NA)
    frame["dte"] = _pattern_validation_option_dte_series(frame)
    frame["dte_bucket"] = frame["dte"].map(_dte_bucket)
    frame["iv_rank_bucket"] = "iv_unknown"
    frame["economics_bucket"] = frame.apply(lambda item: _economics_bucket(item, item.get("entry_type")), axis=1)
    frame["liquidity_bucket"] = "liquidity_unknown"
    frame["exact_evaluated"] = True
    frame["decision_pass"] = True
    frame["replay_source"] = "options_pattern_validation_replay"
    frame["replay_source_path"] = str(path)
    return frame


def _pattern_validation_entry_type(value: Any) -> str:
    text = _as_text(value).lower()
    if "credit" in text:
        return "CREDIT"
    return "DEBIT"


def _pattern_validation_direction_bucket_series(frame: pd.DataFrame) -> pd.Series:
    route = frame.get("strategy_route", pd.Series("", index=frame.index)).astype(str)
    text = route.copy()
    for column in ("bias", "direction"):
        if column not in frame.columns:
            continue
        values = frame[column].astype(str)
        usable = values.str.strip().ne("") & values.str.lower().ne("nan")
        text = text.where(~usable, values)
    lowered = text.str.lower()
    out = pd.Series("neutral_or_unknown", index=frame.index, dtype=object)
    bullish = (
        lowered.str.contains("bull", na=False)
        | route.str.contains("call_debit", na=False)
        | route.isin({"short_put", "bull_put_credit", "long_call"})
    )
    bearish = (
        lowered.str.contains("bear", na=False)
        | route.str.contains("put_debit", na=False)
        | route.isin({"bear_call_credit", "long_put"})
    )
    out.loc[bullish] = "bullish"
    out.loc[~bullish & bearish] = "bearish"
    return out


def _pattern_validation_option_dte_series(frame: pd.DataFrame) -> pd.Series:
    signal = pd.to_datetime(frame.get("signal_date", pd.Series("", index=frame.index)), errors="coerce")
    text = frame.get("lead_option_symbol", pd.Series("", index=frame.index)).fillna("").astype(str)
    if "legs_json" in frame.columns:
        text = text + " " + frame["legs_json"].fillna("").astype(str)
    expiry_code = text.str.upper().str.extract(r"(?<!\d)(\d{6})[CP]\d{8}(?!\d)", expand=False)
    expiry = pd.to_datetime(expiry_code, format="%y%m%d", errors="coerce")
    dte = (expiry - signal).dt.days
    return dte.where(dte.isna() | dte.ge(0), 0)


def _pattern_validation_option_dte(row: Mapping[str, Any]) -> Optional[int]:
    signal_day = _parse_optional_date_value(_mapping_get(row, "signal_date"))
    expiry = _pattern_validation_option_expiry(row)
    if signal_day is None or expiry is None:
        return None
    return max((expiry - signal_day).days, 0)


def _parse_optional_date_value(value: Any) -> Optional[dt.date]:
    text = _as_text(value)
    if not text or text.lower() == "nan":
        return None
    try:
        return parse_as_of(text)
    except Exception:
        parsed = pd.to_datetime(text, errors="coerce")
        if pd.isna(parsed):
            return None
        return parsed.date()


def _pattern_validation_option_expiry(row: Mapping[str, Any]) -> Optional[dt.date]:
    text = " ".join(
        _as_text(_mapping_get(row, key))
        for key in ("lead_option_symbol", "legs_json")
        if _as_text(_mapping_get(row, key))
    )
    match = re.search(r"(?<!\d)(\d{6})[CP]\d{8}(?!\d)", text.upper())
    if not match:
        return None
    value = match.group(1)
    try:
        return dt.date(2000 + int(value[:2]), int(value[2:4]), int(value[4:6]))
    except ValueError:
        return None


def _pattern_validation_spread_width(row: Mapping[str, Any]) -> Optional[float]:
    return _pattern_validation_spread_width_from_legs_json(_mapping_get(row, "legs_json"))


def _pattern_validation_spread_width_from_legs_json(value: Any) -> Optional[float]:
    legs_text = _as_text(value)
    if not legs_text:
        return None
    try:
        legs = json.loads(legs_text)
    except Exception:
        return None
    if not isinstance(legs, list):
        return None
    strikes = [
        _as_float(_mapping_get(leg, "strike"))
        for leg in legs
        if isinstance(leg, Mapping) and _as_float(_mapping_get(leg, "strike")) is not None
    ]
    if len(strikes) < 2:
        return None
    return abs(max(strikes) - min(strikes))


def _pattern_validation_path_date(path: Path) -> Optional[dt.date]:
    match = re.search(r"(\d{4}-\d{2}-\d{2})", path.parent.name)
    if not match:
        return None
    try:
        return parse_as_of(match.group(1))
    except Exception:
        return None


def _filter_replay_by_exit_date(frame: pd.DataFrame, column: str, as_of: Optional[dt.date]) -> pd.DataFrame:
    if as_of is None or frame is None or frame.empty or column not in frame.columns:
        return frame
    parsed = pd.to_datetime(frame[column], errors="coerce")
    mask = parsed.notna() & (parsed < pd.Timestamp(as_of))
    return frame[mask].copy()


def _backfill_regime_from_history(
    frame: pd.DataFrame,
    out_root: Path,
    *,
    date_columns: Sequence[str],
) -> pd.DataFrame:
    if frame is None or frame.empty:
        return frame
    history = _market_regime_history_by_date(out_root)
    out = frame.copy()
    existing = out.get("regime", pd.Series("", index=out.index)).map(_regime_bucket)
    backfill = pd.Series("", index=out.index, dtype=object)
    parsed_dates_by_column: dict[str, pd.Series] = {}
    requested_days: set[str] = set()
    for column in date_columns:
        if column not in out.columns:
            continue
        parsed = out[column].map(lambda value: _date_key(_parse_optional_date_value(value)))
        parsed_dates_by_column[column] = parsed
        requested_days.update(day for day in parsed.astype(str).tolist() if day)
    source_history = _source_market_regime_history_by_date(out_root, requested_days)
    if not history and not source_history:
        return frame
    for column, parsed in parsed_dates_by_column.items():
        candidate = parsed.map(lambda day: source_history.get(day, "") or history.get(day, ""))
        backfill = backfill.where(backfill.astype(str).str.strip().ne(""), candidate)
    out["regime"] = existing.where(existing.ne("regime_unknown"), backfill.map(_regime_bucket)).map(_regime_bucket)
    return out


def _source_market_regime_history_by_date(out_root: Path, days: Iterable[str]) -> dict[str, str]:
    base_root = Path(out_root).parent
    history: dict[str, str] = {}
    for day in sorted({_as_text(item) for item in days if _as_text(item)}):
        regime = _market_regime_from_uw_source_day(base_root, day)
        if regime != "regime_unknown":
            history[day] = regime
    return history


def _market_regime_from_uw_source_day(base_root: Path, day: str) -> str:
    try:
        as_of = parse_as_of(day)
    except Exception:
        return "regime_unknown"
    date_dir = Path(base_root) / as_of.isoformat()
    if not date_dir.exists():
        return "regime_unknown"
    try:
        from ._vendor import data as uw_data

        screener = uw_data.load_stock_screener(date_dir, point_in_time=True)
    except Exception:
        return "regime_unknown"
    if screener is None or screener.empty or "ticker" not in screener.columns:
        return "regime_unknown"
    try:
        price_regime = build_market_price_regime(screener, as_of)
        market_regime = build_market_regime(screener, market_price_regime=price_regime)
    except Exception:
        return "regime_unknown"
    return _regime_bucket(
        _mapping_get(market_regime, "regime")
        or _mapping_get(price_regime, "regime")
        or _mapping_get(price_regime, "tape_direction")
    )


def _backfill_replay_liquidity_from_uw_sources(
    frame: pd.DataFrame,
    out_root: Path,
    *,
    date_columns: Sequence[str],
) -> pd.DataFrame:
    if frame is None or frame.empty:
        return frame
    out = frame.copy()
    if "source_contract_oi" not in out.columns:
        out["source_contract_oi"] = math.nan
    if "source_contract_volume" not in out.columns:
        out["source_contract_volume"] = math.nan
    base_root = Path(out_root).parent
    requested: dict[int, list[tuple[str, str]]] = {}
    symbols_by_day: dict[str, set[str]] = {}
    for idx, row in out.iterrows():
        if _liquidity_bucket(row) != "liquidity_unknown":
            continue
        symbol = _option_symbol_key(
            _mapping_get(row, "option_symbol")
            or _mapping_get(row, "source_contract")
            or _mapping_get(row, "lead_option_symbol")
        )
        if not symbol:
            continue
        for column in date_columns:
            if column not in out.columns:
                continue
            day = _date_key(_parse_optional_date_value(row.get(column)))
            if not day:
                continue
            requested.setdefault(idx, []).append((day, symbol))
            symbols_by_day.setdefault(day, set()).add(symbol)

    if not requested:
        out["liquidity_bucket"] = out.apply(_liquidity_bucket, axis=1)
        return out

    day_cap = _replay_liquidity_backfill_day_cap()
    if day_cap is not None and len(symbols_by_day) > day_cap:
        selected_days = sorted(symbols_by_day.keys(), reverse=True)[:day_cap]
        symbols_by_day = {day: symbols_by_day[day] for day in selected_days}

    cache = {
        day: _same_day_option_liquidity_lookup(base_root, day, symbols=symbols)
        for day, symbols in symbols_by_day.items()
    }
    for idx, requests in requested.items():
        for day, symbol in requests:
            match = cache.get(day, {}).get(symbol)
            if not match:
                continue
            if _as_float(out.at[idx, "source_contract_oi"]) is None:
                out.at[idx, "source_contract_oi"] = match.get("source_contract_oi", math.nan)
            if _as_float(out.at[idx, "source_contract_volume"]) is None:
                out.at[idx, "source_contract_volume"] = match.get("source_contract_volume", math.nan)
            break
    out["liquidity_bucket"] = out.apply(_liquidity_bucket, axis=1)
    return out


def _same_day_option_liquidity_lookup(
    base_root: Path,
    day: str,
    *,
    symbols: Optional[set[str]] = None,
) -> dict[str, dict[str, Any]]:
    try:
        as_of = parse_as_of(day)
    except Exception:
        return {}
    date_dir = Path(base_root) / as_of.isoformat()
    if not date_dir.exists():
        return {}
    lookup: dict[str, dict[str, Any]] = {}
    wanted = {symbol for symbol in (symbols or set()) if symbol}
    for prefix, oi_columns, volume_columns in [
        ("hot-chains-", ["open_interest"], ["volume"]),
        ("chain-oi-changes-", ["curr_oi", "last_oi"], ["volume", "curr_vol", "prev_vol"]),
    ]:
        source = _read_same_day_option_liquidity_export(
            date_dir,
            prefix=prefix,
            oi_columns=oi_columns,
            volume_columns=volume_columns,
            symbols=wanted,
        )
        if source is None or source.empty or "option_symbol" not in source.columns:
            continue
        scoped = source.copy()
        scoped["__symbol_key"] = scoped["option_symbol"].astype(str).str.replace(r"\s+", "", regex=True).str.upper()
        if wanted:
            scoped = scoped[scoped["__symbol_key"].isin(wanted)].copy()
        if scoped.empty:
            continue
        oi_parts = [
            pd.to_numeric(scoped[column], errors="coerce")
            for column in ["open_interest", "curr_oi", "last_oi"]
            if column in scoped.columns
        ]
        volume_parts = [
            pd.to_numeric(scoped[column], errors="coerce")
            for column in ["volume", "curr_vol", "prev_vol"]
            if column in scoped.columns
        ]
        if not oi_parts and not volume_parts:
            continue
        values = pd.DataFrame({"symbol": scoped["__symbol_key"]})
        values["source_contract_oi"] = pd.concat(oi_parts, axis=1).max(axis=1) if oi_parts else math.nan
        values["source_contract_volume"] = pd.concat(volume_parts, axis=1).max(axis=1) if volume_parts else math.nan
        grouped = values.groupby("symbol", as_index=False).max(numeric_only=True)
        for item in grouped.to_dict("records"):
            symbol = _as_text(item.get("symbol"))
            existing = lookup.get(symbol, {})
            lookup[symbol] = {
                "source_contract_oi": max(
                    _as_float(existing.get("source_contract_oi")) or 0.0,
                    _as_float(item.get("source_contract_oi")) or 0.0,
                ),
                "source_contract_volume": max(
                    _as_float(existing.get("source_contract_volume")) or 0.0,
                    _as_float(item.get("source_contract_volume")) or 0.0,
                ),
            }
    return lookup


def _read_same_day_option_liquidity_export(
    date_dir: Path,
    *,
    prefix: str,
    oi_columns: Sequence[str],
    volume_columns: Sequence[str],
    symbols: set[str],
) -> pd.DataFrame:
    try:
        from ._vendor import data as uw_data

        as_of_day = parse_as_of(date_dir.name[:10])
        path = uw_data.find_export(date_dir, prefix, asof_ceiling=as_of_day)
    except Exception:
        return pd.DataFrame()
    wanted_columns = {"option_symbol", *oi_columns, *volume_columns}
    if not symbols:
        return pd.DataFrame()
    try:
        chunks = pd.read_csv(
            path,
            usecols=lambda column: column in wanted_columns,
            low_memory=False,
            chunksize=250_000,
        )
    except Exception:
        return pd.DataFrame()
    matches: list[pd.DataFrame] = []
    try:
        for chunk in chunks:
            if chunk.empty or "option_symbol" not in chunk.columns:
                continue
            chunk = chunk.copy()
            chunk["__symbol_key"] = chunk["option_symbol"].astype(str).str.replace(r"\s+", "", regex=True).str.upper()
            chunk = chunk[chunk["__symbol_key"].isin(symbols)].copy()
            if not chunk.empty:
                matches.append(chunk)
    except Exception:
        return pd.DataFrame()
    if not matches:
        return pd.DataFrame()
    return pd.concat(matches, ignore_index=True, sort=False)


def _option_symbol_key(value: Any) -> str:
    return re.sub(r"\s+", "", _as_text(value)).upper()


def _actual_calibration_slice(
    actual: pd.DataFrame,
    *,
    ticker: str,
    route: str,
    family: str,
    ticker_scoped: bool,
    key: Optional[Mapping[str, Any]] = None,
    bucket_scoped: bool = False,
    bucket_columns: Optional[Sequence[str]] = None,
) -> pd.DataFrame:
    if actual is None or actual.empty:
        return pd.DataFrame()
    scoped = actual.copy()
    if ticker_scoped:
        ticker_key = canonical_ticker_key(ticker)
        scoped = scoped[scoped["canonical_ticker"].astype(str).eq(ticker_key)].copy()
    route_series = scoped.get("strategy_route", pd.Series("", index=scoped.index)).astype(str)
    exact = scoped[route_series.eq(route)].copy()
    if exact.empty:
        return pd.DataFrame()
    if not bucket_scoped:
        return exact
    return _actual_bucket_slice(exact, key or {}, columns=bucket_columns)


def _actual_bucket_slice(
    actual: pd.DataFrame,
    key: Mapping[str, Any],
    *,
    columns: Optional[Sequence[str]] = None,
) -> pd.DataFrame:
    if actual is None or actual.empty:
        return pd.DataFrame()
    scoped = actual.copy()
    bucket_columns = list(columns or ["entry_type", "direction_bucket", "regime", "dte_bucket", "economics_bucket"])
    for column in bucket_columns:
        value = _as_text(key.get(column))
        if (
            value
            and value
            not in {"UNKNOWN", "neutral_or_unknown", "regime_unknown", "dte_unknown", "economics_unknown"}
            and column in scoped.columns
        ):
            scoped = scoped[scoped[column].astype(str).eq(value)].copy()
            if scoped.empty:
                return scoped
    return scoped


def _actual_bucket_support_scopes() -> set[str]:
    return {
        "actual_ticker_bucket",
        "actual_route_bucket",
        "actual_ticker_economics_bucket",
        "actual_route_economics_bucket",
    }


def _actual_family_calibration_slice(
    actual: pd.DataFrame,
    *,
    family: str,
    key: Optional[Mapping[str, Any]] = None,
) -> pd.DataFrame:
    if actual is None or actual.empty or not family:
        return pd.DataFrame()
    scoped = actual[actual.get("strategy_family", pd.Series("", index=actual.index)).astype(str).eq(family)].copy()
    direction = _as_text((key or {}).get("direction_bucket"))
    if direction and direction != "neutral_or_unknown" and "direction_bucket" in scoped.columns:
        narrowed = scoped[scoped["direction_bucket"].astype(str).eq(direction)].copy()
        if not narrowed.empty:
            return narrowed
        direction_values = {
            _as_text(value)
            for value in scoped["direction_bucket"].dropna().tolist()
            if _as_text(value)
        }
        if direction_values and not direction_values.issubset({"neutral_or_unknown"}):
            return narrowed
    return scoped


def _select_actual_calibration_support(
    ticker_bucket: pd.DataFrame,
    route_bucket: pd.DataFrame,
    ticker_economics_bucket: pd.DataFrame,
    route_economics_bucket: pd.DataFrame,
    ticker_route: pd.DataFrame,
    route: pd.DataFrame,
    family: pd.DataFrame,
) -> tuple[str, dict[str, Any]]:
    bucket_candidates = [
        ("actual_ticker_bucket", ticker_bucket, _ticker_expectancy_status),
        ("actual_route_bucket", route_bucket, _expectancy_status),
        ("actual_ticker_economics_bucket", ticker_economics_bucket, _ticker_expectancy_status),
        ("actual_route_economics_bucket", route_economics_bucket, _expectancy_status),
    ]
    best_bucket_scope = "missing"
    best_bucket_metrics = _calibration_metrics_row(pd.Series(dtype=float), status_func=_expectancy_status)
    for scope, frame, status_func in bucket_candidates:
        if frame is None or frame.empty:
            continue
        metrics = _calibration_metrics_row(frame.get("realized_pnl", pd.Series(dtype=float)), status_func=status_func)
        if _as_text(metrics.get("status")).upper() == "PASS":
            return scope, metrics
        if int(metrics.get("sample_size") or 0) > int(best_bucket_metrics.get("sample_size") or 0):
            best_bucket_scope = scope
            best_bucket_metrics = metrics

    route_candidates = [
        ("actual_ticker_route", ticker_route, _ticker_expectancy_status),
        ("actual_route", route, _expectancy_status),
    ]
    best_scope = "missing"
    best_metrics = _calibration_metrics_row(pd.Series(dtype=float), status_func=_expectancy_status)
    for scope, frame, status_func in route_candidates:
        if frame is None or frame.empty:
            continue
        metrics = _calibration_metrics_row(frame.get("realized_pnl", pd.Series(dtype=float)), status_func=status_func)
        if _as_text(metrics.get("status")).upper() == "PASS":
            if _metrics_are_negative(best_bucket_metrics, min_sample=MIN_EXPECTANCY_SAMPLE_SIZE):
                return best_bucket_scope, best_bucket_metrics
            return scope, metrics
        if int(metrics.get("sample_size") or 0) > int(best_metrics.get("sample_size") or 0):
            best_scope = scope
            best_metrics = metrics

    if best_scope == "missing" and family is not None and not family.empty:
        family_metrics = _calibration_metrics_row(
            family.get("realized_pnl", pd.Series(dtype=float)),
            status_func=_expectancy_status,
        )
        best_scope = "actual_strategy_family"
        best_metrics = family_metrics

    bucket_sample = int(best_bucket_metrics.get("sample_size") or 0)
    broad_sample = int(best_metrics.get("sample_size") or 0)
    if _metrics_are_negative(
        best_bucket_metrics,
        min_sample=MIN_PROBATIONARY_ACTUAL_ROUTE_SAMPLE_SIZE,
    ):
        return best_bucket_scope, best_bucket_metrics
    if broad_sample > bucket_sample:
        return best_scope, best_metrics
    if bucket_sample > 0:
        return best_bucket_scope, best_bucket_metrics
    return best_scope, best_metrics


def _replay_calibration_slice(replay: pd.DataFrame, key: Mapping[str, Any]) -> pd.DataFrame:
    if replay is None or replay.empty:
        return pd.DataFrame()
    scoped = replay.loc[replay["strategy_route"].astype(str).eq(_as_text(key.get("strategy_route")))]
    if scoped.empty:
        return scoped
    for column in ["entry_type", "direction_bucket", "regime", "dte_bucket", "economics_bucket"]:
        value = _as_text(key.get(column))
        if (
            value
            and value
            not in {"UNKNOWN", "neutral_or_unknown", "regime_unknown", "dte_unknown", "economics_unknown"}
            and column in scoped.columns
        ):
            narrowed = scoped.loc[scoped[column].astype(str).eq(value)]
            if not narrowed.empty:
                scoped = narrowed
            else:
                return narrowed
    liquidity = _as_text(key.get("liquidity_bucket"))
    if liquidity and liquidity != "liquidity_unknown" and "liquidity_bucket" in scoped.columns:
        exact_liquidity = scoped.loc[scoped["liquidity_bucket"].astype(str).eq(liquidity)]
        if not exact_liquidity.empty:
            scoped = exact_liquidity
        else:
            unknown_liquidity = scoped.loc[scoped["liquidity_bucket"].astype(str).eq("liquidity_unknown")]
            scoped = unknown_liquidity if not unknown_liquidity.empty else exact_liquidity
    return scoped


def _route_replay_calibration_slice(replay: pd.DataFrame, route: str) -> pd.DataFrame:
    if replay is None or replay.empty or "strategy_route" not in replay.columns:
        return pd.DataFrame()
    route_text = _as_text(route)
    if not route_text:
        return pd.DataFrame()
    return replay.loc[replay["strategy_route"].astype(str).eq(route_text)].copy()


def _diagnostic_replay_calibration_slice(replay: pd.DataFrame, key: Mapping[str, Any]) -> tuple[pd.DataFrame, str]:
    """Return nearest replay evidence for gap diagnosis only; never green-gate from this."""

    if replay is None or replay.empty:
        return pd.DataFrame(), "replay_source_empty"
    route = _as_text(key.get("strategy_route"))
    if "strategy_route" not in replay.columns:
        return pd.DataFrame(), "strategy_route:source_missing"
    scoped = replay.loc[replay["strategy_route"].astype(str).eq(route)]
    if scoped.empty:
        return scoped, "strategy_route"

    relaxed: list[str] = []
    unknowns = {"UNKNOWN", "neutral_or_unknown", "regime_unknown", "dte_unknown", "economics_unknown", "liquidity_unknown"}
    for column in ["entry_type", "direction_bucket", "regime", "dte_bucket", "economics_bucket", "liquidity_bucket"]:
        value = _as_text(key.get(column))
        if not value or value in unknowns:
            continue
        if column not in scoped.columns:
            relaxed.append(f"{column}:source_missing")
            continue
        narrowed = scoped.loc[scoped[column].astype(str).eq(value)]
        if narrowed.empty:
            relaxed.append(column)
            continue
        scoped = narrowed
    return scoped, ",".join(relaxed)


def _calibration_metrics_row(pnl_values: pd.Series, *, status_func: Any) -> dict[str, Any]:
    metrics = _expectancy_metrics_row(
        "profitability_calibration",
        Path(""),
        "profitability_calibration",
        pd.to_numeric(pnl_values, errors="coerce"),
        tickers=set(),
        current_tickers=set(),
        open_or_unrealized_count=0,
        note="profitability calibration metrics",
        status_override_func=status_func,
    )
    return metrics


def _hierarchical_route_calibration_ready(
    *,
    actual_scope: str,
    actual_metrics: Mapping[str, Any],
    replay_metrics: Mapping[str, Any],
    route_replay_metrics: Mapping[str, Any],
    model_replay_metrics: Optional[Mapping[str, Any]] = None,
) -> bool:
    """Allow one-lot green calibration from deep route evidence when exact buckets are sparse."""

    if actual_scope not in {
        "actual_ticker_route",
        "actual_route",
        *_actual_bucket_support_scopes(),
    }:
        return False
    if _as_text(actual_metrics.get("status")).upper() != "PASS":
        return False
    if int(actual_metrics.get("sample_size") or 0) < MIN_HIERARCHICAL_ROUTE_SAMPLE_SIZE:
        return False
    exact_replay_sample = int(replay_metrics.get("sample_size") or 0)
    exact_replay_status = _as_text(replay_metrics.get("status")).upper()
    if exact_replay_sample >= MIN_EXPECTANCY_SAMPLE_SIZE and exact_replay_status != "PASS":
        return False
    if _metrics_are_negative(replay_metrics, min_sample=MIN_EXPECTANCY_SAMPLE_SIZE):
        return False
    if not _positive_expectancy_shape(
        int(actual_metrics.get("sample_size") or 0),
        _as_float(actual_metrics.get("win_rate")) or 0.0,
        _as_float(actual_metrics.get("avg_pnl")) or 0.0,
        _as_float(actual_metrics.get("profit_factor")) or 0.0,
        min_sample=MIN_HIERARCHICAL_ROUTE_SAMPLE_SIZE,
        min_win_rate=MIN_EXPECTANCY_WIN_RATE,
        min_skew_win_rate=MIN_EXPECTANCY_SKEW_WIN_RATE,
        min_profit_factor=MIN_EXPECTANCY_PROFIT_FACTOR,
    ):
        return False
    route_sample = int(route_replay_metrics.get("sample_size") or 0)
    deep_route_replay = bool(
        _as_text(route_replay_metrics.get("status")).upper() == "PASS"
        and route_sample >= MIN_HIERARCHICAL_ROUTE_SAMPLE_SIZE
    )
    model_metrics = model_replay_metrics or {}
    model_sample = int(model_metrics.get("sample_size") or 0)
    promoted_selector_route_support = _positive_expectancy_shape(
        model_sample,
        _as_float(model_metrics.get("win_rate")) or 0.0,
        _as_float(model_metrics.get("avg_pnl")) or 0.0,
        _as_float(model_metrics.get("profit_factor")) or 0.0,
        min_sample=MIN_HIERARCHICAL_ROUTE_REPLAY_SAMPLE_SIZE,
        min_win_rate=MIN_EXPECTANCY_WIN_RATE,
        min_skew_win_rate=MIN_EXPECTANCY_SKEW_WIN_RATE,
        min_profit_factor=MIN_EXPECTANCY_PROFIT_FACTOR,
    )
    if not (deep_route_replay or promoted_selector_route_support):
        return False
    supporting_metrics = route_replay_metrics if deep_route_replay else model_metrics
    avg_pnl = _as_float(supporting_metrics.get("avg_pnl"))
    profit_factor = _as_float(supporting_metrics.get("profit_factor"))
    win_rate = _as_float(supporting_metrics.get("win_rate"))
    return bool(
        avg_pnl is not None
        and avg_pnl > 0
        and profit_factor is not None
        and (math.isinf(profit_factor) or profit_factor >= MIN_EXPECTANCY_PROFIT_FACTOR)
        and win_rate is not None
        and win_rate >= MIN_EXPECTANCY_SKEW_WIN_RATE
    )


def _probationary_model_route_calibration_ready(
    *,
    actual_scope: str,
    actual_metrics: Mapping[str, Any],
    replay_metrics: Mapping[str, Any],
    route_replay_metrics: Mapping[str, Any],
    model_replay_metrics: Optional[Mapping[str, Any]] = None,
) -> bool:
    """Allow one-lot probation only when three evidence layers agree.

    The active-selector frame is available only after the policy passes its
    frozen pre-split and held-out gates. Route and actual samples remain
    under-sized here, so this bridge never authorizes scaling beyond one lot.
    """

    if actual_scope not in {
        "actual_ticker_route",
        "actual_route",
        *_actual_bucket_support_scopes(),
    }:
        return False
    actual_sample = int(actual_metrics.get("sample_size") or 0)
    actual_avg = _as_float(actual_metrics.get("avg_pnl"))
    actual_pf = _as_float(actual_metrics.get("profit_factor"))
    actual_win_rate = _as_float(actual_metrics.get("win_rate"))
    if not (
        _as_text(actual_metrics.get("status")).upper() in {"PASS", "WARN"}
        and actual_sample >= MIN_PROBATIONARY_ACTUAL_ROUTE_SAMPLE_SIZE
        and actual_avg is not None
        and actual_avg > 0
        and actual_pf is not None
        and (math.isinf(actual_pf) or actual_pf >= MIN_EXPECTANCY_PROFIT_FACTOR)
        and actual_win_rate is not None
        and actual_win_rate >= MIN_PROBATIONARY_ACTUAL_WIN_RATE
    ):
        return False

    exact_sample = int(replay_metrics.get("sample_size") or 0)
    if exact_sample >= MIN_PROBATIONARY_ACTUAL_ROUTE_SAMPLE_SIZE and _metrics_are_negative(
        replay_metrics,
        min_sample=MIN_PROBATIONARY_ACTUAL_ROUTE_SAMPLE_SIZE,
    ):
        return False

    route_sample = int(route_replay_metrics.get("sample_size") or 0)
    route_avg = _as_float(route_replay_metrics.get("avg_pnl"))
    route_pf = _as_float(route_replay_metrics.get("profit_factor"))
    if not (
        _as_text(route_replay_metrics.get("status")).upper() in {"PASS", "WARN"}
        and route_sample >= MIN_PROBATIONARY_ROUTE_REPLAY_SAMPLE_SIZE
        and route_avg is not None
        and route_avg > 0
        and route_pf is not None
        and (math.isinf(route_pf) or route_pf >= MIN_EXPECTANCY_PROFIT_FACTOR)
    ):
        return False

    model_metrics = model_replay_metrics or {}
    model_sample = int(model_metrics.get("sample_size") or 0)
    model_avg = _as_float(model_metrics.get("avg_pnl"))
    model_pf = _as_float(model_metrics.get("profit_factor"))
    model_win_rate = _as_float(model_metrics.get("win_rate"))
    return bool(
        _as_text(model_metrics.get("status")).upper() in {"PASS", "WARN"}
        and model_sample >= MIN_PROBATIONARY_ROUTE_REPLAY_SAMPLE_SIZE
        and model_avg is not None
        and model_avg > 0
        and model_pf is not None
        and (
            math.isinf(model_pf)
            or model_pf >= MIN_PROBATIONARY_MODEL_ROUTE_PROFIT_FACTOR
        )
        and model_win_rate is not None
        and model_win_rate >= MIN_EXPECTANCY_SKEW_WIN_RATE
    )


def _model_only_selector_route_calibration_ready(
    *,
    actual_scope: str,
    actual_metrics: Mapping[str, Any],
    replay_metrics: Mapping[str, Any],
    route_replay_metrics: Mapping[str, Any],
    model_replay_metrics: Mapping[str, Any],
    model_pre_split_metrics: Mapping[str, Any],
    model_heldout_metrics: Mapping[str, Any],
    selector_exact_replay_metrics: Optional[Mapping[str, Any]] = None,
) -> bool:
    """Allow a one-lot cold start from strong selector-matched partitions.

    Broad route actuals and off-policy replay cohorts do not by themselves
    prove the selector's conditional population. A generic route/economics
    cohort is diagnostic when the active policy has fully passing partitions;
    mature ticker-scoped losses and selector-exact losses remain disqualifying.
    The stricter partition sizes keep this path from promoting a small
    retrospective cohort.
    """

    # A generic route/economics cohort is not selector-matched evidence. The
    # active policy's partitions may bridge it, but mature ticker-scoped losses
    # remain disqualifying. Direct forward evidence is checked again at the
    # order surface, where it is available on the live candidate row.
    if actual_scope.startswith("actual_ticker") and _metrics_are_negative(
        actual_metrics,
        min_sample=MIN_PROBATIONARY_ACTUAL_ROUTE_SAMPLE_SIZE,
    ):
        return False
    if _metrics_are_negative(
        selector_exact_replay_metrics or {},
        min_sample=MIN_PROBATIONARY_ACTUAL_ROUTE_SAMPLE_SIZE,
    ):
        return False

    def positive(metrics: Mapping[str, Any], *, minimum_sample: int, minimum_pf: float) -> bool:
        sample = int(_as_float(metrics.get("sample_size")) or 0)
        avg_pnl = _as_float(metrics.get("avg_pnl"))
        profit_factor = _as_float(metrics.get("profit_factor"))
        return bool(
            sample >= minimum_sample
            and avg_pnl is not None
            and avg_pnl > 0
            and profit_factor is not None
            and (math.isinf(profit_factor) or profit_factor >= minimum_pf)
        )

    return bool(
        positive(
            model_replay_metrics,
            minimum_sample=MIN_SELECTOR_PROMOTION_SAMPLE_SIZE,
            minimum_pf=MIN_PROBATIONARY_MODEL_ROUTE_PROFIT_FACTOR,
        )
        and positive(
            model_pre_split_metrics,
            minimum_sample=MIN_SELECTOR_PROMOTION_SAMPLE_SIZE,
            minimum_pf=MIN_EXPECTANCY_PROFIT_FACTOR,
        )
        and positive(
            model_heldout_metrics,
            minimum_sample=MIN_SELECTOR_HELDOUT_SAMPLE_SIZE,
            minimum_pf=MIN_SLEEVE_ROUTE_PROFIT_FACTOR,
        )
    )


def _current_calibration_verdict(
    *,
    ticker: str,
    key: Mapping[str, Any],
    actual_scope: str,
    actual_metrics: Mapping[str, Any],
    replay_metrics: Mapping[str, Any],
    route_replay_metrics: Mapping[str, Any],
    replay_path: Path,
    replay_error: str,
    model_replay_metrics: Optional[Mapping[str, Any]] = None,
    model_pre_split_metrics: Optional[Mapping[str, Any]] = None,
    model_heldout_metrics: Optional[Mapping[str, Any]] = None,
    selector_exact_replay_metrics: Optional[Mapping[str, Any]] = None,
) -> tuple[str, str, str]:
    actual_status = _as_text(actual_metrics.get("status")).upper() or "BLOCK"
    replay_status = _as_text(replay_metrics.get("status")).upper() or "BLOCK"
    route_replay_status = _as_text(route_replay_metrics.get("status")).upper() or "BLOCK"
    actual_sample = int(actual_metrics.get("sample_size") or 0)
    replay_sample = int(replay_metrics.get("sample_size") or 0)
    route_replay_sample = int(route_replay_metrics.get("sample_size") or 0)
    key_text = _calibration_key_text(key)
    bucket_precise_actual = actual_scope in _actual_bucket_support_scopes()
    if actual_status == "PASS" and replay_status == "PASS" and bucket_precise_actual:
        return (
            "PASS",
            "eligible_for_green_if_all_execution_gates_pass",
            f"{ticker} {key_text} has PASS actual support via {actual_scope} and PASS replay bucket support.",
        )
    if _hierarchical_route_calibration_ready(
        actual_scope=actual_scope,
        actual_metrics=actual_metrics,
        replay_metrics=replay_metrics,
        route_replay_metrics=route_replay_metrics,
        model_replay_metrics=model_replay_metrics,
    ):
        return (
            "PASS",
            "eligible_for_one_lot_green_with_hierarchical_route_support",
            (
                f"{ticker} {key_text} has PASS route-level actual support via {actual_scope} "
                f"(sample={actual_sample}, profit_factor={actual_metrics.get('profit_factor', '')}); "
                f"diagnostic route replay sample={route_replay_sample}, "
                f"profit_factor={route_replay_metrics.get('profit_factor', '')}; promoted selector route support "
                f"(sample={int((model_replay_metrics or {}).get('sample_size') or 0)}, "
                f"profit_factor={(model_replay_metrics or {}).get('profit_factor', '')}). Exact buckets remain sparse, "
                "so green eligibility is capped at one contract until bucket-precise evidence matures."
            ),
        )
    if _probationary_model_route_calibration_ready(
        actual_scope=actual_scope,
        actual_metrics=actual_metrics,
        replay_metrics=replay_metrics,
        route_replay_metrics=route_replay_metrics,
        model_replay_metrics=model_replay_metrics,
    ):
        return (
            "PASS",
            "eligible_for_one_lot_probation_with_model_route_support",
            (
                f"{ticker} {key_text} has positive sparse actual route support via {actual_scope} "
                f"(sample={actual_sample}, profit_factor={actual_metrics.get('profit_factor', '')}), "
                f"positive route replay (sample={route_replay_sample}, "
                f"profit_factor={route_replay_metrics.get('profit_factor', '')}), and positive promoted-selector "
                f"route support (sample={int((model_replay_metrics or {}).get('sample_size') or 0)}, "
                f"profit_factor={(model_replay_metrics or {}).get('profit_factor', '')}). This is a one-contract "
                "probationary bridge, not exact-bucket proof; any mature exact-bucket negative evidence blocks it."
            ),
        )
    if _model_only_selector_route_calibration_ready(
        actual_scope=actual_scope,
        actual_metrics=actual_metrics,
        replay_metrics=replay_metrics,
        route_replay_metrics=route_replay_metrics,
        model_replay_metrics=model_replay_metrics or {},
        model_pre_split_metrics=model_pre_split_metrics or {},
        model_heldout_metrics=model_heldout_metrics or {},
        selector_exact_replay_metrics=selector_exact_replay_metrics or {},
    ):
        pre_sample = int((model_pre_split_metrics or {}).get("sample_size") or 0)
        heldout_sample = int((model_heldout_metrics or {}).get("sample_size") or 0)
        return (
            "PASS",
            "eligible_for_one_lot_cold_start_with_partitioned_selector_route_support",
            (
                f"{ticker} {key_text} has promoted-selector route support across both development partitions "
                f"(pre_split sample={pre_sample}, profit_factor={(model_pre_split_metrics or {}).get('profit_factor', '')}; "
                f"post_split_development sample={heldout_sample}, "
                f"profit_factor={(model_heldout_metrics or {}).get('profit_factor', '')}). "
                f"Broad managed-trade support via {actual_scope} and the off-policy replay bucket are not "
                "selector-matched, so they remain diagnostic. "
                "This is a one-contract evidence pilot; scaling is disabled until selector-attributed actual "
                "outcomes mature."
            ),
        )
    if (
        actual_status == "PASS"
        and actual_scope in {"actual_ticker_route", "actual_route"}
        and route_replay_status == "PASS"
        and (replay_status == "PASS" or _sparse_replay_bucket_positive(replay_metrics))
    ):
        return (
            "WARN",
            "keep_yellow_with_hierarchical_route_support",
            (
                f"{ticker} {key_text} has PASS route-level actual support via {actual_scope} "
                f"(sample={actual_sample}) plus PASS route-level replay support "
                f"(sample={route_replay_sample}); exact replay bucket is {replay_status} "
                f"sample={replay_sample}. Route-level evidence may support a yellow hypothesis but cannot promote "
                "an exact contract to green without precise actual and replay bucket evidence."
            ),
        )
    blockers: list[str] = []
    if actual_status != "PASS":
        blockers.append(f"actual_support={actual_status or 'BLOCK'} sample={actual_sample} scope={actual_scope}")
    elif not bucket_precise_actual:
        blockers.append(f"actual_bucket_precision=route_or_family_only scope={actual_scope} sample={actual_sample}")
    if replay_status != "PASS":
        replay_note = replay_error or f"replay_bucket={replay_status or 'BLOCK'} sample={replay_sample}"
        blockers.append(replay_note)
    status = "WARN" if actual_sample > 0 or replay_sample > 0 else "BLOCK"
    return (
        status,
        "keep_yellow_until_actual_and_replay_bucket_calibration_pass",
        f"{ticker} {key_text} is not green-calibrated: " + "; ".join(blockers) + f". Replay source: {replay_path}.",
    )


def _sparse_replay_bucket_positive(metrics: Mapping[str, Any]) -> bool:
    status = _as_text(metrics.get("status")).upper()
    if status not in {"PASS", "WARN"}:
        return False
    sample = int(_as_float(metrics.get("sample_size")) or 0)
    if sample <= 0:
        return False
    avg_pnl = _as_float(metrics.get("avg_pnl"))
    profit_factor = _as_float(metrics.get("profit_factor"))
    return bool(
        avg_pnl is not None
        and avg_pnl > 0
        and (
            profit_factor is None
            or math.isinf(profit_factor)
            or (math.isfinite(profit_factor) and profit_factor >= MIN_EXPECTANCY_PROFIT_FACTOR)
        )
    )


def _current_calibration_ticket_counts(
    current: pd.DataFrame,
) -> dict[tuple[str, str, str, str, str, str, str, str], int]:
    if current is None or current.empty:
        return {}
    counts: dict[tuple[str, str, str, str, str, str, str, str], int] = {}
    for _, row in current.iterrows():
        lookup_key = _calibration_lookup_key(
            _as_text(row.get("ticker")).upper(),
            _calibration_key_from_row(row),
        )
        counts[lookup_key] = counts.get(lookup_key, 0) + 1
    return counts


def _current_calibration_ticket_count(current: pd.DataFrame, ticker: str, key: Mapping[str, Any]) -> int:
    """Return one exact calibration-bucket count for compatibility callers."""

    return _current_calibration_ticket_counts(current).get(
        _calibration_lookup_key(ticker, key),
        0,
    )


def _selector_policy_flow_alignment(row: Mapping[str, Any], route: str) -> Optional[float]:
    bias = _as_float(row.get("combined_flow_bias"))
    if bias is None:
        bias = _as_float(row.get("flow_bias"))
    if bias is None:
        return None
    if route in {"bull_put_credit", "bull_call_debit", "long_call"}:
        return bias
    if route in {"bear_call_credit", "bear_put_debit", "long_put"}:
        return -bias
    return None


def _selector_policy_expected_move_ratio(row: Mapping[str, Any], entry_type: str) -> Optional[float]:
    live_ratio = _as_float(row.get("live_breakeven_expected_move_ratio"))
    if entry_type == "DEBIT":
        if live_ratio is not None and live_ratio > 0:
            return 1.0 / live_ratio
        expected_move = _as_float(row.get("live_expected_move_pct"))
        spot = _as_float(row.get("spot_live"))
        breakeven = _as_float(row.get("breakeven"))
        route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
        if expected_move is None or expected_move <= 0 or spot is None or spot <= 0 or breakeven is None:
            return None
        distance = (
            (breakeven - spot) / spot
            if route in {"bull_call_debit", "long_call"}
            else (spot - breakeven) / spot
        )
        return expected_move / max(distance, 0.001)
    if live_ratio is not None and live_ratio > 0:
        return live_ratio
    distance = _as_float(row.get("live_distance_pct"))
    expected_move = _as_float(row.get("live_expected_move_pct"))
    if distance is not None and expected_move is not None and expected_move > 0:
        return distance / expected_move
    dated_ratio = _as_float(row.get("dated_expected_move_ratio"))
    return dated_ratio if dated_ratio is not None and dated_ratio > 0 else None


def _selector_one_lot_target_profit(row: Mapping[str, Any]) -> float:
    """Return planned one-contract profit using only entry-time ticket economics."""

    entry_type = _as_text(row.get("entry_type")).upper() or _entry_type_from_route(
        _as_text(row.get("strategy_route"))
    )
    if entry_type == "DEBIT":
        entry = next(
            (
                value
                for value in (
                    _as_float(row.get("entry_limit")),
                    _as_float(row.get("entry_debit")),
                    _as_float(row.get("entry_price")),
                )
                if value is not None and value > 0
            ),
            None,
        )
        target_exit = _as_float(row.get("target_exit")) or _as_float(
            row.get("target_exit_value")
        )
        if entry is not None and target_exit is not None and target_exit > entry:
            return round((target_exit - entry) * 100.0, 2)
        if entry is not None:
            return round(entry * 0.80 * 100.0, 2)
    elif entry_type == "CREDIT":
        entry = next(
            (
                value
                for value in (
                    _as_float(row.get("entry_limit")),
                    _as_float(row.get("entry_credit")),
                    _as_float(row.get("entry_price")),
                )
                if value is not None and value > 0
            ),
            None,
        )
        target_exit = _as_float(row.get("target_exit")) or _as_float(
            row.get("target_exit_value")
        )
        if entry is not None and target_exit is not None and 0 <= target_exit < entry:
            return round((entry - target_exit) * 100.0, 2)
        if entry is not None:
            return round(entry * 0.65 * 100.0, 2)
    max_profit = _as_float(row.get("max_profit"))
    return round(max(max_profit or 0.0, 1.0), 2)


def _selector_economic_score(quality_score: Any, target_profit: Any) -> float:
    quality = max(_as_float(quality_score) or 0.0, 0.0)
    planned_profit = max(_as_float(target_profit) or 0.0, 1.0)
    return round(quality * math.sqrt(planned_profit), 6)


def _selector_policy_ranked_frame(
    frame: pd.DataFrame,
    policy: Mapping[str, Any],
) -> pd.DataFrame:
    """Order selector rows identically in live selection and replay."""

    ranked = frame.copy()
    for column in (
        "__selector_economic_score",
        "__selector_score",
        "decision_score",
        "flow_total_premium",
        "source_contract_oi",
        "entry_quote_width_pct",
    ):
        ranked[column] = pd.to_numeric(
            ranked.get(column, pd.Series(index=ranked.index, dtype=float)),
            errors="coerce",
        )
    ranked["ticker"] = ranked.get(
        "ticker",
        pd.Series("", index=ranked.index, dtype=object),
    ).map(lambda value: _as_text(value).upper())
    rank_column = (
        "__selector_economic_score"
        if _as_text(policy.get("rank_mode")) == "selector_economic_score"
        else "__selector_score"
    )
    return ranked.sort_values(
        [
            rank_column,
            "__selector_score",
            "decision_score",
            "flow_total_premium",
            "source_contract_oi",
            "entry_quote_width_pct",
            "ticker",
        ],
        ascending=[False, False, False, False, False, True, True],
        kind="mergesort",
    )


def _selector_structural_score(score: float, row: Mapping[str, Any]) -> float:
    synthesis_score = _as_float(row.get("synthesis_score"))
    if synthesis_score is None:
        synthesis_score = _as_float(row.get("decision_score"))
    synthesis_component = min(0.5, max(0.0, (synthesis_score or 0.0) / 400.0))
    return round(float(score) - synthesis_component, 6)


def _selector_mature_negative_evidence_reasons(row: Mapping[str, Any]) -> list[str]:
    """Keep known losing evidence from consuming a scarce daily selector slot."""

    if _v0_late_evidence_gates_diagnostic_only() or _current_edge_override_reason(row):
        return []
    reasons: list[str] = []
    if _negative_strategy_expectancy_blocks_green(row):
        reasons.append("mature_negative_strategy_expectancy")
    if _profitability_calibration_actual_support_negative(row):
        reasons.append("mature_negative_calibration_actuals")
    if _negative_route_family_evidence_blocks_action(row):
        reasons.append("mature_negative_route_family_evidence")
    return _dedupe_notes(reasons)


def _selector_underlying_asset_class(row: Mapping[str, Any]) -> str:
    issue_type = _as_text(row.get("issue_type")).upper()
    ticker = _as_text(row.get("ticker")).upper()
    if issue_type == "ETF" or ticker in ACTIONABLE_ETF_ALLOWLIST:
        return "etf"
    if issue_type == "COMMON STOCK":
        return "common_stock"
    return "unknown"


def _selector_etf_has_direct_ticker_support(row: Mapping[str, Any]) -> bool:
    """Require ETF-specific realized evidence instead of borrowing stock replay PF."""

    if _selector_underlying_asset_class(row) != "etf":
        return True
    status = _as_text(row.get("actual_forward_expectancy_status")).upper()
    sample = int(_as_float(row.get("actual_forward_expectancy_sample_size")) or 0)
    avg_pnl = _as_float(row.get("actual_forward_expectancy_avg_pnl"))
    profit_factor = _as_float(row.get("actual_forward_expectancy_profit_factor"))
    return bool(
        status == "PASS"
        and sample >= MIN_TICKER_EXPECTANCY_SAMPLE_SIZE
        and avg_pnl is not None
        and avg_pnl > 0
        and profit_factor is not None
        and profit_factor >= MIN_TICKER_EXPECTANCY_PROFIT_FACTOR
    )


def _selector_rank_only_observations(row: Mapping[str, Any]) -> list[str]:
    """Return non-gating selector observations reserved for future policies."""

    _ = row
    return []


def _live_pair_liquidity(row: Mapping[str, Any], short_key: str, long_key: str) -> Optional[float]:
    short_value = _as_float(row.get(short_key))
    long_value = _as_float(row.get(long_key))
    if short_value is None or long_value is None:
        return None
    return min(short_value, long_value)


def _selector_contract_volume(row: Mapping[str, Any]) -> Optional[float]:
    """Return pair volume for selector eligibility.

    Overnight Schwab volume is 0 until prints hit. During RTH the live pair is
    only the session-so-far print. Either case is not a missing book: use the
    larger of live and dated pair volume.
    """

    live_pair = _live_pair_liquidity(row, "live_short_volume", "live_long_volume")
    dated_source_volume = _as_float(row.get("dated_source_contract_volume"))
    source_volume = _as_float(row.get("source_contract_volume"))
    positives = [
        value
        for value in (live_pair, dated_source_volume, source_volume)
        if value is not None and value > 0
    ]
    if positives:
        return max(positives)
    return live_pair


def _selector_contract_open_interest(row: Mapping[str, Any]) -> Optional[float]:
    """Return pair open interest for selector eligibility."""

    live_pair = _live_pair_liquidity(row, "live_short_oi", "live_long_oi")
    if _as_text(row.get("live_validation_status")).upper() == "PASS" and live_pair is not None:
        return live_pair
    dated_source_oi = _as_float(row.get("dated_source_contract_oi"))
    if dated_source_oi is not None:
        return dated_source_oi
    source_oi = _as_float(row.get("source_contract_oi"))
    if source_oi is not None:
        return source_oi
    return live_pair


def _selector_quote_width_blocker(
    quote_width: Optional[float],
    *,
    source_quote_width_rank_only: bool,
    prefix: str,
) -> Optional[str]:
    """Distinguish missing quotes from measured wide quotes.

    A missing quote is a wait/reprice state. Treating NaN as qw>0.25 labeled
    unvalidated send-now names as wide and blocked them as if the spread had
    failed the live 25% cap.
    """

    if source_quote_width_rank_only:
        return None
    if quote_width is None:
        return f"{prefix}_quote_width_unavailable"
    if quote_width > MAX_SELECTOR_ENTRY_QUOTE_WIDTH_PCT:
        return f"{prefix}_quote_width_above_{MAX_SELECTOR_ENTRY_QUOTE_WIDTH_PCT:.2f}"
    return None


def _selector_policy_row_assessment(
    row: Mapping[str, Any],
    *,
    require_live_probability: bool = True,
    policy: Optional[Mapping[str, Any]] = None,
) -> tuple[bool, float, list[str], str]:
    route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
    entry_type = _as_text(row.get("entry_type")).upper() or _entry_type_from_route(route)
    reasons: list[str] = []
    replay_mode = _truthy(row.get("selector_replay_mode"))
    if route not in {
        "bull_put_credit",
        "bear_call_credit",
        "bull_call_debit",
        "bear_put_debit",
        "long_call",
        "long_put",
    }:
        reasons.append("unsupported_selector_route")
    if _as_text(row.get("underlying_quality_tier")) not in {"", "core", "liquid"}:
        reasons.append("underlying_not_core")
    reasons.extend(_selector_blocking_hard_rejects(row))
    if _earnings_within_selector_risk_horizon(row):
        reasons.append("earnings_within_selector_risk_horizon")
    if policy:
        allowed_entry_types = {
            _as_text(value).upper()
            for value in policy.get("allowed_entry_types", ())
            if _as_text(value)
        }
        if allowed_entry_types and entry_type not in allowed_entry_types:
            reasons.append("active_policy_entry_type_not_allowed")
        allowed_routes = {
            _as_text(value)
            for value in policy.get("allowed_strategy_routes", ())
            if _as_text(value)
        }
        if allowed_routes and route not in allowed_routes:
            reasons.append("active_policy_route_not_allowed")
        required_tiers = {
            _as_text(value).lower()
            for value in policy.get("required_underlying_tiers", ())
            if _as_text(value)
        }
        underlying_tier = _as_text(row.get("underlying_quality_tier")).lower()
        if required_tiers and underlying_tier not in required_tiers:
            reasons.append("active_policy_underlying_tier_not_allowed")
        minimum_volume = _as_float(policy.get("min_contract_volume"))
        contract_volume = _selector_contract_volume(row)
        if minimum_volume is not None and (
            contract_volume is None or contract_volume < minimum_volume
        ):
            reasons.append(f"active_policy_contract_volume_below_{int(minimum_volume)}")
        minimum_oi = _as_float(policy.get("min_contract_oi"))
        contract_oi = _selector_contract_open_interest(row)
        if minimum_oi is not None and (contract_oi is None or contract_oi < minimum_oi):
            reasons.append(f"active_policy_contract_oi_below_{int(minimum_oi)}")
    asset_class = _selector_underlying_asset_class(row)
    replay_asset_class = _as_text(policy.get("replay_asset_class")).lower() if policy else ""
    if replay_asset_class == "common_stock" and asset_class == "etf":
        # The promoted policy was replayed on common stocks only. Do not let an
        # ETF borrow its evidence or consume a live selector slot.
        reasons.append("active_policy_asset_class_not_allowed:etf")
    elif (
        not replay_mode
        and asset_class == "etf"
        and not _selector_etf_has_direct_ticker_support(row)
    ):
        reasons.append("etf_direct_ticker_expectancy_not_proven")
    dte = int(_as_float(row.get("dte")) or 0)
    quote_width = _as_float(row.get("live_quote_width_pct"))
    if quote_width is None:
        quote_width = _as_float(row.get("dated_combo_quote_width_pct"))
    if quote_width is None:
        quote_width = _as_float(row.get("entry_quote_width_pct"))
    source_quote_width_rank_only = bool(
        policy
        and _as_text(policy.get("source_quote_width_policy")).lower()
        == "rank_only_replay"
        and (replay_mode or quote_width is None)
    )
    flow_alignment = _selector_policy_flow_alignment(row, route)
    expected_move_ratio = _selector_policy_expected_move_ratio(row, entry_type)
    regime = _regime_bucket(row.get("regime") or row.get("market_regime"))
    macro_event_count = _macro_events_within_planned_holding_horizon(row)
    macro_calendar_status = _as_text(row.get("macro_calendar_status")).lower()
    if dte <= SHORT_DTE_CONTRACT_RISK_DAYS and macro_event_count > 0:
        reasons.append("short_dte_macro_event_within_holding_horizon")
    if (
        dte <= SHORT_DTE_CONTRACT_RISK_DAYS
        and not replay_mode
        and macro_calendar_status != "verified"
    ):
        reasons.append("short_dte_macro_calendar_unverified")
    score = 0.0
    if entry_type == "CREDIT":
        credit_width = _as_float(row.get("credit_width_ratio"))
        minimum_credit_dte = int(_as_float(policy.get("min_credit_dte")) or 7) if policy else 7
        maximum_credit_dte = int(_as_float(policy.get("max_credit_dte")) or 45) if policy else 45
        if not minimum_credit_dte <= dte <= maximum_credit_dte:
            reasons.append(f"credit_dte_outside_{minimum_credit_dte}_{maximum_credit_dte}")
        if (
            route == "bear_call_credit"
            and regime == "risk_off"
            and dte < MIN_RISK_OFF_BEAR_CALL_DTE
        ):
            reasons.append(
                f"risk_off_bear_call_dte_below_{MIN_RISK_OFF_BEAR_CALL_DTE}"
            )
        if credit_width is None or not MIN_SEND_NOW_CREDIT_WIDTH_RATIO <= credit_width <= 0.30:
            reasons.append("credit_width_outside_0.25_0.30")
        credit_dollars = _as_float(row.get("entry_credit"))
        if credit_dollars is None:
            credit_dollars = _as_float(row.get("credit"))
        if credit_dollars is not None and credit_dollars < MIN_SEND_NOW_CREDIT:
            reasons.append(f"credit_below_send_now_{MIN_SEND_NOW_CREDIT:.2f}")
        credit_flow_gate = not policy or bool(policy.get("credit_flow_gate", True))
        if credit_flow_gate and (flow_alignment is None or flow_alignment < 0.10):
            reasons.append("credit_flow_alignment_below_0.10")
        credit_em_gate = bool(policy.get("credit_expected_move_gate")) if policy else False
        if credit_em_gate and (
            expected_move_ratio is None
            or expected_move_ratio < MIN_SELECTOR_CREDIT_DISTANCE_EXPECTED_MOVE
        ):
            reasons.append(
                "credit_distance_expected_move_below_"
                f"{MIN_SELECTOR_CREDIT_DISTANCE_EXPECTED_MOVE:.2f}"
            )
        quote_width_blocker = _selector_quote_width_blocker(
            quote_width,
            source_quote_width_rank_only=source_quote_width_rank_only,
            prefix="credit",
        )
        if quote_width_blocker:
            reasons.append(quote_width_blocker)
        if flow_alignment is not None:
            score += min(2.0, max(0.0, flow_alignment) * 6.0)
        if credit_width is not None:
            score += min(1.0, max(0.0, credit_width - MIN_SEND_NOW_CREDIT_WIDTH_RATIO) * 8.0)
        sleeve = "CREDIT"
    elif entry_type == "DEBIT" and route in LONG_OPTION_ROUTES:
        if not MIN_LIVE_DTE <= dte <= MAX_LIVE_DTE:
            reasons.append(
                f"long_option_dte_outside_{MIN_LIVE_DTE}_{MAX_LIVE_DTE}"
            )
        if route == "long_call" and regime != "risk_on":
            reasons.append(f"long_option_regime_not_aligned:{regime}")
        if route == "long_put" and regime not in {"risk_off", "mixed"}:
            reasons.append(f"long_option_regime_not_aligned:{regime}")
        if flow_alignment is None or flow_alignment < 0.20:
            reasons.append("long_option_flow_alignment_below_0.200")
        if expected_move_ratio is None or expected_move_ratio < 1.00:
            reasons.append("long_option_expected_move_ratio_below_1.00")
        quote_width_blocker = _selector_quote_width_blocker(
            quote_width,
            source_quote_width_rank_only=source_quote_width_rank_only,
            prefix="long_option",
        )
        if quote_width_blocker:
            reasons.append(quote_width_blocker)
        probability = abs(_as_float(row.get("live_probability_proxy")) or 0.0)
        if require_live_probability and probability < MIN_DEBIT_LONG_DELTA_FOR_GREEN:
            reasons.append(
                f"debit_probability_proxy_below_{int(MIN_DEBIT_LONG_DELTA_FOR_GREEN * 100)}pct"
            )
        if expected_move_ratio is not None:
            score += min(2.0, max(0.0, expected_move_ratio))
        if flow_alignment is not None:
            score += min(2.0, max(0.0, flow_alignment) * 6.0)
        source_liquidity = min(
            _selector_contract_volume(row) or 0.0,
            _selector_contract_open_interest(row) or 0.0,
        )
        score += min(1.0, max(0.0, source_liquidity) / 1_000.0)
        sleeve = "DEBIT"
    elif entry_type == "DEBIT":
        debit_width = _as_float(row.get("debit_width_ratio"))
        default_minimum_dte = 7 if route == "bull_call_debit" else 14
        default_maximum_dte = 45
        minimum_dte = (
            int(_as_float(policy.get("min_debit_dte")) or default_minimum_dte)
            if policy
            else default_minimum_dte
        )
        maximum_dte = (
            int(_as_float(policy.get("max_debit_dte")) or default_maximum_dte)
            if policy
            else default_maximum_dte
        )
        default_max_debit_width = (
            0.45 if route == "bull_call_debit" else MAX_BEAR_PUT_DEBIT_WIDTH_RATIO
        )
        max_debit_width = (
            _as_float(policy.get("max_debit_width_ratio"))
            if policy and "max_debit_width_ratio" in policy
            else default_max_debit_width
        )
        reward_risk = None
        max_profit = _as_float(row.get("max_profit"))
        max_loss = _as_float(row.get("max_loss"))
        if max_profit is not None and max_loss is not None and max_loss > 0:
            reward_risk = max_profit / max_loss
        if policy and "allowed_regimes" in policy:
            allowed_regimes = {
                _regime_bucket(value)
                for value in policy.get("allowed_regimes", ())
                if _as_text(value)
            }
        elif route == "bull_call_debit":
            allowed_regimes = {"risk_on"}
        else:
            allowed_regimes = {"risk_off", "mixed"}
        if allowed_regimes and regime not in allowed_regimes:
            reasons.append(f"debit_regime_not_aligned:{regime}")
        default_minimum_expected_move_ratio = (
            1.00 if route == "bull_call_debit" else 1.25
        )
        minimum_expected_move_ratio = (
            _as_float(policy.get("min_expected_move_ratio"))
            if policy and "min_expected_move_ratio" in policy
            else default_minimum_expected_move_ratio
        )
        default_maximum_iv_rank = 55.0 if route == "bull_call_debit" else 45.0
        maximum_iv_rank = (
            _as_float(policy.get("max_iv_rank"))
            if policy and "max_iv_rank" in policy
            else default_maximum_iv_rank
        )
        iv_rank = _as_float(row.get("iv_rank"))
        if maximum_iv_rank is not None and iv_rank is not None and iv_rank > maximum_iv_rank:
            reasons.append(f"debit_iv_rank_above_{int(maximum_iv_rank)}")
        if not minimum_dte <= dte <= maximum_dte:
            reasons.append("debit_dte_outside_route_policy")
        if (
            debit_width is None
            or debit_width <= 0
            or (max_debit_width is not None and debit_width > max_debit_width)
        ):
            width_label = f"{max_debit_width:.2f}" if max_debit_width is not None else "valid"
            reasons.append(f"debit_width_above_{width_label}")
        minimum_reward_risk = (
            _as_float(policy.get("min_reward_risk"))
            if policy and "min_reward_risk" in policy
            else 1.25
        )
        if minimum_reward_risk is not None and (
            reward_risk is None or reward_risk < minimum_reward_risk
        ):
            reasons.append(f"debit_reward_risk_below_{minimum_reward_risk:.2f}")
        default_minimum_flow_alignment = (
            0.20 if route == "bull_call_debit" else MIN_BEAR_PUT_DEBIT_FLOW_ALIGNMENT
        )
        minimum_flow_alignment = (
            _as_float(policy.get("min_flow_alignment"))
            if policy and "min_flow_alignment" in policy
            else default_minimum_flow_alignment
        )
        if minimum_flow_alignment is not None and (
            flow_alignment is None or flow_alignment < minimum_flow_alignment
        ):
            reasons.append(f"debit_flow_alignment_below_{minimum_flow_alignment:.3f}")
        if minimum_expected_move_ratio is not None and (
            expected_move_ratio is None
            or expected_move_ratio < minimum_expected_move_ratio
        ):
            reasons.append(f"debit_expected_move_ratio_below_{minimum_expected_move_ratio:.2f}")
        minimum_momentum_alignment = (
            _as_float(policy.get("min_momentum_alignment"))
            if policy
            else None
        )
        maximum_momentum_alignment = (
            _as_float(policy.get("max_momentum_alignment"))
            if policy
            else None
        )
        price_move_pct = _as_float(row.get("price_move_pct"))
        momentum_alignment = (
            price_move_pct
            if route == "bull_call_debit"
            else -price_move_pct
            if route == "bear_put_debit" and price_move_pct is not None
            else None
        )
        if minimum_momentum_alignment is not None and (
            momentum_alignment is None
            or momentum_alignment < minimum_momentum_alignment
        ):
            reasons.append(
                f"debit_momentum_alignment_below_{minimum_momentum_alignment:.3f}"
            )
        if maximum_momentum_alignment is not None and (
            momentum_alignment is None
            or momentum_alignment > maximum_momentum_alignment
        ):
            reasons.append(
                f"debit_momentum_alignment_above_{maximum_momentum_alignment:.3f}"
            )
        quote_width_blocker = _selector_quote_width_blocker(
            quote_width,
            source_quote_width_rank_only=source_quote_width_rank_only,
            prefix="debit",
        )
        if quote_width_blocker:
            reasons.append(quote_width_blocker)
        probability = abs(_as_float(row.get("live_probability_proxy")) or 0.0)
        if require_live_probability and probability < MIN_DEBIT_LONG_DELTA_FOR_GREEN:
            reasons.append(
                f"debit_probability_proxy_below_{int(MIN_DEBIT_LONG_DELTA_FOR_GREEN * 100)}pct"
            )
        if expected_move_ratio is not None:
            score += min(2.0, max(0.0, expected_move_ratio))
        if flow_alignment is not None:
            score += min(2.0, max(0.0, flow_alignment) * 6.0)
        if debit_width is not None:
            score += min(1.0, max(0.0, 0.60 - debit_width) * 4.0)
        if reward_risk is not None:
            score += min(1.0, max(0.0, reward_risk - 0.60))
        sleeve = "DEBIT"
    else:
        reasons.append("selector_entry_type_unknown")
        sleeve = entry_type or "UNKNOWN"
    if quote_width is not None and not source_quote_width_rank_only:
        score -= max(0.0, quote_width - 0.25)
    score += min(0.5, max(0.0, (_as_float(row.get("synthesis_score")) or 0.0) / 400.0))
    return not reasons, round(score, 6), reasons, sleeve


def annotate_selector_policy(
    final: pd.DataFrame,
    *,
    enabled: bool = True,
    disabled_reason: str = "",
    supported_routes: Optional[set[str]] = None,
) -> pd.DataFrame:
    """Apply the promoted decision-pass selector to the current recommendation surface."""

    columns = [
        "selector_policy_id",
        "selector_policy_status",
        "selector_policy_score",
        "selector_policy_economic_score",
        "selector_policy_sleeve",
        "selector_policy_reason",
    ]
    if final is None:
        return pd.DataFrame(columns=columns)
    out = final.copy()
    for column in columns:
        out[column] = ""
    if out.empty:
        return out
    if not enabled:
        # A missing or invalid replay must never silently erase selector state.
        # It blocks green orders, but a separately evidenced row can still be a
        # visible yellow recheck instead of disappearing from the report.
        out["selector_policy_id"] = PROMOTED_SELECTOR_POLICY_ID
        out["selector_policy_status"] = "UNAVAILABLE"
        out["selector_policy_reason"] = (
            disabled_reason or "promoted selector replay is unavailable"
        )
        return out
    active_policy = next(
        (
            policy
            for policy in SELECTOR_CHALLENGER_POLICIES
            if _as_text(policy.get("policy_id")) == PROMOTED_SELECTOR_POLICY_ID
        ),
        {},
    )
    daily_cap = _promoted_selector_daily_cap()
    daily_sleeve_cap = max(int(_as_float(active_policy.get("daily_sleeve_cap")) or 1), 1)
    second_slot_max_structural_score_gap = _as_float(
        active_policy.get("second_slot_max_structural_score_gap")
    )
    if second_slot_max_structural_score_gap is None:
        second_slot_max_structural_score_gap = MAX_SELECTOR_SECOND_SLOT_STRUCTURAL_SCORE_GAP
    max_etf_per_day = max(
        int(_as_float(active_policy.get("max_etf_per_day")) or MAX_SELECTOR_ETF_SELECTIONS_PER_DAY),
        0,
    )
    eligible_by_sleeve: dict[str, list[tuple[float, float, Any]]] = {
        "CREDIT": [],
        "DEBIT": [],
    }
    for idx, row in out.iterrows():
        eligible, score, reasons, sleeve = _selector_policy_row_assessment(
            row,
            policy=active_policy,
        )
        route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
        if eligible and supported_routes is not None and route not in supported_routes:
            eligible = False
            reasons.append("active_selector_route_not_proven_in_frozen_replay")
        target_profit = _selector_one_lot_target_profit(row)
        economic_score = _selector_economic_score(score, target_profit)
        out.at[idx, "selector_policy_id"] = PROMOTED_SELECTOR_POLICY_ID
        out.at[idx, "selector_policy_score"] = score
        out.at[idx, "selector_policy_economic_score"] = economic_score
        out.at[idx, "selector_policy_sleeve"] = sleeve
        if eligible and sleeve in eligible_by_sleeve:
            eligible_by_sleeve[sleeve].append((economic_score, score, idx))
            out.at[idx, "selector_policy_status"] = "ELIGIBLE"
            out.at[idx, "selector_policy_reason"] = "entry-time selector rules passed"
        else:
            out.at[idx, "selector_policy_status"] = "BLOCK"
            out.at[idx, "selector_policy_reason"] = "; ".join(_dedupe_notes(reasons))
    selected_tickers: set[str] = set()
    selected_indices: set[Any] = set()
    selected_structural_scores: list[float] = []
    selected_reasons: dict[Any, str] = {}
    selected_etf_count = 0

    def selection_reason(idx: Any, base_reason: str) -> str:
        observations = _selector_rank_only_observations(out.loc[idx])
        if not observations:
            return base_reason
        return f"{base_reason}; rank-only observations: {', '.join(observations)}"

    def ranked_selector_items(
        items: Sequence[tuple[float, float, Any]],
    ) -> list[tuple[float, float, Any]]:
        if not items:
            return []
        rank_rows: list[dict[str, Any]] = []
        for economic_score, selector_score, idx in items:
            rank_row = out.loc[idx].to_dict()
            rank_row.update(
                {
                    "__selector_economic_score": economic_score,
                    "__selector_score": selector_score,
                    "__selector_row_index": idx,
                }
            )
            rank_rows.append(rank_row)
        ranked = _selector_policy_ranked_frame(pd.DataFrame(rank_rows), active_policy)
        return [
            (
                float(row["__selector_economic_score"]),
                float(row["__selector_score"]),
                row["__selector_row_index"],
            )
            for _, row in ranked.iterrows()
        ]

    for sleeve in ("CREDIT", "DEBIT"):
        ranked = ranked_selector_items(eligible_by_sleeve[sleeve])
        selected_in_sleeve = 0
        for _, score, idx in ranked:
            if len(selected_tickers) >= daily_cap:
                break
            ticker = _as_text(out.at[idx, "ticker"]).upper()
            ticker_key = canonical_ticker_key(ticker)
            if ticker_key and ticker_key in selected_tickers:
                continue
            asset_class = _selector_underlying_asset_class(out.loc[idx])
            if asset_class == "etf" and selected_etf_count >= max_etf_per_day:
                continue
            selected_indices.add(idx)
            selected_structural_scores.append(_selector_structural_score(float(score), out.loc[idx]))
            slot_label = (
                f"top {sleeve.lower()} sleeve"
                if selected_in_sleeve == 0
                else f"{sleeve.lower()} sleeve slot {selected_in_sleeve + 1}"
            )
            selected_reasons[idx] = selection_reason(
                idx,
                f"selected as {slot_label}",
            )
            if ticker_key:
                selected_tickers.add(ticker_key)
            if asset_class == "etf":
                selected_etf_count += 1
            selected_in_sleeve += 1
            if selected_in_sleeve >= daily_sleeve_cap:
                break
        if len(selected_tickers) >= daily_cap:
            break
    if len(selected_tickers) < daily_cap and selected_structural_scores:
        ranked_remaining = ranked_selector_items(
            [item for sleeve_rows in eligible_by_sleeve.values() for item in sleeve_rows]
        )
        daily_best_structural_score = max(selected_structural_scores)
        for _, score, idx in ranked_remaining:
            ticker = _as_text(out.at[idx, "ticker"]).upper()
            ticker_key = canonical_ticker_key(ticker)
            if idx in selected_indices or (ticker_key and ticker_key in selected_tickers):
                continue
            asset_class = _selector_underlying_asset_class(out.loc[idx])
            if asset_class == "etf" and selected_etf_count >= max_etf_per_day:
                continue
            structural_score = _selector_structural_score(float(score), out.loc[idx])
            if (
                daily_best_structural_score - structural_score
                > second_slot_max_structural_score_gap
            ):
                continue
            selected_indices.add(idx)
            selected_structural_scores.append(structural_score)
            selected_reasons[idx] = selection_reason(
                idx,
                "selected as additional distinct ticker within "
                f"{second_slot_max_structural_score_gap:.2f} structural selector-score gap",
            )
            if ticker_key:
                selected_tickers.add(ticker_key)
            if asset_class == "etf":
                selected_etf_count += 1
            if len(selected_tickers) >= daily_cap:
                break
    for sleeve, sleeve_rows in eligible_by_sleeve.items():
        for _, _, idx in sleeve_rows:
            if idx in selected_indices:
                out.at[idx, "selector_policy_status"] = "PASS"
                out.at[idx, "selector_policy_reason"] = selected_reasons[idx]
            else:
                out.at[idx, "selector_policy_status"] = "NOT_SELECTED_DAILY_CAP"
                out.at[idx, "selector_policy_reason"] = f"eligible but below daily {sleeve.lower()} quality cap"
    return out


def _selector_policy_audit_note(audit: pd.DataFrame, policy_id: str) -> tuple[bool, str]:
    """Summarize the two frozen replay partitions for one strategy sleeve."""

    if audit is None or audit.empty:
        return False, f"independent selector replay unavailable for {policy_id}"
    rows = audit[audit["policy_id"].astype(str).eq(policy_id)].copy()
    if rows.empty:
        return False, f"independent selector replay missing policy {policy_id}"
    parts: list[str] = []
    promoted = True
    for partition, label in (("pre_split", "pre"), ("heldout_test", "post")):
        match = rows[rows["partition"].astype(str).eq(partition)].head(1)
        if match.empty:
            promoted = False
            parts.append(f"{label} missing")
            continue
        row = match.iloc[0]
        status = _as_text(row.get("partition_status")).upper()
        promoted = promoted and status == "PASS"
        sample = int(_as_float(row.get("sample_size")) or 0)
        profit_factor = _as_float(row.get("profit_factor"))
        pf_text = f"{profit_factor:.3f}" if profit_factor is not None else "n/a"
        risk_profit_factor = _as_float(row.get("risk_normalized_profit_factor"))
        risk_pf_text = (
            f", ROR PF {risk_profit_factor:.3f}"
            if risk_profit_factor is not None
            else ""
        )
        parts.append(
            f"{label} PF {pf_text} (n={sample}, {status or 'UNKNOWN'}){risk_pf_text}"
        )
    return promoted, "; ".join(parts)


def annotate_independent_debit_selector(
    final: pd.DataFrame,
    selector_audit: pd.DataFrame,
    *,
    supported_routes: Optional[set[str]] = None,
    supported_routes_by_policy: Optional[Mapping[str, set[str]]] = None,
) -> pd.DataFrame:
    """Apply route-specific debit policies without borrowing other evidence."""

    if final is None or final.empty:
        return final.copy() if final is not None else pd.DataFrame()
    out = final.copy()
    entry_types = out.apply(
        lambda row: _as_text(row.get("entry_type")).upper()
        or _entry_type_from_route(
            _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
        ),
        axis=1,
    )
    debit_indices = list(out.index[entry_types.eq("DEBIT")])
    if not debit_indices:
        return out

    policy_state: dict[str, tuple[Mapping[str, Any], bool, str]] = {}
    for policy_id in DEBIT_SELECTOR_POLICY_IDS:
        policy = _selector_policy_definition(policy_id)
        promoted, audit_note = _selector_policy_audit_note(
            selector_audit,
            policy_id,
        )
        policy_state[policy_id] = (policy, promoted, audit_note)

    eligible_by_policy: dict[str, list[dict[str, Any]]] = {}
    for idx in debit_indices:
        row = out.loc[idx]
        route = _as_text(row.get("strategy_route")) or _strategy_route_from_row(row)
        policy_id = SELECTOR_POLICY_ID_BY_ROUTE.get(route, "")
        policy, promoted, audit_note = policy_state.get(
            policy_id,
            ({}, False, f"no independent debit policy is configured for {route or 'unknown route'}"),
        )
        out.at[idx, "selector_policy_id"] = policy_id
        out.at[idx, "selector_policy_sleeve"] = route or "DEBIT"
        if not policy:
            out.at[idx, "selector_policy_status"] = "BLOCK"
            out.at[idx, "selector_policy_reason"] = audit_note
            continue
        passed, score, reasons, sleeve = _selector_policy_row_assessment(
            row,
            policy=policy,
        )
        if passed and promoted:
            if supported_routes_by_policy is not None:
                route_support = set(supported_routes_by_policy.get(policy_id, set()))
            else:
                route_support = supported_routes
            if route_support is not None and route not in route_support:
                passed = False
                reasons.append("independent_debit_route_not_proven_in_frozen_replay")
        target_profit = _selector_one_lot_target_profit(row)
        economic_score = _selector_economic_score(score, target_profit)
        out.at[idx, "selector_policy_score"] = score
        out.at[idx, "selector_policy_economic_score"] = economic_score
        out.at[idx, "selector_policy_sleeve"] = route or sleeve or "DEBIT"
        if not passed:
            out.at[idx, "selector_policy_status"] = "BLOCK"
            out.at[idx, "selector_policy_reason"] = "; ".join(_dedupe_notes(reasons))
            continue
        if not promoted:
            out.at[idx, "selector_policy_status"] = "RESEARCH_ONLY"
            out.at[idx, "selector_policy_reason"] = (
                f"independent {route or 'debit'} policy not promoted: {audit_note}"
            )
            continue
        rank_row = row.to_dict()
        rank_row.update(
            {
                "__selector_row_index": idx,
                "__selector_score": score,
                "__selector_economic_score": economic_score,
            }
        )
        eligible_by_policy.setdefault(policy_id, []).append(rank_row)
        out.at[idx, "selector_policy_status"] = "ELIGIBLE"
        out.at[idx, "selector_policy_reason"] = (
            f"independent {route or 'debit'} selector rules passed"
        )

    if not eligible_by_policy:
        return out

    selected_tickers = {
        canonical_ticker_key(value)
        for value in out.loc[
            out.get("selector_policy_status", pd.Series("", index=out.index))
            .astype(str)
            .str.upper()
            .eq("PASS"),
            "ticker",
        ]
        if canonical_ticker_key(value)
    }
    for policy_id in DEBIT_SELECTOR_POLICY_IDS:
        eligible = eligible_by_policy.get(policy_id, [])
        if not eligible:
            continue
        policy = policy_state[policy_id][0]
        ranked = _selector_policy_ranked_frame(pd.DataFrame(eligible), policy)
        daily_cap = max(int(_as_float(policy.get("daily_cap")) or 1), 1)
        selected_indices: list[Any] = []
        for _, ranked_row in ranked.iterrows():
            idx = ranked_row["__selector_row_index"]
            ticker = canonical_ticker_key(out.at[idx, "ticker"])
            if ticker and ticker in selected_tickers:
                continue
            selected_indices.append(idx)
            if ticker:
                selected_tickers.add(ticker)
            if len(selected_indices) >= daily_cap:
                break
        selected_set = set(selected_indices)
        for eligible_row in eligible:
            idx = eligible_row["__selector_row_index"]
            route = _as_text(out.at[idx, "strategy_route"])
            if idx in selected_set:
                out.at[idx, "selector_policy_status"] = "PASS"
                out.at[idx, "selector_policy_reason"] = (
                    f"selected by independently promoted {route} policy"
                )
            else:
                out.at[idx, "selector_policy_status"] = "NOT_SELECTED_DAILY_CAP"
                out.at[idx, "selector_policy_reason"] = (
                    f"eligible but below independent {route} daily cap"
                )
    return out


def _selector_constrained_recommendation_status(
    recommendation_status: Any,
    selector_policy_status: Any,
) -> str:
    """Selector BLOCK is not send-now. It is still a review row.

    Forcing AVOID here deleted the ticket surface: live-validated names with
    contracts and limits never reached GROKO_TRADES.md.
    """

    status = _as_text(recommendation_status).upper()
    selector_status = _as_text(selector_policy_status).upper()
    if not selector_status or selector_status == "PASS":
        return status
    if status in {
        RecommendationStatus.ENTER.value,
        RecommendationStatus.ENTER_WITH_PORTFOLIO_RISK.value,
        RecommendationStatus.WAIT_FOR_PRICE.value,
    }:
        return RecommendationStatus.REVIEW.value
    return status


