def _negative_evidence_row(rows: pd.DataFrame, *, min_sample: int) -> Optional[dict[str, Any]]:
    if rows is None or rows.empty:
        return None
    for _, row in rows.iterrows():
        sample = int(_as_float(row.get("sample_size")) or 0)
