def _local_news_path(date_dir: Path, ticker: str, day: dt.date) -> Optional[Path]:
    if not ticker:
        return None
    path = date_dir / "browser_text" / f"browser-text-capture-news-{ticker}-{day.isoformat()}.txt"
    return path if path.exists() else None


def _local_news_paths(date_dir: Path, ticker: str, day: dt.date) -> list[Path]:
    exact = _local_news_path(date_dir, ticker, day)
    paths: list[Path] = [exact] if exact is not None else []
    news_dir = date_dir / "browser_text"
    if not news_dir.exists():
        return paths
    prefix = "browser-text-capture-news-"
    suffix = f"-{day.isoformat()}.txt"
    for path in sorted(news_dir.glob(f"{prefix}*{suffix}")):
        if path in paths:
            continue
        middle = path.name[len(prefix) : -len(suffix)]
        tickers = {part.strip().upper() for part in middle.split("-") if part.strip()}
        if ticker.upper() in tickers:
            paths.append(path)
    return paths


def _news_evidence_row(ticker: str, path: Path) -> dict[str, Any]:
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
        lines = [line.strip() for line in text.splitlines() if line.strip()]
    except Exception:
        lines = []
        text = ""
    headline = _sanitize_local_news_headline(lines[0]) if lines else ""
    if len(headline) > 180:
        headline = headline[:177] + "..."
    sentiment, status, red_terms, support_terms = _classify_news_text(text)
    if not lines:
        status = "local_news_unreadable" if text else "local_news_empty"
        sentiment = "neutral"
    note_bits = []
    if red_terms:
        note_bits.append("red flags: " + ", ".join(red_terms))
    if support_terms:
        note_bits.append("supportive: " + ", ".join(support_terms))
    if headline:
        note_bits.append("headline: " + headline)
    if not note_bits:
        note_bits.append("local news file present")
    return {
        "ticker": ticker,
        "evidence_type": "local_news",
        "evidence_status": status,
        "source": str(path),
        "headline": headline,
        "sentiment": sentiment,
        "red_flag_terms": ";".join(red_terms),
        "support_terms": ";".join(support_terms),
        "objective_blocker": False,
        "days_to_earnings": "",
        "note": "; ".join(note_bits),
    }


def _sanitize_local_news_headline(headline: str) -> str:
    text = str(headline or "").strip()
    text = re.sub(r"\s+for\s+Codex\s+Daily\s+V\d+\s+rerun", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*Codex\s+Daily\s+V\d+\s+rerun\s*", "local review", text, flags=re.IGNORECASE)
    return re.sub(r"\s+", " ", text).strip()


def _classify_news_text(text: str) -> tuple[str, str, list[str], list[str]]:
    lowered = text.lower()
    red_phrases = (
        "investigation",
        "sec probe",
        "probe",
        "lawsuit",
        "fraud",
        "bankruptcy",
        "bankrupt",
        "downgrade",
        "guidance cut",
        "cuts guidance",
        "misses estimates",
        "recall",
        "delist",
        "short seller",
        "accounting issue",
        "halts",
        "warning",
    )
    support_phrases = (
        "upgrade",
        "beats estimates",
        "raises guidance",
        "guidance raise",
        "buyback",
        "contract",
        "approval",
        "partnership",
        "record revenue",
        "surge",
        "launch",
    )
    red_terms = [phrase for phrase in red_phrases if phrase in lowered]
    support_terms = [phrase for phrase in support_phrases if phrase in lowered]
    if red_terms and support_terms:
        return "mixed", "news_mixed", red_terms, support_terms
    if red_terms:
        return "negative", "news_red_flag", red_terms, support_terms
    if support_terms:
        return "positive", "news_supportive", red_terms, support_terms
    return "neutral", "local_news_available", red_terms, support_terms


def _summarize_catalyst_evidence(evidence: pd.DataFrame) -> tuple[str, list[str], str, Optional[int], str, str, str, bool]:
    if evidence.empty:
        return "clear", ["no local catalyst file or near-term earnings flag"], "", None, "neutral", "", "", False

    statuses = evidence["evidence_status"].astype(str).tolist() if "evidence_status" in evidence.columns else []
    priority = [
        "event_risk",
        "news_red_flag",
        "watch_event",
        "news_mixed",
        "news_supportive",
        "local_news_available",
        "clear",
    ]
    status = next((item for item in priority if item in statuses), "clear")
    notes = _dedupe_notes(evidence.get("note", pd.Series(dtype=str)).astype(str).tolist())[:5]
    sources = _dedupe_notes(evidence.get("source", pd.Series(dtype=str)).astype(str).tolist())
    red_terms = _dedupe_terms(evidence.get("red_flag_terms", pd.Series(dtype=str)).astype(str).tolist())
    support_terms = _dedupe_terms(evidence.get("support_terms", pd.Series(dtype=str)).astype(str).tolist())
    sentiments = {str(value) for value in evidence.get("sentiment", pd.Series(dtype=str)).astype(str).tolist() if str(value)}
    if "negative" in sentiments:
        sentiment = "negative"
    elif "mixed" in sentiments:
        sentiment = "mixed"
    elif "positive" in sentiments:
        sentiment = "positive"
    elif "event" in sentiments:
        sentiment = "event"
    else:
        sentiment = "neutral"
    days_to_earnings: Optional[int] = None
    if "days_to_earnings" in evidence.columns:
        for value in evidence["days_to_earnings"].tolist():
            parsed = _as_float(value)
            if parsed is not None:
                days_to_earnings = int(parsed)
                break
    objective = bool(evidence.get("objective_blocker", pd.Series(dtype=bool)).astype(bool).any())
    return status, notes, "; ".join(sources), days_to_earnings, sentiment, ";".join(red_terms), ";".join(support_terms), objective


def _news_hint(path: Optional[Path]) -> str:
    if path is None:
        return ""
    try:
        text = path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return "local news file present but unreadable"
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if not lines:
        return "local news file present but empty"
    headline = _sanitize_local_news_headline(lines[0])
    if len(headline) > 140:
        headline = headline[:137] + "..."
    return f"local news file present: {headline}"


def _candidate_ticker(row: Mapping[str, Any]) -> str:
    for key in ("ticker", "underlying", "symbol"):
        value = str(row.get(key) or "").strip()
        if value:
            return value.split()[0].upper()
    return ""


def _portfolio_notes_for_ticker(ticker: str, portfolio: Mapping[str, Any]) -> list[str]:
    if not ticker:
        return []
    notes: list[str] = []
    option_underlyings = {str(value).upper() for value in portfolio.get("option_underlyings", []) or []}
    if ticker in option_underlyings:
        notes.append(f"existing option exposure in {ticker}; execution gate unaffected")

    total_value = _as_float(portfolio.get("total_value"))
    equity_exposure = portfolio.get("large_equity_exposure", {}) or {}
    exposure_value = _as_float(equity_exposure.get(ticker)) if isinstance(equity_exposure, Mapping) else None
    if exposure_value:
        if total_value:
            pct = exposure_value / total_value
            notes.append(f"large equity exposure in {ticker} ({pct:.1%} of book); execution gate unaffected")
        else:
            notes.append(f"large equity exposure in {ticker}; execution gate unaffected")

    sector_exposures = portfolio.get("sector_exposures", {}) or {}
    sector = str(portfolio.get("ticker_sector_map", {}).get(ticker, "")).strip() if isinstance(portfolio.get("ticker_sector_map"), Mapping) else ""
    if sector and isinstance(sector_exposures, Mapping):
        sector_pct = _as_float(sector_exposures.get(sector))
        if sector_pct is not None and sector_pct >= 0.25:
            notes.append(f"sector crowding in {sector} ({sector_pct:.1%} of book); execution gate unaffected")

    return notes


def _is_portfolio_risk_review(review: Mapping[str, Any]) -> bool:
    if _truthy(review.get("portfolio_risk_only")):
        return True
    blocker_type = str(review.get("blocker_type") or "").strip().lower().replace("-", "_")
    if blocker_type in {"portfolio", "portfolio_risk", "account_risk"}:
        return True
    agent = str(review.get("agent") or "").strip().lower().replace("-", "_")
    if agent in {"portfolio", "portfolio_risk", "portfolio_risk_agent"}:
        return True
    text = " ".join(
        [
            str(review.get("verdict") or ""),
            str(review.get("note") or ""),
        ]
    ).lower()
    phrases = (
        "existing position",
        "existing exposure",
        "existing option exposure",
        "equity exposure",
        "portfolio concentration",
        "portfolio crowding",
        "portfolio exposure",
        "sector crowding",
        "sector_crowding",
        "crowded book",
        "book exposure",
        "buying power",
        "margin strain",
        "assignment exposure",
        "account exposure",
        "correlated exposure",
        "correlated beta",
    )
    return any(phrase in text for phrase in phrases)


def _is_portfolio_management_process_note(review: Mapping[str, Any]) -> bool:
    agent = str(review.get("agent") or "").strip().lower().replace("-", "_")
    if agent != "portfolio_management":
        return False
    if _truthy(review.get("objective_blocker")) or _is_portfolio_risk_review(review):
        return False
    text = str(review.get("note") or "").strip().lower()
    process_markers = (
        "no sized spread",
        "target exit",
        "invalidation",
        "fresh portfolio context",
        "risk-off sizing",
        "planning size",
        "portfolio risk annotation",
    )
    return any(marker in text for marker in process_markers)


def _is_review_blocking_builtin_caution(review: Mapping[str, Any]) -> bool:
    if _is_external_or_subagent_agent_type(review.get("agent_type")):
        return False
    if str(review.get("verdict") or "").strip().lower() != "caution":
        return False
    if _truthy(review.get("objective_blocker")) or _is_portfolio_risk_review(review):
        return False
    agent = str(review.get("agent") or "").strip().lower().replace("-", "_")
    if agent != "catalyst":
        return False
    evidence = str(review.get("evidence") or "").strip().lower()
    if evidence in {"event_risk", "news_red_flag"}:
        return True
    if str(review.get("confidence") or "").strip().lower() != "high":
        return False
    text = str(review.get("note") or "").strip().lower()
    review_markers = (
        "red flag",
        "sec probe",
        "investigation",
        "fraud",
        "bankruptcy",
        "trading halt",
        "event risk",
    )
    return any(marker in text for marker in review_markers)


def _split_portfolio_rejects(value: Any) -> tuple[list[str], list[str]]:
    rejects = [item.strip() for item in str(value or "").replace("|", ";").split(";") if item.strip()]
    removed: list[str] = []
    remaining: list[str] = []
    for reject in rejects:
        lowered = reject.lower()
        if any(term in lowered for term in PORTFOLIO_REJECT_TERMS):
            removed.append(reject)
        else:
            remaining.append(reject)
    return removed, remaining


def _is_otherwise_qualified(row: Mapping[str, Any], remaining_rejects: Sequence[str]) -> bool:
    if remaining_rejects:
        return False
    quality = str(row.get("quality_status") or row.get("trade_quality") or "").strip().lower()
    status = str(row.get("recommendation_status") or row.get("trade_status") or "").strip().upper()
    if quality in {"qualified", "good", "approved", "valid", "execute"}:
        return True
    return status in {"ENTER", "EXECUTE", "BUY", "SELL_TO_OPEN"}


def _default_status(row: Mapping[str, Any], remaining_rejects: Sequence[str]) -> str:
    if remaining_rejects:
        return RecommendationStatus.AVOID.value
    if _is_otherwise_qualified(row, remaining_rejects):
        return RecommendationStatus.ENTER.value
    return RecommendationStatus.REVIEW.value


def _append_reason(existing: Any, addition: str) -> str:
    existing_text = str(existing or "").strip()
    if not existing_text:
        return addition
    if addition in existing_text:
        return existing_text
    return f"{existing_text}; {addition}"


def _dedupe_notes(notes: Iterable[str]) -> list[str]:
    seen: set[str] = set()
    clean: list[str] = []
    for note in notes:
        text = str(note or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        clean.append(text)
    return clean


def _dedupe_terms(values: Iterable[str]) -> list[str]:
    terms: list[str] = []
    for value in values:
        for term in str(value or "").replace(",", ";").split(";"):
            clean = term.strip()
            if clean and clean not in terms:
                terms.append(clean)
    return terms


def _format_strike(value: Any) -> str:
    number = _as_float(value)
    if number is None:
        return ""
    if float(number).is_integer():
        return str(int(number))
    return f"{number:.3f}".rstrip("0").rstrip(".")


def _parse_occ_symbol(symbol: Any) -> dict[str, Any]:
    compact = re.sub(r"\s+", "", _as_text(symbol).upper())
    match = re.match(r"^(.+?)(\d{2})(\d{2})(\d{2})([CP])(\d{8})$", compact)
    if not match:
        return {}
    root, yy, month, day, right, strike_raw = match.groups()
    try:
        expiry = dt.date(2000 + int(yy), int(month), int(day)).isoformat()
    except ValueError:
        expiry = ""
    return {
        "ticker": root.strip(),
        "expiry": expiry,
        "right": right,
        "strike": int(strike_raw) / 1000.0,
    }


def _format_option_leg(
    symbol: Any,
    action: str,
    *,
    ticker: Any = "",
    expiry: Any = "",
    strike: Any = "",
    right: Any = "",
) -> str:
    parsed = _parse_occ_symbol(symbol)
    ticker_text = _as_text(ticker).upper() or _as_text(parsed.get("ticker")).upper()
    expiry_text = _as_text(expiry) or _as_text(parsed.get("expiry"))
    strike_text = _format_strike(strike) or _format_strike(parsed.get("strike"))
    right_code = (_as_text(right) or _as_text(parsed.get("right"))).upper()
    right_text = "Call" if right_code == "C" else ("Put" if right_code == "P" else "Option")
    parts = [action.upper(), "1"]
    if ticker_text:
        parts.append(ticker_text)
    if expiry_text:
        parts.append(expiry_text)
    if strike_text:
        parts.append(strike_text)
    parts.append(right_text)
    return " ".join(parts)


def _format_trade_plan(
    sell_leg: Any,
    buy_leg: Any,
    entry_limit: Any,
    *,
    entry_type: str = "CREDIT",
) -> str:
    entry = _as_float(entry_limit)
    suffix = f" @ {entry:.2f} {entry_type.upper()}" if entry is not None and entry > 0 else ""
    sell_text = _as_text(sell_leg)
    buy_text = _as_text(buy_leg)
    if sell_text and buy_text:
        return f"{sell_text} / {buy_text}{suffix}".strip()
    return f"{sell_text or buy_text}{suffix}".strip()


def _as_float(value: Any) -> Optional[float]:
    try:
        if value is None or value == "":
            return None
        if pd.isna(value):
            return None
        return float(value)
    except (TypeError, ValueError):
        return None


def _as_text(value: Any) -> str:
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    return str(value).strip()


def _mapping_get(mapping: Mapping[str, Any] | pd.Series, key: str) -> Any:
    if isinstance(mapping, pd.Series):
        return mapping.get(key)
    if isinstance(mapping, Mapping):
        return mapping.get(key)
    return None


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() in {"1", "true", "yes", "y", "on"}


def _write_json(path: Path, payload: Mapping[str, Any]) -> None:
    sanitized = _strict_json_value(payload)
    path.write_text(
        json.dumps(sanitized, indent=2, sort_keys=True, allow_nan=False) + "\n",
        encoding="utf-8",
    )


def _strict_json_value(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {str(key): _strict_json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_strict_json_value(item) for item in value]
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    if isinstance(value, (dt.datetime, dt.date)):
        return value.isoformat()
    if isinstance(value, Enum):
        return _strict_json_value(value.value)
    if value is None or isinstance(value, (str, bool, int)):
        return value
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    item = getattr(value, "item", None)
    if callable(item):
        return _strict_json_value(item())
    return value


def build_color_trade_board_markdown(trade_tickets: pd.DataFrame, *, as_of: str) -> str:
    """Render a colour-coded, operator-facing trade board.

    The CSV artifacts stay authoritative. This is the one surface that answers
    "what do I place today" at a glance, so readiness is a colour rather than a
    status string that has to be decoded.
    """

    lines: list[str] = [
        f"# Groko trades — {as_of}",
        "",
        "🟢 send-now / ready to enter &nbsp;|&nbsp; 🟡 working limit / do not chase &nbsp;|&nbsp; 🔴 blocked this session",
        "",
    ]
    if trade_tickets is None or trade_tickets.empty:
        return "\n".join(
            lines
            + [
                "🔴 **No tickets.** No candidate reached the ticket surface.",
                "",
                "See `no_trade_audit.csv` and `selector_challenger_audit.csv` for the binding gate.",
                "",
            ]
        )

    def icon(row: Mapping[str, Any]) -> str:
        if _truthy(row.get("ready_to_enter")):
            return "🟢"
        target_status = _as_text(row.get("target_order_status")).lower()
        if target_status.startswith("target_order") or target_status.startswith("review_only_"):
            return "🟡"
        return "🔴"

    def required_action(row: Mapping[str, Any]) -> str:
        blockers = _blocker_set(row.get("execution_blockers"))
        if not blockers:
            return _ticket_recheck_summary(row)
        if SELECTOR_POLICY_BLOCKER in blockers:
            reasons = _blocker_set(row.get("selector_policy_reason"))
            entry_type = (
                _as_text(row.get("entry_type")).upper()
                or _entry_type_from_route(_as_text(row.get("strategy_route")))
            )
            if entry_type == "DEBIT" and reasons & {
                "active_policy_entry_type_not_allowed",
                "active_policy_route_not_allowed",
            }:
                return "debit route is outside the promoted credit-only policy"
            selector_reasons: list[str] = []
            if "active_policy_asset_class_not_allowed:etf" in reasons:
                selector_reasons.append("ETF is outside the promoted common-stock replay policy")
            if "active_policy_underlying_tier_not_allowed" in reasons:
                selector_reasons.append("underlying tier is outside the promoted core/liquid policy")
            volume_reasons = sorted(
                reason
                for reason in reasons
                if reason.startswith("active_policy_contract_volume_below_")
            )
            for reason in volume_reasons:
                minimum = reason.rsplit("_", 1)[-1]
                selector_reasons.append(f"contract volume is below the promoted minimum of {minimum}")
            dte_reasons = sorted(
                reason for reason in reasons if reason.startswith("credit_dte_outside_")
            )
            for reason in dte_reasons:
                parts = reason.rsplit("_", 2)
                if len(parts) == 3:
                    selector_reasons.append(
                        f"DTE is outside the promoted {parts[-2]}-{parts[-1]} day credit window"
                    )
            if not selector_reasons:
                selector_reasons = [
                    _selector_rejection_label(reason)
                    for reason in sorted(reasons)
                    if not reason.startswith("active_policy_")
                ]
            return "; ".join(dict.fromkeys(selector_reasons)) or _display_blocker_label(
                SELECTOR_POLICY_BLOCKER
            )
        credit_floor_blockers = sorted(
            blocker for blocker in blockers if blocker.startswith("send_now_credit_below_")
        )
        if credit_floor_blockers:
            entry_limit = _as_float(row.get("entry_limit"))
            if entry_limit is not None:
                return (
                    f"credit ${entry_limit:.2f} is below the ${MIN_SEND_NOW_CREDIT:.2f} "
                    "actionability floor"
                )
        priority = {
            "objective_blocker": 0,
            SELECTOR_POLICY_BLOCKER: 10,
            GOAL_CONFIDENCE_GATE_BLOCKER: 20,
            NEGATIVE_STRATEGY_EXPECTANCY_BLOCKER: 30,
            PROFITABILITY_CALIBRATION_ACTUAL_NEGATIVE_BLOCKER: 31,
            NEGATIVE_ROUTE_FAMILY_EVIDENCE_BLOCKER: 32,
            PROFITABILITY_CALIBRATION_BLOCKER: 33,
            POSITIVE_STRATEGY_EXPECTANCY_BLOCKER: 34,
            "execution_confidence_below_threshold": 40,
            "wait_for_price": 50,
            "contract_specific_agent_reviews_missing": 60,
            "contract_specific_agent_review_blocked": 61,
            "contract_specific_agent_review_caution": 70,
        }
        explanations: list[str] = []
        for blocker in sorted(blockers, key=lambda value: (priority.get(value, 45), value)):
            if blocker == "contract_specific_agent_review_caution":
                explanations.append(_ticket_recheck_summary(row))
            else:
                explanations.append(_display_blocker_label(blocker))
        return "; ".join(dict.fromkeys(explanations))

    working = trade_tickets.copy()
    working["__icon"] = working.apply(icon, axis=1)
    working["__icon_rank"] = working["__icon"].map({"🟢": 0, "🟡": 1, "🔴": 2}).fillna(3)
    working = working.sort_values(["__icon_rank"], kind="mergesort")
    counts = working["__icon"].value_counts().to_dict()
    red_cap = 25
    lines += [
        f"🟢 actionable: **{counts.get('🟢', 0)}** | "
        f"🟡 working / target: **{counts.get('🟡', 0)}** | "
        f"🔴 excluded / rejected: **{counts.get('🔴', 0)}**",
        "",
        "| | Ticker | Structure | Expiry | DTE | Limit | Contracts | Trade / entry confidence | Max profit | Max risk | Target P/L / Risk | Acct risk | Action / binding reason |",
        "|---|---|---|---|---|---|---|---|---|---|---|---|---|",
    ]
    red_shown = 0
    for _, row in working.iterrows():
        if row["__icon"] == "🔴":
            if red_shown >= red_cap:
                continue
            red_shown += 1
        max_profit = _as_float(row.get("position_max_profit")) or 0.0
        max_loss = _as_float(row.get("position_max_loss")) or 0.0
        account_risk = _as_float(row.get("account_risk_pct")) or 0.0
        action = required_action(row)
        target_pnl = (
            "not actionable"
            if row["__icon"] == "🔴"
            else _ticket_target_pnl_and_risk_display(row)
        )
        lines.append(
            f"| {row['__icon']} | **{_as_text(row.get('ticker')).upper()}** "
            f"| {_as_text(row.get('structure'))} | {_as_text(row.get('expiry'))} "
            f"| {int(_as_float(row.get('dte')) or 0)} "
            f"| {_ticket_planned_entry_value(row)[0] or 0:.2f} "
            f"| {_ticket_contracts_display(row)} "
            f"| {_ticket_trade_confidence_display(row)} / {_ticket_entry_confidence_display(row)} "
            f"| ${max_profit:,.0f} | ${max_loss:,.0f} | {target_pnl} "
            f"| {account_risk * 100:.2f}% "
            f"| {action[:240]} |"
        )
    hidden_red = int(counts.get("🔴", 0)) - red_shown
    if hidden_red > 0:
        lines.append(
            f"| 🔴 | … | {hidden_red} more blocked rows | | | | | | | | | | see `decision_board.csv` |"
        )
    lines.append("")

    green_orders = working[working["__icon"].eq("🟢")]
    yellow_targets = working[working["__icon"].eq("🟡")]
    if not green_orders.empty:
        total_profit = pd.to_numeric(green_orders.get("position_max_profit"), errors="coerce").sum()
        total_risk = pd.to_numeric(green_orders.get("position_max_loss"), errors="coerce").sum()
        lines += [
            f"**Actionable plan totals:** max profit ${total_profit:,.0f} | max risk ${total_risk:,.0f}",
            "",
            "## Green Actionable Plans",
            "",
            "```",
        ]
        for _, row in green_orders.iterrows():
            contracts = int(_as_float(row.get("suggested_contracts")) or 0)
            lines.append(
                f"{_as_text(row.get('ticker')).upper():<6} {contracts:>3} x  {_as_text(row.get('trade_plan'))}"
            )
        lines += ["```", ""]
    if not yellow_targets.empty:
        total_profit = pd.to_numeric(yellow_targets.get("position_max_profit"), errors="coerce").sum()
        total_risk = pd.to_numeric(yellow_targets.get("position_max_loss"), errors="coerce").sum()
        total_expected = pd.to_numeric(
            yellow_targets.get(
                "expected_position_pnl",
                pd.Series(0.0, index=yellow_targets.index),
            ),
            errors="coerce",
        ).fillna(0).sum()
        aggregate_expected_ror = total_expected / total_risk if total_risk > 0 else 0.0
        pilot_overrides = yellow_targets[
            yellow_targets.get("model_evidence_pilot", pd.Series(False, index=yellow_targets.index)).map(_truthy)
            & (
                pd.to_numeric(
                    yellow_targets.get(
                        "suggested_contracts",
                        pd.Series(0, index=yellow_targets.index),
                    ),
                    errors="coerce",
                ).fillna(0)
                > pd.to_numeric(
                    yellow_targets.get(
                        "evidence_size_cap",
                        pd.Series(0, index=yellow_targets.index),
                    ),
                    errors="coerce",
                ).fillna(0)
            )
        ]
        lines += [
            f"**Yellow risk-budget scenario:** expected P/L ${total_expected:,.0f} ({aggregate_expected_ror:.2%} of max risk) | "
            f"max profit ${total_profit:,.0f} | max risk ${total_risk:,.0f}",
            "",
            "## Yellow Planning Tickets - Do Not Submit",
            "",
            "These tickets are reference plans only until every required action in the table clears.",
            "",
        ]
        if not pilot_overrides.empty:
            evidence_expected = sum(
                (_as_float(row.get("expected_pnl_one_contract")) or 0.0)
                * int(_as_float(row.get("evidence_size_cap")) or 1)
                for _, row in pilot_overrides.iterrows()
            )
            evidence_contracts = sum(
                int(_as_float(row.get("evidence_size_cap")) or 1)
                for _, row in pilot_overrides.iterrows()
            )
            lines += [
                f"Evidence-backed layer: {evidence_contracts} total contracts with about ${evidence_expected:,.0f} expected P/L. "
                "Scaling above those caps is operator-directed, not validated by selector-attributed outcomes.",
                "",
            ]
        lines.append("```")
        for _, row in yellow_targets.iterrows():
            lines.append(
                f"{_as_text(row.get('ticker')).upper():<6} {_ticket_contracts_display(row):>28} x  {_as_text(row.get('trade_plan'))}"
            )
        lines += ["```", ""]

    lines += [
        "## Artifacts",
        "",
        "- [trade_tickets.csv](trade_tickets.csv)",
        "- [green_trade_tickets.csv](green_trade_tickets.csv)",
        "- [target_order_candidates.csv](target_order_candidates.csv)",
        "- [sizing_audit.csv](sizing_audit.csv)",
        "- [final_recommendations.csv](final_recommendations.csv)",
        "- [no_trade_audit.csv](no_trade_audit.csv)",
        f"- [options_agent_report_{as_of}.md](options_agent_report_{as_of}.md)",
        "",
    ]
    return "\n".join(lines)


def _write_frame(df: pd.DataFrame, path: Path) -> None:
    df.to_csv(path, index=False)


def _write_csv(path: Path, fieldnames: Sequence[str], rows: Sequence[Mapping[str, Any]]) -> None:
    with path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow(dict(row))


def _smoke_report(day: str, manifest: Mapping[str, Any]) -> str:
    agent_lines = "\n".join(f"- {agent['name']}: {agent['role']}" for agent in manifest["agents"])
    return (
        f"# Groko Smoke Report - {day}\n\n"
        "Status: design scaffold only. Live UW, Schwab chain, and research integrations "
        "are intentionally not wired in this first slice.\n\n"
        "## Visibility Invariant\n\n"
        f"{manifest['visibility_invariant']}.\n\n"
        "## Agent Roster\n\n"
        f"{agent_lines}\n"
    )
